(window.GIM_TP=window.GIM_TP||{})["Z.Tetzaveh.0"]={"from":0,"a":[[[],[],[]],[["(שמות כ״ז:כ׳) וְאַתָּה תְּצַוֵּה אֶת בְּנֵי יִשְׂרָאֵל וְגו'. וְאַתָּה הַקְרֵב אֵלֶיךָ אֶת אַהֲרֹן אָחִיךָ וְגו'. אָמַר רִבִּי חִיָּיא, מַאי שְׁנָא הָכָא מִבְכָל אֲתָר, דִּכְתִּיב וְאַתָּה הַקְרֵב אֵלֶיךָ וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב. וְאַתָּה תְּצַוֵּה אֶת בְּנִי יִשְׂרָאֵל. (שמות ל׳:כ״ג) וְאַתָּה קַח לְךָ בְּשָׂמִים רֹאשׁ מָר דְּרוֹר. אֶלָּא כֹּלָּא בְּרָזָא עִלָּאָה אִיהוּ, לְאַכְלְלָא שְׁכִינְתָּא בַהֲדֵיהּ.","אָמַר רִבִּי יִצְחָק, נְהוֹרָא עִלָּאָה, וּנְהוֹרָא תַּתָּאָה כָּלִיל כַּחֲדָא, אִקְרֵי (קל\"ח ע\"ב) וְאַתָּה. כְּמָה דְּאַתְּ אָמַר (נחמיה ט׳:ו׳) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. וְעַל דָּא לָא כְּתִיב, וְהִקְרַבְתָּ אֶת אַהֲרֹן אָחִיךְ. וְצִוִיתָ אֶת בְּנֵי יִשְׂרָאֵל. וְדִבַּרְתָּ אֶל כָּל חַכְמֵי לֵב. בְּגִין דְּהַהוּא זִמְנָא שַׁרְיָא שִׁמְשָׁא בְּסִיהֲרָא, וְאִשְׁתָּתַּף כֹּלָּא כַּחֲדָא, לְשַׁרְיָא עַל אוּמָנוּתָא דְּעוֹבָדָא. אָמַר רִבִּי אֶלְעָזָר, מֵהָכָא, (שמות ל״ו:א׳) אֲשֶׁר נָתַן יְיָ' חָכְמָה וּתְבוּנָה בָּהֵמָּה.","רִבִּי שִׁמְעוֹן אָמַר מֵהָכָא, וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה. אֲשֶׁר מִלֵּאתִים מִבָּעֵי לֵיהּ. אֶלָּא אֲשֶׁר מִלֵּאתִיו, לְהַהוּא לִבָּא, מִלֵּאתִיו רוּחַ חָכְמָה. כְּמָה דְאַתְּ אָמֵר (ישעיהו י״א:ב׳) וְנָחָה עָלָיו רוּחַ יְיָ' רוּחַ חָכְמָה וְגוֹ' וְעַל דָּא אִצְטְרִיךְ אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה, דְּשַׁרְיָא שִׁמְשָׁא בְּסִיהֲרָא בְּאַשְׁלְמוּתָא דְּכֹלָּא, וְעַל דָּא אִתְרְשִׁים כֹּלָּא בְכָל אֲתָר. אָמַר רִבִּי אֶלְעָזָר, אִי הָכִי הָנֵי וְאַתָּה וְאַתָּה, הֵיאַךְ מִתְיַישְּׁבָן בִּקְרָאֵי.","אָמַר לֵיהּ, כֻּלְּהוּ מִתְיַישְּׁבָן נִינְהוּ. וְאַתָּה הַקְּרֵב אֵלֶיךָ: לְיַחֲדָא בַּהֲדֵיהּ, וּלְקָרְבָא בַּהֲדֵיהּ, רָזָא דִּשְׁמָא קַדִישָׁא כְּדְקָא יֵאוֹת. וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב: בְּגִין דְּכֻלְּהוּ לָא אַתְיָין לְמֶעְבַּד עֲבִידְתָּא, עַד דְּרוּחַ קֻדְשָׁא מְמַלְּלָא בְּגַוַּויְיהוּ, וְלָחַשׁ לוֹן בִּלְחִישׁוּ, וּכְדֵין עַבְדֵי עֲבִידְתָּא. וְאַתָּה תְּצַוֵּה אֶת בְּנִי יִשְׂרָאֵל: רוּחַ קֻדְשָׁא פַּקְדָא עָלַיְיהוּ, וְאַנְהִיר עָלַיְיהוּ, לְמֶעְבַּד עוֹבָדָא בִּרְעוּתָא שְׁלִים. וְאַתָּה קַח לְךָ: כְּמָה דְּאוֹקִימְנָא. (דכתיב) וְאַתָּה הַקְרֵב אֵלֶיךָ, וְהָנִי כֻּלְּהוּ, הָכָא בְּעוֹבָדָא דְּמַשְׁכְּנָא. דְּכֹלָּא אִתְעָבִיד בְּרָזָא דָּא.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר (תהילים כ״ב:כ׳) וְאַתָּה יְיָ' אַל תִּרְחָק אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. וְאַתָּה יְיָ' כֹּלָּא חַד. אַל תִּרְחָק: לְאִסְתַּלְּקָא מִינָן, לְמֶהֱוֵי סָלִיק נְהוֹרָא עִלָּאָה מִתַּתָּאָה. דְּהָא כַּד אִסְתָּלַּק נְהוֹרָא עִלָּאָה מִתַּתָּאָה, כְּדֵין אִתְחֲשָׁךְ כָּל נְהוֹרָא, וְלָא אִשְׁתְּכַח כְּלַל בְּעָלְמָא.","וְעַל דָּא אִתְחָרַב בֵּי מַקְדְּשָׁא בְּיוֹמוֹי דְּיִרְמְיָהוּ. וְאַף עַל גַּב דְּאִתְבְּנֵי לְבָתַר, לָא אַהְדָר נְהוֹרָא לְאַתְרֵיהּ כַּדְקָא יֵאוֹת. וְעַל רָזָא דָּא, שְׁמָא דְּהַהוּא נְבִיאָה דְּאִתְנַבֵּי עַל דָּא, יִרְמְיָהוּ. אִסְתַּלְקוּתָא דִּנְהוֹרָא עִלָּאָה, דְּאִסְתָּלַּק לְעֵילָא לְעֵילָּא, וְלָא אַהְדָר לְאַנְהָרָא לְבָתַר כְּדְקָא יֵאוֹת. יִרְמְיָהוּ: אִסְתָּלַּק וְלָא אַהְדָר לְאַתְרֵיהּ, וְאִתְחָרַב בֵּי מַקְדְשָׁא וְאִתְחֲשָׁכוּ נְהוֹרִין.","אֲבָל יְשַׁעְיָהוּ, שְׁמָא גָּרִים לְפוּרְקָנָא, וּלְאַהְדָּרָא נְהוֹרָא עִלָּאָה לְאַתְרִיהּ, (ישעיהו לאנהרא ההוא נהורא עלאה ולמעבד פורקנא) וּלְמִבְנֵי בֵּי מַקְדְשָׁא, וְכָל טָבִין וְכָל נְהוֹרִין, יָהַדְרוּן כְּדִבְּקַדְמֵיתָא. וְעַל דָּא, שְׁמָהָן דִּתְרֵין נְבִיאִין אִלֵּין, קַיְימִין דָּא לָקֳבֵל דָּא, בְּגִין דִּשְׁמָא גָּרִים, וְצֵרוּפָא דְּאַתְוָון דָּא בְּדָא, גַּרְמִין עוֹבָדָא, הֵן לְטָב וְהֵן לְבִישׁ. וְעַל רָזָא דָּא, צֵרוּפָא דְּאַתְוָון דִּשְׁמָהָן קַדִּישִׁין, וְכֵן אָתְוָון בְּגַרְמַיְיהוּ, גַּרְמִין לְאִתְחֲזָאָה רָזִין עִלָּאִין, כְּגַוְונָא דִּשְׁמָא קַדִּישָׁא, דְּאַתְוָון בְּגַרְמַיְיהוּ, גַּרְמִין רָזִין עִלָּאִין קַדִּישִׁין לְאִתְחֲזָאָה בְּהוּ."],[[0,"ואתה תצוה","וגו': \u0003ואתה הקרב\u0004 וגו': אמר רבי חייא, מה השינוי שבכאן מבכל המקומות, שכתוב, \u0003ואתה\u0004 הקרב אליך. \u0003ואתה\u0004 תדבר אל כל חכמי לב. ואתה תצוה את בני ישראל. \u0003ואתה\u0004 קח לך בשמים ראש מר דרור. שלא כתוב כבכל המקומות, והקרבת, ותדבר, ותצוה, ותקח. ומשיב. אלא הכל הוא בסוד עליון, כדי לכלול עמו השכינה. כי השכינה נקראת \u0003אתה,\u0004 וכשכתוב \u0003ואתה\u0004 היינו לכלול עמו השכינה בהצווי ובהדבור וכו'."],[1,"אמר רבי יצחק","וכו': אר\"י אור העליון, שהוא ז\"א, ואור התחתון, שהוא הנוקבא, כלולים יחד במלה ואתה, כי אתה הוא שם הנוקבא כנ\"ל. וה \u0003ו'\u0004 הנוספת היא ז\"א. כמו שאתה אומר, \u0003ואתה\u0004 מחיה את כולם, שסובב על ז\"א ונוקבא. ועל כן לא כתוב, והקרבת את אהרן אחיך. וצוית את בני ישראל ודברת אל כל חכמי לב. משום שבעת ההוא היה שורה השמש, שהוא ז\"א, בלבנה, שהיא הנוקבא, ונשתתף הכל כאחד, דהיינו ז\"א ונוקבא, לשרות על אומנותה של המלאכה. וע\"כ כתוב בהם \u0003ואתה,\u0004 שיורה על ז\"א ונוקבא. אמר ר' אלעזר מכאן נשמע שהשי\"ת היה שורה על האומנות של מלאכת המשכן, שנאמר, אשר נתן ה' חכמה ותבונה בהמה."],[2,"רבי שמעון אמר","וכו': רש\"א מכאן נשמע, שז\"א ונוקבא היו שורים על אומנות מלאכת המשכן. שכתוב, ואתה תדבר אל כל חכמי \u0003לב\u0004 אשר \u0003מלאתיו\u0004 רוח חכמה. שהיה צריך לומר אשר מלאתים, לשון רבים, אם הוא סובב על חכמי לב, אלא אשר \u0003מלאתיו\u0004 סובב על \u0003לב\u0004 ההוא, שהוא השכינה שנקראת לב. כש\"א ונחה עליו רוח ה' רוח חכמה וגו'. וע\"כ צריך לומר אשר \u0003מלאתיו\u0004 רוח חכמה, ללמד שהשמש שהוא ז\"א שורה בלבנה, שהיא הנוקבא הנקראת לב, בשלמות הכל, וע\"כ נתרשם הכל, דהיינו ז\"א ונוקבא, בכל המקומות, במלאכת המשכן, שכתוב בהם \u0003ואתה,\u0004 הרומז לז\"א ונוקבא. אמר ליה ר' אלעזר, א\"כ, אלו, ואתה ואתה, איך הם מתישבים בהמשך המקראות, אם נפרש משמעותם על ז\"א ונוקבא."],[3,"אמר ליה כלהו","וכו': אמר ליה ר\"ש כולם הם מתישבים, ואתה הקרב אליך, פירושו, שאמר למשה שיקרב את \u0003ואתה\u0004 שהוא ז\"א ונוקבא אל אהרן, דהיינו ליחד בו ולקרב אליו סוד השם הקדוש \u0003ואתה\u0004 כראוי. ועל דרך זה, ואתה תדבר אל כל חכמי לב, פירושו שידבר ויקרב וייחד השם \u0003ואתה,\u0004 שהוא זו\"ן, אל כל חכמי לב. משום שכולם לא באו לעשות מלאכת המשכן, עד שרוח הקדש היה מדבר בהם, ולחש להם בחשאי איך לעשותה, ואז עשו המלאכה. ועל דרך זה, ואתה תצוה את בני ישראל, דהיינו שרוח הקדש, הרמוז בהשם ואתה, יצוה את בני ישראל, ויאיר עליהם, כדי שיעשו המעשה ברצון השלם. וכן ואתה קח לך, פירושו, כמו שהעמדנו. וכן ואתה הקרב, וכן כל אלו ואתה, הכתובים כאן במלאכת המשכן, שהכל נעשה בסוד הזה, של השם, ואתה."],[4,"פתח ר\"ש ואמר","וכו': פתח ר\"ש ואמר, ואתה הויה אל תרחק אילותי לעזרתי חושה. \u0003ואתה הויה,\u0004 אשר אתה הוא הנוקבא והשם הויה, הוא ז\"א, מתפלל שהכל יהיה אחד שיהיו מחוברים זה בזה. \u0003אל תרחק,\u0004 פירושו, שלא יתרחק להסתלק ממנו, שאור העליון, ז\"א, לא יסתלק מאור התחתון הנוקבא, כי כשאור העליון מסתלק מן אור התחתון, אז כל אור נחשך ואינו נמצא בעולם. כי העולם מקבל רק מן המלכות, שהיא אור התחתון, ואם אור העליון, שהוא ז\"א, אינו מאיר בה, אין לה מה להאיר לעולם הזה."],[5,"ועל דא אתחרב","וכו': ועל זה, נחרב בית המקדש בימיו של ירמיהו, דהיינו משום שנסתלק ז\"א מן המלכות, ואע\"פ שנבנה אחר כך, בבית שני, עכ\"ז, לא חזר האור למקומו כראוי, וע\"כ השם של נביא ההוא שהתנבא על זה, הוא ירמיהו, שהוא אותיות, \u0003ירום יה\"ו,\u0004 שפירושו הסתלקות אור העליון למעלה למעלה מן המלכות, ולא חזר להאיר אח\"כ כראוי בבית שני. השם ירמיהו, יורה, שאור העליון נסתלק ממלכות, ולא חזר למקומו ונחרב בית המקדש ונחשכו המאורות."],[6,"אכל ישעיהו שמא","וכו': אבל ישעיהו, השם, שהוא אותיות \u0003ישע יה\"ו,\u0004 גורם לגאולה ולהחזיר אור העליון למקומו למלכות, ולבנות בית המקדש, וכל הטוב וכל האורות יחזרו כבתחילה. וע\"כ השמות של ב' נביאים אלו עומדים זה כנגד זה, ששם האחד \u0003ירום יה\"ו,\u0004 ושם השני הוא להיפך, \u0003ישע יה\"ו\u0004 משום שהשם גורם. וצירוף האותיות אלו עם אלו גורמים מעשה לפי משמעותן, הן לטוב והן לרע. ועל סוד הזה הוא צירוף האותיות של שמות הקדושים, וכן האותיות מבחינתן עצמן, גורמים שיראה סודות עליונים כמשמעותו של השם. שהאותיות בעצמן גורמים סודות עליונים קדושים להראות בהן."]],[[0,"","וְאַתָּה תְּצַוֶּה אֶת בְּנֵי יִשְׂרָאֵל וְגוֹ'. וְאַתָּה הַקְרֵב אֵלֶיךְ אֶת אַהֲרֹן אָחִיךְ וְגוֹ' (שמות כז). אָמַר רַבִּי חִיָּיא, מַה שּׁוֹנֶה כָּאן מִבְּכָל מָקוֹם, שֶׁכָּתוּב וְאַתָּה הַקְרֵב אֵלֶיךְ, וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב, וְאַתָּה תְּצַוֶּה אֶת בְּנֵי יִשְׂרָאֵל, (שמות ל) וְאַתָּה קַח לְךְ בְּשָׂמִים רֹאשׁ מָר דְּרוֹר? אֶלָּא הַכֹּל בְּסוֹד עֶלְיוֹן הוּא, לִכְלֹל הַשְּׁכִינָה עִמּוֹ."],[1,"","אָמַר רַבִּי יִצְחָק, אוֹר עֶלְיוֹן וְאוֹר תַּחְתּוֹן כְּלוּלִים כְּאֶחָד, נִקְרָאִים וְאַתָּה, כְּמוֹ שֶׁנֶּאֱמַר (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. וְעַל כֵּן לֹא כָתוּב וְהִקְרַבְתָּ אֶת אַהֲרֹן אָחִיךְ. וְצִוִּיתָ אֶת בְּנֵי יִשְׂרָאֵל, וְדִבַּרְתָּ אֶל כָּל חַכְמֵי לֵב. מִשּׁוּם שֶׁבַּזְּמַן הַהוּא מְאִירָה הַשֶּׁמֶשׁ בַּיָּרֵחַ, וּמִשְׁתַּתֵּף הַכֹּל כְּאֶחָד, לִשְׁרוֹת עַל אֻמָּנוּת מַעֲשֵׂה הַמִּשְׁכָּן. אָמַר רַבִּי אֶלְעָזָר, מִכָּאן (שמות לו) אֲשֶׁר נָתַן ה' חָכְמָה וּתְבוּנָה בָּהֵמָּה."],[2,"","רַבִּי שִׁמְעוֹן אָמַר, מִכָּאן, וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה. אֲשֶׁר מִלֵּאתִים צָרִיךְ לוֹמַר! אֶלָּא אֲשֶׁר מִלֵּאתִיו - לַלֵּב הַהוּא מִלֵּאתִיו רוּחַ חָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהיא) וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וְגוֹ'. וְעַל זֶה צָרִיךְ אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה, שֶׁשּׁוֹרָה הַשֶּׁמֶשׁ בַּיָּרֵחַ בַּשְּׁלֵמוּת שֶׁל הַכֹּל, וְעַל כֵּן נִרְשְׁמוּ הַכֹּל בְּכָל מָקוֹם. אָמַר רַבִּי אֶלְעָזָר, אִם כֵּן, אֵלּוּ וְאַתָּה וְאַתָּה, אֵיךְ מִתְיַשְּׁבִים בַּפְּסוּקִים?"],[3,"","אָמַר לוֹ, כֻּלָּם מִתְיַשְּׁבִים הֵם. וְאַתָּה הַקְרֵב אֵלֶיךְ - לְיַחֵד עִמּוֹ וּלְקָרֵב אֶצְלוֹ סוֹד הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁצָּרִיךְ. וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב - לְפִי שֶׁכֻּלָּם לֹא בָאוּ לַעֲשׂוֹת מַעֲשֶׂה עַד שֶׁרוּחַ הַקֹּדֶשׁ מְדַבֶּרֶת בְּתוֹכָם וְלוֹחֶשֶׁת לָהֶם בְּלַחַשׁ, וְאָז עוֹשִׂים עֲבוֹדָתָם. וְאַתָּה תְּצַוֶּה אֶת בְּנֵי יִשְׂרָאֵל - רוּחַ הַקֹּדֶשׁ מְצַוָּה עֲלֵיהֶם וּמְאִירָה עֲלֵיהֶם לַעֲשׂוֹת מַעֲשֶׂה בְּרָצוֹן שָׁלֵם. וְאַתָּה קַח לְךְ - כְּמוֹ שֶׁפֵּרַשְׁנוּ, (שכתוב) וְאַתָּה הַקְרֵב אֵלֶיךְ. וְאֵלֶּה כֻּלָּם כָּאן בַּמַּעֲשֶׂה שֶׁל הַמִּשְׁכָּן. שֶׁהַכֹּל נַעֲשָׂה בְּסוֹד זֶה."],[4,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים כב) וְאַתָּה ה' אַל תִּרְחָק אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. וְאַתָּה ה' - הַכֹּל אֶחָד. אַל תִּרְחָק - לְהִתְרַחֵק מֵאִתָּנוּ לִהְיוֹת עוֹלֶה הָאוֹר הָעֶלְיוֹן מִלְּמַטָּה. שֶׁהֲרֵי כַּאֲשֶׁר מִתְעַלֶּה הָאוֹר הָעֶלְיוֹן מִלְּמַטָּה, אֲזַי נֶחְשָׁךְ כָּל הָאוֹר וְלֹא נִמְצָא כְּלָל בָּעוֹלָם."],[5,"","וְעַל זֶה נֶחֱרַב בֵּית הַמִּקְדָּשׁ בִּימֵי יִרְמְיָהוּ. וְאַף עַל גַּב שֶׁנִּבְנָה לְבַסּוֹף, לֹא חָזַר הָאוֹר לִמְקוֹמוֹ כְּמוֹ שֶׁצָּרִיךְ. וְעַל סוֹד זֶה שֵׁם הַנָּבִיא הַהוּא שֶׁהִתְנַבֵּא עַל כָּךְ - יִרְמְיָהוּ. הֶעְלֵם שֶׁל הָאוֹר הָעֶלְיוֹן, שֶׁעָלָה לְמַעְלָה לְמַעְלָה וְלֹא חָזַר לְהָאִיר לְבַסּוֹף כְּמוֹ שֶׁצָּרִיךְ. יִרְמְיָהוּ - הִתְעַלָּה וְלֹא חָזַר לִמְקוֹמוֹ, וְנֶחֱרַב בֵּית הַמִּקְדָּשׁ וְנֶחְשְׁכוּ הַמְּאוֹרוֹת."],[6,"","אֲבָל יְשַׁעְיָהוּ, הַשֵּׁם גּוֹרֵם הַיְשׁוּעָה, וּלְהַחֲזִיר הָאוֹר הָעֶלְיוֹן לִמְקוֹמוֹ (ישעיהו, להאיר האור העליון ולעשות ישועה) וְלִבְנוֹת בֵּית הַמִּקְדָּשׁ, וְכָל הַטּוֹבוֹת וְכָל הָאוֹרוֹת יַחְזְרוּ כְּבָרִאשׁוֹנָה. וְעַל זֶה שְׁמוֹתָם שֶׁל שְׁנֵי הַנְּבִיאִים הָאֵלּוּ עוֹמְדִים זֶה לְעֻמַּת זֶה, בְּסִבַּת הַשֵּׁם שֶׁגּוֹרֵם, וְצֵרוּף הָאוֹתִיּוֹת זוֹ בָּזוֹ גּוֹרְמוֹת מַעֲשֶׂה, הֵן לְטוֹב וְהֵן לְרַע. וְעַל סוֹד זֶה צֵרוּף הָאוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים, וְכֵן הָאוֹתִיּוֹת בְּעַצְמָן גּוֹרְמוֹת לְהַרְאוֹת סוֹדוֹת עֶלְיוֹנִים כְּדֻגְמַת הַשֵּׁם הַקָּדוֹשׁ, שֶׁהָאוֹתִיּוֹת בְּעַצְמָן גּוֹרְמוֹת סוֹדוֹת עֶלְיוֹנִים קְדוֹשִׁים לְהַרְאוֹת בָּהֶם."]]],[["רָזָא קַדְמָאָה, יוֹ\"ד, נְקוּדָה קַדְמָאָה דְּקַיְּימָא עַל תֵּשַׁע סַמְכִין דְּסַמְכִין לָהּ. וְאִינּוּן קַיְימִין לְאַרְבַּע סִטְרֵי עָלְמָא. כְּמָה דְּסוֹפָא דְּמַחֲשָׁבָה, נְקוּדָה בַּתְרָאָה, קַיְּימָא לְאַרְבַּע סִטְרֵי עָלְמָא. בַּר דְּהַאי דְּכָר, וְאִיהִי נוּקְבָּא.","וְהַאי קַיְּימָא בְּלָא גּוּפָא, וְכַד קַיְּימָא בִּלְבוּשָׁא, דְּאִתְלָבַּשׁ בְּהוּ, אִיהִי קַיְּימָא עַל תֵּשַׁע סַמְכִין, בְּרָזָא דְּאָת ם בְּלָא עִגּוּלָא. וְאַף עַל גַּב דְּאָת ס' אִיהִי בְּעִגּוּלָא, וְקַיְּימָא בְּעִגּוּלָא. אֲבָל בְּרָזָא דְּאַתְוָון חֲקִיקִן, גּוֹ נְקוּדֵי, טְהִירִין לְעֵילָּא, אִינּוּן בְּרִבּוּעָא, דִּלְתַתָּא אִיהוּ בְּעִגּוּלָא.","הַאי בְּרִבּוּעַ אִיהִי קַיְּימָא בְּשִׁיעוּרָא דְּתֵשַׁע נְקוּדִין, תְּלַת תְּלַת לְכָל סְטָר. וְאִינּוּן בְּשִׁיעוּרָא דְּחוּשְׁבָּנָא תְּמַּנְיָא נְקוּדִין, וְאִינּוּן תֵּשַׁע. וְאִלֵּין אִינּוּן דְּקַיְימִין מֵרָזָא דְּבוּצִינָא בְּרִיבּוּעָא בְּסַמְכִין תִּשְׁעָה לְאָת יוֹ\"ד, נְקוּדָה חֲדָא. אִינּוּן תִּשְׁעָה. אִינּוּן תְּמַנְיָא בְּרָזָא דְּאָת ם בְּרִבּוּעָא, כְּגַוְונָא דָּא:: תְלָת תְלָת לְכָל סְטָר","וְדָא אִיהוּ רָזָא : דְּאָת יוֹ\"ד נְקוּדָה חֲדָא, וְאַף עַל גַּב דְּאִיהִי נְקוּדָה חֲדָא, דִּיּוּקְנָא דִּילָהּ, רֵישָׁא לְעֵילָּא, וְקוֹצָא לְתַתָּא, וְשִׁיעוּרָא דִּילָהּ תְּלַת נְקוּדִין כְּגַוְונָא דָּא וְעַל דָא אִתְפַּשְׁטוּתָא לְאַרְבַּע סִטְרִין, תְלָת, תְלָת לְכָל סְטָר אִיהִי תֵשַׁע וְאִיהִי תְמַנְיָא.","וְאִלֵּין אִינּוּן סַמְכִין דְּנָפְקִין מֵרָזָא דְּבוּצִינָא, לְמֶהוֵי סַמְכִין לְאָת יוֹ\"ד, וְאִלֵּין אִקְרוּן רְתִיכָא דִּילָהּ. וְלָא קַיְּימִין בִּשְׁמָא, בַּר בְּרָזָא דְּתֵשַׁע נְקוּדִין דְּאוֹרַיְיתָא.","וּבְרָזָא דְּסִפְרָא דְּאָדָם, אִתְפְּלָגוּ אִלֵּין תֵּשַׁע דְּאִינּוּן תְּמַנְיָא, בְּצֵרוּפָא דְּאַתְוָון דִּשְׁמָא קַדִּישָׁא, לְצָרְפָא לוֹן וּלְיַחֲדָא לוֹן בְכָל אִינּוּן גַּוְונִין, כַּד נַטְלִין אִלֵּין תְּמַנְיָא דְּאִינּוּן תֵּשַׁע, נַהֲרִין בִּנְהִירוּ דְּאָת ם בְּרִבּוּעָא, וְאַפִּיק נְהוֹרִין תְּמַנְיָא, (ס\"א תמניא אתחזון) אִתְחָזוּן וְאַתְוָון תִּשְׁעָה. וְאִתְפַּלְגָּן לְתַתָּא לְנַטְלָא כָּל מַשְׁכְּנָא.","וְאִינּוּן צֵרוּפָא דִּשְׁמָא קַדִּישָׁא, בְּרָזָא דְּשִׁבְעִין וּתְרֵין אַתְוָון מְחַקְּקָן, דְּנַפְקֵי מֵרָזָא דִּתְלַת גַּוְונִין, יְמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא. וְכֹלָּא מֵרָזָא דִּתְלַת נְקוּדִין, שִׁיעוּרָא דְּאָת יוֹ\"ד, דְּאִיהִי לְד' סִטְרִין, וְאִינּוּן תְּמַנְיָא נְקוּדִין, וְאִינּוּן תֵּשַׁע נְקוּדִין, וְאִינּוּן תְּרֵיסַר נְקוּדִין עִלָּאִין. ג' ג' לְכָל סְטָר וּסְטָר, וּמֵהָכָא נַחְתִּין לְתַתָּא בִּתְרֵיסַר לְשִׁית סִטְרִין. וְכַד אִתְחָקְּקָן תְּרֵיסַר אִלֵּין בְּשִׁית סִטְרִין, אִינּוּן שִׁבְעִין וּתְרֵין שְׁמָהָן, רָזָא דִּשְׁמָא קַדִּישָׁא דְּשִׁבְעִין וּתְרֵין דְּאִינּוּן שְׁמָא דָּא קַדִּישָׁא.","וְכֹלָּא אִיהוּ סָלִיק בִּרְעוּתָא, דִּסְמִיכוּ דְּמַחֲשָׁבָה בְּאִינּוּן סַמְכִין דְּאָת יוֹ\"ד, וְעַל דָּא אַתְוָון בְּצִרוּפַיְּיהוּ, תְּלַת תְּלַת בְכָל צֵרוּפָא דִּילֵיהּ, בְּגִין לְסַלְּקָא בִּרְעוּתָא דְּאָת י', דִּתְלַת נְקוּדִין, כְּמָה דְּאִתְּמַר, וְעַל דָּא לָא אִסְתְּלִיק בִּסְלִיקוּ דְּצֵרוּפָא, אֶלָּא מֵעִקָרָא וְשָׁרְשָׁא דְּרָזָא דְּאִלֵּין סַמְכִין, דְּסַמְכִין לְאָת י' רָזָא דְּאָת ם' בְּרִבּוּעָא, ט' נְקוּדִין, תְּמַנְיָא נְקוּדִין, תְּרֵיסַר נְקוּדִין, שִׁבְעִין וּתְרֵין נְקוּדִין. אִשְׁתְּכַח, דְּכָל רָזָא דִּשְׁמָא קַדִּישָׁא, קַיְּימָא בְּאָת י', וְכֹלָּא רָזָא חֲדָא, וְקַיְּימָא בְּרָזָא דְּבוּצִינָא, כְּמָה דְּאִתְּמַר לְמֶעְבַּד סְמִיכוּ לְכָל אָת וְאָת. וְאִינּוּן סַמְכִין אִינּוּן רְתִיכָא דִּלְהוֹן, דְּכָל אָת וְאָת, כְּמָה דְּאִתְּמַר.","רָזָא תִּנְיָינָא, אָת ה', דְּקַיְּימָא עַל חֲמִשָּׁה סַמְכִין, דְּסַמְכִין לָהּ, דְּנָפְקִין מֵרָזָא דְּבוּצִינָא, כַּד אִתְכְּנַשׁ לְאִסְתַּלְּקָא לְעֵילָּא, מֵרָזָא (ר\"ד ע\"א) דְּמִשְׁחָתָא.","אָת דָּא הֵיכְלָא קַדִּישָׁא אִקְרֵי, לְגוֹ, נְקוּדָה דִּקְאַמְרָן. וְכֹלָּא אִיהוּ בְּרָזָא דִּקְאַמְרָן דְּאָת ם בְּרִבּוּעָא. אֲבָל הָכָא לָא אִתְרְשִׁים בַּר אָת ה', וּרְתִיכָא דִּילָהּ חֲמִשָּׁה סַמְכִין דִּקְאַמְרָן.","דְּכַד בָּטַשׁ נְהִירוּ דְּבוּצִינָא בְּאָת י', אִתְנְהִיר, וּמֵהַהוּא בְּטִישׁוּתָא, אִתְעָבִידוּ אִינּוּן תֵּשַׁע (פנחס רפ\"ג ע\"ב, תצא ר\"ח ע\"א) סַמְכִין דִּקְאַמְרָן. וּמִגּוֹ נְהִירוּ דְּאִתְנְהָר אָת י', אִתְפְּשָּׁטוּ תְּלַת נְקוּדִין דְּי'. תְּרֵין לְעֵילָּא, דְּאִינּוּן רֵישָׁא. וְחַד לְתַתָּא, דְּאִיהוּ קוֹצָא דְּי', כְּגַוְונָא דָּא דְּקַאֲמְרָן. כַּד אִתְפְּשָּׁטוּ, תְּרֵין, אִתְעָבִידוּ תְּלַת. חַד אִתְעָבִיד תְּרֵין. וְאִתְפָּשָׁטוּ, וְאִתְעָבִיד חַד הֵיכָלָא. דָּא הֵיכָלָא, לְבָתַר דְּאִתְעָבִיד הֵיכָלָא לְחַד נְקוּדָה קַדְמָאָה, אִתְעָבִיד בִּגְנִיזוּ טָמִיר רָזָא דְּאָת דָּא, וְקַיְּימָא עַל חָמֵשׁ אַחֲרָנִין."],[[0,"רזא קדמאה יוד","וכו': סוד הראשון הוא יוד דהוי\"ה שהיא נקודה הראשונה, דהיינו חכמה, העומדת על ט' עמודין הסומכים אותה. והם עומדים לד' רוחות העולם, דרום צפון מזרח מערב, שהם ג' קוין ומלכות, כמו שסוף המחשבה, הנקודה האחרונה, שהיא מלכות, עומדת לד' רוחות העולם שהם דרום צפון ומזרח מערב, שהם ג' קוין ומלכות המקבלתם, והן שוות זו לזו, חוץ אשר נקודה העליונה, שהיא \u0003י'\u0004 דהויה היא זכר, ונקודה אחרונה שהיא מלכות, היא נקבה."],[1,"והאי קיימא בלא","וכו': וזהו ה \u0003י'\u0004 שהיא חכמה, עומדת בלי גוף, דהיינו שאין לה כלי, כי אין יותר מג' כלים, בינה ת\"ת ומלכות, ולחכמה אין כלי, אלא שמתלבשת בפנימיות הבינה ות\"ת ומלכות. וכשהיא נמצאת בלבוש, שנתלבשה בהם, היא עומדת על ט' עמודים, שהם חב\"ד חג\"ת נה\"י בסוד אות \u0003ם'\u0004 בלי עגול. ואע\"פ שאות \u0003ס'\u0004 היא עגולה ועומדת בעגול, ה \u0003י'\u0004 ה\"ס \u0003ס'\u0004 ו \u0003ה'\u0004 ראשונה ה\"ס \u0003ם'\u0004 (כנ\"ל תרומה אות כ\"ב) אבל בסוד האותיות החקוקות בנקודות, דהיינו באותיות הרומזות בחינת החכמה המכונה נקודות, נבחן, שהאורות שלמעלה הן במרובע, ושלמטה הן בעגול."],[1,"","פירוש. שמתרץ, שהמדובר הוא כאן, מבחינת הארת החכמה, אשר בבחינת הג\"ר נחשבים המוחין בציור מרובע שהיא \u0003ם',\u0004 שהכונה על ד' בחינות חו\"ב חו\"ג, שבג' קוין חב\"ד העליונים דאו\"א עלאין, שהם נרמזים ביוד דהויה, שכל אחת כלולה מעשרה והם \u0003ם,\u0004 במרובע, ונחשבים ל \u0003ם'\u0004 סתומה על היותם בחסדים נעלמים. שקו האמצעי, שהוא דעת, אינו מגלה בהם החכמה, וע\"כ נחשב קו אמצעי לב' בחינות, חסד וגבורה. אבל לתתא, דהיינו בחב\"ד דישסוית שה\"ס \u0003הי\u0004 ראשונה דהויה, הם בעגול, כלומר שהם בחי' \u0003ל'\u0004 דצלם, שהיא עגול. כי קו האמצעי שבהם, להיותו מיחד את ב' הקוין ומגלה החכמה, נתיחדו החסד וגבורה שבקו אמצעי לבחינה אחת (כנ\"ל תרומה אות כ\"ז ע\"ש) והם רק ג' בחינות חכמה בינה דעת. שבכל אחת עשר ספירות, שהם \u0003ל.\u0004 שהיא עגולה. ומה שלעיל (תרומה אות כ\"ב) אומר ש \u0003ה'\u0004 ראשונה הוא \u0003ם'\u0004 סתומה. וה \u0003י'\u0004 היא \u0003ס',\u0004 המדובר הוא שם לענין מציאות הארת החסדים, שהם באו\"א עלאין בזווג דלא פסיק. שזה נוהג בחב\"ד חג\"ת דבינה, וע\"כ הם \u0003ס',\u0004 שש ספירות, שבכל אחת עשר. וישסו\"ת שהם \u0003ה'\u0004 ראשונה דהויה, הם ד' ספירות נהי\"מ דאו\"א, שה\"ס \u0003ם\u0004 סתומה שלהיותם חכמה בלי חסדים, היא נסתמת ואינה יכולה להאיר."],[2,"האי ברבועא איהי","וכו': רבוע הזה עומד בשיעור של שלש נקודות, שלש שלש לכל צד. והם בשיעור החשבון שמונה נקודות והם תשע נקודות. ומפרש, ואלו הם העומדים ויוצאים מסוד המאור, שהוא בינה דא\"א, וכתר ד \u0003י'\u0004 שהיא או\"א במרובע דהיינו \u0003ם'\u0004 בטי עמודים לאות ה \u0003י',\u0004 שהיא נקודה אחת מהם, דהיינו חב\"ד חג\"ת נה\"י, הם תשע. והם שמונה בסוד אות \u0003ם'\u0004 במרובע ג' ג' לכל צד, כשאין חושבים את ה \u0003י'\u0004 עצמה. דהיינו בינה דעת חג\"ת נה\"י."],[3,"ודא איהי רזא","וכו': ומפרש יותר, ואומר, וזה הוא הסוד. כי אות \u0003י'\u0004 היא נקודה אחת, ואע\"פ שהיא נקודה אחת, הרי הצורה שלה, ראש למעלה. שהוא קוץ העליון של ה \u0003י',\u0004 וקוץ למטה, ועצם הנקודה, וע\"כ השיעור שלה היא ג' נקודות כעין • • • בסוד ימין ושמאל ואמצע, שה\"ס ג' קוין, וע\"כ ההתפשטות לארבעה צדדים ג' ג' לכל צד, היא ט' עם ה \u0003י',\u0004 והיא ח' בלי ה \u0003י'\u0004 עצמה. כנ\"ל."],[3,"","פירוש. כי יש ב \u0003י',\u0004 ראש תוך סוף, שהם קוץ העליון וקוץ התחתון והנקודה עצמה, שהם ג' קוין שבה, כי ראש ותוך שלה הם ב' קוין ימין ושמאל, והסוף שלה, הוא קו האמצעי. והם כלולים זה מזה, ונמצא שיש בראש היוד ג' קוין, ובתוך ה \u0003י'\u0004 ג' קוין, ובסוף שלה ג' קוין, וג' קוין שבראש הם חב\"ד, וג' קוין שבתוך הם חג\"ת, וג' קוין שבסוף הם נה\"י. וכולם הם במרובע בסוד \u0003ם'\u0004 דצל\"ם, דהיינו שקו האמצעי, שבראש ושבתוך ושבסוף, מתחלק לב' בחינות, לחסד ולגבורה, דהיינו לז\"א ומלכות, באופן שבכל ג' קוין, יש ארבע רוחות, שב' קוין ימין ושמאל הם דרום צפון, וב' הבחינות שבקו האמצעי הם מזרח מערב, כי ז\"א ה\"ס מזרח והמלכות ה\"ס מערב. וז\"ש (להלן אות י\"ח) \u0003כד אתפשטו תרין אתעבידו תלת,\u0004 דהיינו כשנתפשטו ב' קוין ימין ושמאל, נעשו ג' קוין, ימין ושמאל ואמצע, \u0003חד אתעביד תרין,\u0004 והאחד, שהוא קו האמצעי, נעשה שנים, דהיינו ב' בחי', שהם ז\"א ומלכות, שהם מזרח מערב כנ\"ל."],[3,"","וזה אומרו כאן, \u0003ועל דא אתפשטותא לארבע סטרין, ג' ג' לכל סטר, איהי תשע ואיהי תמניא,\u0004 כי ג' הקוין מתפשטים לארבע רוחות דרום צפון מזרח מערב, בסוד \u0003ם',\u0004 ונמצא שיש ביוד ג' ממין \u0003ם'\u0004 בראש, שהם ג' קוין חב\"ד, \u0003ם'\u0004 בתוך, שהם ג' קוין חג\"ת, ו \u0003ם'\u0004 בסוף שהם ג' קוין נה\"י. וז\"ש \u0003ג' ג' לכל סטר,\u0004 דהיינו לג' סטרין שב \u0003י',\u0004 יש בכל אחת מהם ג' ג'. \u0003וסטר,\u0004 פירושו בחינה בהרבה מקומות בזוהר. \u0003ואיהי תשע,\u0004 היינו עם עצם בחינת ה \u0003י',\u0004 שהיא חכמה. \u0003ואיהי תמניא.\u0004 בלי ה \u0003י',\u0004 כנ\"ל."],[4,"ואלין אינון סמכין","וכו': ואלו, השמונה נקודות הן עמודים היוצאים מסוד המאור, שהוא בינה דא\"א וכתר דאו\"א, להיות סומכים לאות \u0003י',\u0004 כי ה \u0003י'\u0004 מתלבשת באלו ח' נקודות, שהן בינה דעת חג\"ת נה\"י, והן נקראות מרכבה שלה. ואינם נקראים בשם, רק בסוד ט' נקודות שבתורה. שהן, קמץ פתח צירי הן ג\"ר. סגול שבא חולם, חג\"ת. חירק קבוץ שורק, הנקראים ג\"כ חירק שורק מלאפוס, הן נה\"י. כי ספירות החכמה נקראות נקודות."],[5,"וברזא דספרא דאדם","וכו': ובסוד ספרו של אדם, נחלקו אלו ט' שהן ח', בצירופי האותיות של השם הקדוש. כי הבינה והדעת מאירים ל \u0003ה'\u0004 ראשונה דהויה. וחג\"ת נה\"י מאירים ל \u0003ו'\u0004 דהויה. ועטרת יסוד מאירה ל \u0003ה'\u0004 אחרונה דהויה. כדי לצרף אותם וליחדם בכל אלו האפנים, כי כשאלו הח' שהן ט' נוסעות, דהיינו שמאירים הארתן בדרך ג' קוין בזה אחר זה, (כמ\"ש לעיל בשלח ל\"ט ד\"ה וג' ע\"ש) הן מאירות בהארת אות \u0003ם'\u0004 במרובע, ומוציאים שמונה אורות הנראות כתשעה, ומתחלקים למטה, בין הספירות בינה ז\"א ומלכות כנ\"ל, עד כדי לשאת כל המשכן, שהיא מלכות. כי החכמה אשר ב \u0003י'\u0004 דהוי\"ה אינה מתגלית בכל הספירות אלא רק במלכות (כנ\"ל ב\"א רע\"ו ד\"ה ועוד כמה) וע\"כ צריכות הח' נקודות להתפשט עד המלכות, הנקראת משכן, ששם מתגלה החכמה."],[6,"ואינון צרופא דשמא","וכו': והן, הצירוף של השם הקדוש בסוד ע\"ב אותיות חקוקות, היוצאות מסוד ג' גוונין, ימין ושמאל ואמצע, שהם חג\"ת דז\"א, (כנ\"ל בשלח אות ק\"ס), והכל הוא מסוד ג' נקודות שהן השיעור של אות \u0003י',\u0004 דהיינו ראש תוך סוף שלה כנ\"ל, שהיא מאירה לארבע רוחות, דהיינו בסוד \u0003ם\u0004 דצלם (כנ\"ל אות י\"א) והן שמונה נקודות, זולת החכמה, והן ט' נקודות עם החכמה, כנ\"ל שכל אחת מג' נקודות דראש תוך סוף של ה \u0003י'\u0004 כלולה משלשתן, והן ט', שהן חב\"ד חג\"ת נה\"י. והן י\"ב נקודות עליונות. ג' ג' לכל צד וצד. כי להיותה מאירה ב \u0003ם,\u0004 שיש בה ד' רוחות דרום צפון מזרח מערב, שהוא משום שקו האמצעי נחלק לב', שהם ז\"א ומלכות כנ\"ל. וא\"כ יש לומר, שיש ד' אורות בראש של ה \u0003י',\u0004 שהוא חב\"ד, וד' אורות בתוך של ה \u0003י'\u0004 שהוא חג\"ת, וד' אורות בסוף של ה \u0003י'\u0004 שהוא נה\"י, כי הדעת והת\"ת והיסוד נחלקים כל אחד לב' אורות. ומכאן יורדים למטה בי\"ב לששה קצוות. וכשי\"ב אלו נחקקו בו' קצוות דז\"א, הם ע\"ב שמות, כי ו' פעמים י\"ב הם ע\"ב. שהם סוד השם הקדוש דע\"ב. שהם שם זה הקדוש היוצא מי\"ב נקודות ד \u0003י'\u0004 דהויה."],[7,"וכלא איהו סליק","וכו': והכל הוא עולה ברצון לסמוך את המחשבה, שהיא חכמה, באלו הסומכים של אות \u0003י'\u0004 כלומר, שכל אלו הצירופים של השם ע\"ב, הם כדי לגלות החכמה שב \u0003י'\u0004 דהויה, שנקראת מחשבה. ועל כן באים האותיות בצירופיהם בשם ע\"ב, ג' ג' אותיות בכל צירוף שבו, (כנ\"ל בשלח דף נ\"א בציור הג') כדי לעלות ברצון של אות ה \u0003י'\u0004 דהוי\"ה, שיש בה ג' נקודות, ראש תוך סוף. כמו שאמרנו, וע\"כ אינו עולה בעלית הצירוף אלא מעיקר ושורש של סוד אלו הסמכין, הסומכים לאות \u0003י',\u0004 בסוד אות \u0003ם\u0004 ברבוע כנ\"ל, שהם ג' נקודות רת\"ס, שהם עיקר ושורש כל הסמכין המשתלשלים ממנה, שהם, ט' נקודות, ח' נקודות, י\"ב נקודות, ע\"ב נקודות. נמצא שכל סוד השם הקדוש עומד באות \u0003י',\u0004 והכל סוד אחד, דהיינו סוד המשכת החכמה. ועומד בסוד המאור, שהיא בינה דא\"א שהיא כתר של \u0003י'\u0004 הזאת שהיא או\"א, כמו שאמרנו, לעשות סמיכה לכל אות ואות של השם הויה, (כנ\"ל אות י\"ג) ואלו הסומכים הט' והח' והי\"ב והע\"ב הנ\"ל, הם המרכבה של כל אות ואות של שם הויה. כמו שאמרנו."],[8,"רזא תנינא את","וכו': סוד השני הוא, אות \u0003ה'\u0004 של הוי\"ה, העומדת על חמשה עמודים הסומכים אותה, שהם יוצאים מסוד המאור, שהוא בינה דא\"א, אחר שנאסף ועלה למעלה מסוד המסך, פירו' כי ע\"י עלית המלכות למקום בינה דא\"א, נעשה שם מסך המסיים אל הראש דא\"א. ובינה ותו\"מ דא\"א, יצאו לבר מראש, למקום חג\"ת דא\"א, ששם עומדים או\"א וישסו\"ת דאצילות, (כנ\"ל בהקסה\"ז דף ט\"ו ד\"ה והענין) ואח\"כ לעת גדלות חוזרים בינה ותו\"מ אל הראש דא\"א, שעולים למעלה ממסך המסיים, ונעשו שוב בחינת ראש דא\"א, כנ\"ל (בהקסה\"ז דף ט\"ז ד\"ה ואגליף,) ואז הם מעלים עמהם גם או\"א וישסו\"ת, שה\"ס י\"ה דהויה, אל מקום הראש דא\"א ומאירים אליהם. (כנ\"ל בהקסה\"ז דף כ' ד\"ה ואמא) וז\"ש, שהבוצינא שהיא בינה דא\"א מאיר אל \u0003ה'\u0004 דהויה, \u0003כד אתכנש לאסתלקא לעילא מרזא דמשחתא,\u0004 דהיינו לאחר שחזרה למעלה ממסך המסיים את הראש דא\"א. כי אז הבוצינא מאירה אל ה \u0003ה'\u0004 דהויה. כמבואר."],[9,"את דא היכלא","וכו': אות זו נקראת היכל הקדש אל הנקודה שאמרנו, דהיינו ה \u0003י'\u0004 דהויה. שהכל הוא בסוד שאמרנו, באות \u0003ם'\u0004 במרובע. שפירושו, שאין הארת החכמה מתגלה שם, והיא בסוד דלא אתיידע. אבל כאן לא נרשם אות \u0003ם'\u0004 רק אות \u0003ה'\u0004 משום שכאן מתחיל הגילוי בסוד \u0003ל'\u0004 דצלם. והמרכבה שלה היא ה' עמודים שאמרנו."],[10,"דכד בטש נהירו","וכו': ומפרש מה הם החמשה סמכין. ואומר, כי כשהאיר אור הבוצינא באות \u0003י',\u0004 והוארה, שמאותו ההארה שהאיר הבוצינא, שהיא בינה דא\"א, נעשו אלו ט' עמודים שאמרנו, שה\"ס חב\"ד חג\"ת נה\"י שנתפשטו מן רת\"ס ד \u0003י',\u0004 כנ\"ל. ואז, מתוך ההארה שהוארה אות ה \u0003י'\u0004 נתפשטו ג' נקודות של ה \u0003י'\u0004 ב' נקודות למעלה שהם בראש ה \u0003י',\u0004 דהיינו קוץ העליון וגופו של יוד, ונקודה אחת למטה, שהיא קוץ התחתון של ה \u0003י',\u0004 כעין זה • • • כמו שאמרנו, (לעיל אות י\"א) שה\"ס ג' קוין ימין שמאל ואמצע. וכשנתפשטו שתי נקודות בסוד חולם ושורק, ונעשו ב' קוין, נתחבר אליהם קו האמצעי בסוד החירק, ונעשו ג', והאחד, שהוא קו האמצעי, נעשה ב', דהיינו שנחלק לחסד, שהוא ז\"א, ולגבורה שהיא הנוקבא, (כנ\"ל אות י\"א) ונתפשטו ד' נקודות אלו, ונעשו היכל אחד. היכל הזה, אחר שנעשה היכל לנקודה הראשונה, נעשה בהעלם ובמכוסה סוד אות הזו \u0003ה',\u0004 ועומדת על \u0003ה'\u0004 אחרות."],[10,"","ביאור הדברים. נודע, כי ה' קומות יצאו באצילות ממ\"ה החדש, קומת הכתר בפרצוף עתיק, וקומת חכמה בפרצוף א\"א, וקומת בינה נחלקה בין ב' פרצופין, שכו\"ח שלה נעשה פרצוף או\"א עלאין. ובינה ותו\"מ שלה, נעשו לפרצוף ישסו\"ת. וקומת תפארת יצאה בפרצוף ז\"א. וקומת המלכות יצאה בפרצוף הנוקבא דז\"א. והנך מוצא שקומת בינה לבדה נחלקה בין ב' פרצופין שבכל אחד עשר ספירות, והטעם מבואר (בהקסה\"ז דף י\"ג במראות הסולם ד\"ה ונודע ע\"ש). והם סוד \u0003י\"ה\u0004 דהויה, שאו\"א עלאין ה\"ס \u0003יוד,\u0004 וישסו\"ת ה\"ס \u0003ה.\u0004 ומלבד זה נחלקו גם או\"א עצמם שהם ה \u0003יוד\u0004 דהויה, לב' בחי', בעת יציאת נקודת החולם בכל המדרגות, דהיינו בעת עלית המלכות מכל מדרגה לבינה דכל מדרגה. (כנ\"ל ב\"א דף ד' ד\"ה ביאור) שאז נפלו בינה ותו\"מ של ה \u0003י'\u0004 למדרגה התחתונה שלה שהיא ה \u0003ה'\u0004 דהויה. ותדע שכל בינה ותו\"מ שנפלו ממדרגתם, כשהם חוזרים למדרגתם בעת נקודות השורק, אינם מתיחדים ממש למדרגה אחת עם הכתר וחכמה שנשארו במדרגה, אלא שנתקנו להיות קו שמאל, ובחינת נוקבא לכתר חכמה שנשארו במדרגה."],[10,"","ומכאן יצא, שיש ב' נוקבין לבחינת \u0003י'\u0004 דהויה. שה\"ס או\"א עלאין. א) היא הבינה ותו\"מ שנפלו מן ה \u0003י'\u0004 בעת הקטנות וירדו לישסו\"ת שהיא \u0003ה'\u0004 דהויה, שבינה ותו\"מ אלו ה\"ס \u0003ו' ד'\u0004 דמלוי היוד. נוקבא הב' היא, ישסו\"ת עצמם שהם בינה ותו\"מ דקומת בינה הכוללת שנתקנה למדרגה בפני עצמה, בסוד \u0003ה'\u0004 דהויה. אמנם בעת קטנות אינן נחשבות לנוקבין, כי אז שתיהן הן למטה ממדרגת או\"א שהם \u0003י'\u0004 דהויה, אלא בעת יציאת נקודת השורק, שבינה ותו\"מ דכל המדרגות חוזרות ועולות למדרגתם (כנ\"ל ב\"א דף ר\"צ ד\"ה בגין) ולוקחות עמהן גם מדרגה התחתונה שהיו בה בשעת נפילה (כנ\"ל בהקסה\"ז דף כ' ד\"ה ואמא) נמצא שבינה ותו\"מ של ה \u0003י'\u0004 חזרו ועלו ל \u0003י'\u0004 ונעשו לה לנוקבא. בסוד \u0003ו ד\u0004 דמילוי \u0003יוד.\u0004 ובינה ותו\"מ אלו העלו עמהן גם \u0003ה'\u0004 דהויה, אל ה \u0003י'\u0004 מחמת שהיו מלובשות בהן בשעת הנפילה, ונתקנה גם \u0003ה'\u0004 דהויה להיות לנוקבא אל ה \u0003י'\u0004 דהיינו לקו שמאל שלה. הרי שיש לה אל ה \u0003י'\u0004 ב' נוקבין. א) ה \u0003ו\"ד\u0004 דמלוי \u0003י',\u0004 והיא נחשבת לחגית אל ה \u0003י'.\u0004 ב) היא \u0003ה'\u0004 דהויה והיא נחשבת לנה\"י אל ה \u0003י'.\u0004"],[10,"","וזה אמרו, (באות ט\"ז), \u0003דנפקין מרזא דבוצינא,\u0004 כי כל מדרגה מקבלת הארתה מבחינה שכנגדה בעליון וכיון ש \u0003י\"ה\u0004 דהויה הם שניהם קומת בינה, ע\"כ הם מקבלים מא\"א שהוא קומת חכמה, אבל רק מבחינה שכנגדה, שהיא בינה שבא\"א, והיא הנקראת בוצינא. \u0003כד אתכנש לאסתלקא לעילא מרזא דמשחתא,\u0004 כי מטרם שהבינה דא\"א חזרה ועלתה לראש א\"א, היו כל המדרגות בבחינת קטנות כנ\"ל, ובינה ותו\"מ ד \u0003י'\u0004 שה\"ס \u0003ו\"ד\u0004 דמילוי \u0003יוד.\u0004 ובינה ותו\"מ דקומת בינה שה\"ס \u0003ה'\u0004 דהויה, שתיהן עוד לא היו במדרגות ה \u0003י'\u0004 שיהיו נחשבות לב' נוקבין ד \u0003י',\u0004 אלא שהיו בנפילה מחוץ למדרגת ה \u0003י'.\u0004 אלא אחר שבינה דא\"א חזרה ועלתה לראש דא\"א למעלה מן המסך אז גם בינה ותו\"מ ד \u0003י'\u0004 עלתה למדרגת ה \u0003י'\u0004 ונעשה לבחינת נוקבא שלה שה\"ס \u0003ה'\u0004 בצורת ו\"ד דמילוי יוד."],[10,"","וז\"ש, \u0003דכד בטש נהירו דבוצינא באות י'\u0004 וכו' \u0003אתעבידו אינון תשע סמכין דקאמרן,\u0004 כי ה \u0003י'\u0004 קבלה מן הבוצינא, כל ג' בחינות חולם שורק חירק, שה\"ס ג' קוין, שהם בחינת ראש תוך וסוף של ה \u0003י',\u0004 וכל אחד מהם כלול משלשתם, וע\"כ יש ג' קוין בראש שהם חב\"ד, וג' קוין בתוך שהם חג\"ת, וג' קוין בסוף, שהם נה\"י. אבל ה \u0003ה'\u0004 שה\"ס בינה ותו\"מ ד \u0003י'\u0004 שנפלו ממנה בעת הארת נקודת החולם, דהיינו בקטנות כנ\"ל, הנה היא לא התחילה להאיר להיות בחינת נוקבא אל ה \u0003י'\u0004 ולקבל ממנה, רק אחר \u0003שהבוצינא אתכנש לאסתלקא לעילא מרזא דמשחתא\u0004 כנ\"ל שאז היא הארת השורק, שהיא רק בחינת התוך של ה \u0003י',\u0004 וחג\"ת שלה. ע\"כ אינה מקבלת רק הארת ג' הקוין מחג\"ת ד \u0003י'.\u0004 וזה אמרו \u0003ומגו נהירו דאתנהר את י',\u0004 דהיינו מחלק של הארת ה \u0003י', אתפשטו ג' נקודין\u0004 ד \u0003י'\u0004 וכו' דהיינו בחלק של הארת התוך ד \u0003י'\u0004 שנחלק על ג' קוין, שהם ד' כי \u0003תרין, אתעבידו תלת, וחד אתעביד תרין,\u0004 כמ\"ש לעיל, אז, \u0003ואתעביד חד היכלא,\u0004 שנתקנה להיות היכל אל ה \u0003י',\u0004 שנתקנה להיות נוקבא אל ה \u0003י'.\u0004 כי הנוקבא נקראת \u0003היכל.\u0004 אבל מבחינת ג' קוין דראש ה \u0003י'\u0004 אינה מקבלת, כי הארתה מתחלת מן התוך ד \u0003י'\u0004 כמבואר."],[10,"","וזה אמרו. \u0003דא היכלא, לבתר דאתעביד היכלא לחד נקודה קדמאה,\u0004 דהיינו אחר שקיבלה מן הארת השורק, ועלתה ממקום נפילתה ונעשתה נוקבא לנקודה קדמאה שהיא \u0003י', אתעביד בגניזו טמיר רזא דאת דא,\u0004 שבגניזו ובסתר נעשית אות \u0003ה'\u0004 זו, שה\"ס \u0003ו\"ד\u0004 דמילוי \u0003י',\u0004 שנעשתה נוקבא אליה, דהיינו שהיא גונזת ומעלמת החכמה ונתתקנת בבחינת לא אתידע שה\"ס אמא עלאה. \u0003וקיימא על חמש אחרנין,\u0004 שהיא עומדת על \u0003ה'\u0004 אחרת, שה\"ס \u0003ה'\u0004 דהויה, שה\"ס בינה ותו\"מ דבינה הכוללת דאצילות, הנקראת ישסו\"ת, שבה מתחיל להתגלות הארת החכמה. והיא מלבשת על הסוף של ה \u0003י',\u0004 דהיינו על נה\"י שלה. באפן, שה \u0003י'\u0004 יש לה כל ראש תוך וסוף שבכל אחד ג' מדרגות, ו \u0003ד\"ו\u0004 דמילוי יוד, שהיא בינה ותו\"מ ד \u0003י'\u0004 עצמה, נעשתה \u0003ה'\u0004 ומלבשת על חג\"ת דיוד, ושנים אלו נקראים אבא ואמא עלאין. ו \u0003ה'\u0004 דהויה, שה\"ס ישסו\"ת, מלבשת על נה\"י של ה \u0003י'.\u0004 וע\"כ בב' ההין אלו, אין בכל אחת רק ארבע נקודות ולא כל הט' כמו ה \u0003י',\u0004 כי לכל אחת יש לה רק בחינה אחת מן ה \u0003י',\u0004 לזו תוך, ולזו סוף."]],[[0,"","סוֹד הָרִאשׁוֹן - יוֹ\"ד, נְקֻדָּה רִאשׁוֹנָה שֶׁעוֹמֶדֶת עַל תִּשְׁעָה עַמּוּדִים הַמַּעֲמִידִים אוֹתָהּ. וְהֵם עוֹמְדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, כְּמוֹ שֶׁהַסּוֹף שֶׁל הַמַּחֲשָׁבָה, נְקֻדָּה אַחֲרוֹנָה, עוֹמֶדֶת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. חוּץ מִזֶּה שֶׁזֶּה זָכָר, וְזוֹהִי נְקֵבָה."],[1,"","וְזוֹ עוֹמֶדֶת בְּלִי גוּף, וְכַאֲשֶׁר עוֹמֶדֶת בַּלְּבוּשִׁים שֶׁמִּתְלַבֶּשֶׁת בָּהֶם, הִיא עוֹמֶדֶת עַל תִּשְׁעָה עַמּוּדִים, בַּסּוֹד שֶׁל הָאוֹת ם בְּלִי עִגּוּל. וְאַף עַל גַּב שֶׁאוֹת ס' הִיא בְעִגּוּל וְעוֹמֶדֶת בְּעִגּוּל, אֲבָל בְּסוֹד שֶׁל אוֹתִיּוֹת הַחֲקוּקוֹת תּוֹךְ נְקֻדּוֹת שֶׁל אוֹרוֹת שֶׁל מַעְלָה, הֵם בְּרִבּוּעַ, וְשֶׁל מַטָּה הוּא בְעִגּוּל."],[2,"","זֶה הָרִבּוּעַ הוּא עוֹמֵד בְּשִׁעוּר שֶׁל תֵּשַׁע נְקֻדּוֹת, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד. וְהֵם בְּשִׁעוּר שֶׁל חֶשְׁבּוֹן שְׁמֹנֶה נְקֻדּוֹת, וְהֵם תֵּשַׁע. וְאֵלּוּ הֵם שֶׁעוֹמְדִים מִסּוֹד שֶׁל הַנֵּר בְּרִבּוּעַ בְּתִשְׁעָה עַמּוּדִים לָאוֹת יוֹ\"ד, נְקֻדָּה אַחַת. וְאֵלּוּ הַתִּשְׁעָה הֵם שְׁמוֹנָה בְּסוֹד שֶׁל אוֹת ם בְּרִבּוּעַ, כְּמוֹ זֶה: שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד,"],[3,"","וְזֶהוּ סוֹד הָאוֹת יוֹ\"ד, נְקֻדָּה אַחַת. וְאַף אַף גַּב שֶׁהִיא נְקֻדָּה אַחַת, הַצּוּרָה שֶׁלָּהּ - רֹאשׁ לְמַעְלָה, וְקוֹץ לְמַטָּה. וְהַשִּׁעוּר שֶׁלָּהּ שָׁלֹשׁ נְקֻדּוֹת כְּדֻגְמָא זוֹ: וְעַל כֵּן הִתְפַּשְּׁטוּתָהּ לְאַרְבָּעָה צְדָדִים, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד, הִיא תֵּשַׁע וְהִיא שְׁמוֹנֶה."],[4,"","וְאֵלּוּ הֵם הָעַמוּדִים שֶׁיּוֹצְאִים מִסּוֹד הַנֵּר לִהְיוֹת עַמּוּדִים לָאוֹת יוֹ\"ד, וְאֵלּוּ נִקְרָאִים מֶרְכָּבָה שֶׁלָּהּ. וְלֹא עוֹמְדִים בַּשֵּׁם, רַק בְּסוֹד תֵּשַׁע נְקֻדּוֹת שֶׁל הַתּוֹרָה."],[5,"","וּבַסּוֹד שֶׁל סִפְרוֹ שֶׁל אָדָם נֶחְלְקוּ אֵלּוּ הַתֵּשַׁע שֶׁהֵן שְׁמוֹנֶה, בְּצֵרוּף הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, כְּדֵי לְצָרֵף אוֹתָן וּלְיַחֵד אוֹתָן בְּכָל אֵלּוּ הַצּוּרוֹת כַּאֲשֶׁר נוֹסְעוֹת אֵלּוּ הַשְּׁמוֹנֶה שֶׁהֵן תֵּשַׁע, מְאִירוֹת בָּאוֹר שֶׁל אוֹת ם סְתוּמָה בְּרִבּוּעַ, וּמוֹצִיא אוֹרוֹת שְׁמוֹנָה (שמונהנראים) נִרְאִים וְאוֹתִיּוֹת תֵּשַׁע. וּמִתְחַלְּקוֹת לְמַטָּה לְהַנְהִיג אֶת כָּל הַמִּשְׁכָּן."],[6,"","וְאֵלּוּ הֵם צֵרוּף שֶׁל הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד שֶׁל שִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת מְחֻקָּקוֹת שֶׁיּוֹצְאוֹת מִסּוֹד שֶׁל שָׁלֹשׁ צוּרוֹת, יָמִין וּשְׂמֹאל וְאֶמְצַע, וְהַכֹּל מִסּוֹד שֶׁל שָׁלֹשׁ נְקֻדּוֹת (ציור למעלה). שִׁעוּר שֶׁל אוֹת יוֹ\"ד, שֶׁהִיא לְאַרְבַּע צְדָדִים, וְהֵן שְׁמוֹנֶה נְקֻדּוֹת, וְהֵם תֵּשַׁע נְקֻדּוֹת, וְהֵם שְׁתֵּים עֶשְׂרֵה נְקֻדּוֹת עֶלְיוֹנוֹת, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד וְצַד, וּמִכָּאן יוֹרְדוֹת לְמַטָּה בִּשְׁתֵּים עֶשְׂרֵה לְשִׁשָּׁה קְצָווֹת. וְכַאֲשֶׁר נֶחְקָקוֹת שְׁתֵּים עֶשְׂרֵה אֵלּוּ בְּשֵׁשׁ קְצָווֹת, הֵם שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁל שִׁבְעִים וּשְׁנַיִם שֵׁהֵם הַשֵּׁם הַזֶּה הַקָּדוֹשׁ."],[7,"","וְהַסֹלֹ הוּא עוֹלֶה בְרָצוֹן, שֶׁסָּמַךְ הַמַּחֲשָׁבָה בְּאֵלּוּ שֶׁסּוֹמְכִים אֶת הָאוֹת יוֹ\"ד, וְעַל זֶה הָאוֹתִיּוֹת בְּצֵרוּפֵיהֶן - שָׁלֹשׁ שָׁלֹשׁ בְּכָל צֵרוּף שֶׁלּוֹ, בִּשְׁבִיל לַעֲלוֹת בְּרָצוֹן שֶׁל הָאוֹת י' שֶׁל שָׁלֹשׁ נְקֻדּוֹת, כְּמוֹ שֶׁאָמַרְנוּ, וְעַל זֶה לֹא עוֹלֶה בַּעֲלִיַּת הַצֵּרוּף אֶלָּא מֵעִקָּר וְשֹׁרֶשׁ שֶׁל סוֹד שֶׁל אֵלּוּ הַסּוֹמְכִים שֶׁסּוֹמְכִים לָאוֹת י', סוֹד שֶׁל אוֹת ם בְּרִבּוּעַ, תֵּשַׁע נְקֻדּוֹת, שְׁמוֹנֶה נְקֻדּוֹת, י\"ב נְקֻדּוֹת, שִׁבְעִים וּשְׁתַּיִם נְקֻדּוֹת. נִמְצָא שֶׁכָּל סוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ נִמְצָא בָּאוֹת י', וְהַכֹּל סוֹד אֶחָד וְעוֹמֵד בְּסוֹד הַנֵּר, כְּמוֹ שֶׁאָמַרְנוּ, לַעֲשׂוֹת סֶמֶךְ לְכָל אוֹת וָאוֹת. וְאֵלּוּ הָעַמּוּדִים הֵם מֶרְכָּבָה שֶׁלָּהֶם, שֶׁל כָּל אוֹת וָאוֹת, כְּמוֹ שֶׁאָמַרְנוּ."],[8,"","הַסּוֹד הַשֵּׁנִי - אוֹת חֲמִישִׁית שֶׁעוֹמֶדֶת עַל חֲמִשָּׁה עַמּוּדִים שֶׁסּוֹמְכִים אוֹתָהּ, שֶׁיּוֹצְאִים מִסּוֹד הַנֵּר, כַּאֲשֶׁר נֶאֱסָף לַעֲלוֹת לְמַעְלָה מִסּוֹד הַמִּדָּה."],[9,"","אוֹת זוֹ נִקְרֵאת הֵיכָל הַקָּדוֹשׁ, וּבְתוֹכָהּ הַנְּקֻדָּה שֶׁאָמַרְנוּ. וְהַכֹּל הוּא בַּסּוֹד שֶׁאָמַרְנוּ שֶׁל אוֹת ם בְּרִבּוּעַ. אֲבָל כָּאן לֹא נִרְשֶׁמֶת, רַק אוֹת ה', וְהַמֶּרְכָּבָה שֶׁלָּהּ חֲמִשָּׁה עַמּוּדִים שֶׁאָמַרְנוּ."],[10,"","וְכַאֲשֶׁר מַכֶּה אוֹר הַנֵּר בָּאוֹת י', מְאִירָה, וּמֵהַהַכָּאָה הַהִיא נַעֲשׂוּ אוֹתָם תִּשְׁעָה עַמּוּדִים שֶׁאָמַרְנוּ. וּמִתּוֹךְ הָאוֹר שֶׁמֵּאִיר אוֹת י', נִתְפַּשְּׁטוּ הַשָּׁלֹשׁ נְקֻדּוֹת שֶׁל י'. שְׁתַּיִם לְמַעְלָה, שֶׁהֵן הָרֹאשׁ, וְאֶחָד לְמַטָּה, שֶׁהוּא קוֹץ הַי', כְּמוֹ זֶה שֶׁאָמַרְנוּ. כַּאֲשֶׁר הִתְפַּשְּׁטוּ שְׁתַּיִם, נַעֲשׂוּ שָׁלֹשׁ. אַחַת נֶעֶשְׂתָה שְׁתַּיִם. וְנִתְפַּשְּׁטוּ וְנַעֲשֶׂה הֵיכָל אֶחָד. זֶה הַהֵיכָל, לְאַחַר שֶׁנַּעֲשָׂה הֵיכָל לִנְקֻדָּה אַחַת רִאשׁוֹנָה, נַעֲשָׂה גָנוּז וּמֻסְתָּר סוֹד שֶׁל אוֹת זוֹ, וְעוֹמֶדֶת עַל חָמֵשׁ אֲחֵרוֹת."]]],[["אַרְבְּעָה גְּנִיזִין אִינּוּן, בְּחַד נְקוּדָה דְּקַיְּימָא לְגוֹ בְּאֶמְצָעִיתָא, אִינּוּן חָמֵשׁ. וְאִיהִי ה'. כְּמָה דְּהֵ\"א דִּלְתַתָּא, קַיְּימָא עַל אַרְבַּע, וְאִיהִי נְקוּדָה עַל אַרְבַּע, דְּקַיְּימָא בְּגוֹ אֶמְצָעִיתָא. אוּף הָכָא נָמֵי הַאי. וּמַה דְּקַיְּימָא עַל ה' סַמְכִין, הָכִי הוּא וַדַאי, בְּגִין דְּהַאי נְקוּדָה עִלָּאָה, אִיהִי עַל תְּרֵין גַּוְונִין, חַד בִּלְחוֹדוֹי, וְחַד בִּטְמִירוּ.","וּבְסִפְרָא דְּרָזִין דְּחֲנוֹךְ, ה' וַדַאי קַיְּימָא עַל חָמֵשׁ סַמְכִין דְּנָפְקִין מִגּוֹ בּוּצִינָא. וּכְדֵין אַפִּיק חֲמֵשׁ קַיְימִין אַחֲרָנִין, וְאִשְׁתְּכַח הַאי ה' בְּרָזָא דַּעֲשָׂרָה. וְכַד אִתְפַּרְשַׁת, קַיְּימָא ה' דָּא, עַל סַמְכִין, וְאִינּוּן הֲווֹ תְּלֵיסַר מְכִילָן דְּרַחֲמֵי, בְּחַד דַּרְגָּא דְּאִתּוֹסָף עָלַיְיהוּ.","וְאִלֵּין אִינּוּן (ק\"פ) תְּרֵיסַר דְּקַיְימִין בְּשִׁית. זִמְנִין אִינּוּן אַרְבְּעִין וּתְרֵין. זִמְנִין שִׁבְעִין וּתְרֵין הֲווֹ, אֲבָל (קל\"ב) נַחְתִּין לְתַתָּא. וְהָכָא אִתְפְּרָשׁוּ שְׁבִילִין לְכָל סְטַר, דְּאִינּוּן תְּלָתִין וּתְרֵין, אִשְׁתְּאַר אַרְבְּעִין. וּתְרֵין אוּדְנִין יְמִינָא וּשְׂמָאלָא, הָא אַרְבְּעִין וּתְרֵין, אִלֵּין מ\"ב אַתְוָון עִלָּאִין, דְּאִינּוּן אַתְוָון רַבְרְבָן דְּאוֹרַיְיתָא.","בְּגִין (הקדמה ג' ע\"ב) דְּאִית אַתְוָון רַבְרְבָן, וְאִית אַתְוָון זְעִירִין. אַתְוָון רַבְרְבִין אִינּוּן לְעֵילָּא, אַתְוָון זְעִירִין לְתַתָּא. וְכֹלָּא לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא. בְּגִין דְּאִית שְׁמָהָן קַדִּישִׁין עִלָּאִין, דְּקַיְימִין בִּרְעוּ דְּרוּחָא וְלִבָּא בְּלָא מִלּוּלָא כְּלַל.","וְאִית שְׁמָהָן קַדִּישִׁין תַּתָּאִין, דְּקַיְימִין בְּמִלָּה, וּבִמְשִׁיכוּ דְּמַחֲשָׁבָה וּרְעוּ עָלַיְיהוּ. וְאִית שְׁמָהָן אַחֲרָנִין לְתַתָּא, דְּאִינּוּן מֵהַהוּא סִטְרָא אַחֲרָא, דְּאִיהוּ מִסִּטְרָא דִּמְסָאֲבָא, וְאִלֵּין לָא קַיְימִין, אֶלָּא בִּרְעוּ דְּעוֹבָדָא לְתַתָּא, לְסַלְּקָא רְעוּ דְּהַהוּא עוֹבָדָא דִּלְתַתָּא לְגַבֵּיהּ. בְּגִין דְּאִיהוּ סִטְרָא אַחֲרָא לָאו אִיהוּ, אֶלָּא בְּעוֹבָדִין דְּהַאי עָלְמָא, לְאִסְתַּאֲבָא בְּהוֹן. כְּגַוְונָא דְּבִלְעָם, וְאִינּוּן בְּנֵי קֶדֶם, וְכָל אִינּוּן דְּמִתְעַסְּקֵי בְּהַהוּא סִטְרָא אַחֲרָא.","וְאִלֵּין, לָא קַיְימֵי בְּאַתְוָון רְשִׁימִין מִן כ\"ב דְּאוֹרַיְיתָא, בַּר תְּרֵין, וְאִלֵּין ח' וק', וְסַמְכִין לוֹן בִּסְמִיכוּ (בראשית ב' ע\"א) אַתְוָון דְּשֶׁקֶר. אֲבָל אִלֵּין אִינּוּן אִשְׁתְּמוֹדְעָאן לְגַבַּיְיהוּ יַתִּיר. וְעַל דָּא בִּתְּהִלָּה לְדָוִד, בְּכֻלְּהוּ כְּתִיב ו' בְּכָל אָת וְאָת, בַּר מֵאִלֵּין תְּרֵין, דְּלָא כְּתִיב ו', דְּהָא ו' שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ.","וּבְּגִין כָּךְ אִינּוּן אַרְבְּעִין וּתְרֵין אַתְוָון, דְּעָלְמָא דָּא אִתְבְּרֵי בְּהוּ, אִשְׁתְּכַח הַאי ה' עִלָּאָה, לְסַלְּקָא לְתִשְׁעִין וּתְרֵין, תִּשְׁעִין הֲווֹ, בַּר תְּרֵין אוּדְנִין יְמִינָא וּשְׂמָאלָא. וְרָזָא דָּא (ס\"א וסימניך) (בראשית י״ז:י״ז) וְאִם שָׂרָה הֲבַת תִּשְׁעִים שָׁנָה תֵּלֵד. אֲבָל אִיהוּ בְּחֻשְׁבָּנָא תִּשְׁעִין וּתְרֵין, וְכַד אִתּוֹסָף דַּרְגָּא דְּרָזָא דִּבְרִית, דְּאִיהוּ רְקִיעָא תְּמִינָאָה, וְקַיְּימָא לִתְמַנְיָא יוֹמִין, הָא מֵאָה. וְאִלֵּין וַדַּאי מֵאָה בִּרְכָאן בְּכָל יוֹמָא דְּאִצְטְרִיכָא כְּנֶסֶת יִשְׂרָאֵל לְאִתְעַטְרָא בְּהוּ. וְכֹלָּא בְּרָזָא דְּה'.","הַאי ה', אִיהִי דִּיּוּקְנָא דִּילָהּ בִּתְרֵין נוּנִין, רָזָא דְּמֵאָה, וְאִינּוּן חָמֵשׁ סַמְכִין רְתִיכִין, דְּנַפְקֵי מִגּוֹ בּוּצִינָא, וְאִינּוּן חָמֵשׁ אַחֲרָנִין דְּנַפְקִין מִינָּהּ. וְעַל דָּא דְּיוּקְנָהָא כְּגַוְונָא דָּא ן ן, תְּרֵין נוּנִין, וּנְקוּדָה דְּקַיְימָא בְּאֶמְצָעִיתָא. וְעַל דָּא ו' קַיְּימָא בֵּינַיְיהוּ תָּדִיר, כְּגַוְונָא דָּא (רל\"ה ע\"ב) נוּן, בְּגִין דְּהָכָא אִיהוּ אַתְרֵיהּ לְאִתְעַטְרָא, וְאַף עַל גַּב דְּרָזִין אַחֲרָנִין אִינּוּן בְּרָזָא דְּה', אֲבָל דָּא אִיהוּ בְּרָזִין דְּסִפְרָא דְּחֲנוֹךְ, וְהָכִי הוּא וַדַּאי.","וְכַד אִתְתַּקְנָא בְּאִינּוּן חַמְשִׁין בִּלְחוֹדַיְיהוּ, אִיהוּ נְקוּדָה חֲדָא דְּקַיְּימָא בְּרָזָא דְּנ', כְּגַוְונָא דָּא (ה') נ', נוּ\"ן. וְחַד נְקוּדָה בְּאֶמְצָעִיתָא דְּאִיהִי שַׁלְטָא עָלַיְיהוּ, וְכֹלָּא רָזָא חֲדָא. זַכָּאִין אִינּוּן דְּיַדְעֵי אָרְחוֹי דְּאוֹרַיְיתָא, לְמֵהַךְ בְּאָרְחֵי קְשׁוֹט. זַכָּאִין אִינּוּן בְּהַאי עָלְמָא, וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי.","רָזָא תְּלִיתָאָה אָת ו', הַאי אָת דִּיּוּקְנָא דְּרָזָא דְּאָדָם, כְּמָה דְּאִתְּמַר. וְהָא אוּקִימְנָא, דְּהַאי אָת, קַיְּימָא עַל י\"ב רְתִיכִין. וְכַד מִתְפָּרְשָׁאן, אִינּוּן כ\"ד רְתִיכִין, דִּכְלִילָן בְּהַאי אָת פְּשִׁיטוּ דִּיּוּקְנָא דְּבַר נָשׁ, לָקֳבֵל דְּרוֹעִין וְיַרְכִין וְגוּפָא שַׁיְיפִין דִּלְהוֹן כ\"ד אִינּוּן דִּדְּרוֹעִין, וְיַרְכִין, וְגוּפָא, הָא אִתְּמַר, אֲבָל כֻּלְּהוּ סְתִימִין בְּגוּפָא, וְגוּפָא קַיְּימָא בְּכֻלְּהוּ כ\"ד, וְכֻלְּהוּ רְתִיכִין כְּלִילָן בֵּיהּ בְּגוּפָא, וּבְגִין דִּכְלִילָן כֻּלְּהוּ בֵּיהּ, קַיְּימָא, ו' פְּשִׁיטוּ חַד."],[[0,"ארבעה גניזין אינון","וכו': ארבע נקודות גנוזות הן, שהן ב' קוין ימין ושמאל, וימין ושמאל שבקו אמצעי, שהן גנוזות כנ\"ל, ועם נקודה אחת העומדת בתוכם באמצע, שה\"ס היסוד שבה, ששביל דאבא בנתיב דאמא. (כנ\"ל משפטים אות תקכ\"ח,) הן חמש, והיא \u0003ה',\u0004 דהיינו הנוקבא ד \u0003י'\u0004 הנק' אמא עלאה. כמו ש \u0003ה'\u0004 שלמטה, דהיינו המלכות, עומדת על ארבע, דהיינו על ג' קוין, והמלכות המקבלתם, והיא נקודה על ארבע, כלומר שעצם המלכות, שהיא נקודה, עומדת באמצעם, כי המלכות המקבלת מג' קוין הנחשבת בתוך הארבע, היא בחינת עטרת יסוד, הנקראת מפתחא ולא מלכות ממש, (כנ\"ל בהקדסה\"ז דף מ\"ה ד\"ה ההיא) אף כאן גם כן זה, שיש ד' נקודות גנוזות ובחינת נתיב באמצען. ומה שהיא עומדת על חמשה סמכין אחרים, דהיינו על \u0003ה'\u0004 דהויה, שהיא ישסו\"ת כנ\"ל בדבר הסמוך, הוא כך ודאי, משום שנקודה זו העליונה, שהיא ה \u0003י'\u0004 דהויה, היא על ב' בחינות, אחת, כשהיא בפני עצמה, ואינה מלובשת בישסו\"ת, שאז ה \u0003ו\"ד\u0004 דמילוי \u0003י'\u0004 נעשתה לנוקבא שלה בפני עצמה, שה\"ס ה' בחמש גניזין הנ\"ל. ואחת במכוסה, כלומר שהיא מלובשת בישסו\"ת, ואז נחשב ישסו\"ת לנוקבא של ה \u0003י'\u0004 וה \u0003ו\"ד\u0004 נכללת אז ב \u0003י'\u0004 בבחינת דכר. וע\"כ יש ב' ההין."],[1,"ובספרא דרזין דחנוך","וכו': ובספר הסודות של חנוך, אומר, \u0003ה'\u0004 ודאי שעומדת על ה' סמכין היוצאים מן הבוצינא, שהוא בינה דא\"א, והיינו הו\"ד דמילוי יוד, שה\"ס אמא עלאה, ואז מוציאה \u0003ה'\u0004 זו חמש עמודים אחרים, שהיא \u0003ה'\u0004 ראשונה דהויה, הנקרא ישסו\"ת, ונמצא \u0003ה\u0004 זו בסוד עשר, דהיינו חמש סמכין שלה וחמש סמכין של \u0003ה'\u0004 דהויה, שהם יחד במקום ה \u0003י'\u0004 (כנ\"ל אות י\"ח בהסולם ד\"ה ביאור) וכשנפרדה \u0003ה'\u0004 דהויה מן \u0003ה'\u0004 דו\"ד שבמילוי ה \u0003י',\u0004 ובאה למקומה, עומדת \u0003ה'\u0004 זו על חמשה סמכין, שד' סמכין הם ג' קוין ומלכות המקבלתם, והחמשית ה\"ס נקודה באמצעם, והד' סמכין כלולים זה בזה באופן שיש ג' קוין בכל אחד מהד' סמכין, שהם י\"ב, והם י\"ג מדות הרחמים עם מדרגה אחת הנוספת עליהם. דהיינו עם הנקודה שבאמצע הד' סמכין. והם מקבלים מי\"ג מדות הרחמים שבדיקנא דא\"א."],[2,"ואלין אינון תריסר","וכו': ואלו הם י\"ב העמודים בששה קצוות. כי ישסו\"ת הם ו\"ק דאו\"א, ואלו י\"ב הנ\"ל מאירים בכל קצה שבהם, והם במספר השם ע\"ב, כי ו\"פ י\"ב הוא ע\"ב. ופעם נחשבים להשם מ\"ב, היינו בישסו\"ת עצמם, ופעם לע\"ב, אבל זה הוא כשיורדים למטה לו\"ק דז\"א שרק שם מאיר השם ע\"ב. וכאן בישסו\"ת, מתפשטים מהע\"ב שבילים לכל צד, דהיינו ל\"ב שבילי החכמה, וכשתגרע ל\"ב מע\"ב נשאר ארבעים, ועם ב' אזנים ימין ושמאל, אשר אזנים הם בינה, שהימין הוא ישראל סבא והשמאל הוא תבונה, שהם שורשי האורות, הם ארבעים ושנים, שה\"ס השם מ\"ב. אלו הם מ\"ב אותיות עליונות, שהם אותיות הגדולות שבתורה."],[3,"בגין דאית אתוון רברבן","וכו': כי יש אותיות גדולות. ויש אותיות קטנות, אותיות גדולות הן למעלה, בבינה, ואותיות קטנות למטה במלכות. והכל הוא למטה, במלכות, כעין של מעלה, בבינה. כי יש שמות קדושים עליונים, שבבינה, הנמשכים רק ברצון הרוח והלב בלי דבור כלל. ויש שמות קדושים תחתונים, שבמלכות, הנמשכים בדבור, ובהמשכת המחשבה והרצון עליהם."],[4,"ואית שמהן אחרנין","וכו': ויש שמות אחרים למטה, שהם מסטרא אחרא ההוא, שהוא בצד הטומאה, ואלו אינם נמשכים אלא ברצון של מעשה למטה, להעלות להם הרצון שבמעשה למטה. משום שהסטרא אחרא אינו מתעורר אלא במעשים של עולם הזה להטמאות בהם. כמו בלעם ובני קדם וכל אלו העוסקים בצד אחר ההוא, שהם עוררו אותו ע\"י שעשו מעשים למטה לעוררו."],[5,"ואלין לא קיימי","וכו': ואלו שמסטרא אחרא, אינם עומדים באותיות הרשומות של כ\"ב אותיות התורה חוץ משתים, ואלו הן \u0003ח'\u0004 ו \u0003ק'\u0004 שקליפת היסוד נקרא \u0003ח'\u0004 שה\"ס בני חת שנשאו ונתנו עם אברהם במערת המכפלה. וקליפת המלכות נקרא \u0003ק'\u0004 (כנ\"ל תרומה אות תע\"ה) וסומכים להם לס\"א, בסמיכה ג' אותיות \u0003שק\"ר,\u0004 שנאחזים בהם, אבל אלו ה \u0003ח'\u0004 וה \u0003ק'\u0004 נודעים אצלם יותר. וע\"כ בתהלה לדוד. כתוב בכל הפסוקים \u0003ו'\u0004 באמצע הפסוק אחר הטעם אתנחתא, בכל אות ואות, כלומר בכל פסוק ופסוק, שכל אחד מתחיל באות מיוחדת מאלפא ביתא, חוץ מאלו ב' אותיות \u0003ח'\u0004 ו \u0003ק'\u0004 דהיינו חנון ורחום ה' ארך אפים וגדל חסד, שלא כתוב בו \u0003ו',\u0004 שאינו כתוב וארך אפים וגדל \u0003חסד.\u0004 וכן קרוב ה' לכל קוראיו לכל אשר יקראהו באמת, שלא כתוב, ולכל אשר יקראוהו באמת. שהוא מטעם כי \u0003ו'\u0004 הוא שם הקב\"ה, דהיינו קו האמצעי המיחד הימין והשמאל, ואין הס\"א חפצה בקו האמצעי, וע\"כ באותיות שיש בהם אחיזה לס\"א, לא כתוב \u0003ו'\u0004 באמצע הכתוב, להורות שיש בהם אחיזה לס\"א."],[6,"ובג\"כ אינון ארבעין","וכו': חוזר לענין הא', ואומר, וע\"כ הם מ\"ב אותיות שעולם הזה נברא בהן, (כנ\"ל באות כ\"ב) נמצא ש \u0003ה'\u0004 העליונה זו, דהויה, עולה צ\"ב. שהם מ' שנשארו מע\"ב שבה, וב' אודנין ימין שמאל כנ\"ל, הן מ\"ב, וה' סמכין שלה כל אחד כלול מעשר שהם נ', נ' ומ\"ב הן צ\"ב. \u0003צ'\u0004 הן, חוץ מב' אודנין ימין ושמאל, וז\"ס ואם שרה בת צ' תלד, כי שרה רומזת על אמא, שהיא ה' עליונה דהויה, אבל היא בחשבון צ\"ב דהיינו עם ב' האודנין, וכשנוסף עליהם מדרגת הברית שהוא יסוד, שהוא רקיע השמיני ועומד לשמונה ימים, דהיינו שהמילה הוא לשמונה ימים, צ\"ב ושמונה דיסוד, הם מאה. ואלו הם ודאי, מאה ברכות, שבכל יום צריכה כנסת ישראל, שהיא המלכות, להתעטר בהן. והכל הוא בסוד ה \u0003ה'.\u0004"],[7,"האי ה' איהי","וכו': ה' זו, הצורה שלה היא בב' נונין, שהם סוד מאה, דהיינו ב' ההין, שיש בהן עשרה סמכין, שכל אחד כלול מעשר, הן מאה, ה' אחת היא, ה' סמכין, ומרכבות שיוצאים מתוך הבוצינא, שהיא בינה דא\"א, דהיינו אמא עלאה שהיא ו\"ד דמילוי \u0003י'.\u0004 וה' שניה היא, חמשה סמכין האחרים היוצאים ממנה, שהיא \u0003ה'\u0004 ראשונה דהויה שהיא ישסו\"ת, ועשרה סמכים של ב' ההין אלו ב' נונין. וע\"כ צורותיהן הן כעין זה \u0003ן־ן\u0004, ב' נונין ונקודה העומדת באמצע, וע\"כ \u0003ו'\u0004 עומדת ביניהן תמיד, כעין זה, \u0003נון,\u0004 משום שכאן הוא מקומו של ז\"א, שהיא \u0003ו',\u0004 להתעטר, דהיינו לקבל מוחין דג\"ר. ואע\"פ שיש סודות אחרים בסוד ה \u0003ה',\u0004 אבל אלו הם בסודות ספרו של חנוך, וכך הוא ודאי."],[8,"וכד אתתקנא באינון","וכו': וכשנתקנה בחמשים בלבד, דהיינו אחר שנפרשה \u0003ה'\u0004 דהויה מאמא עלאה ובאה למקומה, היא בנקודה אחת העומדת בסוד ה \u0003נ'\u0004 כעין זה \u0003נון,\u0004 דהיינו שנשמעת כך במבטא, שה \u0003ו',\u0004 היא נקודה אחת באמצען השולטת עליהן. והכל הוא סוד אחד. כנ\"ל. אשרי הם היודעים דרכיה של התורה ללכת בדרכי אמת, אשרי הם בעולם הזה ואשרי הם בעולם הבא."],[9,"רזא תליתאה את","וכו': סוד השלישי הוא אות \u0003ו'\u0004 דהויה, אות הזו היא סוד צורת אדם, דהיינו ז\"א, שבו הויה דמילוי אלפין שבגימטריא אדם, דהיינו מ\"ה. כמו שלמדנו. והרי העמדנו (לעיל אות י\"ד.) שאות זו שהוא \u0003ו'\u0004 הרומזת על ג' קצוות שבו, עומדת על י\"ב מרכבות, שאלו י\"ב מאירים בכל קצה שב \u0003ו',\u0004 וי\"ב פעמים \u0003ו'\u0004 הוא ע\"ב, כמ\"ש שם. וכשמתחלקים על ג' שלישים הם כ\"ד מרכבות, כי ג\"פ כ\"ד הם ע\"ב. כי באות זו כלולים התפשטות צורת אדם, כנגד הזרועות שהם חו\"ג, וירכים שהם נו\"ה, וגופא, שהוא ת\"ת ויסוד, האברים שלהם הם כ\"ד בזרועות, וכ\"ד בירכים וכ\"ד בגוף. וכבר למדנו, אבל כולם סתומים בגוף, שהוא ת\"ת, והגוף עומד בכל ג' כ\"ד, וכל ע\"ב מרכבות כלולות בגוף, ומשום שכולם כלולות בו, עומדת ה \u0003ו'\u0004 בהתפשטות אחד, דהיינו קו אחד, הכולל כולם."]],[[0,"","אַרְבַּע גְּנוּזוֹת הֵן בִּנְקֻדָּה אַחַת שֶׁעוֹמֶדֶת בַּתָּוֶךְ בָּאֶמְצַע, וְהֵן חָמֵשׁ, וְהִיא אוֹת ה'. כְּמוֹ שֶׁאוֹת ה' שֶׁלְּמַטָּה עוֹמֶדֶת עַל אַרְבַּע, וְהִיא נְקוּדָה עַל אַרְבַּע וְעוֹמֶדֶת בְּתוֹךְ הָאֶמְצַע, כְּמוֹ כֵן הוּא כָּאן. וּמַה שֶּׁעוֹמֶדֶת עַל חֲמִשָּׁה עַמּוּדִים, כָּךְ הוּא וַדַּאי, לְפִי שֶׁזּוֹ הַנְּקֻדָּה הָעֶלְיוֹנָה הִיא עַל שְׁתֵּי בְחִינוֹת - אַחַת בְּעַצְמָהּ, וְאַחַת בְּהֶעְלֵם."],[1,"","וּבְסֵפֶר הַסּוֹדוֹת שֶׁל חֲנוֹךְ, אוֹת ה' וַדַּאי עוֹמֶדֶת עַל חֲמִשָּׁה עַמּוּדִים שֶׁיּוֹצְאִים מִתּוֹךְ הַנֵּר, וְאָז מוֹצִיא חֲמִשָּׁה עַמּוּדִים אֲחֵרִים, וְנִמְצֵאת אוֹת ה' הַזּוֹ בְּסוֹד הָעֲשָׂרָה. וְכַאֲשֶׁר נִפְרֶדֶת, עוֹמֶדֶת אוֹת ה' הַזּוֹ עַל עַמּוּדִים, וְאֵלּוּ הֵן י\"ג מִדּוֹת הָרַחֲמִים בְּדַרְגָּה אַחַת שֶׁנּוֹסֶפֶת עֲלֵיהֶן."],[2,"","וְאֵלּוּ הֵם י\"ב שֶׁנִּמְצָאִים בְּשֵׁשׁ. לִפְעָמִים הֵם אַרְבָּעִים וּשְׁתַּיִם, לִפְעָמִים שִׁבְעִים וּשְׁתַּיִם הֵן, אֲבָל יוֹרְדוֹת לְמַטָּה. וְכָאן נִפְרָדִים שְׁבִילִים לְכָל צַד, וְהֵם שְׁלֹשִׁים וּשְׁנַיִם, נִשְׁאָר אַרְבָּעִים. וּשְׁתֵּי אָזְנַיִם יָמִין וּשְׂמֹאל - הֲרֵי אַרְבָּעִים וּשְׁתַּיִם. אֵלּוּ אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת עֶלְיוֹנוֹת, שֶׁהֵן אוֹתִיּוֹת גְּדוֹלוֹת שֶׁל הַתּוֹרָה."],[3,"","לְפִי שֶׁיֵּשׁ אוֹתִיּוֹת גְּדוֹלוֹת, וְיֵשׁ אוֹתִיּוֹת קְטַנּוֹת. אוֹתִיּוֹת גְּדוֹלוֹת הֵן לְמַעְלָה, אוֹתִיּוֹת קְטַנּוֹת לְמַטָּה, וְהַכֹּל לְמַטָּה כְּדֻגְמַת לְמַעְלָה. לְפִי שֶׁיֵּשׁ שֵׁמוֹת קְדוֹשִׁים עֶלְיוֹנִים שֶׁקַּיָּמִים בִּרְצוֹן הָרוּחַ וְהַלֵּב וּבְלִי דִבּוּר כְּלָל."],[4,"","וְיְשׁ שֵׁמוֹת קְדוֹשִׁים תַּחְתּוֹנִים שֶׁעוֹמְדִים בְּדִבּוּר וּבְהַמְשָׁכַת הַמַּחֲשָׁבָה וְהָרָצוֹן עֲלֵיהֶם. וְיֵשׁ שֵׁמוֹת אֲחֵרִים לְמַטָּה, שֶׁהֵם מֵהַצַּד הַהוּא הָאַחֵר, שֶׁהוּא מֵהַצַּד הַטָּמֵא, וְאֵלֶּה לֹא קַיָּמִים אֶלָּא בְרָצוֹן שֶׁל מַעֲשֶׂה לְמַטָּה, לְהַעֲלוֹת רָצוֹן שֶׁל הַמַּעֲשֶׂה הַהוּא שֶׁלְּמַטָּה אֵלָיו. לְפִי שֶׁהַצַּד הַהוּא הָאַחֵר אֵינוֹ, אֶלָּא בְּמַעֲשִׂים שֶׁל זֶה הָעוֹלָם לְהִטָּמֵא בָהֶם, כְּמוֹ בִּלְעָם וְאוֹתָם בְּנֵי קֶדֶם, וְכָל אוֹתָם שֶׁמִּתְעַסְּקִים בְּאוֹתוֹ הַצַּד הָאַחֵר."],[5,"","וְאֵלֶּה לֹא עוֹמְדִים בְּאוֹתִיּוֹת רְשׁוּמוֹת מִן שְׁתַּיִם וְעֶשְׂרִים שֶׁל הַתּוֹרָה, חוּץ מִשְּׁתַּיִם, וְהֵן אוֹת ח' וְאוֹת ק', וְסוֹמְכִים לָהֶם בִּסְמִיכוּת אוֹתִיּוֹת שֶׁל שֶׁקֶר. אֲבָל אֵלּוּ הֵן נוֹדָעוֹת אֶצְלָן יוֹתֵר. וְעַל זֶה בִּתְהִלָּה לְדָוִד, בְּכֻלָּם כָּתוּב אוֹת ו' בְּכָל אוֹת וָאוֹת, חוּץ מֵאֵלּוּ הַשְּׁתַּיִם שֶׁלֹּא כְתוּבָה אוֹת ו', שֶׁהֲרֵי אוֹת ו' הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","וּבִשְׁבִיל זֶה אֵלּוּ הָאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁהָעוֹלָם הַזֶּה נִבְרָא בָהֶן, נִמְצָא שֶׁאוֹת ה' הָעֶלְיוֹנָה הַזֹּאת לְהַעֲלוֹת לְתִשְׁעִים וּשְׁתַּיִם. תִּשְׁעִים הֵם חוּץ מִשְּׁתֵּי אָזְנַיִם יָמִין וּשְׂמֹאל. וְסוֹד זֶה (וסימנך) - (בראשית יז) וְאִם שָׂרָה הֲבַת תִּשְׁעִים שָׁנָה תֵּלֵד. אֲבָל הוּא בְּחֶשְׁבּוֹן תִּשְׁעִים וּשְׁתַּיִם. וְכַאֲשֶׁר נוֹסֶפֶת דַּרְגָּה שֶׁל סוֹד הַבְּרִית, שֶׁהוּא רָקִיעַ שְׁמִינִי, וְעוֹמֵד לִשְׁמוֹנָה יָמִים, הֲרֵי מֵאָה. וְאֵלֶּה וַדַּאי מֵאָה בְרָכוֹת בְּכָל יוֹם שֶׁצְּרִיכָה כְּנֶסֶת יִשְׂרָאֵל לְהִתְקַשֵּׁט בָּהֶן. וְהַכֹּל בְּסוֹד אוֹת ה'."],[7,"","אוֹת ה' זוֹ הִיא צִיּוּר שֶׁלָּהּ בִּשְׁתֵּי אוֹתִיּוֹת נ', סוֹד שֶׁל מֵאָה, וְהֵם חֲמִשָּׁה עַמּוּדִים וּמֶרְכָּבוֹת הַיּוֹצְאִים מִתּוֹךְ הַנֵּר, וְהֵם חֲמִשָּׁה אֲחֵרִים שֶׁיּוֹצְאִים מִמֶּנָּה. וְעַל זֶה צִיּוּרָהּ כְּמוֹ זֶה: ן-ן. שְׁתֵּי נוּנִין, וּנְקֻדָּה שֶׁעוֹמֶדֶת בָּאֶמְצַע. וְעַל זֶה אוֹת ו' עוֹמֶדֶת בֵּינֵיהֶן תָּמִיד, כְּמוֹ זֶה נוּן, לְפִי שֶׁכָּאן הוּא מְקוֹמָהּ לְהִתְקַשֵּׁט, וְאַף עַל גַּב שֶׁסּוֹדוֹת אֲחֵרִים הֵם בְּסוֹד אוֹת ה', אֲבָל זֶה הוּא בְּסוֹדוֹת סִפְרוֹ שֶׁל חֲנוֹךְ, וְכָךְ הוּא בֶּאֱמֶת."],[8,"","וְכַאֲשֶׁר נִתְקֶנֶת בְּאֵלּוּ הַחֲמִשִּׁים לְבַדָּם, הִיא נְקֻדָּה אַחַת שֶׁעוֹמֶדֶת בְּסוֹד הָאוֹת נ', כְּמוֹ זֶה נ' - נוּ\"ן. וּנְקֻדָּה אַחַת בָּאֶמְצַע שֶׁהִיא שׁוֹלֶטֶת עֲלֵיהֶם, וְהַכֹּל בְּסוֹד אֶחָד. אַשְׁרֵי הֵם שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה לָלֶכֶת בִּדְרָכִים אֲמִתִּיּוֹת. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה, וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא."],[9,"","סוֹד שְׁלִישִׁי - אוֹת ו'. אוֹת זוֹ צִיּוּר שֶׁל סוֹד אָדָם, כְּמוֹ שֶׁבֵּאַרְנוּ. וַהֲרֵי בֵּאַרְנוּ שֶׁאוֹת זוֹ עוֹמֶדֶת עַל י\"ב מֶרְכָּבוֹת, וְכַאֲשֶׁר נִפְרָדוֹת, הֵן אַרְבַּע וְעֶשְׂרִים מֶרְכָּבוֹת שֶׁכְּלוּלוֹת בָּאוֹת הַזּוֹ, הִתְפַּשְּׁטוּת דְּמוּת שֶׁל אָדָם, כְּנֶגֶד זְרוֹעוֹת וִירֵכַיִם וְגוּף, אֵיבָרִים שֶׁלָּהֶם אַרְבָּעָה וְעֶשְׂרִים הֵם שֶׁל זְרוֹעוֹת וִירֵכַיִם וְגוּף, הֲרֵי לָמַדְנוּ, אֲבָל כֻּלָּם סְתוּמִים בַּגּוּף, וְהַגּוּף עוֹמֵד בְּכָל הָאַרְבָּעָה וְעֶשְׂרִים, וְכָל הַמֶּרְכָּבוֹת כְּלוּלוֹת בַּגוּף זֶה, וּמִשּׁוּם שֶׁכְּלוּלוֹת כֻּלָּן בּוֹ, עוֹמֶדֶת ו' בְּהִתְפַּשְּׁטוּת אַחַת."]]],[["גּוּפָא חַד כָּלִיל בְּכ\"ד רְתִיכִין, וְאִלֵּין אִינּוּן: רֵישָׁא בְּשִׁית. גּוּפָא בְּי\"ח, וְאַף עַל גַּב דְּכָל רְתִיכִין אִינּוּן (נ\"א י' י') (נ\"א י\"ח) י\"ב לְכָל סְטָר, בְּכֹלָּא קַיְּימָא גּוּפָא. אֲבָל עֶשְׂרִים וְאַרְבַּע אִינּוּן שִׁית דְּרֵישָׁא, דְּאִינּוּן שַׁיְיפִין לְאַעֲלָאָה רֵישָׁא. תִּמְנִי סְרֵי חוּלְיָין דְּקַיְּימָא רֵישָׁא, וְסַמְכָא גּוּפָא עָלַיְיהוּ.","וְכֻלְּהוּ פְּשִׁיטוּ חַד, בְּרֵישָׁא וְגוּפָא, וְאִינּוּן שִׁיתִּין כֻּלְּהוּ כָּלִיל לוֹן, דְּאִיהוּ רָזָא דְּשִׁית. וְעַל דָּא שִׁיעוּרָא דְּאָת ו', רֵישָׁא שִׁיעוּרָא בְּשִׁית נְקוּדִין מַמָּשׁ, גּוּפָא בְּתַמְנֵי סְרֵי. כְּגַוְונָא דָּא כָּל אִלֵּין רָזִין מִתְפָּרְשָׁן, לְאַכְלְלָא לוֹן בְּגוּפָא, בְּגִין דִּדְּרוֹעִין וְיַרְכִין כֻּלְּהוּ בִּגְנִיזוּ, וְעַל דָּא כֹּלָּא אִתְכְּלִיל בְּרָזָא דְּאָת ו' וּדְיּוּקְנָא דִּילָהּ.","וְכַד שְׁלִימוּ דְּאָת דָּא אִתְחָזֵי, כְּדֵין כָּל סִטְרִין בִּישִׁין אִסְתָּתָמוּ, וְאִתְפָּרְשָׁן מִסִּיהֲרָא, וְלָא אִתְחַפְיָין, בְּגִין דְּאִיהוּ מַבְקַע כָּל מַשְׁקוֹפִין דִּרְקִיעִין, וְאַנְהִיר לָהּ, וְלָא יַכְלָא מְקַטְרְגָא לְאַבְאָשָׁא כְּלַל. וְכַד הַאי אִסְתַּלָּק, כְּדֵין סָלִיק וְאַסְטֵי וּמְפַתֵּי, וְיָכִיל לְקַטְרְגָא עַל כָּל בְּנֵי עָלְמָא, בְּגִין דְּאִיהוּ מֶלֶךְ זָקֵן וּכְסִיל, וְהָא אוֹקִימְנָא.","ו' אִיהוּ נְהוֹרָא דְּנָהִיר לְסִיהֲרָא, וְאַף עַל גַּב דִּנְהִירִין סַגִּיאִין אִתְכְּלִילָן בֵּיהּ, נְהוֹרָא דְּנָהִיר לְסִיהֲרָא אִיהוּ חַד פְּשִׁיטוּ לְמַלְיָּא לָהּ. וְאִיהוּ רָזָא דְּאָלֶף, רְשִׁימוּ בְּכָל אִינּוּן רָזִין. וְכַד נָהִיר לְסִיהֲרָא בְּרָזָא דְּו' נָהִיר לָהּ.","וּבְסִפְרָא דְּאָדָם קַדְמָאָה, בְּדִיּוּקְנִין דְּאַתְוָון, ו' חַד נְקוּדָה לְעֵילָּא, וְחָמֵשׁ נְקוּדִין דִּלְתַתָּא, וְכֵן שִׁיעוּרָא דִּילָהּ כְּגַוְונָא דָּא, ו' וְכָל נְקוּדָה קַיְּימָא בְּרָזָא דְּעֶשֶׂר, בְּגִין דְּלֵית לָךָ נְקוּדָה דְּלָא אַשְׁלִים לְעֶשֶׂר, דְּכָל נְקוּדָה אִית בֵּיהּ תֵּשַׁע סַמְכִין רְתִיכִין, וְהַהִיא נְקוּדָה אַשְׁלִים לְעֶשֶׂר. נְקוּדָה דִּימִינָא תֵּשַׁע סַמְכִין רְתִיכִין לָהּ, וְאִיהִי עֲשָׂרָה. וְכֵן לִשְׂמָאלָא. וְכֵן לְכָל סִטְרִין. וְעַל דָּא, כֻּלְּהוּ נְקוּדִין אִינּוּן כָּל חַד וְחַד כְּלָלָא דְּעֶשֶׂר, אִיהִי וּרְתִּיכוֹי. וְכֻלְּהוּ כְּלִילָן בְּהַהוּא פְּשִׁיטוּ דְּאָת ו', בְּגִין כָּךְ כֹּלָּא אִיהוּ בְּדִיּוּקְנָא בְּרָזָא דְּאָת ו'.","וְכַד עָיִיִל שִׁמְשָׁא בְּסִיהֲרָא, (סיהרא) נָפַק מֵהַאי ו' חַד פְּשִׁיטוּ רָזָא דִּבְרִית, כְּגַוְונָא דָּא ג', וְדָא אִיהוּ לְאָעֲלָא בְּנוּקְבָּא. וְכַד אִתְכְּלִיל כֹּלָּא בְּהַאי פְּשִׁיטוּ דְּאָת ו', כְּדֵין קַיְּימָא לְשַׁמְּשָׁא בְּנוּקְבָּא. וְרָזָא דָּא דִּכְתִּיב, וְאַתָּה הַקְרֵב אֵלֶיךָ אֶת אַהֲרֹן אָחִיךָ, לְאִתְכַּלְּלָא (וילך רמ\"ג ע\"ב, קצ\"א ע\"ב) דְּרוֹעָא בְּגוּפָא, וְאֶת בָּנָיו אִתּוֹ, אִלֵּין כָּל אִינּוּן רְתִיכִין וְסַמְכִין דִּילֵיהּ. דְּרוֹעָא שְׂמָאלָא לְגַבֵּיהּ, דִּכְתִּיב, (במדבר ג׳:מ״ה) קַח אֶת הַלְוִיִּם, לְאִשְׁתַּכְּחָא ו' דְּכָלִיל כֹּלָּא. בְּחַד פְּשִׁיטוּ, לְמֶהֱוֵי חַד.","וְעַל דָּא אִשְׁתְּכַח יִחוּדָא בְּהַאי, יְמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא, כֹּלָּא אִיהוּ חַד. וְעַל דָּא אִתְעָבִיד חַד פְּשִׁיטוּ, וְאִקְרֵי אֶחָד, וְלָא תִּשְׁכַּח בַּר פְּשִׁיטוּ חַד בִּלְחוֹדוֹי, וְדָא הוּא חַד.","ה' בַּתְרָאָה, אִתְעָבִיד חַד גּוּפָא, בְּהַאי נְקוּדָה דְּאֶמְצָעִיתָא. וְאָעִיל בָּהּ ו', וְאִשְׁתְּכַח ו' בֵּין ב' נְקוּדִין, חַד לְעֵילָּא, וְחַד לְתַתָּא. וּכְדֵין, אִתְאֲחִיד עָלְמָא עִלָּאָה, בְּעָלְמָא תַּתָּאָה, וְאִיהוּ חַד. וְאוֹקִימְנָא. אָתָא רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא וְנָשְׁקוּ יְדוֹי. בָּכָה רִבִּי אַבָּא וְאָמַר, וַוי לְעָלְמָא כַּד יִתְכְּנִישׁ שִׁמְשָׁא וְיִתְחֲשָּׁךְ עָלְמָא.","אָמַר רִבִּי אֶלְעָזָר, יַרְכִּין לְתַתָּא, בְּרָזָא דְּאָת ו', מְנָא לָן דְּאִתְכְּלִילוּ בְּהַאי אָת. אָמַר לֵיהּ, דִּכְתִּיב, (מלאכי ג׳:כ״ב) זִכְרוּ תּוֹרַת מֹשֶׁה עַבְדִּי, וְלָא כְּתִיב נְבִיאִי, לְאִתְחֲזָאָה דְּכֹלָּא אִתְכְּלִיל בְּרָזָא דְּו', וְאָת ו' אִקְרֵי חַד, וְאִיהוּ חַד בִּלְחוֹדָהָא, וּפְשִׁיטוּ חַד וְהָא אִתְּמַר.","(שמות כ״ח:א׳) וְאַתָּה הַקְרֵב אֵלֶיךָ וְגוֹ'. אָמַר רִבִּי שִׁמְעוֹן, לָא שִׁמֵשׁ מֹשֶׁה (נ\"א שמשא) (נ\"א דאיהו שמשא) בְּסִיהֲרָא, עַד דְּאִתְכְּלִיל בְּכָל סִטְרִין בְּרָזָא דְּו', כְּמָה דְּאוֹקִימְנָא. תָּא חֲזֵי, מַה כְּתִיב, מִתּוֹךְ בְּנֵי יִשְׂרָאֵל לְכַהֲנוֹ לִי. לְכַהֵן לִי לָא כְּתִיב, אֶלָּא לְכַהֲנוֹ לִי, לְשִׁמּוּשָׁא דִּילֵיהּ, לְשִׁמּוּשָׁא דְּאָת דָּא, לְשִׁמּוּשָׁא דִּילֵיהּ וַדַּאי. לִי דָּא אָת ה', לְאַעֲלָא וּלְשַׁמְּשָׁא ו' בְּה', לְמֶהֱוֵי כֹּלָּא חַד. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּעָאלוּ וְנַפְקוּ, וְיַדְעֵי בְּרָזָא דְּאָרְחוֹי דְּאוֹרַיְיתָא, לְמֵהָךְ בְּאֹרַח קְשׁוֹט."],[[0,"גופא חד כליל","וכו': ומפרש, גוף אחד הכולל כ\"ד מרכבות, אלו הם, הראש ד \u0003ו',\u0004 יש בו שש מרכבות, והגוף ד \u0003ו'\u0004 יש בו י\"ח מרכבות, שש וי\"ח הם כ\"ד. ואע\"פ שכל המרכבות הם י\"ב לכל קצה שבו\"ק, וששה פעמים י\"ב הם ע\"ב, ולא כ\"ד. ודאי שבכולם עומד הגוף, אבל מבחינת עשרים וארבע, דהיינו שמחשבים הגוף רק לשליש אחד של ע\"ב, כנ\"ל, הם מתבארים, ששה שבראש, דהיינו חג\"ת נה\"י שבראש, שהם אברים להכניס בהם הראש, דהיינו הג\"ר המכונים ראש. וי\"ח, הם שמונה עשרה חוליות שבשדרה, שהראש עומד עליהם והגוף נסמך בהם."],[0,"","פירוש. כי רישא דמלכא אתתקן בחסד ובגבורה. (כנ\"ל משפטים אות תק\"כ) שפירושו שחסר ג\"ר דראש ואין בו אלא ו\"ק דראש. וז\"ש, \u0003דאינון שייפין לאעלאה רישא,\u0004 שהם כלים המודדים הג\"ר שלו. אמנם הגילוי של הו\"ק דראש אינו במקום הראש אלא בגוף, דהיינו על ג' קוין שבגוף, שהו\"ק דראש מתגלים בכל קו, וג\"פ ששה הם י\"ח, וז\"ס ח\"י חוליות שבשדרה, וז\"ש \u0003תמני סרי חוליין דקיימא רישא וסמכא גופא עלייהו,\u0004 כי ג' קוין שבגוף מגלים הארת החכמה שבראש, ונבחן שהראש עומד עליהם, וכן כל הגוף עומד עליהם."],[1,"וכלהו פשיטו חד","וכו': וכל, הכ\"ד מרכבות הנ\"ל, הם התפשטות אחד בראש וגוף של ה \u0003ו'\u0004 ואלו הששים ספירות כולם כולל אותם ה \u0003ו'\u0004 שהוא סוד שש ספירות חג\"ת נה\"י שכל אחת כלולה מעשר. וע\"כ השיעור של אות \u0003ו'\u0004 הראש של ה \u0003ו'\u0004 הוא בשש נקודות ממש, דהיינו חג\"ת נה\"י, והגוף בשמונה עשרה. כעין זה כל הסודות מתבארים שהם כלולים בגוף, משום שהזרועות והירכים, שהם חו\"ג ונו\"ה, הם בהעלם להיותם בחינות ב' קוין העליונים שאינם מאירים, אלא על ידי קו האמצעי המיחדם זה בזה, שהוא ה \u0003ו'.\u0004 וע\"כ נכלל הכל באות \u0003ו'\u0004 וצורתה."],[2,"וכד שלימו דאת","וכו': וכשהשלמות של אות הזה נראה. דהיינו ה \u0003ו',\u0004 שהוא קו האמצעי כנ\"ל, אז כל צדדים הרעים נסתמים ומתפרדים מן הלבנה, שהיא המלכות, ואינם מכסים אותה. משום, שקו האמצעי, הוא בוקע כל המשקופים שברקיעים ומאיר לה, להמלכות, והמקטרג אינו יכול להרע כלום. וכשזה מסתלק, דהיינו ה \u0003ו'\u0004 שהוא קו האמצעי, אז עולה המקטרג ומסטין ומפתה, ויכול לקטרג על כל בני העולם באשר שהוא מלך זקן וכסיל. וכבר העמדנו."],[3,"ו' איהו נהורא דנהיר","וכו': \u0003ו'\u0004 דהויה, הוא אור המאיר ללבנה, שהיא המלכות. ואע\"פ שאורות רבים נכללים ב \u0003ו'\u0004 שהוא ז\"א, האור שהוא מאיר ללבנה, הוא רק התפשטות אחת למלאות אותה. והוא, ז\"א, הוא סוד \u0003א',\u0004 שצורתה \u0003ו'\u0004 באמצע ב' יודין מימינה ושממאלה דהיינו ז\"א שהוא קו אמצעי המכריע ומייחד את הימין ואת השמאל. וע\"כ הימין והשמאל דבוקים בו בצורת ב' יודין שב \u0003א'.\u0004 בסוד תלת מחד נפקו, חד בתלת קיימא, (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) והוא נרשם בכל אלו הסודות שב \u0003א',\u0004 וכשהוא מאיר ללבנה, שהיא המלכות, בסוד ה \u0003ו'\u0004 מאיר לה. שצורתה קו אחד, שהוא התפשטות קו אמצעי בלבדו, מבחינת מה, שאינו לא קו ימין ולא קו שמאל, אלא התפשטות הכלול משניהם."],[4,"ובספרא דאדם קדמאה","וכו': ובספרו של אדם הראשון, בצורות האותיות, אומר, שצורת ה \u0003ו',\u0004 הוא נקודה אחת מלמעלה, הרומזת על \u0003י'\u0004 דהויה, וחמש נקודות שלמטה, שהן \u0003ה'\u0004 ראשונה דהויה, שה\"ס חמש נקודות (לעיל אות ט\"ז) שהם חמש סמכין. וכן השיעור שלו של ה \u0003ו'\u0004 דהויה שהוא ז\"א, הוא כעין זה, דהיינו שכולל בתוכו י\"ה דהויה, שהוא סוד בן י\"ה. וכל נקודה של ששה נקודות שבו, עומדת בסוד עשר, שאין לך נקודה שאינה משלמת לעשר, כי כל נקודה יש בה ט' סומכים ומרכבות, שהן רת\"ס שבה, שכל אחת שברת\"ס כלולה מג' קוין, (כנ\"ל אות י\"א) שהם ג' נקודות כזה • • •, ע\"ש. ועצם הנקודה משלמת לעשר. כי נקודת הימין ט' סומכים ומרכבות לה, ועמה עצמה היא עשרה, וכן נקודת השמאל וכן לכל הצדדים. וע\"כ הנקודות כולם, הן כל אחת ואחת בכלל עשר, היא ומרכבותיה. וכולן כלולות בהתפשטות ההיא של אות \u0003ו',\u0004 וע\"כ הכל הוא בצורת אות \u0003ו'\u0004 דהיינו שהיא בציור נקודה אחת מלמעלה, וה' נקודות שלמטה, כנ\"ל."],[5,"וכד עייל שמשא","וכו': וכשנכנס השמש, שהוא ז\"א, בלבנה. שהיא המלכות, יוצאת מ \u0003ו'\u0004 הזו התפשטות אחת שה\"ס הברית, דהיינו היסוד, שהוא כעין זה \u0003ג',\u0004 שצורתה \u0003ו'\u0004 עם תוספת נקודה בסופה, שה\"ס העטרה שנתוספה בו, שה\"ס המסך שבו, שבסודו הוא \u0003ג\u0004 ומל \u0003ד\u0004 לים, ש \u0003ג'\u0004 היא יסוד, ו \u0003ד'\u0004 היא המלכות, וזה הוא ליכנס בהנוקבא, שהיא המלכות וכשנכלל כל זה בהתפשטות הזו של אות ה \u0003ו',\u0004 שהוא ז\"א, אז הוא עומד להזדווג עם הנוקבא. וז\"ס שכתוב, \u0003ואתה הקרב אליך את אהרן אחיך,\u0004 שבא לכלול זרוע ימין, שהוא חסד הנקרא אהרן, בגוף, שהוא משה. \u0003ואת בניו אתו,\u0004 אלו הם כל המרכבות והסומכים שלו. וזרוע השמאל כלול בו במשה, שהוא מרכבה לז\"א, שהוא \u0003ו',\u0004 שכתוב, \u0003קח את הלוים.\u0004 והלוים הם זרוע שמאל. שהוא גבורה. כדי שתמצא ה \u0003ו',\u0004 שהוא משה, כלול הכל בהתפשטות אחת להיות אחד."],[6,"וע\"ד אשתכח יחודא","וכו': וע\"כ נמצא יחוד ב \u0003ו'\u0004 הזו, בימין שמאל ואמצע, שהאמצע הוא משה והימין אהרן, והשמאל הלוים, והכל הוא אחד. וע\"כ נעשה התפשטות אחת ונקרא אחד, ולא תמצא בה \u0003ו',\u0004 רק התפשטות אחת לבד, דהיינו קו אחד, וזהו סוד, אחד."],[7,"ה' בתראה, אתעביד","וכו': ה' אחרונה, דהויה, שהיא המלכות, נעשית גוף אחד בזו הנקודה האמצעית, כלומר שאע\"פ שהיא גוף אחד בעשר ספירות, מכל מקום העיקר שבה היא נקודה האמצעית שהיא מלכות, והשאר היא רק בהתכללות. ונכנס בה ה \u0003ו'\u0004 דהוי\"ה, שהוא ז\"א ונמצאת ה \u0003ו'\u0004 בין שתי נקודות, אחת למעלה, שהיא אמא, ואחת למטה שהיא מלכות, ואז נתאחד עולם העליון, שהוא בינה, בעולם התחתון, שהיא מלכות, והן אחת. והעמדנו זה, באו ר' אלעזר ור' אבא ונשקו ידיו של ר\"ש, בכה ר' אבא ואמר. אוי לעולם כשהשמש יאסף, שהוא ר\"ש, ויחשך העולם."],[8,"אמר ר' אלעזר","וכו': אמר ר\"א, הירכין למטה, שהם נצח והוד, שבסוד אות \u0003ו',\u0004 שהוא ת\"ת, מאין לנו שנכללו באות \u0003ו'.\u0004 אמר לו, שכתוב, זכרו תורת משה עבדי, ולא כתוב נביאי, להראות שהכל נכלל ב \u0003ו'\u0004 שהוא ת\"ת, ונביאים, ה\"ס נצח והוד, שהם כלולים במשה שהוא ת\"ת, וע\"כ אין צורך לכתוב משה נביאי. ואות \u0003ו'\u0004 נקרא אחד, והוא אחד בלבדו, והתפשטות אחת, כמו שנתבאר."],[9,"ואתה הקרב אליך","וכו': א\"ר שמעון, לא שמש משה, שהוא השמש, בהלבנה, שהיא המלכות, עד שנכלל בכל הצדדים בסוד אות \u0003ו',\u0004 כמו שהעמדנו, (לעיל אות ל\"ד) דהיינו שנכלל באהרן ובלוים שהם ימין ושמאל. בוא וראה, מה כתוב, מתוך בני ישראל לכהנו לי. לכהן לי לא כתוב, אלא לכהנו לי, עם \u0003ו'\u0004 יתירה, שפירושו לשמוש שלו, לשמוש של אות ה \u0003ו'\u0004 הזו, לשמוש שלו ודאי, ודומה כמו שהיה כתוב, לכהן \u0003ו',\u0004 שהיא ת\"ת, אל, \u0003לי\u0004 שהוא אות \u0003ה'\u0004 דהיינו מלכות, להכניס ולשמש ה \u0003ו'\u0004 ב \u0003ה'\u0004 שיהיה הכל אחד. אשרי הם ישראל, שנכנסו בסודות התורה ויצאו. ויודעים בסודות דרכי התורה. ללכת בדרך האמת."]],[[0,"","גּוּף אֶחָד כָּלוּל בְּאַרְבַּע וְעֶשְׂרִים מֶרְכָּבוֹת, וְאֵלֶּה הֵן: הָרֹאשׁ בְּשֵׁשׁ, הַגּוּף בִּשְׁמוֹנֶה עֶשְׂרֵה. וְאַף עַל גַּב שֶׁכָּל הַמֶּרְכָּבוֹת הֵן (י' י') (י\"ח) שְׁתֵּים עֶשְׂרֵה לְכָל צַד - בַּכֹּל עוֹמֵד הַגּוּף. אֲבָל עֶשְׂרִים וְאַרְבַּע הֵן שֵׁשׁ שֶׁל הָרֹאשׁ, שֶׁהֵם אֵיבָרִים לְהַעֲלוֹת לָרֹאשׁ. שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת שֶׁמַּעֲמִידוֹת אֶת הָרֹאשׁ, וַעֲמִידַת הַגּוּף עֲלֵיהֶן."],[1,"","וְכֻלָּם הֵם הִתְפַּשְּׁטוּת אַחַת בָּרֹאשׁ וּבַגּוּף, וְאֵלּוּ הַשִּׁשִּׁים כֻּלָּם כּוֹלֵל אוֹתָם שֶׁהוּא סוֹד שֶׁל שֵׁשׁ. וְעַל זֶה שִׁעוּר שֶׁל הָאוֹת ו' - הָרֹאשׁ שִׁעוּרוֹ בְּשֵׁשׁ נְקֻדּוֹת מַמָּשׁ, הַגּוּף בִּשְׁמוֹנֶה עֶשְׂרֵה. כְּעֵין זֶה כָּל אֵלּוּ הַסּוֹדוֹת מִתְפָּרְשִׁים, לִכְלֹל אוֹתָם בַּגּוּף, לְפִי שֶׁהַזְּרוֹעוֹת וְהַיְרֵכַיִם כֻּלָּם בְּהֶעְלֵם, וְעַל זֶה כֻּלָּם נִכְלָלִים בְּסוֹד הָאוֹת ו' וְצִיּוּר שֶׁלָּהּ."],[2,"","וְכַאֲשֶׁר שְׁלֵמוּת שֶׁל אוֹת זוֹ נִרְאֵית, אָז כָּל הַצְּדָדִים הָרָעִים נִסְתָּמִים, וְנִפְרָדִים מֵהַלְּבָנָה וְלֹא מְכַסִּים, לְפִי שֶׁהִיא בוֹקַעַת כָּל חַלּוֹנוֹת שֶׁל הָרְקִיעִים וּמְאִירָה לָהּ, וְלֹא יָכוֹל הַמְקַטְרֵג לְהָרַע כְּלָל. וְכַאֲשֶׁר זֶה מִסְתַּלֵּק, אָז עוֹלֶה וּמַסְטִין וּמְפַתֶּה, וְיָכוֹל לְקַטְרֵג עַל כָּל בְּנֵי הָעוֹלָם, לְפִי שֶׁהוּא מֶלֶךְ זָקֵן וּכְסִיל, וַהֲרֵי בֵּאַרְנוּ."],[3,"","אוֹת ו' הִיא אוֹר שֶׁמֵּאִיר לַלְּבָנָה, וְאַף עַל גַּב שֶׁאוֹרוֹת רַבִּים נִכְלָלִים בּוֹ, אוֹר שֶׁמֵּאִיר לַשְּׁכִינָה הוּא אֶחָד פָּשׁוּט לְמַלֹּאת אוֹתָהּ. וְהוּא סוֹד הָאָלֶף, רָשׁוּם בְּכָל אֵלּוּ הַסּוֹדוֹת. וְכַאֲשֶׁר מֵאִיר לַשְּׁכִינָה, בְּסוֹד אוֹת ו' מֵאִיר לָהּ."],[4,"","וּבְסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן, בְּצִיּוּר הָאוֹתִיּוֹת אוֹת ו' נְקֻדָּה אַחַת לְמַעְלָה, וְחָמֵשׁ נְקֻדּוֹת שֶׁלְּמַטָּה, וְכֵן שִׁעוּר שֶׁלָּהּ כְּעֵין זֶה - ו', וְכָל נְקֻדָּה עוֹמֶדֶת בְּסוֹד עֶשֶׂר, לְפִי שֶׁאֵין לְךְ נְקֻדָּה שֶׁלֹּא נִשְׁלֶמֶת לְעֶשֶׂר, שֶׁכָּל נְקֻדָּה יֵשׁ בָּהּ תִּשְׁעָה עַמּוּדִים מֶרְכָּבוֹת, וְהַנְּקֻדָּה הַהִיא מַשְׁלִימָה לְעֶשֶׂר. נְקֻדָּה יְמָנִית תִּשְׁעָה עַמּוּדִים, וּמֶרְכָּבוֹת יֵשׁ לָהּ, וְהִיא עֲשָׂרָה. וְכֵן לִשְׂמֹאל, וְכֵן לְכָל הַצְּדָדִים. וְעַל זֶה כָּל נְקֻדּוֹת אֵלּוּ, כָּל אַחַת וְאַחַת כְּלוּלָה מֵעֶשֶׂר, הִיא וּמַרְכְּבוֹתֶיהָ. וְכֻלָּם כְּלוּלִים בַּהִתְפַּשְּׁטוּת הַהִיא שֶׁל הָאוֹת ו', וְעַל כֵּן הַכֹּל הוּא בְּצִיּוּר בְּסוֹד הָאוֹת ו'."],[5,"","וְכַאֲשֶׁר נִכְנָס הַשֶּׁמֶשׁ בַּלְּבָנָה, (הלבנה) יוֹצֵאת מֵאוֹת ו' הַזּוֹ הִתְפַּשְּׁטוּת אַחַת סוֹד הַבְּרִית, כְּעֵין אוֹת ג', וְזֶהוּ לְהִכָּנֵס בַּנְּקֵבָה. וְכַאֲשֶׁר נִכְלָל הַכֹּל בְּהִתְפַּשְּׁטוּת זוֹ שֶׁל אוֹת ו', אָז עוֹמֵד לְשַׁמֵּשׁ בַּנְּקֵבָה. וְסוֹד זֶה שֶׁכָּתוּב, וְאַתָּה הַקְרֵב אֵלֶיךְ אֶת אַהֲרֹן אָחִיךְ. אֶת - לִכְלֹל הַזְּרוֹעוֹת בַּגּוּף. וְאֶת בָּנָיו אִתּוֹ - אֵלֶּה כָּל אֵלּוּ הַמֶּרְכָּבוֹת וְעַמּוּדִים שֶׁלּוֹ. זְרוֹעַ שְׂמֹאל אֶצְלוֹ, שֶׁכָּתוּב (במדבר ג) קַח אֶת הַלְוִיִּם, שֶׁתִּמָּצֵא אוֹת ו' שֶׁכּוֹלֶלֶת הַכֹּל בְּהִתְפַּשְּׁטוּת אַחַת לִהְיוֹת אֶחָד."],[6,"","וְעַל זֶה נִמְצָא הַיִּחוּד בָּזֶה, יָמִין וּשְׂמֹאל וְאֶמְצַע. הַכֹּל הוּא כְאֶחָד. וְעַל זֶה נַעֲשֵׂית הִתְפַּשְּׁטוּת אַחַת, וְנִקְרָא אֶחָד, וְלֹא תִמְצָא חוּץ מֵהִתְפַּשְּׁטוּת אַחַת בִּלְבַד. וְזֶהוּ אֶחָד."],[7,"","אוֹת ה' אַחֲרוֹנָה נַעֲשֵׂית גּוּף אֶחָד בְּזוֹ הַנְּקֻדָּה הָאֶמְצָעִית. וְנִכְנֶסֶת בָּהּ אוֹת ו', וְנִמְצֵאת אוֹת ו' בֵּין שְׁתֵּי נְקֻדּוֹת, אַחַת לְמַעְלָה וְאַחַת לְמַטָּה. וְאָז מִתְאַחֵד הָעוֹלָם הָעֶלְיוֹן בָּעוֹלָם הַתַּחְתּוֹן, וְהוּא אֶחָד. וּבֵאַרְנוּהָ. בָּא רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְנָשְׁקוּ יָדָיו. בָּכָה רַבִּי אַבָּא וְאָמַר, אוֹי לָעוֹלָם כַּאֲשֶׁר יֵאָסֵף הַשֶּׁמֶשׁ וְיֵחָשֵׁךְ הָעוֹלָם."],[8,"","אָמַר רַבִּי אֶלְעָזָר, הַיְרֵכַיִם שֶׁלְּמַטָּה בְּסוֹד אוֹת ו', מִנַּיִן לָנוּ שֶׁנִּכְלְלוּ בְּאוֹת זוֹ? אָמַר לוֹ, שֶׁכָּתוּב (מלאכי ג) זִכְרוּ תּוֹרַת מֹשֶׁה עַבְדִּי, וְלֹא כָתוּב נְבִיאִי, לְהַרְאוֹת שֶׁהַכֹּל נִכְלָל בְּסוֹד אוֹת ו'. וְאוֹת ו' נִקְרֵאת אֶחָד, וְהִיא אַחַת לְבַדָּהּ וְהִתְפַּשְּׁטוּת אַחַת, וַהֲרֵי נִתְבָּאֵר."],[9,"","וְאַתָּה הַקְרֵב אֵלֶיךְ וְגוֹ' (שמות כח). אָמַר רַבִּי שִׁמְעוֹן, לֹא שִׁמֵּשׁ מֹשֶׁה (השמש) (שהוא שמש) בַּלְּבָנָה עַד שֶׁנִּכְלַל בְּכָל הַצְּדָדִים בְּסוֹד אוֹת ו', כְּמוֹ שֶׁבֵּאַרְנוּ. בֹּא וּרְאֵה מַה כָּתוּב, מִתּוֹךְ בְּנֵי יִשְׂרָאֵל לְכַהֲנוֹ לִי. לְכַהֵן לִי לֹא נֶאֱמַר, אֶלָּא לְכַהֲנוֹ לִי, לַשִּׁמּוּשׁ שֶׁלּוֹ, לַשִּׁמּוּשׁ שֶׁל אוֹת זוֹ, לַשִּׁמּוּשׁ שֶׁלּוֹ וַדַּאי. זוֹ אוֹת ה', לְהַעֲלוֹת וּלְשַׁמֵּשׁ ו' בְּה', לִהְיוֹת הַכֹּל אֶחָד. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁנִּכְנְסוּ וְיָצְאוּ וְיוֹדְעִים בְּסוֹד הַדְּרָכִים שֶׁל הַתּוֹרָה לָלֶכֶת בְּדֶרֶךְ אֱמֶת."]]],[["מִתּוֹךָ בְּנֵי יִשְׂרָאֵל אֲמַאי מִתּוֹךְ בְּנֵי יִשְׂרָאֵל. אֶלָּא כֹּלָּא לָא אִתְקְרֵי לְמֶהֱוֵי חַד כְּדְקָא יֵאוֹת, אֶלָּא מִתּוֹךְ בְּנֵי יִשְׂרָאֵל. דְּהָא בְּנֵי יִשְׂרָאֵל קַיְימֵי לְתַתָּא, לְאִתְפַּתְּחָא אָרְחִין, וּלְאַנְהָרָא שְׁבִילִין, וּלְאַדְלְקָא בּוּצִינִין, וּלְקָרְבָא כֹּלָּא מִתַּתָּא לְעֵילָּא, לְמֶהֱוֵי כֹּלָּא חַד, וּבְגִינֵי כַּךְ כְּתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' וְגוֹ'.","וְאַתָּה הַקְרֵב אֵלֶיךָ וְגוֹ' אָמַר רַבִּי שִׁמְעוֹן, כֹּלָּא אִיהוּ קְרִיבָה, לְמַאן דְּיָדַע לְיַחֲדָא יִחוּדָא, וּלְמִפְלַח לְמָארֵיהּ, דְּהָא בְּזִמְנָא דְּאִשְׁתְּכַח קָרְבְּנָא כְּדְקָא יֵאוֹת, כְּדֵין אִתְקְרִיב כֹּלָּא כַּחֲדָא, (נ\"א דרגין כלהו כחד) וּנְהִירוּ דְּאַנְפִּין, אִשְׁתְּכַח, בְּעָלְמָא בְּבֵי מַקְדְּשָׁא, וְאִתְכַּפְיָא וְאִתְכַּסְיָא סִטְרָא אַחֲרָא, וְשָׁלִיט סִטְרָא דִּקְדוּשָּׁא בִּנְהִירוּ וְחִידוּ. וְכַד קָרְבְּנָא לָא אִשְׁתְּכַח כְּדְקָא יֵאוֹת, אוֹ יִחוּדָא לָא הֲוֵי כְּדְקָא יֵאוֹת, כְּדֵין אַנְפִּין עֲצִיבוּ. וּנְהִירוּ לָא אִשְׁתְּכַח, וְאִתְכַּסְיָא סִיהֲרָא, וְשַׁלְטָא סִטְרָא אַחֲרָא בְּעָלְמָא, (נ\"א דלא אתחריב בי מקדשא אלא בגין וכו') בְּגִין דְּלָא אִית מַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא, כְּדְקָא יֵאוֹת.","אָמַר רַבִּי שִׁמְעוֹן, (פ' בא ל\"ד ע\"א) קוּדְשָׁא בְּרִיךְ הוּא לָא נַסֵּי לְאִיּוֹב, וְלָא אָתָא עִמֵּיהּ בְּנִסְיוֹנָא, כְּנִסְיוֹנָא דִּשְׁאַר צַדִּיקַיָּא, דְּהָא לָא כְּתִיב בֵּיהּ וְהָאֱלהִים נִסָּה אֶת אִיּוֹב, כְּמָה דִּכְתִּיב בְּאַבְרָהָם (בראשית כ״ב:א׳) וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. דְּאִיהוּ בְּיָדֵיהּ אַקְרִיב לִבְרֵיהּ יְחִידָאי לְגַבֵּיהּ. וְאִיּוֹב לָא יָהִיב לֵיהּ וְלָא מָסַר לֵיהּ כְּלוּם. וְלָא אִתְּמַר לֵיהּ, אֲבָל אִתְמְסָר בִּיְדָא דִּמְקַטְרְגָא, בְּדִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּאִיהוּ אַתְּעָר לְהַהוּא מְקַטְרְגָא לְגַבֵּיהּ, מַה דְּאִיהוּ לָא בָּעָא. דְּהָא בְּכָל זִמְנָא אָתָא הַהוּא מְקַטְרְגָא לְאַתְעֲרָא עַל בְּנֵי נָשָׁא, וְהָכָא קוּדְשָׁא בְּרִיךְ הוּא אַתְּעָר לְגַבֵּיהּ, דִּכְתִּיב, (איוב א׳:ח׳) הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב. אֲבָל רָזָא עֲמִיקָא אִיהוּ.","פָּתַח וְאָמַר (בראשית ד׳:ג׳) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה מִנְחָה לַיְיָ'. וַיְהִי מִקֵּץ יָמִים, רָזָא אִיהוּ, מִקֵּץ יָמִים, וְלָא מִקֵּץ (קל\"ד ע\"א) יָמִין, דָּחָה לְקֵּץ יָמִין, וְקָרִיב לְקֵּץ יָמִים. וְהָא אוֹקִימְנָא, דִּכְתִּיב, (דניאל י״ב:י״ג) וְאַתָּה לֵךְ לַקֵּץ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְדָנִיאֵל וְאַתָּה לֵךְ לַקֵּץ. אָמַר לֵיהּ, לְאָן קֵץ, לְקֵּץ הַיָּמִים אוֹ לְקֵּץ הַיָּמִין, עַד דְּאָמַר לֵיהּ לְקֵּץ הַיָּמִין.","וְעַל דָּא דָּחִיל דָּוִד, דִּכְתִּיב, (תהילים ל״ט:ה׳) הוֹדִיעֵנִי יְיָ' קִצִּי. אוֹ לְקֵּץ הַיָּמִים, אוֹ לְקֵּץ הַיָּמִין. וְהָכָא מָה כְּתִיב, וַיְהִי מִקֵּץ יָמִים וְלָא מִקֵּץ יָמִין. וּבְגִינֵי כַּךְ לָא אִתְקַבָּל קָרְבָּנֵיהּ דְּהָא מִסִּטְרָא אַחֲרָא הֲוָה כֹּלָּא.","תָּא חֲזֵי מָה כְּתִיב, (בראשית ד׳:ד׳) וְהֶבֶל הֵבִיא גַּם הוּא. מַאי גַּם הוּא. לְאַסְגָּאָה כֹּלָּא דָּא בְּדָא. קָרְבָּנָא כֹּלָּא וְעִקָרָא דִּילֵיהּ הֲוָה לְקוּדְשָׁא בְּרִיךְ הוּא, וְיָהִיב חוּלָקֵיהּ לְסִטְרָא אַחֲרָא, כְּמָה דְאַתְּ אָמֵר וּמֵחֶלְבֵיהֶן. וְקַיִן, עִקָּרָא עָבֵד מִקֵּץ יָמִים, וְיָהַב חוּלָקָא לְקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא אִתְדָחָא אִיהוּ וְקָרְבָּנֵיהּ.","בְּאִיּוֹב מַה כְּתִיב, (איוב א׳:ה׳) וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה וְגוֹ'. וּכְתִיב וַיְהִי כִּי הִקִּיפוּ יְמֵי הַמִּשְׁתֶּה. וּכְתִיב וְשָׁלְחוּ וְקָרְאוּ לִשְׁלשֶׁת אַחְיוֹתֵיהֶם לֶאֱכוֹל וְלִשְׁתּוֹת עִמָּהֶם, דְּדָא אִיהוּ עִקָּרָא לְסִטְרָא אַחֲרָא. וּלְבָתַר אַקְרִיב עוֹלוֹת, וְעוֹלָה אִיהוּ דְּכַר, וְלָא נוּקְבָּא, וְסַלְּקָא לְעֵילָּא, וְקָרְבָּנָא לָא קָרִיב לְאַכְלְלָא לֵיהּ כְּדְקָא יֵאוֹת.","וְתָּא חֲזֵי, אִלְמָלֵא חוּלָקָא יָהַב לְכֹלָּא, מְקַטְרְגָא לָא יָכִיל לֵיהּ לְבָתַר, וְאִי תֵּימָא אֲמַאי אַבְאִישׁ לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא, בְּגִין דְּגָרִים לְכַסְיָּא נְהוֹרָא וּלְאִתְחַפְיָּא, וְאִיהוּ לָא קָרִיב קָרֵבְּנָא אַחֲרָא, לְאַתְּזָנָא בֵּיהּ אַחֲרָנִין, אֶלָּא עוֹלָה, דְּסַלְּקָא לְעֵילָּא, וְעַל דָּא כְּתִיב, כָּכָה יַעֲשֶׂה אִיּוֹב כָּל הַיָּמִים, דְּאִלְמָלֵא סִטְרָא אַחֲרָא אִתְּזָנַת בְּחוּלָקָא, אִתְעֲבַר מֵעַל מַקְדְּשָׁא וְאִסְתַּלָּק מִנֵּיהּ, וְסִטְרָא דִּקְדוּשָׁה הֲוָה סָלִיק לְעֵילָּא לְעֵילָּא.","אֲבָל אִיהוּ לָא בָּעָא דְּאִתְהֲנֵי אַחֲרָא מִקָרְבָּנֵיה, וְאַעְדֵּי גַּרְמֵיהּ מִנֵּיהּ. מְנָא לָן. דִּכְתִּיב, (איוב א׳:א׳) וְסָר מֵרָע. וְעַל דָּא קָרִיב תָּדִיר עוֹלָה, דְּהָא עוֹלָה לָא אִתְהָנֵי מִנֵּיהּ סִטְרָא אַחֲרָא לְעָלְמִין. וּבְגִין כַּךְ, כָּל מָה דְּנָטִיל לְבָתַר, מִדִּידֵיהּ נָטִיל. וְעַל דָּא אִיּוֹב גָּרִים לְחַפְיָא עָרְלָה עַל בְּרִית קַיָימָא, דְּלָא הֲוָה אַעְדֵּי מִנֵּיהּ. וּבְגִין כַּךְ קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר לְהַהוּא מְקַטְרְגָא, דִּכְתִּיב הֲשַׂמְתָּ לִבְּךָ עַל עַבְדִּי אִיּוֹב."],[[0,"מתוך בני ישראל:","שואל, למה מתוך בני ישראל, ומשיב, אלא הכל אינו נקרא אחד להיות אחד כראוי, אלא מתוך בני ישראל. כי בני ישראל עומדים למטה לפתוח דרכים ולהאיר שבילים ולהדליק הנרות, שהם ספירות העליונות, ולקרב הכל ממטה למעלה, שיהיה הכל אחד. ומשום זה כתוב, ואתם הדבקים בה' וגו'."],[1,"ואתה הקרב אליך","וגו': א\"ר שמעון הכל הוא נקרב על ידי מי שיודע ליחד היחוד ולעבוד לאדונו, שהרי בזמן שנמצא הקרבן כראוי, אז נתקרב הכל יחד, דהיינו הצדדים, ימין ושמאל, והארת הפנים של הקב\"ה, נמצא בעולם בבית המקדש, והסטרא אחרא נכנע ונסתר, וצד הקדושה שולט באורה ושמחה. וכשהקרבן לא נמצא כראוי. או היחוד לא היה כראוי, אז הפנים עצובות ואור אינו נמצא, והלבנה, שהיא המלכות, נסתרת, והסטרא אחרא שולט בעולם, משום שאין מי שיודע ליחד השם הקדוש כראוי."],[2,"אר\"ש קב\"ה לא","וכו': א\"ר שמעון, הקב\"ה לא נסה את איוב, ולא בא עמו בנסיון. כנסיון שאר הצדיקים, שהרי לא כתוב בו, והאלקים נסה את איוב, כמו שכתוב באברהם, והאלקים נסה את אברהם, שהוא בידו הקריב בן יחידו אליו, ואיוב לא נתן לו, ולא מסר לו כלום, ולא נאמר לו שיתן, אבל נמסר ביד המקטרג בדינו של הקב\"ה, שהוא עורר עליו את המקטרג, מה שהוא לא בקש. כי תמיד בא המקטרג להתעורר על בני אדם, וכאן הקב\"ה עורר את המקטרג עליו, שכתוב, השמת לבך על עבדי איוב. אבל סוד עמוק הוא."],[3,"פתח ואמר ויהי","וגו': פתח ואמר, ויהי מקץ ימים ויבא קין מפרי האדמה מנחה לה'. \u0003ויהי מקץ ימים,\u0004 הוא סוד, מקץ ימים, שהוא טומאה ולא מקץ ימין שהוא קדושה (כמ\"ש לעיל בראשית ב' דף כ\"ח ד\"ה קץ) דחה לקץ הימין, וקרב לקץ ימים. והעמדנו, שכתוב, ואתה לך לקץ. אמר הקב\"ה לדניאל, ואתה לך לקץ. אמר לו לאיזה קץ, לקץ הימים או לקץ הימין. עד שאמר לו לקץ הימין."],[4,"וע\"ד דחיל דוד","וכו': ועל זה פחד דוד, שכתוב, הודיעני ה' קצי. אם לקץ הימים או לקץ הימין. וכאן בקין, מה כתוב, ויהי מקץ ימים, ולא מקץ ימין. ומשום זה לא נתקבל קרבנו, כי מסטרא אחרא היה הכל."],[5,"ת\"ח מה כתיב","וכו': בוא וראה, מה כתוב, והבל הביא גם הוא. מהו, \u0003גם הוא.\u0004 הוא לרבות הכל זה בזה, כלומר, לרבות שגם בקרבן הבל היה חלק לסטרא אחרא וגם בקרבן קין היה חלק לקדושה, אלא הבל, כל הקרבן שלו ועקרו היה להקב\"ה, ונתן חלק לסטרא אחרא, כמש\"א ומחלביהן, שהחלב והטוב היה להקב\"ה. וקין, עקרו עשה לקץ הימים, שהוא סטרא אחרא, ונתן רק חלק אל הקב\"ה. וע\"כ נדחה הוא וקרבנו."],[6,"באיוב מה כתיב","וכו': באיוב, מה כתוב, והלכו בניו ועשו משתה וגו', וכתוב, ויהי כי הקיפו ימי המשתה, וכתוב, ושלחו וקראו לשלשת אחיותיהם לאכול ולשתות עמהם, שזה הוא העיקר, שנתן לסטרא אחרא, ואח\"כ הקריב עולות, ועולה הוא זכר ולא נקבה, ועולה כולה למעלה, ולא הקריב קרבן שיכלול אותו כראוי, דהיינו שיתן גם חלק לס\"א."],[7,"ות\"ח אלמלא חולקא","וכו': ובוא וראה, אם היה נתן חלק לכל, דהיינו גם לס\"א, לא היה יכול לו המקטרג אח\"כ. ואם תאמר למה הרע לו הקב\"ה, על מה שלא נתן חלק לס\"א. איזה חטא הוא זה. ומשיב, אלא משום שגרם לכסות האור ולהסתירו, שהוא לא הקריב קרבן אחר לזון בו אחרים, דהיינו הס\"א, שיש לה חלק בקרבנות, (כנ\"ל פרשת נח דף מ\"ח ד\"ה ועם זה) אלא הקריב עולה לבד, שעולה למעלה ואין לס\"א חלק בו, וע\"כ כתוב, ככה יעשה איוב כל הימים. שלא נתן חלק לס\"א, שאם הס\"א היה נזון בחלק, היה נעבר מעל המקדש והיה מסתלק ממנו, וצד הקדושה היה עולה למעלה למעלה."],[8,"אבל איהו לא","וכו': אבל הוא לא רצה שיהנה אחר, דהיינו הס\"א, מקרבנו, והסיר את עצמו ממנו. מאין לנו. כי כתוב וסר מרע. שהסיר עצמו מן הרע, שלא לתת לו שום חלק. וע\"כ הקריב תמיד עולה, כי מן עולה אין הסטרא אחרא נהנה ממנו לעולם, ומשום זה כל מה שלקח הס\"א אח\"כ מאיוב, משלו לקח. וע\"כ גרם איוב לכסות ערלה על ברית קדש, שלא היתה סרה ממנו, מן ברית קודש. ומשום זה עורר עליו הקב\"ה אותו המקטרג, שכתוב, השמת לבך על עבדי איוב."],[8,"","ביאור הדברים. כי בניו של איוב חטאו באכילה ושתיה בימי המשתה, דהיינו ששתו לשכרה, שעי\"ז נמשכה ערלה על ברית קדש, כלומר שהסטרא אחרא סתם האורות המושפעים מן היסוד אל העולם.... \u0003דדא איהו עקרא לסטרא אחרא.\u0004 ואיוב היה בידו למחות ולא מיחה, אלא שהקריב בשבילם קרבן עולה. ואם היה מקריב קרבן חטאת אז היה נותן בזה חלק לסטרא אחרא, והיה מתפרד מן הקדושה, (כנ\"ל פרשת נח אות ק\"ג, ק\"ד, וע\"ש בסולם). אבל כיון שהקריב עולה שאין לס\"א חלק בו, ע\"כ לא נפרשה מן הקדושה, ונמצא שאיוב גרם בזה שישאר הערלה על ברית קודש, מחמת חטאים של בניו, שלא מיחה בהם ולא תקן אותם ע\"י קרבן. וז\"ש \u0003ועל דא איוב גרים לחפיא ערלה על ברית קיימא, דלא הוה אעדי מניה,\u0004 שלא הוסרה הערלה ע\"י קרבן עולה, כמבואר."]],[[0,"","מִתּוֹךָ בְּנֵי יִשְׂרָאֵל. לָמָּה מִתּוֹךְ בְּנֵי יִשְׂרָאֵל? אֶלָּא הַכֹּל לֹא נִקְרָא לִהְיוֹת אֶחָד כְּמוֹ שֶׁצָּרִיךְ, אֶלָּא מִתּוֹךְ בְּנֵי יִשְׂרָאֵל. שֶׁהֲרֵי בְּנֵי יִשְׂרָאֵל קַיָּמִים לְמַטָּה, לִפְתֹּחַ דְּרָכִים וּלְהָאִיר שְׁבִילִים וּלְהַדְלִיק נֵרוֹת, וּלְקָרֵב הַכֹּל מִמַּטָּה לְמַעְלָה לִהְיוֹת הַכֹּל אֶחָד, וּמִפְּנֵי כָּךְ כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' וְגוֹ'."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל הוּא קָרוֹב לְמִי שֶׁיּוֹדֵעַ לְיַחֵד הַיִּחוּד וְלַעֲבֹד לַאֲדוֹנוֹ, שֶׁהֲרֵי בִּזְמַן שֶׁנִּמְצָא קָרְבָּן כְּמוֹ שֶׁצָּרִיךְ, אָז מִתְקָרֵב הַכֹּל כְּאֶחָד, (הדרגות כלן כאחת) וְהֶאָרַת הַפָּנִים נִמְצֵאת בָּעוֹלָם בְּבֵית הַמִּקְדָּשׁ, וְנִכְנָע וְנִסְתָּר הַצַּד הָאַחֵר, וְשׁוֹלֵט הַצַּד שֶׁל הַקְּדֻשָּׁה בְּאוֹר וְשִׂמְחָה. וְכַאֲשֶׁר הַקָּרְבָּן לֹא נִמְצָא כְּמוֹ שֶׁצָּרִיךְ, אוֹ שֶׁהַיִּחוּד לֹא הָיָה כְּמוֹ שֶׁצָּרִיךְ, אָז הַפָּנִים עֲצוּבוֹת, וְאוֹר לֹא נִמְצָא, וּמִתְכַּסָּה הַלְּבָנָה, וְשׁוֹלֵט הַצַּד הָאַחֵר בָּעוֹלָם (שלא נחרב בית המקדש אלא מפני וכו'), מִפְּנֵי שֶׁאֵין מִי שֶׁיּוֹדֵעַ לְיַחֵד הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁצָּרִיךְ."],[2,"","אָמַר רַבִּי שִׁמְעוֹן, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִסָּה אֶת אִיּוֹב וְלֹא בָא עִמּוֹ בְנִסָּיוֹן כַּנִּסָּיוֹן שֶׁל שְׁאָר הַצַּדִּיקִים, שֶׁהֲרֵי לֹא כָתוּב בּוֹ וְהָאֱלֹהִים נִסָּה אֶת אִיּוֹב, כְּמוֹ שֶׁכָּתוּב בְּאַבְרָהָם (בראשית כב) !! וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. שֶׁהוּא בְיָדָיו הִקְרִיב אֶת בְּנוֹ יְחִידוֹ אֵלָיו. וְאִיּוֹב לֹא נָתַן לוֹ וְלֹא מָסַר לוֹ כְלוּם, וְלֹא נֶאֱמַר לוֹ. אֲבָל נִמְסַר בְּיַד הַמְקַטְרֵג בְּדִין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהוּא עוֹרֵר אֶת הַמְקַטְרֵג עָלָיו מַה שֶּׁהוּא לֹא רָצָה. שֶׁהֲרֵי בְּכָל זְמַן בָּא הַמְקַטְרֵג הַהוּא לְעוֹרֵר עַל בְּנֵי אָדָם, וְכָאן הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵר אוֹתוֹ עָלָיו, שֶׁכָּתוּב (איוב א) הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב. אֲבָל סוֹד עָמֹק הוּא."],[3,"","פָּתַח וְאָמַר, (בראשית ד) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה מִנְחָה לַה'. וַיְהִי מִקֵּץ יָמִים, סוֹד הוּא. מִקֵּץ יָמִים וְלֹא מִקֵּץ יָמִין. דָּחָה לְקֵץ הַיָּמִין, וְקֵרַב לְקֵץ הַיָּמִים. וּכְבָר פֵּרַשְׁנוּ, שֶׁכָּתוּב (דניאל יב) וְאַתָּה לֵךְ לַקֵּץ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָנִיֵּאל, וְאַתָּה לֵךְ לַקֵּץ. אָמַר לוֹ, לְאֵיזֶה קֵץ? לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין? עַד שֶׁאָמַר לוֹ, לְקֵץ הַיָּמִין."],[4,"","וְעַל זֶה פָּחַד דָּוִד, שֶׁכָּתוּב (תהלים לט) הוֹדִיעֵנִי ה' קִצִּי. אוֹ לְקֵץ הַיָּמִים, אוֹ לְקֵץ הַיָּמִין. וְכָאן מַה כָּתוּב? וַיְהִי מִקֵּץ יָמִים, וְלֹא מִקֵּץ יָמִין. וּמִפְּנֵי כֵן לֹא הִתְקַבֵּל קָרְבָּנוֹ, שֶׁהֲרֵי מֵהַצַּד הָאַחֵר הָיָה הַכֹּל."],[5,"","בֹּא וּרְאֵה מַה כָּתוּב, (בראשית ד) וְהֶבֶל הֵבִיא גַם הוּא. מַהוּ גַם הוּא? לְרַבּוֹת הַכֹּל זֶה בְזֶה. הַקָּרְבָּן כֻּלּוֹ וְהָעִקָּר שֶׁלּוֹ הָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְנָתַן מֵחֶלְקוֹ לַצַּד הָאַחֵר, כְּמוֹ שֶׁנֶּאֱמַר וּמֵחֶלְבֵיהֶן. וְקַיִן, הָעִקָּר עָשָׂה מִקֵּץ יָמִים, וְנָתַן חֵלֶק לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה נִדְחָה הוּא וְקָרְבָּנוֹ."],[6,"","בְּאִיּוֹב מַה כָּתוּב? (איוב א) וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה וְגוֹ'. וְכָתוּב וַיְהִי כִּי הִקִּיפוּ יְמֵי הַמִּשְׁתֶּה. וְכָתוּב וְשָׁלְחוּ וְקָרְאוּ לִשְׁלֹשֶׁת אַחְיֹתֵיהֶם לֶאֱכֹל וְלִשְׁתּוֹת עִמָּהֶם. שֶׁזֶּהוּ הָעִקָּר לַצַּד הָאַחֵר. וְאַחַר כָּךְ הִקְרִיב עוֹלוֹת, וְעוֹלָה הוּא זָכָר, וְלֹא נְקֵבָה, וְעוֹלָה לְמַעְלָה, וְהַקָּרְבָּן לֹא הִקְרִיב לִכְלֹל אוֹתוֹ כְּמוֹ שֶׁצָּרִיךְ."],[7,"","וּבֹא רְאֵה, אִם הָיָה נוֹתֵן חֵלֶק לְכֻלָּם, הַמְקַטְרֵג לֹא הָיָה יָכוֹל לוֹ לְבַסּוֹף. וְאִם תֹּאמַר, מַדּוּעַ הֵרַע לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא, מִפְּנֵי שֶׁגָּרַם לְכַסּוֹת הָאוֹר וּלְהַעְלִימוֹ, וְהוּא לֹא הִקְרִיב קָרְבָּן אַחֵר לָזוּן בּוֹ אֲחֵרִים, אֶלָּא עוֹלָה, שֶׁעוֹלָה לְמַעְלָה, וְעַל זֶה כָּתוּב, כָּכָה יַעֲשֶׂה אִיּוֹב כָּל הַיָּמִים. שֶׁאִלּוּ הַצַּד הָאַחֵר הָיָה נִזּוֹן בְּחֶלְקוֹ, הָיָה עוֹבֵר מֵעַל הַמִּקְדָּשׁ וּמִסְתַּלֵּק מִמֶּנּוּ, וְצַד הַקְּדֻשָּׁה הָיָה עוֹלֶה לְמַעְלָה לְמַעְלָה."],[8,"","אֲבָל הוּא לֹא רָצָה שֶׁיֵּהָנוּ אֲחֵרִים מִקָּרְבָּנוֹ, וְהֵסִיר עַצְמוֹ מִמֶּנּוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (איובא) וְסָר מֵרָע. וְעַל זֶה הִקְרִיב תָּמִיד עוֹלָה, שֶׁהֲרֵי עוֹלָה לֹא נֶהֱנֶה מִמֶּנָּה הַצַּד הָאַחֵר לְעוֹלָם. וּמִפְּנֵי כֵן, כָּל מַה שֶׁנָּטַל לְבַסּוֹף, מִמֶּנּוּ נָטַל. וְעַל זֶה אִיּוֹב גָּרַם לְכַסּוֹת בְּעָרְלָה עַל בְּרִית הַקִּיּוּם, שֶׁלֹּא הָיָה מִסְתַּלֵּק מִמֶּנּוּ. וּמִפְּנֵי כֵן הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵר אֶת הַמְקַטְרֵג הַהוּא, שֶׁכָּתוּב הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב."]]],[["תָּא חֲזֵי, כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאִתְאַחֲדָא בְּהוּ בְּיִשְׂרָאֵל בְּמִצְרַיִם, לָא קַיְּימָא שַׁעֲתָא. בְּגִין דְּעָרְלָה חַפְיָא נְהוֹרָא, עַד זִמְנָא דְּהַהוּא מְקַטְרְגָא הֲוָה נָטִיל דִּילֵיהּ מֵאִיּוֹב, וְעַל דָּא פָּקִיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֵיכְלֵיהּ לְהַהוּא פֶּסַח בִּבְהִילוּ, עַד דְּהַהוּא סִטְרָא אַחֲרָא אִשְׁתָּדַּל בֵּיהּ בְּאִיּוֹב, וּפָקִיד לְאִתְעַבְּרָא עָרְלָה מִנַּיְיהוּ, וּכְדֵין אִתְאֲחָד קוּדְשָׁא בְּרִיךְ הוּא בְּיִשְׂרָאֵל, וְהַהוּא סִטְרָא אַחֲרָא אִתְפְּרַשׁ מִן קֻדְשָׁא, וְאִשְׁתָּדַּל בֵּיהּ בְּאִיּוֹב, וְנָטִיל מִדִילֵיהּ. וּכְדֵין (שמות יב) פֶּסַח הוּא לַיְיָ' וַדַּאי. דְּעַד הַשְׁתָּא לָא הֲוָה פֶּסַח לַיְיָ'. זַכָּאִין אִינּוּן דְּיַדְעֵי וּמְיַחֲדֵי יִחוּדָא דְּמָארֵיהוֹן כְּדְקָא יֵאוֹת.","כְּתִיב (שמות לד יז) אֱלהֵי מַסֵּכָה לא תַעֲשֶׂה לָּךְ, וּכְתִיב בַּתְרֵיהּ אֶת חַג הַמַּצוֹת תִּשְׁמֹר. (מאי עביד) מַאי הַאי לְגַבֵּי הַאי. אֶלָּא הָכִי אוּקְמוּהָ, מַאן דְּאָכִיל חָמֵץ בְּפֶסַח (כאילו עביד כוכבים ומזלות למפלח לגרמיה, דהא רזא הכי הוא דחמץ בפסח) כְּמַאן דְּפָלַח לְכּוֹכָבִים וּמַזָּלוֹת אִיהוּ.","תָּא חֲזֵי, כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם נָפְקוּ מֵרְשׁוּ דִּלְהוֹן, מֵרְשׁוּ אַחֲרָא, מֵהַהוּא רְשׁוּ דְּאִקְרֵי חָמֵץ, נַהֲמָא בִּישָׁא. וְעַל דָּא אִקְרֵי כּוֹכָבִים וּמַזָּלוֹת הָכִי, וְדָא אִיהוּ רָזָא דְּיֵצֶר הָרָע, פּוּלְחָנָא נוֹכְרָאָה, דְּאִקְרֵי אוּף הָכִי שְׂאוֹר. וְדָא אִיהוּ יֵצֶר הָרָע, דְּהָכִי אִיהוּ יֵצֶר הָרָע בְּבַר נָשׁ, כְּחָמִיר בְּעִיסָה, עָאל בִּמְעוֹי דְּבַר נָשׁ זְעֵיר זְעֵיר, וּלְבָתַר אַסְגֵּי בֵּיהּ, עַד דְּכָל גּוּפָא אִתְעֲרַב בַּהֲדֵיהּ. וְדָא אִיהוּ כּוֹכָבִים וּמַזָּלוֹת. וְעַל דָּא כְּתִיב, (תהילים פ״א:י׳) לֹא יִהְיֶה בְךָ אֵל זָר. אֵל זָר וַדַּאי.","אֶת חַג הַמַּצּוֹת תִּשְׁמֹר, רִבִּי יְהוּדָה פָּתַח, (ישעיהו ב׳:כ״ב) חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ כִּי בַמֶּה נֶחְשָׁב הוּא. הַאי קְרָא אוּקְמוּהָ. אֲבָל מַאי חִדְלוּ לָכֶם מִן הָאָדָם, וְכִי אַזְהַר לֵיהּ לְבַר נָשׁ לְאִתְמָנְע מִשְּׁאָר בְּנֵי נָשָׁא. אוּף אִינּוּן נָמֵי לְגַבֵּיהּ, יִשְׁתַּכְחוּן בְּנֵי נָשָׁא דְּלָא יִקְרְבוּן אִלֵּין בְּאִלֵּין לְעָלְמִין. אֶלָּא הָא אוּקְמוּהָ בְּמַאן דְּאֲשְׁכִּים לְפִתְחָא דְּחַבְרֵיהּ לְמֵיהָב לֵיהּ שְׁלָם.","וַאֲנָא אוֹקִימְנָא לֵיהּ בִּקְרָא אַחֲרָא, דִּכְתִּיב, (משלי כ״ז:י״ד) מְבָרֵךְ רֵעֵהוּ בְּקוֹל (רכ\"ו ע\"ב) גָּדוֹל בַּבֹּקֶר הַשְׁכֵּם קְלָלָה תֵּחָשֶׁב לוֹ. וְאַף עַל גַּב דְּכֹלָּא שַׁפִּיר. אֲבָל מַאי חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ. הָכָא פָּקִיד קוּדְשָׁא בְּרִיךְ הוּא לְבַר נָשׁ, וְאַזְהִיר לֵיהּ לְאִסְתַּמְּרָא מֵאִינּוּן בְּנֵי נָשָׁא, דְּסָטוּ אָרְחַיְיהוּ מֵאֹרַח טָב לְאֹרַח בִּישׁ, וּמְסָאֲבֵי נַפְשַׁיְיהוּ בְּהַהוּא מְסָאֲבוּ אַחֲרָא.","דְּהָא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְבַר נָשׁ, עָבֵד לֵיהּ בְּדִיּוּקְנָא עִלָּאָה, וְנָפַח בֵּיהּ רוּחָא (נ\"א נשמתא) קַדִּישָׁא, דְּכָלִיל בִּתְלַת כְּמָה דְּאוֹקִימְנָא, דְּאִית בֵּיהּ נֶפֶשׁ רוּחַ וּנְשָׁמָה, וְעֵילָּא מִכֹּלָּא נְשָׁמָה, דְּאִיהִי חֵילָא עִלָּאָה לְמִנְדַּע, וּלְמֵטַר פִּקּוּדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. וְאִי הַהִיא נִשְׁמְתָא קַדִּישָׁא אָעִיל לָהּ בְּפוּלְחָנָא אַחֲרָא, הַאי אִיהוּ מַסְאִיב לָהּ, וְנָפִיק מִפּוּלְחָנָא דְּמָארֵיהּ. בְּגִין דִּתְלַת חֵילִין אִלֵּין, כֻּלְּהוּ חַד, נֶפֶשׁ רוּחַ וּנְשָׁמָה מִשְׁתַּתְּפֵי כַּחֲדָא, וַהֲווּ חַד, וְכֹלָּא כְּגַוְונָא דְּרָזָא עִלָּאָה. (על דא נאמר (שם י\"ג) הולך את חכמים וגו')","וְאִי חָזֵינָן לְהַאי בַּר נָשׁ, דַּהֲווֹ בֵּיהּ אִלֵּין דַּרְגִּין כֻּלְּהוּ. עַד לָא קַיְּימָא בְּקִיּוּמֵיהּ לְמִנְדַּע מַאן אִיהוּ, בְּמַאי אִתְיְדַע (דלא) לְקָרְבָא בַּר נָשׁ בַּהֲדֵיהּ, אוֹ לְאִתְמָנְעָא מִנֵּיה. (ס\"א בר נש דאית ביה דרגין אלין כלהו וקיימא בקיומיה דא איהו גבר שלים עבדא מהימנא דמאריה ובעי לאשתתפא ביה ולאתחברא בהדיה למילף אורחוי מניה. ובמאי אתיידע בר נש למנדע מאן איהו לקרבא בהדיה או לאתמנעא מניה) בְּרוּגְזֵיהּ מַמָּשׁ, יְדַע לֵיהּ בַּר נָשׁ, וְיִשְׁתְּמוֹדַע מַאן אִיהוּ. אִי הַהִיא נִשְׁמְתָא קַדִּישָׁא נָטַר בְּשַׁעֲתָא דְּרוּגְזוֹי, (אתיא עליה) דְּלָא יֶעְקַר לָהּ מֵאַתְרָהָא, בְּגִין לְמִשְׁרֵי תְּחוֹתָהּ הַהוּא אֵל זָר, דָּא אִיהוּ בַּר נָשׁ כְּדְקָא יֵאוֹת. דָּא אִיהוּ עַבְדָּא דְּמָארִיהּ, דָּא אִיהוּ גְּבָר שְׁלִים.","וְאִי הַהוּא בַּר נָשׁ לָא נָטִיר לָהּ, וְאִיהוּ עָקַר קְדוּשָּׁה דָּא עִלָּאָה מֵאַתְרֵיהּ, לְמִשְׁרֵי בְּאַתְרֵיהּ סִטְרָא אַחֲרָא. וַדַּאי דָּא אִיהוּ בַּר נָשׁ דְּמָרִיד בְּמָארֵיהּ, וְאָסִיר לְקָרְבָא בַּהֲדֵיהּ וּלְאִתְחַבְּרָא עִמֵּיהּ, וְדָא אִיהוּ (איוב י״ח:ד׳) טֹרֵף נַפְשׁוֹ בְּאַפּוֹ. אִיהוּ טָרִיף וְעָקַר נַפְשֵׁיהּ, בְּגִין רוּגְזֵיהּ, וְאַשְׁרֵי בְּגַוֵּיהּ אֵל זָר. וְעַל דָּא כְּתִיב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, דְּהַהִיא נִשְׁמְתָא קַדִּישָׁא טָרִיף לָהּ, וְסָאִיב לָהּ, בְּגִין אַפּוֹ. אֲשֶׁר נְשָׁמָה אַחְלַף בְּאַפּוֹ. כִּי בַמֶּה נֶחְשָׁב הוּא. כּוֹכָבִים וּמַזָּלוֹת אִתְחֲשִׁיב הַהוּא בַּר נָשׁ."],[[0,"ת\"ח כד בעא","וכו': בוא וראה, כשרצה הקב\"ה להתאחד בישראל במצרים, לא עמדה השעה, משום שהערלה, דהיינו הס\"א, כסה האור, עד שבא הזמן, שהמקטרג היה לקח את שלו מאיוב, ואז צוה הקב\"ה לאכול את הפסח בחפזון, דהיינו כל עוד שאותו הס\"א עסק בו באיוב, וצוה להסיר הערלה מהם, ואז התאחד הקב\"ה בישראל, והסטרא אחרא נפרד מן הקדושה ועסק באיוב ולקח את שלו. ואז פסח הוא לה', כי עד עתה לא היה הפסח לה'. אשרי הם שיודעים ומיחדים יחוד אדונם כראוי."],[0,"","פירוש. כבר ידעת שאין גילוי הארת החכמה, אלא בשעת גילוי העונשים והדינים הנמשכים, על הרשעים שהמשיכו חכמה ממעלה למטה, (כמ\"ש לעיל וירא דף ס\"ד ד\"ה וז\"ש חד, באורך ע\"ש) ואם פסק גילוי הדינים נפסק הארת החכמה. והטעם הוא, כדי להבריח בעת ההוא את הס\"א הרוצה לינק ולהמשיך החכמה ממעלה למטה."],[0,"","וזה אמרו, \u0003כד בעא קב\"ה לאתאחדא\u0004 וכו', דהיינו כשרצה לגלות להם הארת החכמה שיתיחד בהם, \u0003לא קיימא שעתא בגין דערלה חפיא נהורא.\u0004 כי הערלה, שהוא הס\"א, היתה מחכה לזמן גילוי חכמה, כדי להמשיך ממעלה למטה, וע\"כ נסתרה ונכסה הארת החכמה, שזה נבחן שהערלה מכסה וסותם אור העליון שלא יופיע. \u0003עד זמנא דההוא מקטרגא הוה נטיל דיליה מאיוב,\u0004 דהיינו עד זמן גילוי העונשים והדינים, שסובלים הרשעים שהמשיכו החכמה ממעלה למטה, שגילוי דינים האלו, מבריחים הס\"א, והחכמה יכולה להאיר. ונודע, שסוד קרבן פסח ה\"ס גילוי הארת החכמה, וז\"ש, \u0003וע\"ד פקיד ליה קב\"ה למיכליה לההוא פסח בבהילו, עד דההוא סטרא אחרא אשתדל ביה באיוב,\u0004 שהארת החכמה באה עם אכילת הפסח, וצוה הקב\"ה לאכלו בחפזון, שפירושו, לא יאוחר משיעור זמן הגילוי של העונשים שענש הס\"א את איוב, כי אז אין חשש מיניקת הס\"א, וז\"ש \u0003וכדין פסח הוא לה' ודאי,\u0004 דהיינו שיש בטחון שלא יטו את הארת החכמה ממעלה למטה, ויביאו את הפסח לרשות הס\"א \u0003דעד השתא לא הוה פסח לה',\u0004 כלומר, שאם היה מתגלה הארת החכמה הבאה עם אכילת הפסח שלא בזמן גילוי העונשים, לא היתה ההארה לה', אלא לס\"א, שהיו ממשיכים אותה ממעלה למטה."],[1,"כתיב, אלהי מסכה לא תעשה לך:","וכתוב אחריו, את חג המצות תשמור. שואל מה זה אצל זה. ומשיב, אלא כך העמידו, מי שאוכל חמץ בפסח הוא כמי שעובד עבודה זרה."],[2,"ת\"ח כד נפקו וכו':","בוא וראה, כשיצאו ישראל ממצרים, יצאו מרשות שלהם, מרשות הסטרא אחרא, מרשות ההיא שנקרא חמץ, לחם רע, ע\"כ נקרא עבודה זרה כך, בשם חמץ. וזה הוא סוד יצר הרע, שהוא עבודה זרה, שנקרא גם כן שאור. וזה הוא יצר הרע, שכך הוא יצר הרע באדם כמו שאור בעיסה. נכנס לאט לאט במעיו של האדם ואח\"כ מתרבה בו, עד שכל הגוף מעורב בו. וזהו עבודה זרה, וע\"כ כתוב, לא יהיה בך אל זר. אל זר ודאי."],[3,"את חג המצות תשמר:","ר' יהודה פתח, חדלו לכם מן האדם אשר נשמה באפו כי במה נחשב הוא. מקרא זה העמידוהו, אבל מהו חדלו לכם מן האדם. וכי הזהיר הנביא להמנע משאר בני אדם, וכן שאר בני אדם יחדלו ממנו, ויהיו נמצאים בני האדם, שלא יקרבו זה אל זה לעולם. ומשיב, אלא העמידו הכתוב, במי שמשכים לפתחו של חבירו לתת לו שלום, מטרם שמברך אל הקב\"ה, וע\"ז נאמר חדלו וגו'."],[4,"ואנא אוקימנא ליה","וכו': ואני העמדתי הכתוב, חדלו לכם וגו', עם כתוב אחר, שכתוב, מברך רעהו בקול גדול בבקר השכם קללה תחשב לו. ואע\"פ שהכל טוב, כלומר, אע\"פ שכבר ברך אל הקב\"ה. וא\"צ להזהיר על זה חדלו לכם וגו' אבל מהו חדלו לכם מן האדם אשר נשמה באפו. כאן צוה הקב\"ה את האדם והזהירו שישמור עצמו מאלו האנשים שהטו דרכיהם מדרך טוב לדרך רע ומטמאים עצמם בטומאה דסטרא אחרא."],[5,"דהא כד ברא","וכו': כי כשברא הקב\"ה את האדם, עשה אותו בצורה העליונה ונפח בו רוח קדוש הכלול משלשה כמו שהעמדנו, שיש בו, נפש רוח ונשמה, והנשמה היא למעלה מכולם, שהיא כח עליון לדעת ולשמור מצות הקב\"ה. ואם מכניס נשמה הקדושה ההיא בעבודה אחרת, זה הוא המטמא אותה, ויוצא מעבודת רבונו. משום שג' כחות אלו כולם אחד, נפש רוח ונשמה משתתפים יחד והם אחד כמו בסוד העליון, שבינה וז\"א ומלכות הם אחד, כן נפש רוח ונשמה הם אחד, כי מהם הם נמשכים."],[6,"ואי חזינן להאי","וכו': ואם רואים אדם, שיש בו אלו מדרגות כולן, שהן נפש רוח ונשמה, ועוד לא עמד על בוריו לדעת מי הוא, במה נודע אם להתקרב אליו אדם, או להמנע ממנו. הנה בכעסו ממש אדם יודע אותו, ויכירו מי הוא. אם שומר נשמה הקדושה ההיא בשעת כעסו, שלא יעקר אותה ממקומה, ויבא לשרות במקומה אל זר, זה הוא אדם כראוי, זהו עבד לרבונו, זה הוא אדם השלם."],[7,"ואי ההוא בר","וכו': ואם אדם ההוא אינו שומר אותה, והוא עוקר קדושה זו העליונה, מחמת שבא לידי כעס, ומשרה במקומה, סטרא אחרא. ודאי זה הוא אדם שמרד באדונו, ואסור לקרב אליו ולהתחבר עמו. וזהו, \u0003טורף נפשו באפו,\u0004 שטורף ועוקר נפשו מחמת כעסו, ומשרה בעצמו אל זר. ועליו כתוב, חדלו לכם מן האדם אשר נשמה \u0003באפו,\u0004 היינו שטורף נשמה הקדושה ההיא ומטמא אותה בשביל \u0003אפו,\u0004 דהיינו מחמת שבא לידי כעס, אשר החליף נשמתו בכעסו. \u0003כי במה נחשב הוא.\u0004 היינו, שאדם ההוא נחשב \u0003לבמה\u0004 שעובדים עליה עבודה זרה."]],[[0,"","בֹּא וּרְאֵה, כַּאֲשֶׁר רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְאַחֵד בָּהֶם בְּיִשְׂרָאֵל בְּמִצְרַיִם, לֹא עָמְדָה לָהֶם הַשָּׁעָה, מִפְּנֵי שֶׁהָעָרְלָה מְכַסָּה הָאוֹר עַד זְמַן שֶׁהַמְקַטְרֵג הַהוּא הָיָה לוֹקֵחַ אֶת שֶׁלּוֹ מֵאִיּוֹב, וְעַל זֶה צִוָּה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לֶאֱכֹל אֶת אוֹתוֹ פֶסַח בְּחִפָּזוֹן, עַד שֶׁהַצַּד הָאַחֵר הַהוּא הִתְעַסֵּק בּוֹ בְּאִיּוֹב, וְצִוָּה לְהַעֲבִיר עָרְלָה מֵהֶם, וְאָז הִתְאַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיִשְׂרָאֵל, וְהַצַּד הָאַחֵר נִפְרַד מִן הַקְּדֻשָּׁה, וְהִתְעַסֵּק בּוֹ בְּאִיּוֹב וְלָקַח מִשֶּׁלּוֹ, וְאָז (שמות יב) פֶּסַח הוּא לַה', וַדַּאי. שֶׁעַד כָּאן לֹא הָיָה פֶּסַח לַה'. אַשְׁרֵי אֵלֶּה שֶׁיּוֹדְעִים וּמְיַחֲדִים יִחוּד קוֹנָם כְּמוֹ שֶׁצָּרִיךְ."],[1,"","כָּתוּב (שם לד) אֱלֹהֵי מַסֵּכָה לֹא תַעֲשֶׂה לָּךְ, וְכָתוּב אַחֲרָיו אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. מַה (עושה) זֶּה אֵצֶל זֶה? אֶלָּא כָּךְ פֵּרְשׁוּהָ, מִי שֶׁאוֹכֵל חָמֵץ בְּפֶסַח (כאלו עובד כוכבים ומזלות לעבד להם, שכן הסוד כך הוא שחמץ בפסח) כְּמִי שֶׁעוֹבֵד לְכוֹכָבִים וּמַזָּלוֹת הוּא."],[2,"","בֹּא וּרְאֵה, כַּאֲשֶׁר יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, יָצְאוּ מֵרָשׁוּת שֶׁלָּהֶם, מֵרָשׁוּת אַחֶרֶת, מֵהָרָשׁוּת הַהִיא שֶׁנִּקְרֵאת חָמֵץ, לֶחֶם רַע. וְעַל זֶה נִקְרָאִים כּוֹכָבִים וּמַזָּלוֹת כָּךְ, וְזֶהוּ סוֹד שֶׁל יֵצֶר הָרָע, עֲבוֹדָה זָרָה, שֶׁנִּקְרֵאת גַּם כָּךְ - שְׂאוֹר. וְזֶהוּ יֵצֶר הָרָע, שֶׁכָּךְ הוּא יֵצֶר הָרָע בַּבֶּן אָדָם כִּשְׂאוֹר שֶׁבָּעִסָּה, שֶׁנִּכְנָס בְּמֵעָיו שֶׁל אָדָם מְעַט מְעַט, וּלְבַסּוֹף מִתְרַבֶּה בוֹ עַד שֶׁכָּל הַגּוּף מְעֹרָב בּוֹ. וְזֶהוּ כּוֹכָבִים וּמַזָּלוֹת. וְעַל זֶה כָּתוּב, (תהלים פא) לֹא יִהְיֶה בְךְ אֵל זָר. אֵל זָר וַדַּאי."],[3,"","אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. רַבִּי יְהוּדָה פָּתַח, (ישעיה ב) חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ כִּי בַמֶּה נֶחְשָׁב הוּא. פָּסוּק זֶה פֵּרְשׁוּהוּ, אֲבָל מַה זֶּה חִדְלוּ לָכֶם מִן הָאָדָם? וְכִי מַזְהִיר לוֹ לָאָדָם לְהִמָּנַע מִשְּׁאָר בְּנֵי אָדָם אֲפִלּוּ הֵם גַּם כֵּן מִמֶּנּוּ יִמָּצְאוּ בְנֵי אָדָם שֶׁלֹּא יִתְקָרְבוּ אֵלּוּ בְאֵלּוּ לְעוֹלָמִים? אֶלָּא זֶה פֵּרְשׁוּהוּ בְּמִי שֶׁמַּשְׁכִּים לְפֶתַח חֲבֵרוֹ לְהָבִיא לוֹ שָׁלוֹם."],[4,"","וַאֲנַחְנוּ בֵּאַרְנוּ אוֹתוֹ בְפָסוּק אַחֵר, שֶׁכָּתוּב (משלי כז) מְבָרֵךְ רֵעֵהוּ בְּקוֹל גָּדוֹל בַּבֹּקֶר הַשְׁכֵּים קְלָלָה תֵחָשֶׁב לוֹ. וְאַף עַל פִּי שֶׁהַכֹּל טוֹב, אֲבָל מַה זֶּה חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ? כָּאן צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם וּמַזְהִיר אוֹתוֹ לְהִשָּׁמֵר מֵאֵלּוּ בְּנֵי אָדָם שֶׁנָּטוּ דַרְכָּם מִדֶּרֶךְ טוֹב לְדֶרֶךְ רַע, וּמְטַמְּאִים נַפְשָׁם בַּטֻּמְאָה הַהִיא הָאַחֶרֶת."],[5,"","שֶׁהֲרֵי, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם, עָשָׂה אוֹתוֹ בִּדְמוּת עֶלְיוֹנָה, וְנָפַח בּוֹ רוּחַ (נשמה) קְדוֹשָׁה, שֶׁכְּלוּלָה בְשָׁלֹשׁ, כְּמוֹ שֶׁפֵּרַשְׁנוּ, שֶׁיֵּשׁ בּוֹ נֶפֶשׁ רוּחַ וּנְשָׁמָה, וְעֶלְיוֹן מֵהַכֹּל הִיא הַנְּשָׁמָה, שֶׁהִיא כֹּחַ עֶלְיוֹן לָדַעַת וְלִשְׁמֹר צִוּוּיֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִם הַנְּשָׁמָה הַהִיא הַקְּדוֹשָׁה מַעֲלָה אוֹתָהּ בַּעֲבוֹדָה אַחֶרֶת, זֶה הוּא שֶׁמְּטַמֵּא אוֹתָהּ, וְיוֹצֵא מֵעֲבוֹדַת קוֹנוֹ. מִפְּנֵי שֶׁשְּׁלֹשָׁה כֹחוֹת אֵלּוּ, כֻּלָּם אֶחָד, נֶפֶשׁ רוּחַ וּנְשָׁמָה מִשְׁתַּתְּפִים כְּאֶחָד, וְהָיוּ אֶחָד, וְהַכֹּל כְּדֻגְמַת הַסּוֹד הָעֶלְיוֹן. (ועל זה נאמר (שם יג) הולך את חכמים וגו')."],[6,"","וְאִם רָאִינוּ לְזֶה הָאָדָם שֶׁהָיוּ בוֹ אֵלֶּה הַמַּדְרֵגוֹת כֻּלָּן, עַד שֶׁלֹּא עוֹמְדִים בִּקְבִיעוּת לְדַעַת מִי שֶׁהוּא, בַּמֶּה יִתְוַדַּע (שלא) לְהִתְקָרֵב הָאָדָם אֵלָיו אוֹ לְהִתְרַחֵק מִמֶּנּוּ. (בן אדם שיש בו מדרגות אלו כלם ועומדים קימים, זהו אדם שלם, עבד נאמן לאדונו, וצריך להשתתף בו ולהתחבר בו ללמד דרכים ממגו. ובמה יודע בן אדם לדעת מי הוא להתקרב אליו או להתרחק ממגו, ') בְּרֻגְזוֹ מַמָּשׁ יֵדַע לוֹ הָאָדָם וְיִוָּדַע מִי הוּא. אִם הַנְּשָׁמָה הַהִיא הַקְּדוֹשָׁה שׁוֹמֵר בִּשְׁעַת רֻגְזוֹ (בא עליה) שֶׁלֹּא יַעֲקֹר אוֹתָהּ מִמְּקוֹמָהּ, שֶׁאָז יָבא תַחְתֶּיהָ אוֹתוֹ אֵל זָר - זֶהוּ בֶּן אָדָם כְּמוֹ שֶׁצָּרִיךְ, זֶהוּ עֶבֶד שֶׁל אֲדוֹנוֹ, זֶהוּ גֶבֶר שָׁלֵם."],[7,"","וְאִם הָאָדָם הַהוּא לֹא שָׁמַר לָהּ וְהוּא עָקַר הַקְּדֻשָּׁה הַזּוֹ הָעֶלְיוֹנָה מִמְּקוֹמָהּ לִשְׁכֹּן בְּתוֹכָהּ הַצַּד הָאַחֵר - וַדַּאי זֶהוּ אָדָם שֶׁמּוֹרֵד בְּרַבּוֹ, וְאָסוּר לְהִתְקָרֵב אֵלָיו וּלְהִתְחַבֵּר עִמּוֹ, וְזֶהוּ (איוב יח) טֹרֵף נַפְשׁוֹ בְּאַפּוֹ. הוּא טוֹרֵף וְעוֹקֵר נַפְשׁוֹ בְּסִבַּת רֻגְזוֹ, וּמוֹשִׁיב בְּתוֹכָהּ אֵל זָר. וְעַל זֶה כָּתוּב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה הַהִיא טוֹרֵף אוֹתָהּ וּמְטַמֵּא אוֹתָהּ מִשּׁוּם אַפּוֹ. אֲשֶׁר נְשָׁמָה הֶחֱלִיף בְּאַפּוֹ. כִּי בַמֶּה נֶחְשָׁב הוּא - עֲבוֹדָה זָרָה נֶחְשָׁב אוֹתוֹ בֶּן אָדָם."]]],[["וּמַאן דְּאִתְחַבָּר עִמֵּיהּ, וּמַאן דְּאִשְׁתָּעֵי (ס\"א משתתף) בַּהֲדֵיהּ, כְּמַאן דְּאִתְחַבָּר בְּכּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ. מַאי טַעְמָא. בְּגִין דְכּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ שָׁארֵי בְּגַוֵּיהּ. וְלָא עוֹד, אֶלָּא דְּעָקַר קְדוּשָּׁה עִלָּאָה מֵאַתְרֵיהּ, וְשָׁארִי בְּאַתְרֵיהּ כּוֹכָבִים וּמַזָּלוֹת אֵל זָר. מַה אֵל זָר כְּתִיב בֵּיהּ (ויקרא י״ט:ד׳) אַל תִּפְנוּ אֶל הָאֱלִילִים, כְּגַוְונָא דָּא, אָסִיר לְאִסְתַּכְּלָא בְּאַנְפּוֹי.","וְאִי תֵּימָא הָא רוּגְזָא דְּרַבָּנָן. רוּגְזָא דְּרַבָּנָן טָב אִיהוּ לְכָל סִטְרִין, דְּהָא תָּנֵינָן דְּאוֹרַיְיתָא אֶשָּׁא אִיהִי, וְאוֹרַיְיתָא קָא מַרְתְּחָא לֵיהּ, דִּכְתִּיב, (ירמיהו כ״ג:כ״ט) הֲלֹא כֹה דְּבָרִי כָּאֵשׁ נְאֻם יְיָ'. רוּגְזָא דְּרַבָּנָן בְּמִלֵּי דְּאוֹרַיְיתָא. רוּגְזָא דְּרַבָּנָן לְמֵיהַב יְקָרָא לְאוֹרַיְיתָא, וְכֹלָּא לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוִי, לְכַךְ נֶאֱמַר (דברים ד׳:כ״ד) כִּי יְיָ' אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא אֵל קַנָּא.","אֲבָל אִי בְּמִלִּין אַחֲרָנִין, לָאו פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הַאי, בְּגִין דִּבְכָל חַטָּאִים דְּקָא עָבִיד בַּר נָשׁ, לָאו אִיהוּ כּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ כְּהַאי, וְאָסִיר לְקָרְבָא בַּהֲדֵיהּ דְּהַאי. וְאִי תֵּימָא הָא לְשַׁעֲתָא הֲוָה, דְּעָבַר וְהָדַר אַהְדָּר. לָאו הָכִי, דְּכֵיוָן דְּאִעֲקָר קְדוּשָּׁא דְּנַפְשֵׁיהּ מִנֵּיהּ וּמֵאַתְרֵיהּ, וְהַהוּא אֵל זָר, מַקְפַּח הַהוּא אֲתָר, אִתְתָּקַּף בֵּיהּ, וְלָא שָׁבִיק לֵיהּ. בַּר כַּד אִתְדָּכֵי בַּר נָשׁ מִכֹּל וָכֹל, וְעָקַר לֵיהּ לְעָלְמִין, וּלְבָתַר אִשְׁתָּדַּל לְאִתְקַדְּשָׁא וּלְאַמְשָׁכָא קְדוּשָּׁה עָלֵיהּ. כְּדֵין וּלְוָאי דְּאִתְקַדֵשׁ. אֲמַר לֵיהּ רִבִּי יוֹסֵי, אִתְקָדָּשׁ מַמָּשׁ. (ס\"א אמאי והא אתדחי ואתקדש)","אֲמַר לֵיהּ תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִיהוּ עָקַר קְדוּשָּׁה דְּנַפְשֵׁיהּ, וְשַׁרְיָא בְּאַתְרֵיהּ הַהוּא אֵל זָר דְּאִקְרֵי טָמֵא, אִסְתְּאָב בַּר נָשׁ, וְסָאִיב לְמַאן דְּקָרִיב בַּהֲדֵיהּ, וְהַהִיא קְדוּשָּׁה עָקְרַת מִנֵּיהּ, וְכֵיוָן דְּעָקְרַת מִנֵּיהּ זִמְנָא חֲדָא, כַּמָּה דְּיַעֲבִיד בַּר נָשׁ עוֹד, לָא תִּיתוּב לְאַתְרָהָא.","אֲמַר לֵיהּ אִי הָכִי, כַּמָה מִסְאֲבִין אִינּוּן דְּמִּתְדָכָּאן. אֲמַר לֵיהּ שָׁאנִי מִסְאֲבוּ אַחֲרָא, דְּלָא יָכִיל לְמֶעְבַּד יַתִּיר. אֲבָל דָּא שַׁנְיָא מִכֹּלָּא, דְּכָל גּוּפָא סָאִיב מִגּוֹ וּמִבַּר, וְנַפְשָׁא, וְכֹלָּא מַסְאִיב. וּשְׁאַר מִסְאֲבוּ דְּעָלְמָא, לָאו אִיהוּ אֶלָּא גּוּפָא לְבַר בִּלְחוֹדוֹי, וּבְּגִין כָּךְ כְּתִיב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, דְּאַחְלָף קְדוּשָּׁה דְּמָארֵיהּ בְּגִין אַפּוֹ, דְּדָא אִיהוּ מִסְאֲבוּ דְּמַסְאִיב כֹּלָּא. כִּי בַמֶּה נֶחְשָׁב הוּא. בָּמָה כּוֹכָבִים וּמַזָּלוֹת וַדַּאי נֶחְשָׁב אִיהוּ.","תָּא חֲזֵי, הַאי אִיהוּ רוּגְזָא דְּאִיהוּ כּוֹכָבִים וּמַזָּלוֹת, סִטְרָא אַחֲרָא, כְּמָה דְּאַמָרָן, דְּבָעֵי בַּר נָשׁ לְאִסְתַּמְּרָא מִנֵּיהּ וּלְאִתְפָּרָשָׁא מֵעֲלוֹי, וְעַל דָּא כְּתִיב (שמות לה) אֱלהֵי מַסֵּכָה לא תַעֲשֶׂה לָּךְ. לָּךְ: בְּגִין לְאַבְאָשָׁא גַּרְמָךְ. וּכְתִיב בַּתְרֵיהּ אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. תִּשְׁמֹר: דָּא סִטְרָא דִּקְדוּשָּׁה, דְּבָעֵי בַּר נָשׁ לְנַטְרָא לֵיהּ, וְלָא יָחְלָף לֵיהּ בְּגִין סִטְרָא אַחֲרָא. וְאִי יֶחְלָף לֵיהּ הָא אִיהוּ מַסְאִיב, וְסָאִיב לְכָל מַאן דְּקָרִיב בַּהֲדֵיהּ.","אֶת חַג הַמַּצּוֹת תִּשְׁמֹר, הַאי אִיהוּ אֲתָר דְּאִקְרֵי שָׁמוֹר. וּבְּגִין כָּךְ כְּתִיב, אֶת חַג הַמַּצּוֹת תִּשְׁמֹר שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת כַּאֲשֶׁר צִוִּיתִיךָ. שִׁבְעַת יָמִים אִלֵּין, לָאו אִינּוּן כְּשִׁבְעַת הַיָּמִים דְּסֻכּוֹת, דְּאִינּוּן עִלָּאִין וְאִלֵּין תַּתָּאִין. וְעַל דָּא, בְּאִינּוּן הַלֵּל גָּמוּר, וּבְהָנִי לָאו הַלֵּל גָּמוּר, וְעַל דְּאִינּוּן לְתַתָּא, שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת. מַצֹּת כְּתִיב חָסֵר בְּלָא ו', דְּעַד לָא שָׁרָאן אִינּוּן יוֹמִין עִלָּאִין, רָזָא דְּו'.","וְאִי תֵּימָא, כֵּיוָן דְּהַאי רָזָא דְּחַג הַמַּצּוֹת אִתְקַדָּשׁ, אֲמַאי נַחְתָּא, דְּהָא תָּנֵינָן מַעֲלִין בַּקֹּדֶשׁ וְלָא מוֹרִידִין, אֲמַאי נַחְתָּא לְתַתָּא בְּאִינּוּן יוֹמִין תַּתָּאִין.","תָּא חֲזֵי, כְּתִיב (ויקרא ט״ז:ו׳) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ וְגוֹ', מַאן דִּיְכַפֵּר, אִצְטְרִיךְ (נ\"א לכפרא) עָלֵיהּ בְּקַדְמִיתָא, וּבָתַר עַל בֵּיתֵיהּ. כְּגַוְונָא דָּא, הַאי דַּרְגָּא, שָׁאֲרִי לְאִתְקַדְּשָׁא וּלְנָפְקָא בִּקְדוּשָׁה, לְכַפְּרָא עָלֵיהּ, וְכֵיוָן דְּאִיהוּ אִתְקַדָּשׁ, בָּעֵי לְכַפָּרָא עַל בֵּיתֵיהּ, וּלְקַדְּשָׁא לוֹן, וְעַל דָּא נַחְתָּא לְתַתָּא לְקַדְּשָׁא בֵּיתֵיהּ. וּבְמָּה מְקַדֵּשׁ לוֹן, בְּיִשְׂרָאֵל דִּלְתַתָּא. בְּחוּשְׁבָּנָא דְעוֹמֵר וְכֵיוָן דְּאִלֵּין מִתְקַדְשָׁאן, בָּעֵינָן לְסַלְּקָא לָהּ לְעֵילָּא, דְּהָא כַּד בֵּיתָא דְּמַטְרוֹנִיתָא אִתְקַדְשַׁת, כְּדֵין סַלְקַת לְעֵילָּא, לְאִתְקַשְּׁרָא בְּאִינּוּן יוֹמִין עִלָּאִין לְעֵילָּא."],[[0,"ומאן דאתחבר עמיה","וכו': ומי שמתחבר עמו, ומי שמדבר עמו הוא כמו שמתחבר בעבודה זרה ממש, מהו הטעם, משום שעבודה זרה ממש שורה בתוכו, דהיינו אל זר, ולא עוד אלא שעקר קדושה עליונה ממקומה והשרה במקומה עבודה זרה, אל זר. מה אל זר כתוב בו, אל תפנו אל האלילים, כמו זה, אסור להסתכל בפניו של הכועס."],[1,"ואי תימא הא","וכו': ואם תאמר, הרי יש כעס חכמים. ומשיב, כעסם של חכמים טוב הוא לכל הצדדים. כי למדנו, שהתורה אש היא, והתורה מרתיחה אותו, שכתוב, הלא דברי כאש נאם ה'. כעס חכמים הוא בדברי תורה. כעס חכמים הוא לתת כבוד לתורה. והכל לעבודת ה' הוא. לכך נאמר, כי ה' אלקיך אש אוכלה הוא אל קנא."],[2,"אבל אי במלין","וכו': אבל אם הכעס הוא בדברים אחרים ולא בדברי תורה, אין זה עבודת הקב\"ה משום שבכל החטאים שעושה האדם אינם עבודה זרה ממש כמו הכועס, אסור לקרב אל זה. ואם תאמר, הרי לשעה הוא עבר וכעס, ואח\"כ חזר בתשובה. אינו כן, כי כיון שעקר קדושת נפשו ממנו וממקומה, ואותו אל זר, עשק מקום ההוא, הוא מתחזק בו ואינו עוזב אותו. חוץ כשנטהר האדם מכל וכל, ועקר מתוכו את אל זר לעולם. ואח\"כ השתדל להתקדש ולהמשיך קדושה עליו, אז הלואי שיתקדש. א\"ל ר' יוסי הוא מתקדש ממש."],[3,"א\"ל ת\"ח בשעתא","וכו': אמר לו, בוא וראה בשעה שהוא עוקר קדושת נפשו, ושורה במקומה אל זר ההוא הנקרא טמא, נטמא האדם, ומטמא את מי שקרב אליו, וקדושה ההיא נעקרה ממנו, וכיון שנעקרה ממנו פעם אחת, כמה שעשה האדם, לא תשוב עוד למקומה."],[4,"א\"ל אי הכי","וכו': אמר לו אם כן, כמה טמאים הם שמטהרים. אמר לו משונה הוא טומאה אחרת, שאינו יכול לעשות יותר מלטמא אותו בחוץ. אבל זה הכועס משונה מכל, שכל גופו טימא מפנים ומחוץ, והנפש והכל מטמא. ושאר טומאות העולם אינו מטמא אלא הגוף מבחוץ בלבד. ומשום זה כתוב, חדלו לכם מן האדם אשר נשמה באפו, דהיינו, שהחליף קדושת רבונו בשביל כעסו. שזה הוא טומאה שמטמא לכל. כי \u0003במה\u0004 נחשב הוא, במה של עבודה זרה, ודאי נחשב הוא."],[5,"ת\"ח האי איהו","וכו': בוא וראה, הכעס הזה שהוא עבודה זרה, סטרא אחרא, כמו שאמרנו, שצריך האדם להשמר ממנו ולהפרד מעליו, וע\"כ כתוב, אלהי מסכה לא תעשה לך. \u0003לך\u0004 פירושו, שלא להרע לעצמך, וכתוב אחריו, את חג המצות תשמר. תשמר, היינו צד הקדושה, שאדם צריך לשמרה ולא יחליף אותה בסטרא אחרא. ואם החליפה בס\"א, הרי הוא טמא, ומטמא כל מי שקרב אליו."],[6,"את חג המצות תשמר:","זה הוא מקום שנקרא שמור. דהיינו המלכות הנקראת שמור, ומשום זה כתוב, את חג המצות תשמר שבעת ימים תאכל מצות כאשר צויתיך. שבעת ימים אלו של חג המצות, אינם כשבעת הימים של סוכות, כי של סוכות המה עליונים דהיינו ז\"ס חג\"ת נהי\"מ דבינה, שזו\"ן עלו והלבישו אותם. ואלו של חג המצות המה תחתונים, דהיינו ז\"ס חג\"ת נהי\"מ של המלכות, וע\"כ באלו של סוכות אומרים הלל שלם ובאלו של חג המצות אין אומרים הלל שלם. ומשום שהם ז' ימים שלמטה, של המלכות, כתוב, שבעת ימים תאכל מצת, מצת כתוב חסר, בלי \u0003ו,\u0004 להורות, כי טרם שרו עליהם ימים עליונים של סוד ה \u0003ו',\u0004 שהוא ז\"א."],[7,"ואי תימא כיון","וכו': ואם תאמר, כיון שסוד הזה של חג המצות נתקדש, כי בלילה הא' דפסח, נתקדשו זו\"ן, וקבלו המוחין דאו\"א עלאין, דהיינו שעלו והלבישו אותם א\"כ למה ירדה שוב המלכות למטה ממקומה, הרי למדנו מעלין בקודש ואין מורידין, ולמה ירדה מאו\"א למטה באלו ז' ימים תחתונים."],[8,"ת\"ח כתיב וכפר","וגו': בוא וראה, כתוב וכפר בעדו ובעד ביתו וגו', להורות, שמי שמכפר, צריך לכפר על עצמו תחילה, ואח\"כ על ביתו, כעין זה, מדרגה זו, דהיינו המלכות, התחילה להתקדש ולצאת בקדושה, בלילה הא' דפסח, כדי לכפר על עצמה, וכיון שהיא נתקדשה, צריכה לכפר על ביתה ולקדש אותם וע\"כ ירדה למטה, לקדש ביתה. ובמה מקדש אותם, הוא על ידי ישראל שלמטה. וכיון שאלו נתקדשו צריכים להעלות אותה למעלה כי כשבית המטרוניתא. שהיא המלכות, מתקדש, אז עולית למעלה להתקשר בימים העליונים למעלה."],[8,"","פירוש. נודע שאין העדר ברוחניות, וכל שינוי מקום אין הפירוש שעזב ונעדר מן מקום ראשון ובא למקום הב', אלא תוספת מקום יש כאן, שנשאר כולו במקום ראשון וגם בא למקום הב'. ולפי\"ז בלילה הא' דפסח שזו\"ן עלו לאו\"א, והנוקבא נתקנה במוחין דאו\"א, הרי נשארה הנוקבא גם במקומה למטה. וז\"ס חג\"ת נהי\"מ דנוקבא שנשארו למטה במקומה, מכונים \u0003בית\u0004 הנוקבא, כי דומה כמו שהנוקבא עלתה למעלה ולא לקחה עמה ביתה, ונמצא שהתקון הגדול שקבל הנוקבא בלילה א' דפסח, לא הגיע כלום לביתה שנשאר למטה."],[8,"","וזה אמרו, \u0003מאן דיכפר\u0004 וכו' \u0003שארי לאתקדשא ולנפקא בקדושה לכפרא עליה.\u0004 שבליל א' דפסח התחילה להתקדש בבחינת \u0003וכפר בעדו,\u0004 שהיא עצמה קבלה התקון מחמת עלותה, \u0003וכיון דאיהו אתקדש בעי לכפרא על ביתיה,\u0004 כי ביתה, דהיינו ז\"ס חג\"ת נהי\"מ שלה שנשארו למטה שלא עלו עמה, עוד לא קבלו כפרה, דהיינו מוחין דאמא המכונים כפרה, בסוד יום הכפורים שהיא אמא, \u0003ועל דא נחתא לתתא דקדשא ביתיה,\u0004 וע\"כ אחר לילה א' דפסח ירדה המלכות מאו\"א למקומה למטה כדי לקדש ז\"ס שלה שנשארו למטה. \u0003ובמה מקדש לון בישראל דלתתא,\u0004 דהיינו עי\"ז שישראל מקיימים את חג המצות תשמר שבעת ימים, שבזה מתתקנים ז' ימים תג\"ת נהי\"מ שלה שנשארו למטה המכונים ביתה, בסוד \u0003ובעד ביתו.\u0004 כנ\"ל. \u0003וכיון דאלין מתקדשא בעינן לסלקא לה\u0004 וכו', ואחר שז' ימים אלו קבלו תיקון במקומם, צריכים להעלות שוב את המלכות לאו\"א, שזה נעשה ע\"י ספירת העומר, כמו שמבאר והולך."]],[[0,"","וּמִי שֶׁמִּתְחַבֵּר עִמּוֹ וּמִי שֶׁמְּדַבֵּר עִמּוֹ, כְּמִי שֶׁמִּתְחַבֵּר בְּכוֹכָבִים וּמַזָּלוֹת מַמָּשׁ. מָה הַטַּעַם? מִשּׁוּם שֶׁכּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ שׁוֹרִים בְּתוֹכוֹ. וְלֹא עוֹד, אֶלָּא שֶׁעוֹקֵר קְדֻשָּׁה עֶלְיוֹנָה מִמְּקוֹמָהּ, וּמַשְׁכִּין בִּמְקוֹמָהּ עֲבוֹדָה זָרָה אֵל זָר. מָה אֵל זָר כָּתוּב בּוֹ (ויקרא יט) אַל תִּפְנוּ אֶל הָאֱלִילִים - כְּדֻגְמַת זֶה אָסוּר לְהִסְתַּכֵּל בְּפָנָיו."],[1,"","וְאִם תֹּאמַר, הֲרֵי רֹגֶז שֶׁל חֲכָמִים - רֹגֶז שֶׁל הַחֲכָמִים טוֹב הוּא לְכָל הַצְּדָדִים, שֶׁהֲרֵי לָמַדְנוּ שֶׁהַתּוֹרָה הִיא אֵשׁ, וְהַתּוֹרָה הִיא מַרְתִּיחָה אוֹתוֹ, שֶׁכָּתוּב (ירמיה כג) הֲלוֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. רֹגֶז שֶׁל חֲכָמִים בְּדִבְרֵי תוֹרָה. רֹגֶז שֶׁל חֲכָמִים לָתֵת כָּבוֹד לַתּוֹרָה, וְהַכֹּל לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא הָיָה, לְכָךְ נֶאֱמַר (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא אֵל קַנָּא."],[2,"","אֲבָל אִם בִּדְבָרִים אֲחֵרִים, לֹא עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא זֶה, לְפִי שֶׁבְּכָל הַחֲטָאִים שֶׁעוֹשֶׂה הָאָדָם, הִיא לֹא עֲבוֹדָה זָרָה מַמָּשׁ כְּמוֹ זֶה, וְאָסוּר לְהִתְקָרֵב בְּקִרְבָתוֹ שֶׁל זֶה. וְאִם תֹּאמַר, זֶה לְפִי שָׁעָה הָיָה, שֶׁעָבַר וְאַחַר כָּךְ חָזַר - לֹא כָּךְ. שֶׁכֵּיוָן שֶׁעָקַר הַקְּדֻשָּׁה שֶׁל נַפְשׁוֹ מִמֶּנּוּ וּמִמְּקוֹמוֹ, וְאוֹתוֹ אֵל זָר מְקַפֵּחַ הַמָּקוֹם הַהוּא, מִתְחַזֵּק בּוֹ וְלֹא עוֹזֵב אוֹתוֹ, חוּץ מִכַּאֲשֶׁר נִטְהָר הָאָדָם מִכֹּל וָכֹל וְעוֹקֵר אוֹתוֹ לְעוֹלָמִים, וְאַחַר כָּךְ מִשְׁתַּדֵּל לְהִתְקַדֵּשׁ וּלְהַמְשִׁיךְ קְדֻשָּׁה עָלָיו, וְאָז הַלְוַאי וְיִתְקַדֵּשׁ. אָמַר לוֹ רַבִּי יוֹסִי, מִתְקַדֵּשׁ מַמָּשׁ. (למה, ' והרי נדחה והתקדש)."],[3,"","אָמַר לוֹ, בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהוּא עוֹקֵר קְדֻשָּׁה שֶׁל נַפְשׁוֹ, וְשׁוֹכֵן בִּמְקוֹמוֹ הָאֵל זָר הַהוּא שֶׁנִּקְרָא טָמֵא, נִטְמָא הָאָדָם וּמְטַמֵּא לְמִי שֶׁקָּרֵב עִמּוֹ, וְהַקְּדֻשָּׁה הַהִיא בּוֹרַחַת מִמֶּנּוּ. וְכֵיוָן שֶׁבּוֹרַחַת מִמֶּנּוּ פַּעַם אַחַת, כָּל מַה שֶּׁיַּעֲשֶׂה הָאָדָם עוֹד, לֹא תָשׁוּב לִמְקוֹמָהּ."],[4,"","אָמַר לוֹ, אִם כֵּן, כַּמָּה טְמֵאִים יֵשׁ שֶׁמְּטַהֲרִים? אָמַר לוֹ, שׁוֹנָה טֻמְאָה אַחֶרֶת שֶׁלֹּא יְכוֹלָה לַעֲשׂוֹת יוֹתֵר. אֲבָל זֶה מְשֻׁנֶּה מִכֻּלָּם, שֶׁכָּל גּוּפוֹ נִטְמָא מִבִּפְנִים וּמִבַּחוּץ, וְנַפְשׁוֹ וְכֻלּוֹ נִטְמָא. וּשְׁאָר טֻמְאוֹת שֶׁבָּעוֹלָם לֹא נִטְמָא אֶלָּא גוּפוֹ מִבַּחוּץ בִּלְבַד, וְלָכֵן כָּתוּב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, שֶׁמַּחֲלִיף קְדֻשַּׁת רַבּוֹ מִשּׁוּם אַפּוֹ, שֶׁזּוֹהִי טֻמְאָה שֶׁמְּטַמְּאָה הַכֹּל. כִּי בַמֶּה נֶחְשָׁב הוּא - בָּמָה שֶׁל עֲבוֹדָה זָרָה וַדַּאי נֶחְשָׁב הוּא."],[5,"","בֹּא וּרְאֵה, זֶהוּ רֹגֶז שֶׁל עֲבוֹדָה זָרָה, הַצַּד הָאַחֵר, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁרוֹצֶה הָאָדָם לְהִשָּׁמֵר מִמֶּנּוּ וּלְהִפָּרֵד מֵעָלָיו, וְעַל זֶה כָּתוּב (שמות לד) אֱלֹהֵי מַסֵּכָה לֹא תַעֲשֶׂה לָּךְ. לָּךְ - כְּדֵי לְהָרַע לְךְ. וְכָתוּב אַחֲרָיו, אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. תִּשְׁמֹר - זֶה צַד הַקְּדֻשָּׁה שֶׁצָּרִיךְ הָאָדָם לִשְׁמֹר אוֹתוֹ וְלֹא יַחֲלִיף אוֹתוֹ בִּגְלַל הַצַּד הָאַחֵר. וְאִם יַחֲלִיף אוֹתוֹ, הֲרֵי הוּא טָמֵא, וּמְטַמֵּא לְכָל מִי שֶׁמִּתְקָרֵב אֵלָיו."],[6,"","אֶת חַג הַמַּצּוֹת תִּשְׁמֹר - זֶהוּ מָקוֹם שֶׁנִּקְרָא שָׁמוֹר. וּמִפְּנֵי כֵן כָּתוּב אֶת חַג הַמַּצּוֹת תִּשְׁמֹר, שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת כַּאֲשֶׁר צִוִּיתִךְ. שִׁבְעַת יָמִים אֵלּוּ אֵינָם כְּשִׁבְעַת הַיָּמִים שֶׁל סֻכּוֹת, שֶׁהֵם עֶלְיוֹנִים, וְאֵלּוּ תַחְתּוֹנִים. וְעַל זֶה, בְּאֵלּוּ הַלֵּל גָּמוּר, וּבְאֵלּוּ אֵין הַלֵּל גָּמוּר, וְעַל שֶׁהֵם לְמַטָּה - שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת. מַצּת כָּתוּב חָסֵר בְּלִי אוֹת ו', שֶׁטֶּרֶם שׁוֹרִים אֵלּוּ הַיָּמִים הָעֶלְיוֹנִים, סוֹד אוֹת ו'."],[7,"","וְאִם תֹּאמַר, כֵּיוָן שֶׁסּוֹד זֶה שֶׁל חַג הַמַּצּוֹת הִתְקַדֵּשׁ, מַדּוּעַ יוֹרֵד? שֶׁהֲרֵי לָמַדְנוּ, מַעֲלִים בַּקֹּדֶשׁ וְלֹא מוֹרִידִים. וּמַדּוּעַ יוֹרֶדֶת לְמַטָּה בְּאֵלּוּ הַיָּמִים הַתַּחְתּוֹנִים?"],[8,"","בֹּא וּרְאֵה, כָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ וְגוֹ'. מִי שֶׁיְּכַפֵּר צָרִיךְ (לכפר) עַל עַצְמוֹ תְחִלָּה, וְאַחַר כָּךְ עַל בֵּיתוֹ. כְּדֻגְמַת זֶה, מַדְרֵגָה זוֹ מַתְחִילָה לְהִתְקַדֵּשׁ וְלָצֵאת בִּקְדֻשָּׁה לְכַפֵּר עָלָיו, וְכֵיוָן שֶׁהוּא הִתְקַדֵּשׁ, צָרִיךְ לְכַפֵּר עַל בֵּיתוֹ וּלְקַדֵּשׁ אוֹתָם, וְעַל זֶה יוֹרֵד לְמַטָּה לְקַדֵּשׁ בֵּיתוֹ. וּבַמֶּה מְקַדֵּשׁ לָהֶם? בְּיִשְׂרָאֵל שֶׁלְּמַטָּה, בְּחֶשְׁבּוֹן הָעֹמֶר. וְכֵיוָן שֶׁאֵלּוּ מִתְקַדְּשִׁים, צְרִיכִים לְהַעֲלוֹת אוֹתָהּ לְמַעְלָה. שֶׁהֲרֵי כַּאֲשֶׁר בֵּית הַמַּלְכָּה מִתְקַדֵּשׁ, אָז עוֹלֶה לְמַעְלָה, לְהִתְקַשֵּׁר בְּאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים לְמַעְלָה."]]],[["וְעַל דָּא אֲנָן עַבְדִּין חוּשְׁבָּנָא, בְּקִיּוּמָא עַל קַיְימִין, בְּגִין דְּאִינּוּן יוֹמִין, יוֹמִין עִלָּאִין אִינּוּן, וְכֵן בְּכָל זִמְנָא דְּעָאל בַּר נָשׁ לְאִינּוּן יוֹמִין עִלָּאִין, בֵּין בִּצְלוֹתָא, בֵּין בִּשְׁבָחָא, אִצְטְרִיךְ לְקַיְּימָא עַל רַגְלוֹי, יַרְכִּין וְגוּפָא כַּחֲדָא תַּמָּן. יַרְכִּין וְגוּפָא לְקַיְּימָא, כִּדְכוּרָא דְּקַיְּימָא בְּחֵילֵיהּ, וְלָא כְּנוּקְבָא דְּאָרְחָהָא לְמֵיתַב. וְעוֹד בְּגִין שְׁבָחָא דְּעָלְמָא עִלָּאָה.","וּבְגִין דְּאִיהוּ רָזָא דִּדְכוּרָא, נָשִׁים פְּטוּרוֹת מֵחוּשְׁבָּנָא דָּא, וְלָא מִתְחַיְיבָן לְמִימְנִי בַּר דְּכוּרִין, לְאִתְקַשְּׁרָא כָּל חַד כְּדְקָא יֵאוֹת. כְּגַוְונָא דָּא, (שמות כ״ג:י״ז) יֵרָאֶה כָּל זְכוּרְךָ, דְּכוּרִין, וְלָא נָשִׁין. בְּגִין דְּרָזָא דִּבְרִית בִּדְכוּרָא אִיהוּ, וְלָא בְּנוּקְבָּא, וּבְגִין דְּקַיְּימָא רָזָא לְעֵילָּא, נָשִׁין לָא מִתְחַיְיבָן.","וְרָזָא אוֹלִיפְנָא הָכָא, דִּבְכָל שִׁבְעַת יוֹמִין, מֵאִלֵּין יוֹמִין עִלָּאִין, נַטְלָא קְדוּשָּׁא יוֹמָא חַד (ומתאחד) דְּאִלֵּין תַּתָּאֵי, וְהַאי תַּתָּאָה אִקְרֵי שָׁבוּעַ, דְּאִתְקַדָּשׁ בְּשִׁבְעָה יוֹמִין עִלָּאִין. וְכֵן בְּכָל שִׁבְעָה וְשִׁבְעָה מֵאִינּוּן חַמְשִׁין יוֹמִין, עַד וְלָא עַד בִּכְלָל, וְכַד אִשְׁתְּכָחוּ אַרְבְּעִין וּתֵשַׁע יוֹמִין עִלָּאִין, אִשְׁתְּכָחוּ לְתַתָּא שֶׁבַע יוֹמִין, דְּאִתְקַדָּשׁוּ בְּהוּ וְכָל חַד אִקְרֵי שָׁבוּעַ, דְּעָאל בְּאִינּוּן שֶׁבַע. וְעַל דָּא כְּתִיב, (ויקרא כ״ג:ט״ו) שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת תִּהְיֶינָה. בְּגִין דְּאִינּוּן נוּקְבִין, נָקַט קְרָא לִישָׁנָא דְּנוּקְבִין.","וְכַד אִתְקַדָּשׁוּ בְּהוּ, וּבֵיתָא, מִתַּתְקְנָא לְאִתְחַבְּרָא אִתְּתָא בְּבַעְלָהּ, כְּדֵין אִקְרֵי חַג שָׁבוּעוֹת, מֵאִינוּן נוּקְבֵי דְּשָׁארוּ עָלַיְיהוּ אִינּוּן יוֹמִין עִלָּאִין, דְּאִתְקַדָּשׁוּ בְּהוּ. וּבְּגִין כָּךְ כְּתִיב בְּשָׁבוּעוֹתֵיכֶם, אִינּוּן דִּלְכוֹן, וְלָא כְּתִיב בְּשָׁבוּעוֹת, בְּגִין דְּהָכִי נָמֵי מִתְקַדְּשִׁין יִשְׂרָאֵל לְתַתָּא עִמְּהוֹן.","וְעַל דָּא כַּד מָטוּן לְתֵשַׁע וְאַרְבְּעִין יוֹמִין, הַהוּא יוֹמָא עִלָּאָה דְּעָלַיְיהוּ, דְּאִיהוּ יוֹמָא דְּחַמְשִׁין, דְּשַׁלִּיט עַל תִּשְׁעָה וְאַרְבְּעִין יוֹמִין, רָזָא דִּכְלָלָא דְּאוֹרַיְיתָא, בְּתִשְׁעָה וְאַרְבְּעִין אַנְפִּין, וּכְדֵין הַהוּא יוֹמָא עִלָּאָה, יוֹמָא דְּחַמְשִׁין, בְּאִתְעָרוּתָא דִּלְתַתָּא, אַפִּיק אוֹרַיְיתָא כְּלָלָא בְּתִשְׁעָה וְאַרְבְּעִין אַנְפִּין.","רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהילים פ״ד:ד׳) גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ אֲשֶׁר שָׁתָה אֶפְרוֹחֶיהָ אֶת מִזְבְּחוֹתֶיךָ וְגוֹ'. גַּם צִפּוֹר מָצְאָה בַיִת, אִלֵּין צִפֳּרֵי שְׁמַיָא, דְּמִנְּהוֹן שַׁוְיָין מָדוֹרֵיהוֹן לְבַר, וּמִנְּהוֹן שַׁוְיָין מָדוֹרֵיהוֹן בְּבֵיתָא, כְּגוֹן דְּרוֹר, דְּאִיהוּ עוֹפָא דְּשַׁוֵּי דִּיוּרֵיהּ בְּבֵיתָא דְּכָל בַּר נָשׁ, וְלָא דָּחִיל. אֲמַאי. בְּגִין דְּכֹלָּא קָרָאן לֵיהּ דְּרוֹר. מַאי דְּרוֹר. חִירוּ, כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ה:י׳) וּקְרָאתֶם דְּרוֹר, וְתַרְגּוּמוֹ חִירוּ. וְדָא אִיהוּ צִפּוֹר דְּרוֹר. דְּהָא מִיּוֹמָא דְּעָבִיד קִנָּא בְּבֵיתָא אַפִּיק בְּנִין, מָדוֹרֵיהּ בְּבֵיתָא חַמְשִׁין יוֹמִין, וּלְבָתַר מִתְפָּרְשָׁן אִלֵּין מֵאִלֵּין, וְדָא הוּא עוֹפָא דְּאִקְרֵי דְּרוֹר: חִירוּ.","תָּא חֲזֵי מַה כְּתִיב, וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר בָּאָרֶץ. מֵהָכָא נָפְקָא חִירוּ לְכֹלָּא, וּבְגִין דְּנָפְקָא מִנֵּיהּ חִירוּ, אוֹרַיְיתָא דְּנַפְקַת מִנֵּיהּ אִקְרֵי חִירוּ. וְעַל דָּא כְּתִיב, (שמות ל״ב:ט״ז) חָרוּת עַל הַלֻּחֹת, אַל תִּקְרֵי חָרוּת, אֶלָּא חֵירוּת, וְדָא אוֹרַיְיתָא דְּאִתְקְרֵי חֵירוּת דְּהָא מָה דְּאַפִּיק יוֹמָא דָּא עִלָּאָה, אִקְרֵי חִירוּ, וְאִיהוּ חִירוּ דְּכֹלָּא. וְהַאי יוֹמָא אִיהוּ חִירוּ עִלָּאָה, בְּגִין דְּאִית חִירוּ תַּתָּאָה, וְחִירוּ עִלָּאָה. הֵ\"א עִלָּאָה, הֵ\"א תַּתָּאָה. חִירוּ עִלָּאָה. חִירוּ תַּתָּאָה שְׁמִטָּה וְיוֹבֵל כַּחֲדָא אִינּוּן.","תְּרֵין נַהֲמֵי אָכְלוּ יִשְׂרָאֵל, חַד, כַּד נָפְקוּ מִמִּצְרַיִם, אָכְלוּ מַצָּה, לֶחֶם עוֹנִי. וְחַד בְּמַדְבְּרָא, לֶחֶם מִן הַשָּׁמַיִם. (חד בפסח וחד בשבועות) דִּכְתִּיב, (שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם וְעַל דָּא קָרְבָּנָא דְּיוֹמָא דָּא נָהֲמָא אִיהוּ. וְעַל נָהֲמָא, אִתְקְרִיבוּ כָּל שְׁאַר קָרְבָּנִין. דְּנָהֲמָא אִיהוּ עִקָר, דִּכְתִּיב, (ויקרא כ״ג:י״ח) וְהִקְרַבְתֶּם עַל הַלֶּחֶם שִׁבְעַת כְּבָשִׂים וְגוֹ', וּכְתִיב (ויקרא כ״ג:י״ז) מִמּוֹשְׁבוֹתֵיכֶם תָּבִיאוּ לֶחֶם תְּנוּפָה וְגוֹ', דְּדָא אִיהוּ נָהֲמָא דְּאֲחְכִּימוּ בֵּיהּ יִשְׂרָאֵל, חָכְמְתָא עִלָּאָה דְּאוֹרַיְיתָא, וְעָאלוּ בְּאָרְחָהָא.","הַשְׁתָּא אִית לָן לְאִסְתַּכְּלָא, בַּפֶּסַח נָפְקוּ יִשְׂרָאֵל מִנָּהֲמָא דְּאִתְקְרֵי חָמֵץ, כְּתִיב, (שמות י״ג:ז׳) וְלָא יֵרָאֶה לְךָ חָמֵץ, וּכְתִיב (שמות י״ב:י״ט) כִּי כָּל אוֹכֵל מַחְמֶצֶת מַאי טַעֲמָא. בְּגִין יְקָרָא דְּהַהוּא נַהֲמָא דְּאִתְקְרֵי מַצָּה. הַשְׁתָּא דְּזָכוּ יִשְׂרָאֵל לְנַהֲמָא עִלָּאָה יַתִּיר לָא יֵאוֹת הֲוָה לְאִתְבַּטְּלָא חָמֵץ, וְלָא אִתְחַזְיָא כְּלַל. וַאֲמַאי קָרְבָּנָא דָּא, חָמֵץ הֲוָה, דִּכְתִּיב סֹלֶת תִּהְיֶינָה חָמֵץ תֵּאָפֶינָה. וְתוּ, דְּהַשְׁתָּא בְּיוֹמָא דָּא אִתְבָּטַּל יֵצֶר הָרָע, וְאוֹרַיְיתָא דְּאִתְקְרֵי חִירוּ אִשְׁתְּכַחַת."],[[0,"ועל דא אנן","וכו': ועל זה אנו עושים חשבון דהיינו שסופרים ספירת העומר, בעמידה על רגלים, משום שאלו הימים שאנו סופרים, הם ימים העליונים. דהיינו הספירות של ז\"א, שהוא דכר. וכן בכל זמן שאדם נכנס באלו ימים עליונים של ז\"א, בין בתפילה ובין בשבח, צריך האדם לעמוד על רגליו, שהירכים והגוף משמשים שם בז\"א בשוה יחד. והירכים והגוף צריכים לעמוד כזכר העומד בכחו, ולא כנקבה, שדרכה לשבת. ועוד, משום השבח של עולם העליון צריכים לעמוד."],[0,"","פירוש שאור הזכר מאיר מלמעלה למטה, שהיא בחינת ג\"ר, וע\"כ כל הראש תוך וסוף שלו, שהם חב\"ד חג\"ת נה\"י צריכים לשמש בהלבשת האור. וע\"כ צריך גם האדם שהוא בתפלה או בשבח לז\"א, שהוא דכר, לעמוד על רגליו, שגם נה\"י שלו שנקראים רגלים יהיו בשמוש. אבל אור הנקבה, מאיר מלמטה למעלה, שהוא בחינת ו\"ק וחסר ג\"ר, ע\"כ אינם צריכים רק ראש ותוך, שהם חב\"ד חג\"ת דכלים שילבישו האורות דרוח נפש, ונמצאים הנה\"י שה\"ס הרגלין פנוים בלי אור, ואינם משמשים כלום, כמו היושב בכסא, שהרגלים הם בלי שמוש. וע\"כ כשהאדם בשבחות או בתפלה אל המלכות שהוא נקבה, צריך גם האדם להיות בישיבה, ולא ישמש ברגליו (ועי' בפתיחה לחכמת הקבלה אות כ\"ד,) שיש ערך ההפכי בין כלים לאורות, שהחסר נה\"י דכלים הוא חסר ג\"ר באורות."],[1,"ובגין דאיהו רזא","וכו': ומשום שספירת העומר, הוא סוד הזכר, שממשיכים ספירות העליונים דז\"א, הנשים פטורות מספירה זו ואינן מחויבות לספור אלא הזכרים בלבד, להתקשר כל אחד כראוי, כעין זה, יראה כל זכורך, שהזכרים מחויבים להראות ולא נשים. משום שסוד הברית הוא בזכר ולא בנקבה, ומשום שהסוד הוא למעלה בזכר, בז\"א, נשים אינן מחויבות."],[2,"ורזא אוליפנא הכא","וכו': וסוד למדנו כאן, שבכל שבעת ימים מאלו ימים העליונים, דז\"א, מקבל קדושה יום אחד מאלו התחתונים, של המלכות, ויום תחתון הזה של המלכות נקרא \u0003שבוע,\u0004 משום שנתקדש משבעה ימי העליונים. וכן בכל שבעה ושבעה מאלו חמשים ימים העליונים, עד יום החמשים ולא עד בכלל, כלומר, שיום החמשים אינם בכלל המתקנים לימים תחתונים, וכשנמצא מ\"ט ימים עליונים נמצאים למטה במלכות שנתקדשו שבעה ימים שלה. כי כל יום נתתקן ע\"י שבעה ימים העליונים, שע\"י חג\"ת נהי\"מ דחסד דז\"א מתתקן חסד דמלכות וע\"י חג\"ת נהי\"מ דגבורה דז\"א מתתקנת גבורה דמלכות וכו' עד\"ז. וכל אחד שנתקן במלכות, נקרא \u0003שבוע,\u0004 משום שנכנס באלו שבעה ימים העליונים, וע\"כ כתוב, שבע שבתות תמימות תהיינה, שיורה על ז' ימים התחתונים שהם חג\"ת נהי\"מ דמלכות שכל אחד נקרא שבוע, ומשום שהם נקבות, להיותם ז\"ס דמלכות, אחז הכתוב לשון נקבה בהן, שנאמר, שבתות תמימות תהיינה."],[3,"וכד אתקדשו בהו","וכו': וכשז\"ס דמלכות נתקדשו בהם, במ\"ט ספירות העליונות, והבית, שהם ז\"ס דמלכות שלא קבלו תקונים בלילה הא' דפסח (כנ\"ל אות ס\"ד ד\"ה פירוש) נתתקן להתחבר אשה בבעלה, דהיינו שתתחבר המלכות עם ז\"א, אז נקרא חג השבועות על שם אלו הנוקבות, דהיינו ז\"ס דמלכות הנקראים ז' שבועות כנ\"ל, ששורים עליהם אלו ימים העליונים, שהם מ\"ט ימים דז\"א, שנתקדשו בהם. ומשום זה כתוב, \u0003בשבועותיכם,\u0004 שהמשמעות שהם שלכם, ולא כתוב, בשבועות, משום שכמו שנתקדשו ז\"ס דמלכות שנקראים שבועות, נתקדשו גם כן ישראל למטה עמהם. כי ישראל למטה תלויים בקדושת המלכות, שממנה הם מקבלים, וע\"כ נאמר בשבועותיכם."],[4,"ועל דא כד","וכו': וע\"כ כשמגיעים למ\"ט ימים, יום ההוא העליון שעליהם, שהוא יום החמשים, שהוא בינה, השולט על מ\"ט ימים, דהיינו מ\"ט ספירות דז\"א, שהם סוד כלל התורה, דהיינו ז\"א הנקרא תורה, שיש בה מ\"ט פנים, אז יום ההוא העליון, שהוא יום החמשים, בינה, ע\"י התעוררות התחתונים, הוציא התורה, שהוא ז\"א, דהיינו המוחין דג\"ר שלו, שהיא כלל מ\"ט פנים, שנתקנו ע\"י ספירת מ\"ט ימים."],[5,"ר' אלעזר פתח","וכו': ר\"א פתח ואמר, גם צפור מצאה בית ודרור קן לה אשר שתה אפרוחיה את מזבחותיך וגו'. \u0003גם צפור מצאה בית.\u0004 אלו הם צפרי השמים, שמהם עושים קן שלהם בחוץ. ומהם שעושים קן שלהם בבית דירתו של אדם, כמו דרור, שהוא עוף המשים קנו בבית כל אדם, ואינו מפחד. למה, משום שהכל קוראים אותו \u0003דרור,\u0004 מהו דרור. הוא חירות. כמש\"א, וקראתם דרור, ותרגומו חירו. וזה הוא צפור דרור. כי מיום שעושה קן בבית ומוציא בנים, הוא דר בבית חמשים יום. ואח\"כ נפרדים אלו מאלו. וזהו עוף שנקרא דרור, שפירושו חירות. הרומז לבינה. והמלכות נקראת צפור."],[6,"תא חזי, מה","וכו': בוא וראה מה כתוב, וקדשתם את שנת מחמשים שנה וקראתם דרור בארץ. שנת החמשים הוא בינה, שמכאן יוצאת חירות לכל. ומשום שיוצאת ממנו חרות, התורה היוצאת מבינה, נקרא חירות, וע\"כ כתוב, חרות על הלחת. אל תקרי חרות אלא חירות. שזה הוא התורה הנקראת חירות. כי מה שיום זה העליון, דהיינו בינה, מוציא, נקרא חירות, והוא חירות לכל. ויום ההוא הוא חירות עליון, משום שיש חירות תחתון וחירות עליון, דהיינו \u0003ה'\u0004 עליונה שהיא בינה ו \u0003ה'\u0004 תחתונה שהיא מלכות. חירות עליון וחירות תחתון שהם שמטה שהיא מלכות, ויובל שהיא בינה, הם כאחד, דהיינו שמלבישים זה את זה, ואז הבינה נקראת חירות עליון והמלכות חירות תחתון."],[7,"תרין נהמי אכלי","וכו': שני מיני לחם אכלו ישראל. אחד, כשיצאו ממצרים אכלו מצה לחם עוני שהוא לחם מן המלכות. ואחד, במדבר, שאכלו לחם מן השמים שהוא לחם דז\"א, שנקרא שמים. שכתוב, הנני ממטיר לכם לחם מן השמים. ועל כן הקרבן של יום הזה של חג השבועות, הוא לחם, ועל הלחם נקרב כל שאר הקרבנות, הלחם הוא עיקר, שכתוב, והקרבתם על הלחם שבעת כבשים וגו' ממושבותיכם תביאו לחם תנופה וגו'. שזה הוא לחם שהחכימו בו ישראל חכמה עליונה של התורה. ובאו בדרכיה."],[8,"השתא אית לן לאסתכלא","וכו': עתה יש להסתכל, בפסח יצאו ישראל מהלחם שנקרא חמץ. שכתוב, ולא יראה לך חמץ. וכתוב כי כל אוכל מחמצת. מהו הטעם יצאו מחמץ, הוא משום הכבוד של לחם ההוא שנקרא מצה. ושואל, עתה שזכו ישראל ללחם עליון יותר, ללחם דז\"א, לא יפה היה שיתבטל החמץ ולא יראה כלל. ולמה קרבן זה של לחם הבכורים היה חמץ, שכתוב, סלת תהיינה חמץ תאפינה. עוד, הרי ביום הזה נתבטל היצר הרע, שה\"ס חמץ. כי התורה שנקרא חירות נמצאת ולמה הביאו חמץ."]],[[0,"","וְעַל זֶה אָנוּ עוֹשִׂים חֶשְׁבּוֹן בַּעֲמִידָה עַל הָרַגְלַיִם, לְפִי שֶׁאֵלּוּ הַיָּמִים, יָמִים עֶלְיוֹנִים הֵם. וְכֵן בְּכָל זְמַן שֶׁנִּכְנָס אָדָם לְאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים, בֵּין בִּתְפִלָּה בֵּין בְּשֶׁבַח, צָרִיךְ לַעֲמֹד עַל רַגְלָיו, הַיְרֵכַיִם וְהַגּוּף כְּאֶחָד שָׁם. יְרֵכַיִם וְגוּף לַעֲמִידָה כְּזָכָר שֶׁעוֹמֵד בְּכֹחוֹ, וְלֹא כִנְקֵבָה שֶׁדַּרְכָּהּ לָשֶׁבֶת. וְעוֹד, מִשּׁוּם שֶׁבַח שֶׁל הָעוֹלָם הָעֶלְיוֹן."],[1,"","וּמִשּׁוּם שֶׁהוּא סוֹד הַזָּכָר, נָשִׁים פְּטוּרוֹת מֵחֶשְׁבּוֹן זֶה, וְלֹא מְחֻיָּבִים לִמְנוֹת, רַק הַזְּכָרִים, לְהִתְקַשֵּׁר כָּל אֶחָד כְּמוֹ שֶׁצָּרִיךְ. כְּעֵין זֶה, (שמות כג) יֵרָאֶה כָל זְכוּרְךְ. זְכָרִים וְלֹא נָשִׁים. מִשּׁוּם שֶׁסּוֹד הַבְּרִית בְּזָכָר הוּא, וְלֹא בִנְקֵבָה, וּמִשּׁוּם שֶׁעֲמִידָה סוֹד לְמַעְלָה, נָשִׁים לֹא מִתְחַיְּבוֹת."],[2,"","וְסוֹד לָמַדְנוּ כָאן, שֶׁבְּכָל שִׁבְעַת הַיָּמִים מֵאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים נוֹטֶלֶת הַקְּדֻשָּׁה יוֹם אֶחָד (ומתאחד) שֶׁל אֵלּוּ הַתַּחְתּוֹנִים, וְזוֹ הַתַּחְתּוֹנָה נִקְרֵאת שָׁבוּעַ, שֶׁמִּתְקַדֵּשׁ בְּשִׁבְעָה יָמִים עֶלְיוֹנִים. וְכֵן בְּכָל שִׁבְעָה וְשִׁבְעָה מֵאֵלּוּ חֲמִשִּׁים יָמִים, עַד וְלֹא עַד בִּכְלָל. וְכַאֲשֶׁר נִמְצָאִים אַרְבָּעִים וְתִשְׁעָה יָמִים עֶלְיוֹנִים, נִמְצְאוּ לְמַטָּה שֶׁבַע יָמִים שֶׁמִּתְקַדְּשִׁים בָּהֶם, וְכָל אֶחָד נִקְרָא שָׁבוּעַ שֶׁעוֹלֶה בְאֵלּוּ הַשֶּׁבַע. וְעַל זֶה כָּתוּב (ויקרא כג) שֶׁבַע שַׁבָּתוֹת תְּמִימֹת תִּהְיֶינָה. מִשּׁוּם שֶׁאֵלּוּ נְקֵבוֹת, תָּפַס הַכָּתוּב לָשׁוֹן שֶׁל נְקֵבוֹת."],[3,"","וְכַאֲשֶׁר הִתְקַדְּשׁוּ בָהֶם וְהַבַּיִת נִתְקַן לְהִתְחַבֵּר אִשָּׁה בְּבַעְלָהּ, אָז נִקְרָא חַג הַשָּׁבוּעוֹת, מֵאוֹתָן נְקֵבוֹת שֶׁשּׁוֹרִים עֲלֵיהֶן אוֹתָם יָמִים עֶלְיוֹנִים שֶׁנִּתְקַדְּשׁוּ בָּהֶם. וּמִשּׁוּם זֶה כָּתוּב בְּשָׁבֻעֹתֵיכֶם, הֵם שֶׁלָּכֶם, וְלֹא כָתוּב בְּשָׁבוּעוֹת, לְפִי שֶׁכָּךְ גַּם מִתְקַדְּשִׁים יִשְׂרָאֵל לְמַטָּה עִמָּהֶם."],[4,"","וְעַל זֶה כַּאֲשֶׁר מַגִּיעִים לְתִשְׁעָה וְאַרְבָּעִים יָמִים, הַיּוֹם הַהוּא הָעֶלְיוֹן שֶׁעֲלֵיהֶם, שֶׁהוּא יוֹם הַחֲמִשִּׁים שֶׁשּׁוֹלֵט עַל תִּשְׁעָה וְאַרְבָּעִים יָמִים, סוֹד כְּלָלוּת הַתּוֹרָה, בְּתֵשַׁע וְאַרְבָּעִים פָּנִים, וְאָז הַיּוֹם הָעֶלְיוֹן הַהוּא, הַיּוֹם הַחֲמִשִּׁים, בְּהִתְעוֹרְרוּת שֶׁל מַטָּה, מוֹצִיא תוֹרָה כְּלוּלָה בְּתֵשַׁע וְאַרְבָּעִים פָּנִים."],[5,"","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים פד) גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ אֲשֶׁר שָׁתָה אֶפְרֹחֶיהָ אֶת מִזְבְּחוֹתֶיךְ וְגוֹ'. גַּם צִפּוֹר מָצְאָה בַיִת, אֵלּוּ צִפֳּרֵי שָׁמַיִם שֶׁמֵּהֶם שָׂמִים מְדוֹרֵיהֶם בַּחוּץ, וּמֵהֶם שָׂמִים מְדוֹרֵיהֶם בַּבַּיִת, כְּמוֹ הַדְּרוֹר, שֶׁהוּא עוֹף שֶׁעוֹשֶׂה דִירָתוֹ בְּבַיִת שֶׁל כָּל אָדָם וְלֹא מְפַחֵד. מַדּוּעַ? מִפְּנֵי שֶׁכֻּלָּם קוֹרְאִים לוֹ דְרוֹר. מַהוּ דְרוֹר? חֵרוּת, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) וּקְרָאתֶם דְּרוֹר, וְתַרְגּוּמוֹ חֵרוּת. וְזֶהוּ צִפּוֹר דְּרוֹר. שֶׁהֲרֵי מִיּוֹם שֶׁעוֹשֶׂה קֵן בְּבַיִת, מוֹצִיא בָנִים, מְגוּרָיו בַּבַּיִת חֲמִשִּׁים יָמִים, וּלְאַחֲרֵיהֶם נִפְרָדִים אֵלּוּ מֵאֵלּוּ, וְזֶהוּ עוֹף שֶׁנִּקְרָא דְרוֹר - חֵרוּת."],[6,"","בֹּא וּרְאֵה מַה כָּתוּב, וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר בָּאָרֶץ. מִכָּאן יוֹצֵאת חֵרוּת לְכֻלָּם. וּמִפְּנֵי שֶׁיּוֹצֵאת מִמֶּנּוּ חֵרוּת, תּוֹרָה שֶׁיּוֹצֵאת מִמֶּנּוּ נִקְרֵאת חֵרוּת. וְעַל זֶה כָּתוּב (שמות לב) חָרוּת עַל הַלֻּחֹת, אַל תִּקְרָא חָרוּת אֶלָּא חֵרוּת, וְזוֹ הַתּוֹרָה שֶׁנִּקְרֵאת חֵרוּת, שֶׁהֲרֵי מַה שֶּׁמּוֹצִיא יוֹם זֶה הָעֶלְיוֹן נִקְרָא חֵרוּת, וְהוּא חֵרוּת שֶׁל הַכֹּל. וְזֶה הַיּוֹם הוּא חֵרוּת עֶלְיוֹנָה, מִשּׁוּם שֶׁיֵּשׁ חֵרוּת תַּחְתּוֹנָה וְחֵרוּת עֶלְיוֹנָה. הֵ\"א עֶלְיוֹנָה, הֵ\"א תַחְתּוֹנָה. חֵרוּת עֶלְיוֹנָה. וְחֵרוּת תַּחְתּוֹנָה שְׁמִטָּה וְיוֹבֵל כְּאֶחָד הֵם."],[7,"","שְׁנֵי מִינֵי לֶחֶם אָכְלוּ יִשְׂרָאֵל: אֶחָד כַּאֲשֶׁר יָצְאוּ מִמִּצְרַיִם, אָכְלוּ מַצָּה, לֶחֶם עֹנִי. וְאֶחָד בַּמִּדְבָּר, לֶחֶם מִן הַשָּׁמַיִם (אחד בפסח ואחד בשבועות), שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. וְעַל זֶה קָרְבָּן שֶׁל יוֹם זֶה הוּא לֶחֶם. וְעַל לֶחֶם מַקְרִיבִים כָּל שְׁאָר קָרְבָּנוֹת, שֶׁהַלֶּחֶם הוּא הָעִקָּר, שֶׁכָּתוּב (ויקרא כג) וְהִקְרַבְתֶּם עַל הַלֶּחֶם שִׁבְעַת כְּבָשִׂים וְגוֹ', וְכָתוּב (שם) מִמּוֹשְׁבתֵיכֶם תָּבִיאוּ לֶחֶם תְּנוּפָה וְגוֹ'. שֶׁזֶּהוּ לֶחֶם שֶׁחָכְמוּ בוֹ יִשְׂרָאֵל, חָכְמָה עֶלְיוֹנָה שֶׁל הַתּוֹרָה, וְנִכְנְסוּ בִדְרָכֶיהָ."],[8,"","עַתָּה יֵשׁ לָנוּ לְהִתְבּוֹנֵן, בְּפֶסַח יָצְאוּ יִשְׂרָאֵל מִלֶּחֶם שֶׁנִּקְרָא חָמֵץ. כָּתוּב (שמות יג) וְלֹא יֵרָאֶה לְךְ חָמֵץ, וְכָתוּב (שם יב) כִּי כָל אֹכֵל מַחְמֶצֶת. מָה הַטַּעַם? בִּשְׁבִיל כָּבוֹד שֶׁל הַלֶּחֶם הַהוּא הַנִּקְרָא מַצָּה. וְעַכְשָׁו שֶׁזָּכוּ יִשְׂרָאֵל לְלֶחֶם עֶלְיוֹן יוֹתֵר, לֹא רָאוּי הָיָה שֶׁיִּתְבַּטֵּל הֶחָמֵץ וְלֹא יֵרָאֶה כְלָל. וּמַדּוּעַ קָרְבָּן זֶה הָיָה חָמֵץ? שֶׁכָּתוּב סֹלֶת תִּהְיֶינָה חָמֵץ תֵּאָפֶינָה. וְעוֹד, שֶׁעַתָּה בְּיוֹם זֶה מִתְבַּטֵּל יֵצֶר הָרָע, וְהַתּוֹרָה שֶׁנִּקְרֵאת חֵרוּת נִמְצֵאת."]]],[["אֶלָּא, לְמַלְכָּא דְּהֲוָה לֵיהּ בַּר יְחִידָאי, וְחָלַשׁ. יוֹמָא חַד הֲוָה תָּאִיב לְמֵיכַל, אָמְרוּ יֵיכוּל בְּרֵיהּ דְּמַלְכָּא (ס\"א מיכלא דאסוותא דא) אַסְוָותָא דָּא, וְעַד דְּיֵיכוּל לֵיהּ, לָא יִשְׁתְּכַּח מֵיכְלָא וּמְזוֹנָא אַחֲרָא בְּבֵיתָא. עָבְדוּ הָכִי. כֵּיוָן דְּאָכַל הַהוּא אַסְוָותָא, אָמַר מִכָּאן וּלְהָלְאָה יֵיכוּל כָּל מָה דְּאִיהוּ תָּאִיב, וְלָא יָכִיל לְנַזְקָא לֵיהּ.","כַּךָ כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, לָא הֲוֵי יַדְעֵי עִקָרָא וְרָזָא דִּמְהֵימְנוּתָא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יִטְעֲמוּן יִשְׂרָאֵל אַסְוָותָא, וְעַד דְּיֵיכְלוּן אַסְוָותָא דָּא, לָא אִתְחָזֵי לְהוֹן מֵיכְלָא אַחֲרָא. כֵּיוָן דְּאָכְלוּ מַצָּה, דְּאִיהִי אַסְוָותָא לְמֵיעַל וּלְמִנְדַּע בְּרָזָא דִּמְהֵימְנוּתָא. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מִכָּאן וּלְהָלְאָה אִתְחָזֵי לוֹן חָמֵץ, וְיֵיכְלוּן לֵיהּ, דְּהָא לָא יָכִיל לְנַזְקָא לוֹן. וְכָּל שֶׁכֵּן דִּבְיוֹמָא דְּשָׁבוּעוֹת, אִזְדָּמַן נַהֲמָא עִלָּאָה, דְּאִיהוּ אַסְוָותָא בְּכֹלָּא.","וְעַל דָּא מְקָרְבִין חָמֵץ, לְאִתּוֹקְדָא עַל מַדְבְּחָא. וּמְקָרְבִין תְּרֵין נַהֲמִין אַחֲרָנִין כַּחֲדָא. וְחָמֵץ, אִתּוֹקְדָא בְּנוּרָא דְּמַדְבְּחָא וְלָא יָכִיל לְשַׁלְּטָאָה, וּלְנַזְקָּא לוֹן לְיִשְׂרָאֵל. וּבְגִינֵי כַּךְ, יִשְׂרָאֵל קַדִּישִׁין אִתְדָּבָקוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאַסְוָותָא דְּאוֹרַיְיתָא בְּיוֹמָא דָּא. וְאִלְמָלֵי הֲווֹ נַטְרֵי יִשְׂרָאֵל תְּרֵין סִטְרִין דְּנַהֲמֵי אִלֵּין, לָא הֲווֹ עַיְילִין בְּדִינָא לְעָלְמִין.","בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה, דְּאִיהוּ יוֹמָא דְּדִינָא, (בכל יומא) דְּלָאו אִיהוּ, אֶלָּא לְאִינּוּן דְּלָא נַטְלוּ מֵיכְלָא דְּאַסְוָותָא, וְשָׁבְקוּ לְאַסְוָותָא דְּאוֹרַיְיתָא, בְּגִין מֵיכְלָא אַחֲרָא דְּאִיהוּ חָמֵץ. דְּהָא בְּיוֹמָא דָּא דְּרֹאשׁ הַשָּׁנָה, הַהוּא חָמֵץ סַלְּקָא, וּמְקַטְרְגָא עָלֵיהּ דְּבַר נָשׁ, וְאַלְשִׁין עָלֵיהּ, וְאִיהוּ קַיְּימָא בְּיוֹמָא דָּא מְקַטְרְגָא עַל עָלְמָא. וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל כֹּלָּא וְדָאִין עָלְמָא.","וּבְגִינֵי כַּךְ כַּד יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, אֲטְעִים לְהוּ מֵהַהוּא נַהֲמָא עִלָּאָה, דְּהַהוּא אֲתָר, וּמִגּוֹ הַהוּא נַהֲמָא, הֲווֹ יַדְעִין וּמִסְתַּכְּלִין בְּרָזֵי דְּאוֹרַיְיתָא, לְמֵהַךְ בְּאֹרַח מֵישָׁר, וְהָא אוּקְמוּהָ מִלָּה אִינּוּן חַבְרַיָּיא בְּרָזִין (ס\"א אלין דקאמרן) אִלֵּין כִּדְקָאמְרָן.","רִבִּי שִׁמְעוֹן וְרִבִּי אֶלְעָזָר בְּרֵיהּ, הֲווֹ אַזְלֵי בְּאָרְחָא, וַהֲווּ אַזְלִין עִמְּהוֹן, רִבִּי אַבָּא וְרִבִּי יוֹסֵי, עַד דַּהֲווֹ אַזְלֵי אִעֲרָעוּ בְּחַד סָבָא, וַהֲוָה אָחִיד בִּידֵיהּ חַד יַנּוּקָא, זָקַף עֵינוֹי רִבִּי שִׁמְעוֹן וְחָמָא לֵיהּ, אָמַר לֵיהּ לְרִבִּי אַבָּא וַדַּאי מִלִּין חַדְתִּין אִית גַּבָּן בְּהַאי סָבָא.","כַּד מָטוּ לְגַבֵּיהּ, אָמַר רִבִּי שִׁמְעוֹן, בְּמָטוּל דְּקּוּפְטְרָךְ בְּגַבָּךְ קָא אָתִית, מַאן אַנְתְּ. אָמַר לֵיהּ, יוּדָאי אֲנָא. אָמַר, מִלִּין חַדְתִּין וַדַּאי יוֹמָא דָּא לְגַבָּךְ, אָמַר לֵיהּ לְאָן הוּא אַרְעָךְ. אָמַר לֵיהּ, דִּיוּרִי הֲוָה בְּאִינּוּן פְּרִישֵׁי מַדְבְּרָא, דַּהֲוֵינָא, מִשְׁתָּדַּל בְּאוֹרַיְיתָא, וְהַשְׁתָּא אֲתֵינָא לְיִשׁוּבָא, לְמֵיתַב בְּצִלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאִלֵּין יוֹמֵי דְּיַרְחָא שְׁבִיעָאָה דָּא.","חַדֵּי רִבִּי שִׁמְעוֹן, אָמַר, נֵתִיב, דְּוַדַּאי קוּדְשָׁא בְּרִיךְ הוּא שַׁדְרָךְ לְגַבָּן. אָמַר לֵיהּ, חַיֶּיךָ דְּנִשְׁמַע מִלָּה מִפּוּמָךְ, מֵאִינּוּן מִלִּין חַדְתִּין עַתִּיקִין, דִּנְטַעְתּוּן תַּמָּן בְּמַדְבְּרָא, מֵהַאי יַרְחָא שְׁבִיעָאָה. וַאֲמַאי אִתְפְּרַשְׁתּוּן הַשְׁתָּא מִמַּדְבְּרָא, לְמֵיתֵי לְיִשׁוּבָא. אָמַר לֵיהּ הַהוּא סָבָא, בִּשְׁאֶלְתָּא דָּא, יְדַעְנָא דְּחָכְמְתָא גַּבָּךְ, וּמִילָּךְ מָטוּ לִרְקִיעֵי דְּחָכְמְתָא. (ס\"א נטו לתקיעו דחכמתא)","פָּתַח הַהוּא סָבָא וְאָמַר, (דברים א׳:ל״א) וּבַמִּדְבָּר אֲשֶׁר רָאִיתָ אֲשֶׁר נְשָׂאֲךָ יְיָ' אֱלֹהֶיךָ כַּאֲשֶׁר יִשָּׂא אִישׁ אֶת בְּנוֹ וְגוֹ'. הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, וּבַמִּדְבָּר אֲשֶׁר נְשָׂאֲךָ, מַהוּ רָאִיתָ. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא דָּבַר לוֹן לְיִשְׂרָאֵל בְּמַדְבְּרָא, מַדְבְּרָא תַּקִּיפָא, כְּמָה דִּכְתִּיב, (דברים ח׳:ט״ו) נָחָשׁ שָׂרָף וְעַקְרָב וְגוֹ'. וּמַדְבְּרָא דְּאִיהוּ תַּקִּיף מִשְּׁאַר מַדְבְרִין בְּעָלְמָא. מַאי טַעֲמָא."],[[0,"אלא למלכא דהוה","וכו': ומשיב, אלא בדומה למלך שהיה לו בן יחיד, ונחלה, יום אחד היה משתוקק לאכול. אמרו, יאכל בנו של המלך רפואה זו וטרם שיאכל אותו לא ימצא שום מאכל ומזון אחר בבית. עשו כך. כיון שאכל הרפואה ההוא אמר, מכאן והלאה יאכל כל מה שרוצה, ולא יוכל להזיק לו."],[1,"כך כד נפקו","וכו': כך, כשיצאו ישראל ממצרים, לא היו יודעים העיקר והסוד של האמונה, אמר הקב\"ה יטעמו ישראל רפואה וכל עוד שיאכלו רפואה זו לא יראה להם מאכל אחר, דהיינו חמץ כיון שאכלו מצה, שהיא רפואה לבא ולדעת בסוד האמונה, שהיא מלכות, אמר הקב\"ה, מכאן והלאה, ראוי להם חמץ, ויאכלו אותו, כי אינו יכול עוד להזיק להם. וכ\"ש ביום השבועות, שנמצא לחם העליון. של ז\"א, שהוא רפואה לגמרי."],[2,"וע\"ד מקרבין חמץ","וכו': ועל כן מקריבים חמץ, שהוא יצר הרע, (כנ\"ל אות ע\"ג) שישרף על המזבח, דהיינו ע\"י הקרבנות שמקריבים על המזבח, ומקריבים שתי הלחם אחרים, על ידי תנופה עמהם יחד, אחרים פירושו, חוץ מן הקרבנות. והחמץ שהוא היצר הרע נשרף באש המזבח, על ידי הקרבנות, ואינו יכול לשלוט ולהזיק לישראל. ומשום זה ישראל הקדושים מתדבקים בו בהקב\"ה ביום הזה ברפואה של התורה. ואם היו שומרים ישראל ב' מיני לחם אלו, דהיינו מצה, ולחם העליון של ז\"א, לא היו באים בדין לעולם."],[2,"","ביאור הדברים. כי בדרך כלל יש ב' מיני מוחין לנוקבא. א) מזמן היותה בסוד ב' מאורות הגדולים, דהיינו מטרם המיעוט, שאז היתה בקומה אחת עם ז\"א ולא היתה מקבלת ממנו, אלא שניהם מקבלים בשוה מאמא, שז\"א היה מלביש קו ימין שלה שהוא חסדים והמלכות היתה מלבשת קו שמאל שלה, שהוא חכמה בלי חסדים. שאז קטרגה הירח, מחמת שבלי חסדים אין החכמה יכולה להאיר, והיתה הארתה בצמצום גדול. ואח\"כ נאמר לה לכי ומעטי את עצמך, שאז ירדה למטה מחזה דז\"א, שהמסך שבחזה דז\"א מיעטה עד שלית לה מגרמה ולא מידי, והכל היא מקבלת מז\"א, אבל תחת זה, היא נבנית במוחין גדולים מחכמה וחסדים עד שהיא בזווג פב\"פ עם ז\"א, (כנ\"ל ב\"א דף ק\"ח ד\"ה וכבר ע\"ש כל ההמשך) אמנם אין העדר ברוחניות, ואע\"פ שנתמעטה וחזרה אחר המיעוט לבחינת פב\"פ, לא נתבטל בה משום זה המוחין שמלפני המיעוט. אלא המוחין שמלפני המיעוט להיות הארתם מצומצמת הם מכונים מוחין דאחורים, וה\"ס מצה, הנקראת לחם עוני, והמוחין שלאחר המיעוט נקראים מוחין דפנים, וכן לחם מן השמים, מטעם שמוחין אלו מקבלת מז\"א שנקרא שמים. וכן הם נבחנים שיש בהם חמץ, שפירושם דינים, מחמת המיעוט שנתמעטה שירדה מחזה ולמטה דז\"א, שהדינין הנמצאים בנקודת החזה דז\"א ה\"ס חמץ. אבל חמץ הזה מתתקן עד שנהפך להיות קדושה ורחמים. כי נגלה שזולת המיעוט והדינים האלו היתה המלכות נשארת בלחם עוני, ולא היתה מקבלת מוחין הגדולים דפנים בפנים לעולם. ונמצא שיש ב' מיני תקונים בב' מיני מוחין דמלכות. התקון של מוחין דאחורים הוא לבער החמץ ולהרחיקו בבל יראה ובל ימצא. כי החכמה מבערת כל הדינים. אבל אינם עוקרים את החמץ לגמרי מהמקומות התחתונים שעודו נמצא שם. ונמצא שהוא רפואה אבל לא לגמרי, משא\"כ המוחין דפנים, שעל ידיהם מתהפך החמץ ונעשה קדושה ורחמים נמצא שנעקר החמץ לגמרי ואין לו מקום עוד להתעורר. וע\"כ נבחן זה לרפואה גמורה."],[2,"","וזה אמרו, \u0003תרין נהמי אכלו ישראל, חד כד נפקו ממצרים אכלו מצה לחם עוני,\u0004 דהיינו המוחין דאחורים של המלכות, שהארתם מצומצמת מחמת חסרון חסדים, והוא לחם עוני, אמנם אלו המוחין הם של המלכות, עצמה שקבלה מבינה ולא על ידי ז\"א, כנ\"ל. וע\"כ אומר לעיל (אות ס\"ד) ששבעה ימים דמצות הם תחתונים, דהיינו המוחין דמלכות עצמה עיין שם. \u0003וחד במדברא, לחם מן השמים,\u0004 שהוא מן, שהיה ממוחין דז\"א עצמו. \u0003וע\"ד קרבנא דיומא דא נהמא איהו,\u0004 דהיינו גם כן לחם מן השמים כמו המן, אלא הם בחינת המוחין של המלכות שקבלתם מן השמים שהוא ז\"א, דהיינו המוחין דפנים בפנים. כי נאמר עליהם, ממושבותיכם תביאו לחם תנופה. דהיינו מן הארץ שהוא מלכות, אלא שקבלתם משמים, שהוא ז\"א ואינם מוחותיה עצמה כמו מוחין דאחורים. \u0003דנהמא איהו עקר, דכתיב, והקרשתם על הלחם שבעת כבשים,\u0004 כי הלחם, שהוא מוחין דפנים בפנים הנמשכים בשבועות ע\"י תנופת הלחם, הוא העיקר הנרצה, והקרבנות שמקריבים הם להשלים את הלחם, כי מה שאמרנו לעיל, שהחמץ שיש במוחין דפנים מתהפך להיות קדושה ורחמים, הוא ע\"י הקרבת הקרבנות, שאש המזבח מהפך את החמץ, שה\"ס הדינין שבאו מחמת המיעוט, לסוד ריח ניחוח אשה לה'. \u0003ממושבותיכם תביאו לחם תנופה,\u0004 מביא כתוב הזה, לדייק שהכונה היא על לחם מן הארץ הבא ממושבותיכם, ולא מן כמו שאכלו במדבר. \u0003דדא איהו נהמא, דאחכימו בית ישראל חכמתא עלאה דאורייתא,\u0004 להיותם המוחין דפנים הבאים מז\"א שנקרא אורייתא, אל המלכות, וישראל שקבלו ג\"כ המוחין הללו, זכו ג\"כ לחכמה עליונה."],[2,"","וזהו שמשיב על הקושיא, כיון שיום השבועות גדול מפסח למה הותר החמץ בשבועות, והרי החמץ הם דינים ויצר הרע. ומשיב ששני מיני רפואות הם א) הוא מצה, שהוא להרחיק הדינים אבל עוד אין מהפכים אותם לרחמים. ב) הוא לחם בכורים והקרבנות שמקריבים עליהם על המזבח. שע\"י הקרבנות נשרף החמץ על המזבח ומתהפך לריח ניחח, שרפואה זו הוא רפואה גמורה עד שהחמץ נעשה קדושה ונאמר בלחם תנופה חמץ תאפינה. וז\"ש, \u0003ואלמלי הוו נטרי ישראל תרין סטרין דנהמא אלין, לא הוו עיילין בדינא לעלמין,\u0004 כי ע\"י המצה והלחם תנופה והקרבנות נהפכו הדינים להיות קדושה ורחמים בכל מקום שהם. כנ\"ל."],[3,"ביומא דראש השנה","וכו': ביום רה\"ש, שהוא יום הדין, שהוא אינו אלא לאלו שלא לקחו מאכל הרפואה, שהוא מצות, שהם מוחין דאחורים, ועזבו את רפואת התורה, שהוא מוחין דפב\"פ מז\"א הנקרא תורה, שע\"י ב' רפואות אלו נתתקן מאכל האחר שהוא חמץ, ונתהפך לקדושה כנ\"ל בדבור הסמוך. כי ביום הזה של ראש השנה, חמץ ההוא עולה ומקטרג על האדם ומלשין עליו, והיא עומד ביום הזה להיות מקטרג על העולם, והקב\"ה יושב בדין על הכל, ודן את העולם."],[4,"ובגיני כך כד","וכו': ומשום זה כשנתן הקב\"ה התורה לישראל, הטעים אותם מלחם עליון ההוא, דהיינו ממוחין דפנים דז\"א, ממקום ההוא, מן המלכות שמקבלת הימנו, שנקראת מקום. מתוך לחם ההוא היו יודעים ומסתכלים בסודות התורה ללכת בדרך הישר. וכבר החברים העמידו הדבר בסודות אלו, כמו שאמרנו."],[5,"ר' שמעון ור' אלעזר","וכו': ר\"ש, ור\"א בנו היו הולכים בדרך והלכו עמהם ר' אבא ור' יוסי. בעוד שהיו הולכים, פגשו זקן אחד, שהיה אוחז בידו ילד אחד. זקן, רומז למוחין דפנים, ילד, רומז למוחין דאחורים. נשא ר\"ש עיניו וראה אותו. אמר לו לרבי אבא, ודאי שיש לנו דברים חדשים בזקן הזה."],[6,"כד מטו לגביה","וכו': כשהגיעו אצלו א\"ל רבי שמעון, במשא קשורה בך על גבך, אתה בא, כלומר, שאין לך חמור שישא משאך. רמז לו על מוחין דאחורים שאוחז, שהם עליו כמשא, מי אתה. אמר לו יהודי אני. אמר ר\"ש, דברים חדשים ודאי יש אצלך ביום הזה. אמר לו ר\"ש, איפה הוא ארצך. אמר לו, דירתי היה בין אלו פורשי המדבר, שהייתי משתדל שם בתורה, ועתה באתי לישוב, לשבת בצלו של הקב\"ה בימים אלו של חדש השביעי הזה. \u0003מטול\u0004 פירושו משא. כי תרגום למשא, הוא למטול. (ש\"ב ט\"ו ל\"ג). \u0003דקופטרך\u0004 פירושו הקשורה בך בחבלים, מלשון כקפטורין יוצאת מתוך הושט (תנחומא מקץ.) שפירושו חבלים."],[7,"חדי ר' שמעון","וכו': שמח ר\"ש, אמר, נשב, כי ודאי הקב\"ה שלחך אלינו. אמר לו, חייך, שנשמע דבר מפיך מאלו דברים חדשים ישנים, שנטעתם שם במדבר מחודש השביעי הזה. ולמה נפרדת עתה מן המדבר לבא לישוב. אמר לו זקן ההוא, בשאלה זו, יודע אני שחכמה בך, ודבריך מגיעים לרקיע החכמה."],[8,"פתח ההוא סבא","וכו': פתח זקן ההוא, ואמר, ובמדבר אשר ראית אשר נשאך ה' אלקיך כאשר ישא איש את בנו וגו'. מקרא זה כך היה צריך לומר, ובמדבר אשר נשאך, מהו ראית. ומשיב, אלא הקב\"ה דבר לישראל במדבר, מדבר חזק, כמו שכתוב, נחש שרף ועקרב וגו'. ומדבר שהוא חזק מכל המדבריות שבעולם, מהו הטעם שהוליך שם את ישראל."]],[[0,"","אֶלָּא, לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יְחִידִי, וְנֶחֱלָה. יוֹם אֶחָד הָיָה מִתְאַוֶּה לֶאֱכֹל. אָמְרוּ, יֹאכַל בֶּן הַמֶּלֶךְ (מאכל של רפואה) רְפוּאָה זוֹ, וְעַד שֶׁיֹּאכַל אוֹתָהּ, לֹא יִמָּצֵא מַאֲכָל וּמָזוֹן אַחֵר בַּבַּיִת. עָשׂוּ כֵן. כֵּיוָן שֶׁאָכַל הָרְפוּאָה הַהִיא, אָמַר, מִכָּאן וָהָלְאָה יֹאכַל כָּל מַה שֶּׁהוּא מִתְאַוֶּה וְלֹא יָכוֹל לְהַזִּיק לוֹ."],[1,"","כָּךָ כַּאֲשֶׁר יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא הָיוּ יוֹדְעִים עִקָּר וְסוֹד שֶׁל הָאֱמוּנָה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִטְעֲמוּ יִשְׂרָאֵל רְפוּאָה, וְעַד שֶׁיֹּאכְלוּ רְפוּאָה זוֹ, לֹא יֵרָאֶה לָהֶם מַאֲכָל אַחֵר. כֵּיוָן שֶׁאָכְלוּ מַצָּה, שֶׁהִיא רְפוּאָה לַעֲלוֹת וְלָדַעַת בְּסוֹד הָאֱמוּנָה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִכָּאן וָהָלְאָה רָאוּי לָהֶם חָמֵץ וְיֹאכְלוּ אוֹתוֹ, שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהַזִּיק לָהֶם. וְכָל שֶׁכֵּן שֶׁבְּיוֹם הַשָּׁבוּעוֹת שֶׁנִּמְצָא לֶחֶם עֶלְיוֹן, שֶׁהוּא רְפוּאָה לַכֹּל."],[2,"","וְעַל זֶה מַקְרִיבִים חָמֵץ לְהִשָּׂרֵף עַל הַמִּזְבֵּחַ. וּמַקְרִיבִים שְׁתֵּי לֶחֶם אֲחֵרִים כְּאֶחָד. וְחָמֵץ נִשְׂרָף בְּאֵשׁ הַמִּזְבֵּחַ, וְלֹא יָכוֹל לִשְׁלֹט וּלְהַזִּיק לָהֶם לְיִשְׂרָאֵל. וּמִשּׁוּם זֶה יִשְׂרָאֵל קְדוֹשִׁים נִדְבָּקִים בּוֹ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, בָּרְפוּאָה שֶׁל הַתּוֹרָה בְּיוֹם זֶה. וְאִם הָיוּ שׁוֹמְרִים יִשְׂרָאֵל שְׁנֵי צְדָדִים שֶׁל לֶחֶם אֵלּוּ, לֹא הָיוּ עוֹלִים בְּדִין לְעוֹלָם."],[3,"","בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין, (בכל יום) שֶׁאֵין הוּא, אֶלָּא לְאֵלּוּ שֶׁלֹּא לָקְחוּ מַאֲכָל שֶׁל הָרְפוּאָה, וְעָזְבוּ אֶת מַאֲכַל הַתּוֹרָה מִשּׁוּם מַאֲכָל אַחֵר שֶׁהוּא חָמֵץ. כִּי בְּיוֹם זֶה שֶׁל רֹאשׁ הַשָּׁנָה הֶחָמֵץ הַהוּא עוֹלֶה, וּמְקַטְרֵג עַל הָאָדָם וּמַלְשִׁין עָלָיו, וְהוּא עוֹמֵד בְּיוֹם זֶה מְקַטְרֵג עַל הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל כֻּלָּם וְדָן אֶת הָעוֹלָם."],[4,"","וּמִסִּבָּה זוֹ, כַּאֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַתּוֹרָה לְיִשְׂרָאֵל, הִטְעִים לָהֶם מֵהַלֶּחֶם הָעֶלְיוֹן הַהוּא שֶׁל הַמָּקוֹם הַהוּא, וּמִתּוֹךְ הַלֶּחֶם הַהוּא הָיוּ יוֹדְעִים וּמִסְתַּכְּלִים בְּסוֹדוֹת הַתּוֹרָה לָלֶכֶת בְּדֶרֶךְ יָשָׁר, וַהֲרֵי בֵּאֲרוּ הַדְּבָרִים אֵלּוּ הַחֲבֵרִים בְּסוֹדוֹת (אלו שאנחנו אומרים) אֵלּוּ כְּמוֹ שֶׁאָמַרְנוּ."],[5,"","רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר בְּנוֹ הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהָיוּ הוֹלְכִים עִמָּהֶם רַבִּי אַבָּא וְרַבִּי יוֹסֵי. עַד שֶׁהָיוּ הוֹלְכִים, פָּגְשׁוּ בְזָקֵן אֶחָד, וְהָיָה אוֹחֵז בְּיָדוֹ תִּינוֹק אֶחָד. הֵרִים עֵינָיו רַבִּי שִׁמְעוֹן וְרָאָה אוֹתוֹ. אָמַר לוֹ לְרַבִּי אַבָּא, וַדַּאי דְּבָרִים חֲדָשִׁים יֵשׁ לָנוּ אֵצֶל הַזָּקֵן."],[6,"","כַּאֲשֶׁר הִגִּיעוּ אֵלָיו, אָמַר רַבִּי שִׁמְעוֹן, בְּמַשָּׂא הַקָּשׁוּר בְּגַבְּךְ אַתָּה בָּא? מִי אַתָּה? אָמַר לוֹ, יְהוּדִי אָנִי. אָמַר, דְּבָרִים חֲדָשִׁים וַדַּאי בְּיוֹם זֶה אֶצְלְךְ. אָמַר לוֹ, לְהֵיכָן הוּא דַּרְכְּךְ? אָמַר לוֹ, דִּירָתִי הָיְתָה בְּאֵלּוּ פּוֹרְשֵׁי הַמִּדְבָּר, שֶׁהָיִיתִי מִשְׁתַּדֵּל בַּתּוֹרָה, וְעַתָּה בָּאתִי לְיִשּׁוּב לָשֶׁבֶת בְּצֵל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָמִים אֵלּוּ שֶׁל הַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה."],[7,"","שָׂמַח רַבִּי שִׁמְעוֹן, אָמַר, נֵשֵׁב, בְּוַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתְךְ אֵלֵינוּ. אָמַר לוֹ, חַיְּיִךְ שֶׁנִּשְׁמַע דָּבָר מִפִּיךְ, מֵאֵלּוּ הַדְּבָרִים הַחֲדָשִׁים עַתִּיקִים שֶׁנְּטַעְתֶּם שָׁם בַּמִּדְבָּר מֵחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה, וּמַדּוּעַ נִפְרַדְתֶּם עַתָּה מֵהַמִּדְבָּר לָבא לְיִשּׁוּב? אָמַר לוֹ אוֹתוֹ הַזָּקֵן, בִּשְׁאֵלָה זוֹ יָדַעְתִּי שֶׁחָכְמָה אֶצְלְךְ וּדְבָרֶיךְ מַגִּיעִים לִרְקִיעֵי הַחָכְמָה (נוטים לתקיעת החכמה)."],[8,"","פָּתַח הַזָּקֵן הַהוּא וְאָמַר, (דברים א) וּבַמִּדְבָּר אֲשֶׁר רָאִיתָ אֲשֶׁר נְשָׂאֲךְ ה' אֱלֹהֶיךְ כַּאֲשֶׁר יִשָּׂא אִישׁ אֶת בְּנוֹ וְגוֹ'. פָּסוּק זֶה כָּךְ הָיָה צָרִיךְ לוֹמַר, וּבַמִּדְבָּר אֲשֶׁר נְשָׂאֲךְ. מַהוּ רָאִיתָ? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא הִנְהִיג אֶת יִשְׂרָאֵל בַּמִּדְבָּר, מִדְבָּר חָזָק, כְּמוֹ שֶׁכָּתוּב (דברים ח) נָחָשׁ שָׂרָף וְעַקְרָב וְגוֹ'. וּמִדְבָּר שֶׁהוּא חָזָק מִשְּׁאָר מִדְבָּרִיּוֹת בָּעוֹלָם. מָה הַטַּעַם?"]]],[["בְּגִין דְּהַהוּא שַׁעֲתָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם וְאִשְׁתְּלִימוּ לְשִׁתִּין רִבְּבָן, אִתְתָּקַּף מַלְכוּתָא קַדִּישָׁא, וְאִסְתַּלָּק עַל כֹּלָּא, וְסִיהֲרָא אִתְנְהִירַת וּכְדֵין אִתְכַּפְיָא מַלְכוּ חַיָּיבָא סִטְרָא אַחֲרָא. וְאַפִּיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַךְ בְּמַדְבְּרָא תַּקִּיפָא. דְּאִיהוּ אֲתָר וְשֻלְטָנוּ דְּסָמָאֵ\"ל חַיָּיבָא, דְּאִיהוּ דִּילֵיהּ מַמָּשׁ, בְּגִין לְתַּבְרָא תּוּקְפֵּיהּ וְחֵילֵיהּ, וּלְכַתְּתָא רֵישֵׁיהּ, (ס\"א ולאחתא ליה) וּלְאַכְפְּיָא לֵיהּ, דְּלָא יִשְׁלוֹט. וְאִלְמָלֵא דְּחָאבוּ יִשְׂרָאֵל, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַעְבְּרָא לֵיהּ מֵעָלְמָא, וְעַל דָּא אַעְבַּר לוֹן בְּאַחֲסַנְתֵּיהּ וְעַדְבֵיהּ וְחוּלָקֵיהּ מַמָּשׁ.","כֵּיוָן דְּחָאבוּ בְּכַמָּה זִמְנִין, נָשִׁיךְ לוֹן חִוְיָא, וּכְדֵין אִתְקְיָּים (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ רֹאשׁ וְגוֹ'. יִשְׂרָאֵל מָחוּ רֵישֵׁיהּ בְּקַדְמִיתָא, וְלָא יַדְעֵי לְאִסְתַּמְּרָא מִינֵּיהּ, וּלְבָתַר אִיהוּ מָחָא בְּבַתְרַיְיתָּא, וְנָפְלוּ כֻּלְּהוּ בְּמַדְבְּרָא, וְאִתְקָיָּים וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. וְאַרְבְּעִין שְׁנִין לָקוּ מִנֵּיהּ, לָקֳבֵל מ' מַלְקוּת דְּבֵי דִּינָא.","וְעַל דָּא כְּתִיב אֲשֶׁר רָאִיתָ, בְּעֵינַיְיהוּ הֲוֹי חֲמָאן לְהַהוּא מָארֵי דְּמַדְבְּרָא, אָזִיל כָּפִית קָמַיְיהוּ, וְנַטְלֵי אַחַסַנְתֵּיהּ וְעַדְבֵיהּ. מְנָּלָן. מִדִּכְתִּיב (שמות ט״ו:ט״ו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם, וְאִלֵּין אִינּוּן (דברים ח׳:ט״ו) נָחָשׁ שָׂרָף וְעַקְרָב. וַאֲנָן אוּף הָכִי אִתְפְּרַשְׁנָא מִיִשׁוּבָא לְמַדְבְּרָא תַּקִּיפָא, וּלְעַיְינָא תַּמָּן בְּאוֹרַיְיתָא, בְּגִין לְאַכְפְּיָא לְהַהוּא סִטְרָא.","וְתוּ דְּלָא מִתְיַשְּׁבָן מִלֵּי דְּאוֹרַיְיתָא, אֶלָּא תַּמָּן. דְּלֵית נְהוֹרָא אֶלָּא הַהוּא דְּנָפִיק מִגּוֹ חֲשׁוֹכָא, דְּכַד אִתְכַּפְיָא סִטְרָא דָּא, אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, וְאִתְיָיקָּר בִּיקָרֵיהּ. וְלֵית פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא מִגּוֹ חֲשׁוֹכָא, וְלֵית טוּבָא אֶלָּא מִגּוֹ בִּישָׁא. וְכַד עָאל בַּר נָשׁ בְּאוֹרַח בִּישָׁא, וְשָׁבִיק לֵיהּ, כְּדֵין אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא בִּיקָרֵיהּ, וְעַל דָּא שְׁלִימוּ דְּכֹלָּא טוֹב וָרָע כַּחֲדָא, וּלְאִסְתַּלְּקָא לְבָתַר בְּטוֹב, וְלֵית טוֹב אֶלָּא הַהוּא דְּנָפַק מִגּוֹ בִּישָׁא. וּבְהַאי טוֹב, אִסְתַּלָּק יְקָרֵיהּ, וְדָא אִיהוּ פּוּלְחָנָא שְׁלִים.","וַאֲנָן, עַד הַשְׁתָּא יָתִיבְנָא תַּמָּן, כָּל יוֹמֵי שַׁתָּא, בְּגִין לְאַכְפְּיָא בְּמַדְבְּרָא לְהַהוּא סִטְרָא. הַשְּׁתָּא דְּמָטָא זִמְנָא דְּפוּלְחָנָא קַדִּישָׁא, דְּסִטְרָא דִּקְדוּשָׁא, אַהֲדַרְנָא לְיִשׁוּבָא דְּתַמָּן אִיהוּ פּוּלְחָנָא דִּילֵיהּ. וְתוּ, דְּהַשְׁתָּא בְּרֹאשׁ הַשָּׁנָה מָטָא זִמְנָא דְּהַהוּא חִוְיָא, לְמִתְבַּע דִּינָא מִקָּמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְתַמָּן אִיהוּ שַׁלִּיט. וּבְגִין כַּךְ נָפַקְנָא מִתַּמָּן וַאֲתֵינָא לְיִשׁוּבָא.","פָּתַח הַהוּא סָבָא וְאָמַר, (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ, הַשְׁתָּא אִיהוּ זִמְנָא, לְאִתְּעָרָא דִּינָא עִלָּאָה תַּקִּיפָא, וְכַד אִיהוּ אִתְּעַר סִטְרָא אַחֲרָא אִתְתָּקַּף בַּהֲדֵיהּ, וְכֵיוָן דְּאִיהוּ אִתְתָּקַּף, סָלִיק וְחַפְיָא לְסִיהֲרָא, דְּלָא נָהִיר נְהוֹרָא, וְאִתְמַלְיָא מִסִּטְרָא דְּדִינָא. כְּדֵין כָּל עָלְמָא אִיהוּ בְּדִינָא, עִלָּאִין וְתַתָּאִין, וְכָרוֹזָא כָּרִיז בְּכֻלְּהוּ רְקִיעִין, אַתְקִינוּ כּוּרְסְיָא דְּדִינָא, לְמָארֵיהּ דְּכֹלָּא, דְּאִיהוּ בָּעֵי לְמֵידָן.","וְרָזָא הָכָא, וְאִתְנְהִיר לָן בְּמַדְבְּרָא, אֲמַאי אִתְּעַר דִּינָא עִלָּאָה בְּיוֹמָא דָּא. אֶלָּא כָּל רָזִין וְכָל קִדוּשִׁין יַקִירִין, כֻּלְּהוּ תַּלְיָין בִּשְׁבִיעָאָה. וְהַהוּא שְׁבִיעָאָה עִלָּאָה, עָלְמָא עִלָּאָה, דְּאִקְרֵי עָלְמָא דְּאָתֵי. מִנֵּיהּ נַהֲרִין כָּל בּוּצִינִין, וְכָל קִדוּשִׁין, וְכָל בִּרְכָּאן. וְכַד מָטֵי זִמְנָא, לְחַדְתּוּתֵי בִּרְכָּאן וְקִדּוּשִׁין לְאַנְהֲרָא, בָּעָא לְאַשְׁגָּחָא בְכָל תִּקּוּנָא דְּעָלְמִין כֻּלְּהוּ, וְכָל אִינּוּן תִּקּוּנִים לְאִתְקַיְּימָא כֻּלְּהוֹן, סַלְּקִין מִגּוֹ תַּתָּאֵי, אִי אִינּוּן כַּשְׁרָאן. וְאִי לָא כַּשְׁרָאן, כְּדֵין קַיְּימָא (ס\"א מלה) דְּלָא נָהִיר, עַד דְּאִתְפָּרְשָׁן חַיָּיבִין מִגּוֹ זַכָּאִין, כְּדֵין אִתְּעַר דִּינָא.","וּמֵהַהוּא דִּינָא, אִתְתָּקַּף סִטְרָא אַחֲרָא, וְאִשְׁתְּכַח מְקַטְרְגָא, בְּגִין דְּיִנָתְנוּן לֵיהּ אִינּוּן, חַיָּיבַיָּא. בְּגִין דְּעָלֵיהּ כְּתִיב, (איוב כ״ח:ג׳) וּלְכָל תַּכְלִית הוּא חוֹקֵר. וְחַפְיָא לְסִיהֲרָא, אֲמַאי (ד\"א לא מסרא לון בידא דמקטרגא.) בְּגִין דְּלֵית תִּיאוּבְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לְאוֹבָדָא לְעוֹבָדֵי יְדוֹי.","וְהַהוּא סִטְרָא אַחֲרָא, קַיְּימָא קְלִיפָא תַּקִּיפָא, דְּלָא יָכִיל לְאִתָּבְּרָא, בַּר בְּהַהוּא עֵיטָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לְיִשְׂרָאֵל, דִּכְתִּיב תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. בְּגִין לְתַּבְרָא הַהוּא כִּסֵּה דְּאִתְחֲפְיָא סִיהֲרָא, וְלָא נָהִיר.","וְכַד מִתְּעֲרֵי יִשְׂרָאֵל לְתַתָּא בְּשׁוֹפָר, הַהוּא קַלָּא דְּנָפִיק מִשּׁוֹפָר, בָּטַשׁ בַּאֲוִירָא, וּבָקַע רְקִיעִין, עַד דְּסַלְּקָא לְגַבֵּי הַהוּא טִנָרָא תַּקִּיפָא, (נ\"א סטרא אחרא) דְּחָפֵי לְסִיהֲרָא, אַשְׁגַּח, וְאַשְׁכַּח אִתְעֲרוּתָא דְּרַחֲמֵי, כְּדֵין הַהוּא דְּסָלִיק וְקַיְּימָא לְעֵילָּא, אִתְעַרְבָב. כְּדֵין הַהוּא קַלָּא קַיְּימָא, וְאַעְבַּר הַהוּא דִּינָא, וְכֵיוָן דִּלְתַתָּא אַתְּעָרוּ רַחֲמֵי, הָכִי נָמֵי לְעֵילָּא, אִתְּעַר שׁוֹפְרָא אַחֲרָא עִלָּאָה, וְאַפִּיק קָלָא דְּאִיהוּ רַחֲמֵי, וְאַתְעָרְעוּ קָלָא בְּקָלָא, רַחֲמֵי בְּרַחֲמֵי, וּבְאִתְעָרוּתָא דִּלְתַתָּא, אִתְּעַר הָכִי נָמֵי לְעֵילָּא."],[[0,"בגין דההוא שעתא","וכו': ומשיב, משום שבשעה ההיא שיצאו ישראל ממצרים ונשלמו לששים רבוא, נתחזק המלכות הקדושה ונתעלה על הכל, והלבנה, שהיא המלכות, האירה. ואז נכנעה מלכות הרשעה סטרא אחרא, והוציא הקב\"ה את ישראל ללכת במדבר החזק, שהוא מקום והשליטה של סמאל הרשע, שהוא שלו ממש, כדי לשבור תוקפו וכחו ולכתת ראשו ולהכניעו שלא ישלוט. ואם לא חטאו ישראל רצה הקב\"ה להעבירו מן העולם. וע\"כ העביר את ישראל בנחלתו וגורלו וחלקו ממש."],[1,"כיון דחאבו בכמה","וכו': כיון שחטאו כמה פעמים, נשך אותם הנחש, ואז נתקיים, הוא ישופך ראש, שישראל הכו ראשו תחילה, ולא ידעו, להשמר ממנו, ואח\"כ הנחש הכה לאחרונה, ונפלו כולם במדבר ונתקיים, ואתה תשופנו עקב. וארבעים שנה הוכו על ידו כנגד ארבעים מכות של בית דין."],[2,"וע\"ד כתיב אשר","וכו': וע\"כ כתוב, \u0003אשר ראית,\u0004 כי בעיניהם היו רואים את בעל המדבר, שהולך אסור לפניהם, ולקחו נחלתו וגורלו. מאין לנו. הוא משכתוב, אז נבהלו אלופי אדום, שאלו הם נחש שרף ועקרב. ואנו גם כן נפרדנו מן הישוב אל המדבר החזק, ולעסוק שם בתורה, כדי להכניע לצד ההוא."],[3,"ותו דלא מתישבן","וכו': ועוד, כי דברי תורה אינם מתישבים אלא שם, כי אין אור אלא אותו היוצא מתוך החשך. כי כאשר צד הזה נכנע, מתעלה הקב\"ה למעלה ונתגדל כבודו, ואין עבודת הקב\"ה אלא מתוך החשך, ואין טוב אלא מתוך הרע, וכשהאדם נכנס לדרך רע ועוזב אותו, אז מתעלה הקב\"ה בכבודו. וע\"כ שלמות הכל, הוא טוב ורע יחד, ולהסתלק אח\"כ אל הטוב. ואין טוב אלא אותו שיוצא מתוך הרע, ובטוב הזה מתעלה כבודו של הקב\"ה, וזה הוא עבודה שלמה."],[4,"ואנן עד השתא","וכו': ואנו עד עתה ישבנו שם כל ימות השנה, כדי להכניע צד ההוא במדבר, עתה שהגיע הזמן של עבודת הקדש של צד הקדוש, אנו חוזרים לישוב, ששם הוא עבודת הקב\"ה. ועוד, שעתה בראש השנה הגיע הזמן של נחש ההוא לבקש דין מלפני הקב\"ה. ושם במדבר הוא שולט, וע\"כ יצאנו משם ובאנו לישוב."],[5,"פתח ההוא סבא","וכו': פתח זקן ההוא, ואמר, תקעו בחדש שופר בכסא ליום חגנו. עתה הוא הזמן שיתעורר דין עליון חזק, וכשהוא מתעורר, הסטרא אחרא מתחזק עמו, וכיון שהסטרא אחרא מתחזק, הוא עולה ומכסה את הלבנה שהיא המלכות, ואינה מאירה אור, ומתמלאת מצד הדין. ואז כל העולם הוא בדין, העליונים והתחתונים. וכרוז יוצא בכל הרקיעים, התקינו כסא הדין לאדון הכל, שהוא רוצה לדון."],[6,"ורזא הכא ואתנהיר","וכו': וסוד יש כאן והאיר לנו במדבר, למה נתעורר דין העליון ביום הזה. ומשיב, אלא כל הסודות וכל הקדושות היקרות, כולם תלוים בשביעי, שהוא מלכות, ושביעי העליון ההוא, שהוא עולם העליון הנקרא עולם הבא, דהיינו בינה, ממנה מאירים כל הנרות וכל הקדושות וכל הברכות אל המלכות, וכשהגיע הזמן לחדש הברכות והקדושות שיאירו, צריך להשגיח בכל התקון של העולמות כולם, כדי לחדש הברכות והקדושות, וכל התקונים לקיים כל העולמות, עולים מן התחתונים אם מעשיהם ישרים. ואם אינם ישרים, אז עומדת המלכות, שאינה מאירה עד שיפרידו הרשעים מן הצדיקים. ואז נתעורר הדין."],[7,"ומההוא דינא אתתקף","וכו': ומדין ההוא מתחזק הסטרא אחרא, ונמצא מקטרג כדי שיתנו לו אלו הרשעים. משום שעליו כתוב, ולכל תכלית הוא חוקר. ומכסה את הלבנה שלא תאיר. ולמה אינו מוסר את הרשעים בידי המקטרג, משום שאין חפצו של הקב\"ה להאביד מעשה ידיו."],[8,"וההוא סטרא אחרא","וכו': וסטרא אחרא ההוא, נמצאת קליפה קשה. שאי אפשר לשברה חוץ בעצה ההוא שהקב\"ה נתן לישראל שכתוב, תקעו בחדש שופר בכסה ליום חגנו. כדי לשבור כיסוי ההוא שנתכסה ממנו הלבנה, שהוא מלכות, ואינה מאירה."],[9,"וכד מתערי ישראל לתתא","וכו': וכשישראל מתעוררים למטה בתקיעת שופר, קול ההוא היוצא משופר, בוטש באויר ובוקע רקיעים עד שעולה לאבן החזק ההוא, דהיינו הסטרא אחרא, המכסה את הלבנה, הוא משגיח ומוצא התעוררות הרחמים, אז סטרא אחרא ההוא שעלה ועומד למעלה ומכסה את הלבנה מתבלבל. אז עומד קול ההוא ומעביר את הדין ההוא, מן המלכות. וכיון שנתעורר הרחמים למטה במלכות, התעורר גם כן למעלה, שופר אחר עליון, שהוא בינה, ומוציא קול, דהיינו המוחין דז\"א שנקרא קול, שהוא רחמים, ונפגשים קול בקול, רחמים ברחמים. כי בהתעוררות שלמטה, נתעורר גם כן למעלה."],[9,"","ביאור הדברים. בראש השנה, התעוררות הראשון שביום ד' דמעשה בראשית חוזר לעולם, דהיינו שהנוקבא נאחזת בקו שמאל, בלי ימין. (כנ\"ל פרשת נח אות צ\"ח ע\"ש בהסולם) ואז נמשכת ממנה דינים לעולם. כי מחמת היותה חכמה בלי חסדים אינה יכולה להאיר, וזה נבחן שהס\"א מכסה אותה מכח מעשי התחתונים שאינם כשרים, שהם הרשעים הדבוקים בקו שמאל, וז\"ש (באות פ\"ט) \u0003ואי לא כשראן, כדין קיימא דלא נהיר\u0004 וכו'. וסוד תקיעת שופר, ה\"ס העלאת מ\"ן דמסך דחירק שעל ידו מתמעט כח השמאל ומתיחד עם הימין, וז\"ס קול שופר, כי קול רומז על ז\"א, שנקרא קול, שה\"ס קו האמצעי הכלול מג' קוין שה\"ס אש מים רוח. וע\"כ נתבלבלה הס\"א המכסה את המלכות בכח קו שמאל, כי הקו שמאל נתמעט ואבד הג\"ר שלו ומכ\"ש הסטרא אחרא ששואב כחו ממנו, וז\"ש, \u0003כדין ההוא דסליק וקיימא לעילא אתערבב,\u0004 שהארתו סר ממנו, \u0003כדין ההוא קלא קיימא ואעבר ההוא דינא,\u0004 שמעביר דין השמאל, שאינו חפץ להתיחד עם הימין, ועתה נכנע ומקבל חסדים מימין ונתגלה הרחמים במלכות. וז\"ש, \u0003וכיון דלתתא אתערו רחמי, הכי נמי לעילא אתער שופרא אחרא עלאה, ואפיק קלא דאיהו רחמי,\u0004 שהבינה מתעוררת ומולידה המוחין דז\"א הנק' קול, שה\"ס קו האמצעי הממשיך המוחין דבינה, בסוד תלת מחד נפקי חד בתלת קיימא, ונמשכים אל המלכות וז\"ש \u0003ואתערעו קלא בקלא רחמי ברחמי,\u0004 שנפגשים הקול והרחמים מבינה, ונפגשים עם קו האמצעי והרחמים שיצא במלכות ע\"י אתערותא דלתתא של קול שופר. \u0003ובאתערותא דלתתא\u0004 של קול שופר, \u0003אתער הכי נמי לעילא,\u0004 שנמשכים המוחין דבינה לז\"א ומז\"א אל המלכות, שמוחין אלו הם אתערותא דלעילא בסוד קול שופר. ששופר העליון ה\"ס בינה, וקול שלו, הם המוחין דג' קוין הנמשכים ממנה, המכונים אש מים רוח."]],[[0,"","מִשּׁוּם שֶׁבַּשָּׁעָה הַהִיא שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם וְנִשְׁלְמוּ לְשִׁשִּׁים רִבּוֹא, הִתְחַזְּקָה הַמַּלְכוּת הַקְּדוֹשָׁה וְעָלְתָה עַל הַכֹּל, וְהֵאִירָה הַלְּבָנָה, וְאָז נִכְנְעָה מַלְכוּת הָרְשָׁעָה, הַצַּד הָאַחֵר, וְהוֹצִיא אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לָלֶכֶת בְּמִדְבָּר חָזָק, שֶׁהוּא מְקוֹם וְשִׁלְטוֹן סָמָאֵ\"ל הָרָשָׁע, שֶׁהוּא שֶׁלּוֹ מַמָּשׁ, כְּדֵי לִשְׁבֹּר חָזְקוֹ וְכֹחוֹ וּלְכַתֵּת רֹאשׁוֹ (ולהורידאותו) וּלְהַכְנִיעַ אוֹתוֹ שֶׁלֹּא יִשְׁלֹט. וְאִלְמָלֵא חָטְאוּ יִשְׂרָאֵל, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מִן הָעוֹלָם, וְעַל זֶה הֶעֱבִיר אוֹתָם בְּנַחֲלָתוֹ וְגוֹרָלוֹ וְחֶלְקוֹ מַמָּשׁ."],[1,"","בִּגְלַל שֶׁחָטְאוּ בְּכַמָּה פְעָמִים, נָשַׁךְ אוֹתָם הַנָּחָשׁ, וְאָז הִתְקַיֵּם (בראשית ג) הוּא יְשׁוּפְךְ רֹאשׁ וְגוֹ'. יִשְׂרָאֵל הִכּוּ רֹאשׁוֹ בַתְּחִלָּה וְלֹא יָדְעוּ לְהִשָּׁמֵר מִמֶּנּוּ, וּלְבַסּוֹף הוּא הִכָּה בָאַחֲרוֹנָה, וְנָפְלוּ כֻלָּם בַּמִּדְבָּר, וְהִתְקַיֵּם וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. וְאַרְבָּעִים שָׁנָה לָקוּ מִמֶּנּוּ, כְּנֶגֶד אַרְבָּעִים מַלְקוֹת שֶׁל בֵּית דִּין."],[2,"","וְעַל זֶה כָּתוּב אֲשֶׁר רָאִיתָ, בְּעֵינֵיהֶם הָיוּ רוֹאִים אֶת אֲדוֹן הַמִּדְבָּר הוֹלֵךְ קָשׁוּר לִפְנֵיהֶם, וְלָקְחוּ נַחֲלָתוֹ וְגוֹרָלוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמות טו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם, וְאֵלֶּה הֵם (דבריםח) נָחָשׁ שָׂרָף וְעַקְרָב. וַאֲנַחְנוּ גַּם כָּךְ נִפְרַדְנוּ מֵהַיִּשּׁוּב לַמִּדְבָּר הֶחָזָק לְעַיֵּן שָׁם בַּתּוֹרָה, כְּדֵי לְהַכְנִיעַ אֶת הַצַּד הָאַחֵר."],[3,"","וְעוֹד, שֶׁלֹּא מִתְיַשְּׁבִים דִּבְרֵי תוֹרָה אֶלָּא שָׁם, שֶׁאֵין אוֹר אֶלָּא אוֹתוֹ הַיּוֹצֵא מִתּוֹךְ הַחֹשֶׁךְ. שֶׁכַּאֲשֶׁר נִכְנָע צַד זֶה, מִתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּמִתְכַּבֵּד בִּכְבוֹדוֹ, וְאֵין עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִתּוֹךְ הַחֹשֶׁךְ, וְאֵין הַטּוֹב אֶלָּא מִתּוֹךְ הָרָע. וְכַאֲשֶׁר נִכְנָס בֶּן אָדָם בְּדֶרֶךְ רָעָה וְעָזַב אוֹתָהּ, אָז מִתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ, וְעַל זֶה שְׁלֵמוּת הַכֹּל - טוֹב וָרַע כְּאֶחָד, וְלַעֲלוֹת אַחַר כָּךְ בְּטוֹב, וְאֵין טוֹב אֶלָּא הַהוּא שֶׁיָּצָא מִתּוֹךְ הָרָע. וּבְטוֹב זֶה מִתְעַלֶּה כְבוֹדוֹ, וְזוֹהִי עֲבוֹדָה שְׁלֵמָה."],[4,"","וַאֲנַחְנוּ עַד עַכְשָׁו יוֹשְׁבִים שָׁם כָּל יְמֵי הַשָּׁנָה בִּכְדֵי לְהַכְנִיעַ בַּמִּדְבָּר לַצַּד הָאַחֵר. עַכְשָׁו שֶׁהִגִּיעַ זְמַן עֲבוֹדַת הַקֹּדֶשׁ שֶׁל צַד הַקְּדֻשָּׁה, חָזַרְנוּ לְיִשּׁוּב, שֶׁשָּׁם הִיא עֲבוֹדָתוֹ. וְעוֹד, שֶׁעַתָּה בְּרֹאשׁ הַשָּׁנָה הִגִּיעַ זְמַן שֶׁל הַנָּחָשׁ הַהוּא לִתְבֹּעַ דִּין מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁם הוּא שׁוֹלֵט, וּמִפְּנֵי כָּךְ יָצָאנוּ מִשָּׁם וּבָאנוּ לְיִשּׁוּב."],[5,"","פָּתַח הַזָּקֵן הַהוּא וְאָמַר, (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. עַכְשָׁו הוּא הַזְּמַן לְהִתְעוֹרֵר הַדִּין הָעֶלְיוֹן הֶחָזָק, וְכַאֲשֶׁר הוּא מִתְעוֹרֵר, הַצַּד הָאַחֵר מִתְחַזֵּק כְּנֶגְדּוֹ. וּמִכֵּיוָן שֶׁהוּא מִתְחַזֵּק, עוֹלֶה וּמְכַסֶּה לַלְּבָנָה, שֶׁלֹּא מְאִירָה אוֹר, וּמִתְמַלֵּאת מִצַּד הַדִּין. אָז כָּל הָעוֹלָם הוּא בְדִין, עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכָרוֹז קוֹרֵא בְכָל הָרְקִיעִים: הַתְקִינוּ כִסֵּא שֶׁל דִּין לַאֲדוֹן הַכֹּל, שֶׁהוּא רוֹצֶה לָדוּן."],[6,"","וְסוֹד כָּאן, וְהֵאִיר לָנוּ בַמִּדְבָּר, מַדּוּעַ מִתְעוֹרֵר דִּין עֶלְיוֹן בְּיוֹם זֶה. אֶלָּא כָּל סוֹדוֹת וְכָל הַקְּדֻשּׁוֹת הַנִּכְבָּדוֹת, כֻּלָּם תְּלוּיִים בַּשְּׁבִיעִי. וְהַשְּׁבִיעִי הַהוּא הָעֶלְיוֹן, עוֹלָם הָעֶלְיוֹן, שֶׁנִּקְרָא עוֹלָם הַבָּא. מִמֶּנּוּ מְאִירִים כָּל הַנֵּרוֹת וְכָל הַקְּדֻשּׁוֹת וְכָל הַבְּרָכוֹת. וְכַאֲשֶׁר מַגִּיעַ הַזְּמַן לְחַדֵּשׁ הַבְּרָכוֹת וְהַקְּדֻשּׁוֹת לְהָאִיר, צָרִיךְ לְהַשְׁגִּיחַ בְּכָל תִּקּוּן שֶׁל הָעוֹלָמוֹת כֻּלָּם, וְכָל הַתִּקּוּנִים הָהֵם לְקַיֵּם כֻּלָּם עוֹלִים מִתּוֹךְ הַתַּחְתּוֹנִים, אִם הֵם כְּשֵׁרִים. וְאִם אֵינָם כְּשֵׁרִים, אָז עוֹמֶדֶת, (דבר) שֶׁלֹּא מְאִירָה, עַד שֶׁנִּפְרָדִים הַחַיָּבִים מִתּוֹךְ הַזַּכָּאִים, אָז מִתְעוֹרֵר הַדִּין."],[7,"","וּמֵהַדִּין הַהוּא מִתְחַזֵּק הַצַּד הָאַחֵר, וְנִמְצָא מְקַטְרֵג, כְּדֵי שֶׁיִּנָּתְנוּ לוֹ אֵלּוּ הַחַיָּבִים, מִפְּנֵי שֶׁכָּתוּב (איוב כח) וּלְכָל תַּכְלִית הוּא חוֹקֵר. וּמְכַסֶּה לַלְּבָנָה. מַדּוּעַ (לא מוסרת אותם ביד המקטרג) ? מִפְּנֵי שֶׁאֵין רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבֵּד אֶת מַעֲשֵׂי יָדָיו."],[8,"","וְהַצַד הָאַחֵר הַהוּא עוֹמֵד כִּקְלִפָּה חֲזָקָה, שֶׁאֵינָהּ יְכוֹלָה לְהִשָּׁבֵר חוּץ בְּאוֹתָהּ עֵצָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְיִשְׂרָאֵל, שֶׁכָּתוּב תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. כְּדֵי לִשְׁבֹּר הַכִּסּוּי הַהוּא שֶׁמְּכַסֶּה אֶת הַלְּבָנָה, וְלֹא מְאִירָה."],[9,"","וְכַאֲשֶׁר מִתְעוֹרְרִים יִשְׂרָאֵל לְמַטָּה בַּשּׁוֹפָר, הַקּוֹל הַהוּא שֶׁיּוֹצֵא מֵהַשּׁוֹפָר מַכֶּה בָאֲוִיר, וּבוֹקֵעַ אֶת הָרְקִיעִים, עַד שֶׁעוֹלֶה לְגַבֵּי הַסֶּלַע הַהוּא הֶחָזָק, (הצד האחר) שֶׁמְּכַסֶּה לַלְּבָנָה, מַשְׁגִּיחַ וּמוֹצֵא הִתְעוֹרְרוּת הָרַחֲמִים, אָז הַהוּא שֶׁעוֹלֶה וְעוֹמֵד לְמַעְלָה, מִתְעַרְבֵּב. אָז הַקּוֹל הַהוּא עוֹמֵד וּמַעֲבִיר הַדִּין הַהוּא, וְכֵיוָן שֶׁלְּמַטָּה מִתְעוֹרְרִים הָרַחֲמִים, כָּךְ גַּם לְמַעְלָה מִתְעוֹרֵר שׁוֹפָר אַחֵר עֶלְיוֹן וּמוֹצִיא קוֹל שֶׁהוּא רַחֲמִים, וּמִתְעַרְבְּבִים קוֹל בְּקוֹל, רַחֲמִים בְּרַחֲמִים, וּבַהִתְעוֹרְרוּת שֶׁל לְמַטָּה מִתְעוֹרֵר כָּךְ גַּם לְמַעְלָה."]]],[["וְאִי תֵּימָא, הֵיךְ יָכִיל קָלָא דִּלְתַתָּא, אוֹ אִתְּעָרוּתָא דִּלְתַתָּא לְאַתְעֲרָא, הָכִי נָמֵי. תָּא חֲזֵי, עָלְמָא תַּתָּאָה, קַיְּימָא לְקַבְּלָא תָּדִיר, וְהוּא אִקְרֵי אֶבֶן טָבָא. וְעָלְמָא עִלָּאָה לָא יָהִיב לֵיהּ, אֶלָּא כְּגַוְונָא דְּאִיהוּ קַיְּימָא. אִי אִיהוּ קַיְּימָא בִּנְהִירוּ דְּאַנְפִּין מִתַּתָּא, כְּדֵין הָכִי נַהֲרִין לֵיהּ מִלְעֵילָּא. וְאִי אִיהוּ קַיְּימָא בַּעֲצִיבוּ, יַהֲבִין לֵיהּ דִּינָא בְּקָבְלֵיהּ.","כְּגַוְונָא דָּא, (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה. חֶדְוָה דְּבַּר נָשׁ, מָשִׁיךְ לְגַבֵּיהּ חֶדְוָה אַחֲרָא עִלָּאָה. הָכִי נָמֵי הַאי עָלְמָא תַּתָּאָה, כְּגַוְונָא דְּאִיהִי אִתְעַטְּרָת, הָכִי אַמְשִׁיךְ מִלְעֵילָּא. בְּגִין כָּךְ מְקַדְּמֵי יִשְׂרָאֵל, וְאַתְעֲרֵי בַּשּׁוֹפָר קָלָא דְּאִיהוּ (רזא דרחמי) כָּלִיל בְּאֶשָּׁא וּמַיָא וְרוּחָא, וְאִתְעָבִיד חַד, וְסַלְּקָא לְעֵילָּא, וּבָטַשׁ בְּהַאי אֶבֶן טָבָא, וְאִצְטְבַּע בְּאִינּוּן גַּוְונִין דְּהַאי קָלָא, וּכְדֵין כְּמָה דְּאִתְחַזִיאָת, הָכִי מָשִׁיךְ מִלְּעֵילָּא.","וְכֵיוָן דְּאִתַּקְנַת בְּהַאי קָלָּא. רַחֲמֵי נַפְקֵי מִלְּעֵילָּא, וְשַׁרְיָין עָלָהּ, וְאִתְכְּלִילָא בְּרַחֲמֵי, מִתַּתָּא וּמִלְּעֵילָּא. וּכְדֵין אִתְעַרְבָּב סִטְרָא אַחֲרָא. (אסתכל וחמי בנהירו דאנפין) וְאִתְחַלָּשׁ תֻּקְפֵּיהּ, וְלָא יָכִיל לְקַטְרְגָא. וְהַאי אֶבֶן טָבָא, קַיְּימָא בִּנְהִירוּ דְּאַנְפִּין, מִכָּל סִטְרִין, בִּנְהִירוּ דִּלְתַתָּא, וּבִנְהִירוּ דִּלְעֵילָּא.","אֵימָתַי קַיְּימָא בִּנְהִירוּ דִּלְעֵילָּא, הֲוֵי אוֹמֵר בְּיוֹמָא דְּכִפּוּרֵי. וּבְיוֹמָא דְּכִפּוּרֵי אִתְנְהִיר הַהוּא אֶבֶן טָבָא, בִּנְהִירוּ דִּלְעֵילָּא, מִגּוֹ נְהִירוּ דְּעָלְמָא דְּאָתֵי, (ואתערבב ההוא דלטורא) וּכְדֵין מְתַקְּנִין יִשְׂרָאֵל לְתַתָּא חַד שָׂעִיר, וּמְשַׁדְּרִין לְהַאי מַדְבְּרָא תַּקִּיפָא, דְּאִיהוּ שַׁלְטָא עָלֵיהּ.","וְהַהוּא סִטְרָא אַחֲרָא, אִיהוּ נְקוּדָה אֶמְצָעִיתָא דְּחָרִיבוּ דְּעָלְמָא, בְּגִין דְּכָל חָרִיבוּ וְשִׁמָמוֹן (ס\"א מניה, הוא מההוא סטרא אחרא דשליט) מִנֵיהּ, הַהוּא סִטְרָא אַחֲרָא שַׁלִּיט עָלֵיהּ. וּנְקוּדָה אֶמְצָעִיתָא דְּכָל יִשּׁוּבָא, סִטְרָא דִּקְדוּשָּׁה אִיהוּ, וְעַל דָּא, קַיְּימָא יְרוּשָׁלַ ם בְּאֶמְצָעִיתָא דְּכָל יִשּׁוּבָא דְּעָלְמָא.","בִּתְרֵין נְקוּדִין אִתְפְּרָשַׁת מָלְכוּ שְׁמַיָא, סִטְרָא דִּקְדוּשָּׁא, חַד דִּילָהּ, וְחַד דְּעָלְמָא דְּאָתֵי, נְקוּדָה עִלָּאָה טְמִירָאָה, וְעַל דָּא קַיְּימָא בִּתְרֵין נְקוּדִין: נְקוּדָה דִּילָהּ קַיְּימָא תְּחוֹתָהּ, יְרוּשָׁלַ ם, אֶמְצָעִיתָא דְּכָל יִשּׁוּבָא. נְקוּדָא דְּנַטְלָא מֵאִימָא עִלָּאָה טְמִירָא, (רי\"ט ע\"ב, רפ\"א ע\"ב) אִיהוּ גַּן עֵדֶן דְּאַרְעָא, דְּקַיְּימָא בְּאֶמְצָעִיתָא דְּכָל עָלְמָא, לְכָל סִטְרִין, דְּחָרִיבוּ וְיִשׁוּבָא, וְכָל סִטְרִין דְּעָלְמָא.","וְעַל דָּא, בְּאֶמְצָעִיתָא (קל\"ב ע\"ב) דְּגַן עֵדֶן, קַיְּימָא נְקוּדָה חֲדָא עִלָּאָה טְמִירָא וּגְנִיזָא, דְּלָא יְדִיעַ. וְחַד עַמּוּדָא, נָעִיץ מִתַּתָּא לְעֵילָּא, גּוֹ הַהִיא נְקוּדָה, וּמִתַּמָּן נַבְעֵי מַיָּא, דְּאִתְפְּרִישׁוּ לְאַרְבַּע סִטְרֵי עָלְמָא. אִשְׁתְּכָחוּ תְּלַת נְקוּדִין בְּעָלְמָא, דְּקַיְימָאן דָּא עַל דָּא, כְּגַוְונָא דִּתְלַת נְקוּדִין דְּאוֹרַיְיתָא.","תָּא חֲזֵי, הַהוּא שָׂעִיר דִּמְשַׁדְּרִין יִשְׂרָאֵל לַעֲזָאזֵל, לְהַהוּא מַדְבְּרָא, בְּגִין לְמֵיהַב חוּלָקָא לְהַהוּא סִטְרָא אַחֲרָא, לְאִתְעַסְּקָא בַּהֲדֵיהּ. וְאִי תֵּימָא, תְּרֵין שְׂעִירִין אֲמַאי הָכָא, חַד לַיְיָ' וְחַד לְהַהוּא סִטְרָא אַחֲרָא. תִּינַח הַהוּא שָׂעִיר דְּסִטְרָא אַחֲרָא. לַיְיָ' אֲמַאי.","אֶלָּא לְמַלְכָּא דְּהֲוָה אַרְגִּיז עַל בְּרֵיהּ, קָרָא לְסַנְטִירָא, הַהוּא דְּעָבִיד דִּינָא בִּבְנֵי נָשָׁא תָּדִיר, בְּגִין דְּיִזְדָּמַּן לְמֶעְבַּד דִּינָא בִּבְרֵיהּ. הַהוּא סַנְטִירָא חַדֵּי, וְעָאל בְּבֵי מַלְכָּא לְמֵיכַל תַּמָּן, כֵּיוָן דְּאַשְׁגַּח בֵּיהּ בְּרֵיהּ, אָמַר, וַדַּאי לָא עָאל סַנְטִירָא דָּא בְּבֵי אַבָּא, אֶלָּא בְּגִין דְּאַרְגִּיז מַלְכָּא עָלַי. מָה עָבֵד, אָזַל וְאִתְפְּיָיס בַּהֲדֵיהּ. כֵּיוָן דְּאִתְפָּיַיס בַּהֲדֵיהּ, פָּקִיד מַלְכָּא לְמֶעְבַּד סְעוּדָתָא עִלָּאָה לֵיהּ וְלִבְרִיהּ, וּפָקִיד דְּלָא יָדַע בֵּיהּ הַהוּא סַנְטִירָא. לְבָתַר עָאל הַהוּא סַנְטִירָא. אָמַר מַלְכָּא הַשְׁתָּא אִי יִנְדַּע דָּא, מִסְּעוּדָתָא עִלָּאָה דְּאַתְקִינִית לִי וְלִבְרִי, יִתְעַרְבֵּב פָּתוֹרָא. מָה עֲבַד. קָרָא לַמְּמָנָא עַל סְעוּדָתָא, אָמַר לֵיהּ, אַתְקִין מִדִי, וּתְשָׁוֵי קַמָּאי, וּתְשָׁוֵי קַמֵּיהּ דְּהַהוּא סַנְטִירָא, בְּגִין דְּיַחְשִׁיב דְּסָעִיד קַמָּאי מִדִּילִי, וְלָא יִנְדַּע בְּהַהִיא סְעוּדָתָא יַקִּירָא דְּחֶדְוָה דִּילִי וְדִבְרִי, וְיִטּוֹל הַהוּא חוּלָקָא וְיֵזִיל לֵיהּ, וְיִתְפְּרַשׁ מִחֶדְוָה דִּסְעוּדָתָא דִּילָן. וְאִי לָאו דְּמַלְכָּא עָבִיד הָכִי, לָא יִתְפְּרַשׁ הַהוּא סַנְטִירָא מִבֵּי מַלְכָּא."],[[0,"ואי תימא היך","וכו': ואם תאמר, איך יכול הקול שלמטה, או התעוררות שלמטה, לעורר כנגדו למעלה גם כן. בוא וראה, עולם התחתון שהוא מלכות, עומד תמיד לקבל, והוא נקרא אבן טוב, ועולם העליון שהוא בינה, אינו נותן לו, אלא כמו שהוא עומד, אם עומד בהארת הפנים מלמטה, אז כך מאירים לו מלמעלה. ואם הוא עומד בעצבות נותנים לו כנגדו דין."],[1,"כגוונא דא, עבדו","וכו': כעין זה, עבדו את ה' בשמחה, כי שמחת האדם מושכת שמחה אחרת העליונה. כך, עולם התחתון הזה, דהיינו המלכות, כמו שהיא מתעטרת, כך ממשכת מלמעלה. משום זה, מקדימים ישראל ומעוררים קול בשופר, שהוא כלול באש מים ורוח, דהיינו קו האמצעי הכלול מג' קוין, ונעשו אחד, ועולה למעלה, ומכה באבן טוב הזה, דהיינו שממעט קו השמאל שלה, כנ\"ל בסמוך, ונצטבעת באלו ג' גוונין, שהם לבן אדום ירוק, שהם ג' קוין הכלולים בקול הזה, ואז כמו שהיא ראויה כך היא ממשכת מלמעלה."],[2,"וכיון דאתקנת בהאי","וכו': וכיון שהמלכות נתתקנה בקול הזה מלמטה, יוצאים רחמים מלמעלה ושורים עליה, ונכללה ברחמים ממטה ומלמעלה, ואז נתערבב הסטרא אחרא, מטעם הנ\"ל (באות צ\"ב בהסולם) ונחלש תוקפו, ואינו יכול לקטרג. ואבן הטוב הזה, שהיא המלכות, עומד בהארת הפנים מכל הצדדים בהארה שלמטה ובהארה שלמעלה."],[3,"אימתי קיימא בנהירו","וכו': מתי עומדת בהארה שלמעלה. הוי אומר, ביום הכפורים, שביום הכפורים הואר אבן טוב ההוא, דהיינו המלכות, בהארה עליונה מתוך האור של עולם הבא, שהוא בינה, ואז מתקנים ישראל שעיר אחד ושולחים אותו למדבר הזה החזק שהוא שולט עליו. ועי' פרשת נח אות ק\"ה, ביאור השעיר לעזאזל, ובסולם בכל ההמשך."],[4,"וההוא סטרא אחרא","וכו': וסטרא אחרא ההוא הוא נקודה האמצעית של חלק העולם החרב, משום שכל חורבן ושממה שבעולם, סטרא אחרא ההוא שולט עליו. ונקודה האמצעית של חלק העולם המיושב, הוא צד הקדוש. דהיינו המלכות, וע\"כ עומדת ירושלים באמצע חלק העולם המיושב. שה\"ס המלכות."],[5,"בתרין נקודין אתפרשת","וכו': בב' נקודות, נבדלת מלכות שמים צד הקדושה, אחת שלה, ואחת שקבלה מעולם הבא, שהיא בינה, שהיא נקודה עליונה מכוסה, וע\"כ עומדת המלכות בב' נקודות: נקודה שלה עומדת תחתיה, שהיא ירושלים שהיא אמצעית של כל הישוב. הנקודה המכוסה שקבלה מאמא עלאה, היא גן עדן הארץ העומד באמצעית כל העולם לכל בחינותיו, של חורבן ושל ישוב, וכל צדדי העולם."],[6,"וע\"ד באמצעיתא דגן","וכו': וע\"כ באמצע גן עדן, עומדת נקודה אחת עליונה צט) \u0003וע\"ד באמצעיתא דגן\u0004 וכו': וע\"כ באמצע גן עדן, עומדת נקודה אחת עליונה מכוסה וגנוזה שאינו ידועה. ועמוד אחד תקוע ממטה למעלה, תוך נקודה ההיא, ומשם נובעים מים, שנחלקים לארבעה צדדי העולם. נמצא, שיש ג' נקודות בעולם העומדות זו על זו, כעין ג' נקודות שבתורה."],[6,"","ביאור הדברים. כי נתבאר לעיל ב' מצבים שבמלכות, מצב א' בזמן שהיתה למעלה מחזה דז\"א, והיתה מלבשת קו שמאל דבינה, שה\"ס נקודת השורק שבבינה, שהוא חכמה בלי חסדים, שמשם נמשכים רק דינים וחורבן בלבד. (כנ\"ל אות צ\"ב) מצב ב' אחר שנתמעטה וירדה תחת החזה דז\"א, ומקבלת החסדים מז\"א, שאז מה דהוית יבשה אתעבידת ארעא דעבדא פירין ואיבין דהיינו ישוב העולם. כמ\"ש שם. \u0003ונקודה אמצעיתא דכל ישובא סטרא דקדושה איהו.\u0004 והס\"א נאחזת במצב הא' של המלכות שה\"ס השמאל הממשיך דינים וחורבן ושממה. וז\"ש, \u0003וההוא סטרא אחרא איהו נקודה דאמצעיתא דחריבו דעלמא.\u0004 ונמצא עתה, שהעולם נחלק בין המלכות וסטרא אחרא, שהמלכות שולטת על חלק הישוב שבעולם העושה פירות, והסטרא אחרא הנאחזת במצב הא', שולטת על חלק החורבן והשממה שבעולם. וע\"כ נקראת המלכות נקודה אמצעית דישובא דעלמא, והסטרא אחרא נקראת, נקודה אמצעית דחריבו דעלמא."],[6,"","והנה גם בבינה יש אותם ב' מצבים, כי בעת שהיתה במצב של נקודת השורק מטרם הכרעת קו האמצעי נמשך ממנה דינים קשים וחורבן. ואחר הכרעת קו אמצעי, שהחכמה דשמאל נתלבשה בחסדים דימין, היא מאירה ועושה פירות וכל המוחין נמשכים ממנה. אמנם יש הפרש גדול מבינה למלכות, כי הבינה אע\"פ שנתמעטה מג\"ר דג\"ר ע\"י קו האמצעי מכל מקום היא ראויה עוד להמשכת החכמה, בבחינת שמאל בלי ימין, משום שבבינה עצמה אין דינים רק דינים מתערין ממנה, מה שאין כן המלכות, אחר שנתמעטה וירדה למטה מחזה דז\"א, כבר נפגמה ע\"י מסך העומד בחזה דז\"א ואינה ראויה עוד לחכמה, רק לחסדים בלבד, שה\"ס ישוב העולם. באופן, שבבינה שולטים ב' המצבים ביחד, וע\"כ היא שורש בין לחורבן הנמשך ממצב הא' בין לישוב עולם הנמשך ממצב הב'. משא\"כ המלכות אחר שבאה למצב הב' כבר אין מצב הא' שולט בה, וע\"כ היא שורש לישוב העולם בלבד ולא לחורבן."],[6,"","אמנם כשהמלכות נתקנה בבחינת גן עדן, שפירושו הוא. שנעשתה לגמרי כמו בינה הנקראת עדן, כנ\"ל (ב\"ב אות ד') שאומר, \u0003נימוסי דגנתא דעדן. כמה דאיהי ברזא עלאה.\u0004 שכל חוקי הגן העדן הוא כמו שהמלכות הוא בסוד העליון, בבינה. ע\"ש. נמצא אז, שגם נקודת הבינה מתלבשת במלכות, שהוא שורש בין לחורבן ובין לישוב, ונמצא משום זה, שיש במלכות ב' בחינות הנקודות, א' שלה עצמה, שהיא נקודה אמצעית לישוב העולם בלבד. ואחת בבחינת גן עדן שבה, שיש בה גם נקודת הבינה, שהיא נקודה אמצעית דהיינו שורש בין לחריבו דעלמא ובין לישובא דעלמא, כמבואר."],[6,"","וזה אמרו, \u0003בתרין נקודין אתפרשת מלכו שמיא סטרא דקדושה. חד דילה,\u0004 אחר שנתקנה במצב הב'. \u0003וחד דעלמא דאתי,\u0004 מבינה, דהיינו אחר שנתקנה בבחינת גן עדן. \u0003נקודה דילה\u0004 וכו' \u0003אמצעיתא דכל ישובא,\u0004 דהיינו רק לחסדים, ואין בה שום שורש לחורבן. \u0003נקודה דנטלא מאמא עלאה טמירא,\u0004 דהיינו בעת, \u0003איהו גן עדן דארעא,\u0004 אז נמצאת, \u0003דקיימא באמצעיתא דכל עלמא לכל סטרין, דחריבו, וישובא,\u0004 שיש בה ב' השורשים הן לחורבן מבחינת צד שמאל, בלי ימין והן לישוב מבחינת קו האמצעי המיחד ב' הקוין שבה. \u0003נקודה אמצעית\u0004 היינו יסוד, ששם הבית קבול, ומשם התולדות לתחתונים."],[6,"","וז\"ש \u0003באמצעיתא דגן עדן קיימא נקודה\u0004 וכו', היינו היסוד, \u0003וחד עמודא נעיץ\u0004 וכו', היינו עמוד האמצעי. \u0003נבעי מיא,\u0004 היינו אורות, \u0003לד' סטרי עלמא,\u0004 היינו ג' קוין, ומלכות המקבלתם."],[6,"","וז\"ש \u0003אשתכחו ג' נקודין בעלמא דקיימאן דא על דא,\u0004 דהיינו נקודה שבגן עדן, שהיא שורש בין לחורבן ובין לישוב. ותחתיה הנקודה של המלכות שמחזה ולמטה, שהיא שורש לישוב בלבד. ותחתיה נקודה דסטרא אחרא שהיא שורש לחורבן בלבד."],[7,"תא חזי ההוא","וכו': בוא וראה, שעיר ההוא שישראל משלחים לעזאזל, למדבר ההוא, הוא לתת חלק לס\"א, להתעסק עמו. (כנ\"ל פרשת נח אות ק\"ה ע\"ש בסולם) ואם תאמר, למה כאן ב' שעירים, אחד לה' ואחד לסטרא אחרא ההוא. יתכן, לשלוח שעיר ההוא של הסטרא אחרא לעזאזל, אבל שעיר לה' למה."],[8,"אלא למלכא דהוה","וכו': ומשיב, אלא דומה למלך שכעס על בנו, קרא לסנטר ההוא. שעושה תמיד דין בבני אדם, כדי שיבא לעשות דין בבנו. סנטר ההוא שמח ונכנס לבית המלך לאכול שם. כיון שהביט בו בנו, אמר, ודאי לא בא סנטר הזה בבית אבי, אלא משום שהמלך כעס עלי. מה עשה הלך ונתרצה עמו. כיון שנתרצה עמו, צוה המלך לעשות סעודה עליונה לו ולבנו. וצוה שלא ידע אותו סנטר בה. אח\"כ בא אותו סנטר, אמר המלך, עתה, אם זה ידע מסעודה העליונה שתקנתי לי ולבני, יתבלבל השלחן. מה עשה קרא לממונה על הסעודה, אמר לו התקן משהו ותשים לפני ותשום לפני סנטר ההוא, כדי שיחשוב שסעד אצלי משלי, ולא ידע באותה סעודה היקרה, אשר לי ובני, ויטול אותו החלק וילך לו, ויפרד משמחת הסעודה שלנו. ואם לא עשה המלך כך לא היה נפרד אותו סנטר מבית המלך."]],[[0,"","וְאִם תֹּאמַר, אֵיךְ יָכוֹל קוֹל שֶׁל לְמַטָּה אוֹ הִתְעוֹרְרוּת שֶׁל לְמַטָּה לְהִתְעוֹרֵר - כְּמוֹ כֵן? בֹּא וּרְאֵה, עוֹלָם הַתַּחְתּוֹן עוֹמֵד לְקַבֵּל תָּמִיד, וְהוּא נִקְרָא אֶבֶן טוֹבָה, וְעוֹלָם הָעֶלְיוֹן לֹא נוֹתֵן לוֹ, אֶלָּא כְּמוֹ שֶׁהוּא עוֹמֵד. אִם הוּא קַיָּם בְּהֶאָרַת פָּנִים מִלְּמַטָּה, כְּמוֹ כֵן מְאִירִים לוֹ מִלְמַעְלָה. וְאִם הוּא עוֹמֵד בְּעַצְבוּת, נוֹתְנִים לוֹ דִּין כְּנֶגְדּוֹ."],[1,"","כְּמוֹ זֶה, (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה. שִׂמְחָה שֶׁל בֶּן אָדָם מוֹשֵׁךְ לְעַצְמוֹ שִׂמְחָה אַחֶרֶת עֶלְיוֹנָה. כָּךְ גַּם זֶה הָעוֹלָם הַתַּחְתּוֹן - כְּמוֹ שֶׁהִיא מִתְעוֹרֶרֶת, כָּךְ מוֹשֵׁךְ מִלְמַעְלָה. מִשּׁוּם כָּךְ מַקְדִּימִים יִשְׂרָאֵל וּמְעוֹרְרִים בַּשּׁוֹפָר קוֹל שֶׁהוּא (סוד של רחמים) כָּלוּל בְּאֵשׁ וּמַיִם וְרוּחַ, וְנַעֲשֶׂה אֶחָד, וְעוֹלֶה לְמַעְלָה, וּמַכֶּה בָּאֶבֶן הַטּוֹבָה הַזּוֹ, וְנִצְבָּע בִּגְוָנִים אֵלּוּ שֶׁל הַקּוֹל הַזֶּה, וְאָז כְּמוֹ שֶׁמִּתְרָאֶה, כָּךְ מוֹשֵׁךְ מִלְמַעְלָה."],[2,"","וְכֵיוָן שֶׁנִּתְקֶנֶת בְּקוֹל זֶה, רַחֲמִים יוֹצְאִים מִלְמַעְלָה וְשׁוֹרִים עָלֶיהָ, וְנִכְלֶלֶת בְּרַחֲמִים מִלְּמַטָּה וּמִלְמַעְלָה. וְאָז מִתְעַרְבֵּב הַצַּד הָאַחֵר, (מסתכל ורואה בהארת הפנים) וְנֶחֱלָשׁ כֹּחוֹ וְלֹא יָכוֹל לְקַטְרֵג. וְהָאֶבֶן הַטּוֹבָה הַזּוֹ קַיֶּמֶת בְּהֶאָרַת הַפָּנִים מִכָּל הַצְּדָדִים - בְּהֶאָרָה שֶׁל לְמַטָּה וּבְהֶאָרָה שֶׁל לְמַעְלָה."],[3,"","מָתַי עוֹמֶדֶת בְּהֶאָרָה שֶׁל לְמַעְלָה? הֱיֵה אוֹמֵר בְּיוֹם הַכִּפּוּרִים. וּבְיוֹם הַכִּפּוּרִים מְאִירָה הָאֶבֶן הַטּוֹבָה הַהִיא בְּאוֹר שֶׁל לְמַעְלָה מִתּוֹךְ הָאוֹר שֶׁל הָעוֹלָם הַבָּא, (ומתערבב המקטרג ההוא), וְאָז מְתַקְּנִים יִשְׂרָאֵל לְמַטָּה שָׂעִיר אֶחָד, וְשׁוֹלְחִים לַמִּדְבָּר הַזֶּה הֶחָזָק שֶׁהוּא שׁוֹלֵט עָלָיו."],[4,"","וְהַצַד הָאַחֵר הַהוּא הוּא נְקֻדָּה אֶמְצָעִית שֶׁל הָעוֹלָם הֶחָרֵב, מִשּׁוּם שֶׁכָּל חָרָבָה וּשְׁמָמָה (הוא ממגו, מהצד האחר ההוא השולט) מִמֶּנּוּ, הַצַּד הָאַחֵר הַהוּא שׁוֹלֵט עָלָיו, וּנְקֻדָּה הָאֶמְצָעִית שֶׁל כָּל הַיִּשּׁוּב, צַד הַקְּדֻשָּׁה הוּא. וְעַל זֶה עוֹמֶדֶת יְרוּשָׁלַיִם בְּאֶמְצַע כָּל הַיִּשּׁוּב שֶׁל הָעוֹלָם."],[5,"","בִּשְׁתֵּי נְקֻדּוֹת נִבְדֶּלֶת מַלְכוּת שָׁמַיִם, צַד הַקְּדֻשָּׁה - אַחַת שֶׁלָּהּ, וְאַחַת שֶׁל הָעוֹלָם הַבָּא. נְקֻדָּה עֶלְיוֹנָה נֶעְלֶמֶת, וְעַל זֶה קַיֶּמֶת בִּשְׁתֵּי נְקֻדּוֹת. נְקֻדָּה שֶׁלָּהּ עוֹמֶדֶת תַּחְתֶּיהָ, יְרוּשָׁלַיִם, אֶמְצַע שֶׁל כָּל הַיִּשּׁוּב. נְקֻדָּה שֶׁלּוֹקַחַת מֵאִמָּא עֶלְיוֹנָה וּסְתוּמָה, הִיא גַן עֵדֶן שֶׁל הָאָרֶץ, שֶׁעוֹמֶדֶת בָּאֶמְצָע שֶׁל כָּל הָעוֹלָם לְכָל הַצְּדָדִים, שֶׁל הֶחָרָבָה וְהַיִּשּׁוּב וְכָל צִדְדֵי הָעוֹלָם."],[6,"","וְעַל זֶה בְּאֶמְצַע גַּן עֵדֶן עוֹמֶדֶת נְקֻדָּה אַחַת עֶלְיוֹנָה נֶעְלֶמֶת וּסְתוּמָה שֶׁלֹּא נוֹדַעַת. וְעַמּוּד אֶחָד נָעוּץ מִלְּמַטָּה לְמַעְלָה תּוֹךְ הַנְּקֻדָּה הַהִיא, וּמִשָּׁם נוֹבְעִים מַיִם שֶׁנִּפְרָדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. נִמְצְאוּ שָׁלֹשׁ נְקֻדּוֹת בָּעוֹלָם שֶׁעוֹמְדוֹת זוֹ עַל זוֹ, כְּדֻגְמַת שָׁלֹשׁ נְקֻדּוֹת שֶׁל הַתּוֹרָה."],[7,"","בֹּא וּרְאֵה, הַשָּׂעִיר הַהוּא שֶׁשּׁוֹלְחִים יִשְׂרָאֵל לַעֲזָאזֵל לַמִּדְבָּר הַהוּא, כְּדֵי לָתֵת חֵלֶק לַצַּד הָאַחֵר הַהוּא לְהִתְעַסֵּק אִתּוֹ. וְאִם תֹּאמַר, שְׁנֵי שְׂעִירִים לָמָּה כָּאן? אֶחָד לַה', וְאֶחָד לַצַּד הָאַחֵר הַהוּא. נִיחָא הַשָּׂעִיר הַהוּא שֶׁל הַצַּד הָאַחֵר, אַךְ לַה' מַדּוּעַ?"],[8,"","אֶלָּא, לְמֶלֶךְ שֶׁהָיָה כּוֹעֵס עַל בְּנוֹ, קָרָא לַשּׁוֹטֵר, זֶה שֶׁעוֹשֶׂה דִּין בִּבְנֵי אָדָם תָּמִיד, כְּדֵי שֶׁיִּתְכּוֹנֵן לַעֲשׂוֹת דִּין בִּבְנוֹ. הַשּׁוֹטֵר הַהוּא שָׂמַח, וְנִכְנַס לְבֵית הַמֶּלֶךְ לֶאֱכֹל שָׁם. כֵּיוָן שֶׁרָאָה אוֹתוֹ בְנוֹ, אָמַר, וַדַּאי לֹא נִכְנַס הַשּׁוֹטֵר כָּאן בְּבֵית אָבִי אֶלָּא מִשּׁוּם שֶׁכָּעַס הַמֶּלֶךְ עָלַי. מֶה עָשָׂה? הָלַךְ וְהִתְפַּיֵּס עִמּוֹ. וּמִשּׁוּם שֶׁהִתְפַּיֵּס עִמּוֹ, צִוָּה הַמֶּלֶךְ לַעֲשׂוֹת סְעוּדָה עֶלְיוֹנָה לוֹ וְלִבְנוֹ, וְצִוָּה שֶׁלֹּא יֵדַע בּוֹ הַשּׁוֹטֵר הַהוּא. לְבַסּוֹף נִכְנַס הַשּׁוֹטֵר הַהוּא. אָמַר הַמֶּלֶךְ, עַתָּה אִם יֵדַע זֶה מֵהַסְּעוּדָה הָעֶלְיוֹנָה שֶׁהֵכַנְתִּי לִי וְלִבְנִי, יִתְבַּלְבֵּל הַשֻּׁלְחָן. מֶה עָשָׂה? קָרָא לַמְמֻנֶּה עַל הַסְּעוּדָה וְאָמַר לוֹ, תָּכִין מַשֶּׁהוּ וְתָשִׂים לְפָנַי, וְתָשִׂים לִפְנֵי הַשּׁוֹטֵר הַהוּא, כְּדֵי שֶׁיַּחְשֹׁב שֶׁסּוֹעֵד לְפָנַי מִשֶּׁלִּי, וְלֹא יֵדַע מֵהַסְּעוּדָה הַחֲשׁוּבָה הַהִיא שֶׁל שִׂמְחָה שֶׁלִּי וְשֶׁל בְּנִי, וְיִקַּח הַחֵלֶק הַהוּא וְיֵלֵךְ לוֹ, וְיִתְרַחֵק מֵהַשִּׂמְחָה שֶׁל הַסְּעוּדָה שֶׁלָּנוּ. וְאִם לֹא שֶׁעָשָׂה הַמֶּלֶךְ כָּךְ, לֹא יִתְרַחֵק הַשּׁוֹטֵר הַהוּא מִבֵּית הַמֶּלֶךְ."]]],[["כַּךָ אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, אַזְמִינוּ תְּרֵין שְׂעִירִין, חַד לִי וְחַד לְהַהוּא דַּלְטוֹרָא, בְּגִין דְּיַחְשִׁיב דְּמִסְּעוּדָתָא דִּילִי קָאֲכִיל, וְלָא יִנְדַּע בִּסְעוּדָתָא דְּחֶדְוָה אַחֲרָא דִּילָן, וְיִסַּב הַהוּא חוּלָקָא, וְיֵזִיל לְאָרְחֵיהּ, וְיִתְפְּרַשׁ מִבֵּיתִי. כֵּיוָן דְּאִמָא עִלָּאָה, עָלְמָא דְּאָתֵי, אָתֵי לְמִשְׁרֵי (ק' ע\"ב) גּוֹ הֵיכְלָא דְּעָלְמָא תַּתָּאָה, לְאַשְׁכְּחָא נְהִירוּ (נ\"א לאשגחא עלה בנהירו) דְּאַנְפִּין, דִּין הוּא דְּלָא יִשְׁתְּכַּח הַהוּא דַּלְטוֹרָא, וְלָא מָארֵי דְּדִינִין לְקַמֵּיהּ, כַּד אַפִּיק כָּל בִּרְכָאן, וְאַנְהִיר לְכֹלָּא. וְכָל הַהוּא חִירוּ יִשְׁתְּכַּח, וְיִשְׂרָאֵל נַטְלֵי מֵאִינּוּן בִּרְכָאן.","דְּהָא כַּד עָלְמָא דְּאָתֵי, עָאל לְהֵיכָלָא דְּעָלְמָא תַּתָּאָה, וְאַשְׁכַּח דְּחַדֵּי עָלְמָא תַּתָּאָה עִם בְּנוֹי בְּהַהִיא סְעוּדָתָא עִלָּאָה, כְּדֵין אִיהוּ בָּרִיךְ פַּתוֹרָא, וְעָלְמִין כֻּלְּהוּ מִתְבָּרְכִין, וְכָל חִידוּ וְכָל נְהִירוּ דְּאַנְפִּין אִשְׁתְּכָחוּ תַּמָּן. הֲדָא הוּא דִכְתִיב, (ויקרא טז) לִפְנֵי יְיָ' תִּטְהָרוּ. (ק' ע\"ב)","כְּתִיב (ויקרא ט״ז:ח׳) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת גּוֹרָל אֶחָד לַיְיָ' וְגוֹרָל אֶחָד לַעֲזָאזֵל. דָּא אִיהוּ הַהוּא חֶדְוָה דְּהַהוּא דַּלְטוֹרָא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יָטִיל עִמֵּיהּ גּוֹרָל, וְזַמִּין לֵיהּ, וְלָא יָדַע דְּנוּר דָּלִיק אַטִּיל עַל רֵישֵׁיהּ, וְעַל עַמָּא דִּילֵיהּ, כְּמָה דְאַתְּ אָמֵר (משלי כ״ה:כ״ב) כִּי גֶחָלִים אַתָּה חוֹתֶה עַל רֹאשׁוֹ.","וְסִימָנִךָ, (אסתר ה׳:י״ב) אַף לֹא הֵבִיאָה אֶסְתֵּר הַמַלְכָּה עִם הַמֶּלֶךְ אֶל הַמִשְׁתֶּה אֲשֶׁר עָשָׂתָה כִּי אִם אוֹתִי. וּכְתִיב, וַיֵּצֵא הָמָן בַּיּוֹם הַהוּא שָׂמֵחַ וְטוֹב לֵב. בְּהַהוּא חוּלָקָא דְּנָטִיל, וְאָזִיל לֵיהּ. וּלְבָתַר כַּד אָתֵי מַלְכָּא עִלָּאָה, לְבֵי מַטְרוֹנִיתָא, מַטְרוֹנִיתָא תַּבְעַת עָלָהָא, וְעַל בְּנָהָא, וְעַל עַמָּא מִן מַלְכָּא.","וַאֲפִילּוּ בְּזִמְנָא דְּיִשְׂרָאֵל בְּגָלוּתָא, וְצַלּוּ צְלוֹתִין בְּכָל יוֹמָא, אִיהִי סַלְקַת בְּיוֹמָא דָּא, לְקָמֵי מַלְכָּא עִלָּאָה, וְתַבְעַת עַל בְּנָהָא. וּכְדֵין אִתְגְּזָרוּ, כָּל אִינּוּן נוּקְמִין, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד עִם אֱדוֹם, וְאִתְגְּזַר הֵיךְ זַמִין דַּלְטוֹרָא דָּא לְאִתְעַבְּרָא מֵעָלְמָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח.","וְסִימָנִךָ, בְּזִמְנָא דְּגָלוּתָא (אסתר ז׳:ד׳) כִּי נִמְכַּרְנוּ אֲנִי וְגוֹ'. כִּי אֵין הַצָּר שׁוֶֹה בְּנֶזֶק הַמֶּלֶךְ. מַאי בְּנְזֶק הַמֶּלֶךְ. כְּמָה דְאַתְּ אָמֵר, (יהושע ז׳:ט׳) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךָ הַגָּדוֹל. דְּהָא שְׁמָא עִלָּאָה, לָא אִתְקָיָּים בְּקִיּוּמֵיהּ, וְדָא אִיהוּ בְּנֶזֶק הַמֶּלֶךְ.","וּכְדֵין וְהָמָן נִבְעָת מִלִּפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה כְּדֵין, נְהִירוּ דְּאַנְפִּין, וְכָל חִידוּ אִשְׁתְּכַח, וְיִשְׂרָאֵל נַפְקֵי לְחִירוּ, בְּהַהוּא יוֹמָא. כְּדֵין מֵהַהוּא יוֹמָא וּלְהָלְאָה, חִירוּ וְחֶדְוָה בְּאִתְגַּלְּיָא, לְשַׁלְּטָאָה עָלַיְיהוּ, כְּדֵין בָּעֵי לְמֵחדֵי עִמְּהוֹן, מִכָּאן וּלְהָלְאָה, כְּמָה דְּיָהֲבוּ לֵיהּ חוּלָקָא לְאִתְפָּרְשָׁא מִנְהוֹן, הָכִי נָמֵי יַהֲבִין לִשְׁאַר עַמִּין, לְאִתְפָּרְשָׁא מִנְּהוֹן לְתַתָּא.","תָּא חֲזֵי, מָה הוּא רָזָא דְּקָרְבְּנָא, לְקָרְבָא שָׂעִיר, (לקבל שעיר) וְלָא מִלָּה אַחֲרָא. וַאֲמַאי שָׂעִיר בְּרֹאשׁ חֹדֶשׁ, וְהָכָא נָמֵי שָׂעִיר. אֶלָּא אִי תֵּימָא בְּגִין דְּאִיהוּ סִטְרָא דִּילֵיהּ יֵאוֹת. אֲמַאי לָא הֲוִי עֵז.","אֶלָּא מִלָּה דָּא אִצְטְרִיךְ, וְאִיהִי אִשְׁתְּכָחַת לְמָארֵיהוֹן דְּחָרָשִׁין, דְּכָל עוֹבָדַיְיהוּ בְּמָה דְּלָא (אתחבר) יְהֵא בְּנוּקְבָּא. וְעַל דָּא שָׂעִיר לָא אִתְחַבָּר בְּנוּקְבָּא, בְּסִטְרִין דִּילֵיהּ כֻּלְּהוּ. עֵז כַּד אִתְחַבָּר בְּנוּקְבָּא. וּבְגִין דְּאִיהוּ מַלְכָּא, יַהֲבִין לֵיהּ בְּגִין יְקָרָא דִּילֵיהּ, הַאי דְּלָא אִתְחַבָּר בְּנוּקְבָּא, וְלָא יָהִיב חֵילֵיהּ לְאַחֲרָא. וְדָא אִשְׁתְּמוֹדָע לְאִינּוּן חָרָשִׁין, דְּמִשְׁתַּמְּשִׁין בְּהָנֵי עוֹבָדֵי. וּבְגִינֵי כַּךְ, שַׁרְיָין עַל הַהוּא שָׂעִיר, כָּל אִינּוּן חֲטָאֵיהוֹן.","וְתָּא חֲזֵי, אַף עַל גַּב דְּאִיהוּ חוּלָקָא לְהַהוּא סִטְרָא אַחֲרָא, רָזָא הָכָא, כָּל הָנֵי סִטְרִין אַחֲרָנִין דִּלְתַתָּא, (דאקרון מצולות ים) כֻּלְּהוּ מִסְאֲבִין יַתִּיר. וְכָל מַה דְּנַחְתִּין דַּרְגִּין תַּתָּאִין, הָכִי מִסְאֲבוּ דִּלְהוֹן יַתִּיר. וּבְגִין כַּךְ, בָּעֵז יַתִּיר חוּלָקֵיהוֹן, בְּגִין דְּשַׂעֲרָא דִּילֵיהּ תַּלְיָא יַתִּיר מִבְּעִירָא אַחֲרָא, כְּמָה דְּדִינָא דִּלְהוֹן תָּלֵי לְתַתָּא בִּמְסָאֲבוּ. אֲבָל הַאי מַלְכּוּ חַיָּיבְתָא אַחֲרָא, מַלְכָּא דְּכֹלָּא בְּהַהוּא סִטְרָא, בָּרוּר אִיהוּ יַתִּיר מִסְאֲבוּ דִּילֵיהּ, וְלָא מִסְאֲבוּ שְׁלִים כְּהָנֵי תַּתָּאֵי. וְעַל דָּא שָׂעִיר, דִּשְׂעַר דִּילֵיהּ לָא תַּלְיָא, וְלָא שְׁעִיעַ. לָא שְׁעִיעַ, בְּגִין דְּהַהוּא מִסְאֲבוּ דִּילֵיהּ. וְלָא תַּלְיָא, בְּגִין דְּלָא יִתְתָּקַף בֵּיהּ מִסְאֲבוּ כְּהָנִי תַּתָּאֵי, וְעַל דָּא וַדַּאי שָׂעִיר וְלָא אַחֲרָא."],[[0,"כך אמר קב\"ה","וכו': כך אמר הקב\"ה לישראל הזמינו ב' שעירים, אחד לי ואחד לאותו המלשין, דהיינו הס\"א, כדי שיחשוב שאכל מסעודה שלי, ולא ידע משמחת הסעודה האחרת שלנו, ויקח חלק ההוא וילך לדרכו ויפרד מביתי. כיון דאמא עלאה, שהיא עולם הבא, דהיינו בינה, באה לשרות בתוך ההיכל של עולם התחתון להשגיח עליה בהארת הפנים, דין הוא שלא ימצא לפניו אותו המלשין, ולא בעלי הדין, בעת שמוציא כל הברכות ומאיר לכל, וכל חירות ההוא נמצא במלכות, וישראל מקבלים מאלו הברכות."],[0,"","פירוש, בראש השנה חוזרת המלכות למצב הא' הנ\"ל (באות צ\"ב) שאז נמשך ממנה דינים וחורבן, שהס\"א נאחזת בה בבחינת נקודה דאמצעיתא דחריבו דעלמא, ומקטרגת על העולם שרוצית לבטל הקו ימין לגמרי. ואז נתן הקב\"ה עצה לתקוע בשופר, כדי לעורר מלתתא המסך דחירק של קו האמצעי ולמעט הג\"ר דקו שמאל (כנ\"ל וירא אות שפ\"א בהסולם ע\"ש) שבזה מתערבב הס\"א שכל כחו מקו שמאל הוא, והעולם נצול מדינים וחורבן. אמנם אחר שנתבטל הג\"ר דשמאל, יש לס\"א אחיזה במקום החסרון, וע\"כ צריכים לתקון ב', להעביר הס\"א ממקום החסרון, באופן שתפרד לגמרי מן הקדושה, וזה נעשה ביום הכפורים, שאז נותנים חלק לס\"א בשעיר הזה ששולחים המדברה. פירוש. שביום הכפורים המלכות עולה לבינה, ומקבלת ממנה נקודה עלאה שהיא שורש בין לחורבן ובין לישוב, (כנ\"ל אות צ\"ח) שהג\"ר דשמאל חוזרים, ויש שם גם תקון דקו אמצעי הממשיך חכמה המלובשת בחסדים כנ\"ל, וע\"כ מבחינה זו עושים ב' שעירים שעיר אחד לה' ושעיר אחד לעזאזל אל המדבר, ששעיר הזה ה\"ס המשכת ג\"ר דשמאל שממשיכים מנקודת הבינה, כדי להעביר הס\"א ממקום החסרון, וז\"ס ששולחים אותו המדבר, שהוא מקום החורבן, כמו שנמשך משמאל, ונמצא שהקדושה בעצמה נותנת חלק לס\"א. אבל הוא לרעתה, כדי להעבירה מקדושה ולתת מוחין הגדולים דחכמה וחסדים יחדיו לישראל. ועם זה תבין מ\"ש (בוירא אות שפ\"ד) \u0003ביום ראש השנה בעי לערבבא ליה,\u0004 דהיינו לבטל הג\"ר דשמאל, שבזה מתערבב השטן, ואובד שליטתו כנ\"ל. \u0003ביום הכפורים בעי לנייחא ולמעבד ליה נייחא דרוחא בשעיר\u0004 וכו', דהיינו ששוב ממשיכים הג\"ר שנתבטלו ברה\"ש, שבזה קונה הס\"א שליטה ויש לו נחת רוח. וע\"ש (באות שפ\"ז). אמנם הוא לרעתו כנ\"ל."],[0,"","וז\"ש כאן, \u0003אזמינו תרין שעירין חד לי וחד לההוא דלטורא\u0004 וכו' \u0003ויסב ההוא חולקא\u0004 דהיינו הג\"ר דשמאל, ששולחים המדברה למקום החורבן להחזירו לשליטתו, לבחינת נקודה דאמצעיתא דחריבו דעלמא, \u0003ויזיל לאורחיה,\u0004 למקום החורבן ושממון, \u0003ויתפרש מביתי,\u0004 שעי\"ז הוא מתפרד מן הקדושה, שאין לו עוד מקום חסרון להאחז שם. וז\"ש \u0003כיון דאמא עלאה עלמא דאתי, אתי למשרי גו היכלא דעלמא תתאה,\u0004 כי ביום הכפורים המלכות מלבשת הבינה כנ\"ל, שה\"ס נקודה דאמצעיתא לכל עלמא בין לחורבן ובין לישוב, \u0003דין הוא דלא ישתכח ההוא דלטורא,\u0004 דהיינו שמשלימים החסרון דקדושה ואין מקום לס\"א להאחז במקום החסרון, \u0003ולא מארי דדינין לקמיה,\u0004 כי אין פחד עוד מהדינים שג\"ר דשמאל גורם, כיון ששולחים את השעיר אל החורבן והשממון, והקדושה הוא רק במקום הישוב, ונפרד הס\"א מן הקדושה, ואז משפעת אמא עלאה, מבחינת מה שהיא גם נקודה דאמצעיתא דישוב העולם, שבזה \u0003ואנהיר לכלא\u0004 דהיינו לחכמה וחסדים ביחד. \u0003וכל ההוא חירו ישתכח, וישראל נטלי מאינון ברכאן.\u0004 ובזה מתבאר כל ההמשך."],[1,"דהא כד עלמא","וכו': כי כשעולם הבא, שהיא בינה נכנס אל ההיכל של עולם התחתון, שהיא מלכות, ונמצא עולם התחתון, שהוא שמח עם בניו בסעודה ההיא העליונה, הנמשכת מבינה, אז הבינה, מברך השלחן, והעולמות כולם מתברכים, וכל שמחה וכל הארת פנים נמצאים שם. ז\"ש, לפני ה' תטהרו."],[2,"כתיב ונתן אהרן","וכו': כתוב, ונתן אהרן על שני השעירים גורלות גורל אחד לה' וגורל אחד לעזאזל. זה הוא השמחה של המלשין, אשר הקב\"ה מפיל גורל עמו, ומזמין אותו, שיקח השעיר לעזאזל, ואינו יודע שאש דולק מפיל על ראשו ועל עם שלו. כמש\"א כי גחלים אתה חותה על ראשו."],[3,"וסימנך אף לא","וכו': והסימן שלך, הכתוב, אף לא הביאה אסתר המלכה עם המלך אשר עשתה כי אם אותי. וכתיב, ויצא המן ביום ההוא שמח וטוב לב, באותו החלק שקבל, והלך לו. ואח\"כ, כשבא המלך העליון לבית המלכה, המלכה מבקשת עליה ועל בניה ועל העם, מן המלך."],[4,"ואפילו בזמנא דישראל","וכו': ואפילו בזמן שישראל בגלות, ומתפללים תפלות בכל יום, המלכות עולה ביום הזה, יוה\"כ, לפני המלך, ומבקשת על בניה. ואז נגזר כל אלו הנקמות שעתיד הקב\"ה לעשות לאדום, ונגזר איך עתיד המלשין הזה לעבור מן העולם. כמו שאתה אומר בלע המות לנצח."],[5,"וסימנך בזמנא דגלותא","וכו': והסימן שלך, כי בזמן הגלות כתוב, כי נמכרנו אני ועמי וגו' כי אין הצר שוה בנזק המלך. מהו בנזק המלך. הוא כמו שאתה אומר, והכריתו את שמנו מן הארץ ומה תעשה לשמך הגדול. כי שם הגדול לא ימצא בקיומו. וזה הוא נזק המלך."],[6,"וכדין והמן נבעת","וכו': ואז, והמן שהוא הס\"א נבעת מלפני המלך והמלכה, ואז כל הארת הפנים וכל שמחה נמצא, וישראל יוצאים לחירות ביום ההוא, יוה\"כ. אז מיום ההוא והלאה, חירות ושמחה בגלוי שולטות עליהם, אז רוצה לשמוח עמהם. מכאן ולהלאה, כמו שנותנים לו, לס\"א, חלק כדי שיתפרד מישראל כך נותנים לשאר העמים חלק, שיתפרדו למטה מישראל."],[7,"תא חזי מה","וכו': בוא וראה, מהו סוד הקרבן להקריב שעיר ולא דבר אחר. ולמה בראש חדש מקריבים שעיר וכאן ביוה\"כ גם כן שעיר. אלא אם תאמר שזה הוא משום שהשעיר הוא צד שלו, יפה הוא, אבל למה לא היה עז, שהוא גדול ורק שעיר שהוא קטן."],[8,"אלא מלה דא","וכו': ומשיב, אלא דבר זה צריך, דהיינו רק שעיר, והוא ידוע לכל בעלי כשפים, שכל מעשיהם במה שלא מתחבר בנקבה. וע\"כ \u0003שעיר,\u0004 שעוד לא נתחבר בנקבה, בצדדים שלו, של הס\"א. הם כולם, והטעם, משום שאל אחר אסתרס ולא עביד פירי. אבל \u0003עז,\u0004 הוא כשכבר נתחבר בנקבה. ועושה פירות ע\"כ אינו בחלק הס\"א. ומשום שהס\"א הוא מלך, כמ\"ש מלך זקן וכסיל, נותנים לו בשביל כבודו שעיר, שלא נתחבר בנקבה, ולא נתן כחו לאחר. שהוא מינו, כנ\"ל, וזה נודע לכל אלו המכשפים שמשתמשים במעשים אלו. ומשום זה, שורים על השעיר ההוא כל חטאתם."],[9,"ות\"ח, אע\"ג דאיהו","וכו': ובוא וראה, אע\"פ שהשעיר הוא חלק לסטרא אחרא, יש כאן סוד שבצד הטומאה, כל הבחינות שהם יותר למטה הם טמאים יותר, וכל מה שיורדות מדרגות התחתונות, כך הטומאה שלהם יותר. ומשום זה, ב \u0003עז\u0004 חלקם של הס\"א הוא יותר, משום שהשערות שלו תלויות למטה יותר מבהמה אחרת, כמו שהדין שלהם תלוי למטה בטומאה. אבל מלכות הרשעה האחרת הזו, שהוא מלך של כל הסטרא אחרא, הטומאה שלו ברורה וזכה יותר ואינו בטומאה שלמה כאלו התחתונים. וע\"כ נותנים לו \u0003שעיר,\u0004 שהשערות שלו אינן תלויות למטה ואינו חלק. אינו חלק, משום הטומאה שלו, ואינם תלוים למטה, כדי שלא יתחזק בו הטומאה כאלו מדרגות הסמרא אחרא שלמטה. וע\"כ הוא ודאי שעיר, ולא דבר אחר."],[9,"","פירוש. העז ששערותיו תלויות למטה. יורה על ג\"ר דשמאל הנמשכים ממעלה למטה, שזהו טומאה חמורה. ושעיר שיש בו שערות אבל אינן נמשכות למטה, יורה על טומאה קלושה מבחינת ו\"ק דשמאל, שנמשכות מעט אבל לא למטה. וכיון ששעיר לעזאזל נשלח למלך של הס\"א, שאין טומאתו אלא מבחינת ו\"ק דשמאל. ע\"כ נשלח לו שעיר ולא עז. וזהו טעם נוסף על הטעם הנ\"ל."]],[[0,"","כָּךָ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, תַּזְמִינוּ שְׁנֵי שְׂעִירִים, אֶחָד לִי וְאֶחָד לַמְקַטְרֵג הַהוּא, כְּדֵי שֶׁיַּחְשֹׁב שֶׁמִּסְּעוּדָה שֶׁלִּי הוּא אוֹכֵל, וְלֹא יֵדַע בִּסְעוּדַת הַשִּׂמְחָה הָאַחֶרֶת שֶׁלָּנוּ, וְיִקַּח הַחֵלֶק הַהוּא וְיֵלֵךְ לְדַרְכּוֹ וְיִתְרַחֵק מִבֵּיתִי. כֵּיוָן שֶׁאִמָּא הָעֶלְיוֹנָה, עוֹלָם הַבָּא, בָּאָה לִשְׁרוֹת תּוֹךְ הַהֵיכָל שֶׁל הָעוֹלָם הַתַּחְתּוֹן לִמְצֹא אוֹר (להשגיח עליה בהארה) שֶׁל הַפָּנִים, דִּין הוּא שֶׁלֹּא יִמָּצֵא הַמְקַטְרֵג הַהוּא, וְלֹא בַעֲלֵי הַדִּין לְפָנָיו, כַּאֲשֶׁר מוֹצִיא כָל הַבְּרָכוֹת וּמֵאִיר לְכֻלָּם. וְכָל שֶׁפַע הַחֵרוּת הַהוּא נִמְצָא, וְיִשְׂרָאֵל נוֹטְלִים מֵאֵלּוּ הַבְּרָכוֹת."],[1,"","שֶׁהֲרֵי כַּאֲשֶׁר הָעוֹלָם הַבָּא נִכְנָס לַהֵיכָל שֶׁל הָעוֹלָם הַתַּחְתּוֹן וּמוֹצֵא שֶׁשָּׂמֵחַ הָעוֹלָם הַתַּחְתּוֹן עִם בָּנָיו בַּסְּעוּדָה הָעֶלְיוֹנָה הַהִיא, אָז הוּא מְבָרֵךְ הַשֻּׁלְחָן, וְהָעוֹלָמוֹת כֻּלָּם מִתְבָּרְכִים, וְכָל שִׂמְחָה וְכָל הֶאָרַת הַפָּנִים נִמְצָאוֹת שָׁם. זֶהוּ שֶׁכָּתוּב (ויקרא טז) לִפְנֵי ה' תִּטְהָרוּ."],[2,"","כָּתוּב (ויקרא טז) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִם גֹּרָלוֹת גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל. זוֹהִי הַשִּׂמְחָה הַהִיא שֶׁל הַמְקַטְרֵג הַהוּא, כְּדֵי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַפִּיל עִמּוֹ גוֹרָל, וּמַזְמִין אוֹתוֹ, וְלֹא יוֹדֵעַ שֶׁאֵשׁ דּוֹלֵק שָׁם עַל רֹאשׁוֹ וְעַל הָעָם שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (משלי כה) כִּי גֶחָלִים אַתָּה חֹתֶה עַל רֹאשׁוֹ."],[3,"","וְסִימָנְךָ - (אסתר ה) אַף לֹא הֵבִיאָה אֶסְתֵּר הַמַּלְכָּה עִם הַמֶּלֶךְ אֶל הַמִּשְׁתֶּה אֲשֶׁר עָשָׂתָה כִּי אִם אוֹתִי. וְכָתוּב, וַיֵּצֵא הָמָן בַּיּוֹם הַהוּא שָׂמֵחַ וְטוֹב לֵב. בַּחֵלֶק הַהוּא שֶׁנּוֹטֵל, וְהוֹלֵךְ לוֹ. וּבַסּוֹף, כַּאֲשֶׁר בָּא הַמֶּלֶךְ הָעֶלְיוֹן לְבֵית הַמַּלְכָּה, הַמַּלְכָּה מְבַקֶּשֶׁת עָלֶיהָ וְעַל בָּנֶיהָ וְעַל עַמָּהּ מִן הַמֶּלֶךְ."],[4,"","וַאֲפִלּוּ בִּזְמַן שֶׁיִּשְׂרָאֵל בְּגָלוּת וּמִתְפַּלְלִים תְּפִלּוֹת בְּכָל יוֹם, הִיא עוֹלָה בְּיוֹם זֶה לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן וּמְבַקֶּשֶׁת עַל בָּנֶיהָ, וְאָז נִגְזָרוֹת כָּל אוֹתָן נְקָמוֹת שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת עִם אֱדוֹם, וְנִגְזָר אֵיךְ עָתִיד הַמְקַטְרֵג הַזֶּה לַעֲבֹר מִן הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח."],[5,"","וְסִימָנְךָ - בִּזְמַן הַגָּלוּת (אסתר ז) כִּי נִמְכַּרְנוּ אֲנִי וְגוֹ'. כִּי אֵין הַצָּר שֹׁוֶה בְּנֵזֶק הַמֶּלֶךְ. מַה זֶּה בְּנֵזֶק הַמֶּלֶךְ? כְּמוֹ שֶׁנֶּאֱמַר (יהושע ז) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. שֶׁהֲרֵי הַשֵּׁם הָעֶלְיוֹן לֹא מִתְקַיֵּם בְּקִיּוּמוֹ, וְזֶהוּ בְּנֵזֶק הַמֶּלֶךְ."],[6,"","וְאָז, וְהָמָן נִבְעַת מִלִּפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה. אָז אוֹר הַפָּנִים וְכָל שִׂמְחָה נִמְצֵאת, וְיִשְׂרָאֵל יוֹצְאִים לַחֵרוּת בַּיּוֹם הַהוּא. וְאָז, מֵהַיּוֹם הַהוּא וָהָלְאָה, חֵרוּת וְשִׂמְחָה בְגִלּוּי לִשְׁלֹט עֲלֵיהֶם, וְאָז צָרִיךְ לִשְׂמֹחַ עִמָּהֶם. מִכָּאן וָהָלְאָה, כְּמוֹ שֶׁנָּתְנוּ לוֹ חֵלֶק לְהִתְרַחֵק מֵהֶם, כָּךְ גַּם נוֹתְנִים לִשְׁאָר הָעַמִּים לְהִתְרַחֵק מֵהֶם לְמַטָּה."],[7,"","בֹּא וּרְאֵה, מַה הוּא סוֹד הַקָּרְבָּנוֹת לְהַקְרִיב שָׂעִיר (כנגד שעיר) וְלֹא דָבָר אַחֵר? וּמַדּוּעַ שָׂעִיר בְּרֹאשׁ חֹדֶשׁ, וְכָאן גַּם כֵּן שָׂעִיר? אֶלָּא, אִם תֹּאמַר מִשּׁוּם שֶׁהוּא צַד שֶׁלּוֹ - טוֹב. מַדּוּעַ לֹא הָיָה עֵז?"],[8,"","אֶלָּא דָּבָר זֶה צָרִיךְ, וְהוּא נִמְצָא לְבַעֲלֵי כִשּׁוּפִים, שֶׁכָּל מַעֲשֵׂיהֶם בְּמַה שֶּׁלֹּא (מתחבר) יִהְיֶה בִנְקֵבָה. וְעַל זֶה שָׂעִיר, שֶׁלֹּא הִתְחַבֵּר בִּנְקֵבָה בְּכָל הַצְּדָדִים שֶׁלּוֹ. עֵז, כַּאֲשֶׁר הִתְחַבֵּר בִּנְקֵבָה. וּמִשּׁוּם שֶׁהוּא מֶלֶךְ, נוֹתְנִים לוֹ מִשּׁוּם הַכָּבוֹד שֶׁלּוֹ, זֶה שֶׁלֹּא הִתְחַבֵּר בִּנְקֵבָה וְלֹא נָתַן כֹּחוֹ לְאַחֵר. וְזֶה יָדוּעַ לְאוֹתָם הַמְכַשְּׁפִים שֶׁמִּשְׁתַּמְּשִׁים בְּמַעֲשִׂים אֵלֶּה. וּמִפְּנֵי כָּךְ שׁוֹרִים עַל הַשָּׂעִיר הַהוּא כָּל אוֹתָם הַחֲטָאִים."],[9,"","בֹּא וּרְאֵה, אַף עַל גַּב שֶׁהוּא חֵלֶק לַצַּד הָאַחֵר הַהוּא - סוֹד כָּאן. כָּל אֵלּוּ צְדָדִים אֲחֵרִים שֶׁלְּמַטָּה (שגקראים מצולות ים), כֻּלָּם טְמֵאִים יוֹתֵר. וְכָל מַה שֶּׁיּוֹרְדִים מִדְּרָגוֹת תַּחְתּוֹנוֹת, כָּךְ הַטֻּמְאָה שֶׁלָּהֶם יוֹתֵר. וּמִפְּנֵי כֵן בְּעֵז, חֶלְקָם יוֹתֵר, מִשּׁוּם שֶׁהַשְּׂעָרוֹת שֶׁלּוֹ תְּלוּיוֹת יוֹתֵר מִבְּהֵמָה אַחֶרֶת, כְּמוֹ שֶׁדִּין שֶׁלָּהֶם תָּלוּי לְמַטָּה בַטֻּמְאָה. אֲבָל מַלְכוּת הָרְשָׁעָה הַזּוֹ הָאַחֶרֶת, מֶלֶךְ שֶׁל הַכֹּל בַּצַּד הַהוּא, הַטֻּמְאָה שֶׁלּוֹ הִיא יוֹתֵר מֻבְחֶרֶת, וְלֹא טֻמְאָה שְׁלֵמָה כְּאֵלֶּה הַתַּחְתּוֹנִים. וְעַל זֶה שָׂעִיר, שֶׁהַשֵּׂעָר שֶׁלּוֹ לֹא תָלוּי וְלֹא חָלָק. לֹא חָלָק, מִפְּנֵי הַטֻּמְאָה הַהִיא שֶׁלּוֹ. וְלֹא תָלוּי, כְּדֵי שֶׁלֹּא תִתְחַזֵּק בּוֹ טֻמְאָה כְּאֵלֶּה הַתַּחְתּוֹנִים, וְעַל זֶה וַדַּאי שָׂעִיר, וְלֹא אַחֵר."]]],[["כִּפּוּר, אֲמַאי אִקְרֵי כִּפּוּר, אֶלָּא בְּגִין דְּנָקִי כָּל מְסָאֲבוּ, וְאַעְבַּר לֵיהּ מִקַּמֵיהּ, בְּהַהוּא יוֹמָא. וְעַל דָּא, יוֹם כִּפּוּר: יוֹמָא דִּנְקִיוּתָא, וְהָכִי קָרֵינָא לֵיהּ. כְּתִיב (ויקרא ט״ז:ל׳) כִּי בַיוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם, כִּי הַיּוֹם הַזֶּה מִבָּעֵי לֵיהּ, מַאי כִּי בַיוֹם הַזֶּה. אֶלָּא בְּגִין דְּאִתְדָכֵּי מַקְדְּשָׁא לְעֵילָּא, אִתְנַקֵי (נ\"א ואתנהיר') כְּתִיב כִּי בַיוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם, יְכַפֵּר וִינָקֵי בְּקַדְמִיתָא בַּיוֹם הַזֶּה, בְּגִין דְּיִתְדָּכֵי, וּלְבָתַר עֲלֵיכֶם.","תּוּ, יְכַפֵּר בַּיוֹם הַזֶּה, וִינָקֵי לֵיהּ בְּקַדְמִיתָא, וְכָל דָּא עֲלֵיכֶם, בְּגִינֵכוֹן אִצְטְרִיךְ לְנַקָּאָה לֵיהּ, וּלְדַכְּאָה לֵיהּ בְּקַדְמִיתָא. יְכַפֵּר, מַאן יְכַפֵּר. אֶלָּא דָּא הוּא עָלְמָא עִלָּאָה, דְּנָהִיר וְנָקֵי לְכֹלָּא. וְעַל דָּא כֻּלְּהוּ סִטְרִין בִּישִׁין, דְּאִקְרוּן מְצוּלוֹת יָם, אִתְעֲבָרוּ. וּכְמָּה דְּאִינּוּן מְצוּלוֹת יָם תַּלְיָין, הָכִי נָמֵי תַּלְיָיא שַׂעֲרָא (ס\"א דיליה, דהוא סטרא וכו') דִּילֵיהּ כָּל הַהוּא סִטְרָא דִּלְהוֹן, וְשַׂעֲרָא דְּהַהוּא סִטְרָא לָא שְׁעִיעַ.","כְּגַוְונָא דָּא כְּתִיב, (ויקרא ט״ז:ט״ז) וְכִפֶּר עַל הַקֹּדֶשׁ מִטוּמְאֹת בְּנִי יִשְׂרָאֵל וּמִפִּשְׁעֵיהֶם לְכָל חַטֹּאתָם. וְכָל חֲטֹאתָם מִּבָּעֵי לֵיהּ, אֶלָּא לְהַנָאָה לְהוֹן, מִכָּאן וּלְהָלְאָה לְכָל חֶטְאָם דְּלָא יָכִיל מְקַטְרְגָא לְשַׁלְּטָאָה עָלַיְיהוּ (ועל דא) בְּיוֹמָא דְּכִפּוּר, דְּאִיהוּ קִנּוּחָא דְּכָל חוֹבִין, וְנַקְיוּ דִּלְהוֹן. בָּעָאן יִשְׂרָאֵל לְנַקָּאָה גַּרְמַיְיהוּ, וּלְמֵהַךְ יְחֵפֵי רַגְלִין, כְּמַלְאָכֵי עִלָּאִין. חֲמֵשׁ עִנּוּיִין, בְּגִין לְאִסְתַּיְּיעָא בְּחָמֵשׁ סִטְרִין עִלָּאִין, דְּיוֹמָא דְּכִפּוּרֵי אַפִּיק לוֹן, וְאִינּוּן תַּרְעִין דִּילֵיהּ.","וְאִי שְׁתִיָּה קָא חָשִׁיב, דְּאִיהוּ מִסִּטְרָא דְּיִצְחָק, הָא שִׁית, וְאַף עַל גַּב דְּבִכְלָל אֲכִילָה אִיהוּ, וּכְדֵין אִינּוּן שִׁית, וְעִנּוּיָא בַּתְרָאָה תַּשְׁמִישׁ הַמִּטָּה אִיהוּ, וּבְדַרְגָּא שְׁתִיתָאָה שְׁכִיחַ, וְלָקֳבְלֵיהּ אֲנָן עָבְדִין עִנּוּיָא דָּא.","כְּתִיב (במדבר כ״ט:ז׳) וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה, וּכְתִיב (ויקרא כ״ג:כ״ז) אַך בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר, בָּעֲשִׂירִי מִבָּעֵי לֵיהּ, מַאי בֶּעָשׂוֹר. אֶלָּא, בְּגִין דְּהַשְׁתָּא בְּיוֹמָא דָּא, כָּל דַּרְגִּין עִלָּאִין, אַתְיָין אִלֵּין עַל אִלֵּין, לְמִשְׁרֵי עַל סִיהֲרָא, וּלְאַנְהֲרָא לָהּ. וְכֻלְּהוּ בְּרָזָא דְּעֶשֶׂר, עַד דְּסַלְּקָא לְמֵאָה. וְכַד קַיְּימָא בְּרָזָא דְּמֵאָה, כַּדִּין כֹּלָּא חַד, וְאִקְרֵי יוֹם הַכִּפּוּרִים. וְעַל דָּא בֶּעָשׂוֹר, כְּמָה דְּאַתְּ אָמַר זָכוֹר, שָׁמוֹר, דְּכֻלְּהוּ אַתְיָין בְּגִין לְעַשָׂרָא וּלְאַנְהָרָא בְּרָזָא דְּעֶשֶׂר.","אַהְדָּר הַאי סָבָא רֵישֵׁיהּ לָקֳבְלֵיהּ דְּרַבִּי שִׁמְעוֹן, וְאָמַר לֵיהּ, (רבי שמעון) הָא יָדַעְנָא דִּשְׁאֶלְתָּא תִּבָּעֵי בְּהַאי, בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי. אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן וַדַּאי, (ס\"א דא בעשירי יאות הוא, והכי הוא, אבל בעשור אמאי וכו') בֶּעָשׂוֹר יֵאוֹת הוּא. אִי הָכִי הוּא, אֲמַאי סָלִיק לְמֵאָה, וְהָא מִקְרָא לָא אִתְחָזֵי, אֶלָּא דְּסָלִיק לְשִׁבְעִין, מַשְׁמַע דִּכְתִּיב בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי, וְכַד מְעַשְּׂרֵי לְשְׁבִיעָאָה עֶשֶׂר זִמְנִין, הָא וַדַּאי סָלִיק לְשִׁבְעִין. אֲמַר לֵיהּ, עַל דָּא אַהֲדַרְנָא רֵישָׁא לְגַבָּךְ, דְּהָא יָדַעְנָא דְּחַכִּימָא אַנְתְּ.","תָּא חֲזֵי, תְּרֵין רָזִין הָכָא, חַד דְּהָא סִיהֲרָא חֹדֶשׁ הַשְּׁבִיעִי אִקְרֵי, וּבְּגִין כָּךְ אִקְרֵי חֹדֶשׁ הַשְּׁבִיעִי עָשׂוֹר, בְּגִין דְּקָא מְנָהֲרִין לָהּ עֶשֶׂר זִמְנִין, הָא מֵאָה. וְתוּ, הַאי מִלָּה דְּקָאַמְרַת, וַדַּאי לְשִׁבְעִין סְלִיקָא בְּהַאי יוֹמָא, (ובדרגא דשבעין איהו, ובדרגא דמאה איהו. לדרגא דמאה לאשלמא ולאנהרא.) וּבְהַאי דַּרְגָּא דְּשִׁבְעִין, דְּהָא בְּיוֹמָא דָּא נָטִיל לְכָל עַמָּא דְּיִשְׂרָאֵל לְמֵידָן, וְכֻלְּהוּ קַיְימִין בְּנִשְׁמְתָא יַתִּיר מִגּוּפָא, דְּהָא בְּיוֹמָא דָּא עִנּוּיָא דְּנַפְשָׁא אִיהוּ, וְלָא מִגּוּפָא, כְּמָה דְּאַתְּ אָמַר וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם כִּי כָל הַנֶּפֶשׁ אֲשֶׁר לא תְעוּנֶּה. וְהַאי יוֹמָא נָטִיל לְכָל נַפְשָׁאן וַהֲווּ בִּרְשׁוּתֵיהּ, וְאִי לָא קַיְּימָא בְּרָזָא (נ\"א ברשותא) דְּשִׁבְעִין, לֵית לֵיהּ רְשׁוּ בְּנַפְשָׁאן, (ס\"א לקיימא תמן) דְּקִיּוּמָא דְּנַפְשָׁאן בְּרָזָא דְּשִׁבְעִין, כְּמָה דְאַתְּ אָמֵר (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה וְגוֹ'."],[[0,"כפור אמאי אקרי","וכו': שואל, כפור, למה נקרא כפור. ומשיב, משום שמנקה כל טומאה ומעביר אותה מלפניו ביום הזה. וע\"כ יום כפור, פירושו, יום של נקיון, וכך אנו קוראים אותו. כתוב, כי ביום הזה יכפר עליכם לטהר אתכם. שואל, כי היום הזה היה צריך לומר, מהו כי ביום הזה. ומשיב, אלא משום שנטהר מקדש של מעלה, שהוא המלכות, והואר. ע\"כ כתוב, כי ביום הזה יכפר עליכם, שפירושו יכפר וינקה תחילה ביום הזה, דהיינו המלכות, כדי שיטהר ויכפר אח\"כ עליכם."],[1,"תו, יכפר ביום","וכו': עוד פירוש, יכפר ביום הזה, שהוא מלכות, וינקה אותו תחילה, וכל זה שצריכים לנקותו, הוא \u0003עליכם,\u0004 בשבילכם, צריכים לנקותו ולטהרו תחילה. \u0003יכפר.\u0004 שואל, מי יכפר. ומשיב, אלא זה הוא עולם העליון, שהוא בינה, המאיר ומנקה הכל. וע\"כ כל צדדים הרעים, הנקראים מצולות ים, נעברים. וכמו שאלו מצולות ים תלויות, אף כך תלויות השערות שלו, של השעיר, שהוא הצד שלהם דהיינו הס\"א, והשערות של אותו הצד אינן חלקות, אלא קשות הרומזות על דינים."],[2,"כגוונא דא כתיב","וכו': כעין זה כתוב, וכפר על הקדש מטומאות בני ישראל ומפשעיהם לכל חטאתם. דהיינו שלא יוכל המקטרג לשלוט עליהם. וע\"כ ביום כפור, שהוא קנוח כל העונות ונקיון שלהם צריכים ישראל לטהר עצמם וללכת יחפי רגלים כמלאכים העליונים. חמשה ענוים הם ביוהכ\"פ, שהם אכילה ושתיה, רחיצה, סיכה, נעילת הסנדל, ותשמיש המטה, כדי להעזר מחמש צדדים העליונים, שהם חג\"ת נ\"ה, שיום הכפורים, שהוא בינה, הוציא אותם, והם שערים שלה."],[3,"ואי שתיה קא חשיב","וכו': ואם חושבים שתיה, לעינוי מיוחד, הרי יש ששה עינוים, משום ששתיה הוא מצד יצחק, שהוא גבורה, ואכילה הוא מצד אברהם שהוא חסד, וע\"כ הם שנים, ואע\"פ ששתיה הוא בכלל אכילה, ואז הם ששה, ועינוי האחרון. תשמיש המטה הוא ונמצא במדרגה הששית, שהוא יסוד, וכנגדו אנו עושים עינוי הזה."],[4,"כתיב ובעשור לחדש","וכו': כתוב ובעשור לחדש השביעי הזה, וכתוב, אך בעשור לחדש, שואל, כתוב בעשור, בעשירי היה צריך לומר, מהו בעשור. ומשיב, אלא משום שעתה ביום הזה, כל מדרגות עליונות באות אלו על אלו, דהיינו שנמשכות ע\"ס שיש בהן ג\"ר מאמא, לשרות על הלבנה, שהיא מלכות, ולהאיר לה, וכולן בסוד עשר, עד שעולות למאה, כי עשר פעמים עשר הם מאה. וכשהוא עומדת בסוד מאה, דהיינו שיש לה ג\"ר, אז הכל אחד, שהמלכות היא אחד עם אמא, ונקראות שתיהן יום הכפורים. וע\"כ נאמר, בעשור שהוא לשון מקור, כש\"א, זכור או שמור. משום שעשירי היה משמע שיורה על המלכות לבדה שהיא ספירה עשירית, אבל בעשור, שהוא לשון מקור, יורה על כל עשר ספירות ביחד, שכולם באות מאמא כדי לעשר לכל ספירה ולהאיר בסוד עשר, דהיינו שכולל גם ג\"ר."],[5,"אהדר האי סבא","וכו': החזיר סבא ההוא ראשו כנגד ר\"ש, ואמר לו, יודע אני שיש לך שאלה בכתוב, הזה, בעשור לחדש השביעי. א\"ל ר\"ש ודאי, בעשור, יפה הוא מה שאמרת שיורה על עשר, אבל אם כן הוא, למה עולה למאה, והרי מן הכתוב אינו משמע אלא שעולה לשבעים, שכתוב, בעשור לחדש השביעי, וכו', וכשמעשרים לשביעי עשרה פעמים, הרי ודאי שעולים לשבעים. אמר לו, על זה החזרתי ראשי אליך, כי אני יודע שחכם אתה."],[6,"ת\"ח תרין רזין","וכו': בוא וראה ב' סודות יש כאן. א' כי הלבנה, שהיא מלכות, נקראת חדש השביעי, ומשום זה נקרא חדש השביעי עשור, שאומר ובעשור לחדש השביעי, משום שמאירים לה עשרה פעמים, דהיינו ע\"ס, ועשר פעם עשר הוא מאה. ועוד יש כאן סוד, כי דבר ההוא שאמרת, אשר בעשור יורה, להעשיר את השביעי, ודאי הוא שעולה לשבעים ביום ההוא, באפן שהיא במדרגת \u0003שבעים\u0004 ובמדרגת \u0003מאה,\u0004 היא במדרגת \u0003מאה\u0004 להשלים אותה בג\"ר ולהאיר לה. והיא במדרגת \u0003שבעים,\u0004 כי ביום הזה לוקחת המלכות לכל עם ישראל לדון אותם, וכולם עומדים בנשמה יותר מבגוף, כי ביום הזה עינוי הנפש הוא, ולא הגוף, כש\"א, ועניתם את נפשותיכם כי כל הנפש אשר לא תעונה. שיום ההוא לוקח לכל הנפשות והם ברשותו, ואם לא היתה עומדת בסוד \u0003שבעים,\u0004 לא היה לה רשות בנפשית, כי קיום הנפשות הוא בסוד שבעים, כמו שנאמר ימי שנותינו בהם שבעים שנה."],[6,"","פירוש. שנתבאר לעיל (באות צ\"ח) שביום הכפורים המלכות עולה לאמא. ומקבל ממנה תחילה הנקודה שלה שהיא שורש בין לחריבו דעלמא ובין דישובא דעלמא, שמבחינה זו אנו עושים התקון של שעיר אחד לה' ושעיר אחד לעזאזל. ואח\"כ מקבלת מאמא מוחין השלמים דפנים. שהם ג\"ר. ואלו המוחין השלמים דפנים הם מדרגת מאה של המלכות ביום ההוא. ואלו המוחין שמקבלת בנקודה דבינה, הם בחינת מוחין דו\"ק, להיותם מבחינת קו שמאל דאמא בלבד, וע\"כ נצטוינו בחמשה עינוים הנוהגים בקו שמאל דאמא מטרם ביאת קו אמצעי ליחד הקוין. ואלו המוחין דו\"ק הם סוד \u0003שבעים,\u0004 שיורה שהוא חסר ג\"ר דפנים. ואלו המוחין הם שלמות הנפש. וע\"כ כתוב והנפש אשר לא תעונה. כי החכמה דשמאל מתגלה רק במלכות. (כנ\"ל בראשית א' דף רע\"ז ד\"ה ועוד כמה ע\"ש) ואור המלכות הוא אור הנפש. וז\"ש, \u0003קיומא דנפשאן ברזא דשבעין\u0004 ששלימות הנפש הוא דוקא מהמוחין של המלכות שהם בבחינת \u0003שבעים,\u0004 שהיא מקבלת ע\"י ה' עינוים. כי המוחין שהם בבחי' \u0003מאה,\u0004 שהם ג\"ר דפנים, אין שם עוד בחינת שבעים, שהם חכמה דשמאל. (כנ\"ל אות צ\"ט ובהסולם שם)."]],[[0,"","כִּפּוּר, מַדּוּעַ נִקְרָא כִּפּוּר? אֶלָּא מִפְּנֵי שֶׁמְּנַקֶּה כָּל טֻמְאָה וּמַעֲבִיר אוֹתָהּ מִלְּפָנָיו בַּיּוֹם הַהוּא. וְעַל זֶה יוֹם כִּפּוּר יוֹם שֶׁל נִקָּיוֹן, וְכָךְ קוֹרְאִים לוֹ, שֶׁכָּתוּב (ויקרא טז) כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם. כִּי הַיּוֹם הַזֶּה צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה כִּי בַיּוֹם הַזֶּה? אֶלָּא מִשּׁוּם שֶׁמְּטַהֵר מִקְדָּשׁ לְמַעְלָה וּמִתְנַקֶּה (ומאיר), כָּתוּב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם. יְכַפֵּר וִינַקֶּה בַתְּחִלָּה בַּיּוֹם הַזֶּה, כְּדֵי שֶׁיִּטְהַר, וּלְבַסּוֹף עֲלֵיכֶם."],[1,"","עוֹד, יְכַפֵּר בַּיּוֹם הַזֶּה, וִינַקֶּה לוֹ בַתְּחִלָּה. וְכָל זֶה עֲלֵיכֶם, בְּסִבַּתְכֶם צָרִיךְ לְנַקּוֹת אוֹתָהּ, וּלְטַהֵר אוֹתָהּ תְּחִלָּה. יְכַפֵּר - מִי יְכַפֵּר? אֶלָּא זֶהוּ עוֹלָם הָעֶלְיוֹן שֶׁמֵּאִיר וּמְנַקֶּה לְכֻלָּם. וְעַל זֶה כָּל צְדָדִים רָעִים, שֶׁנִּקְרָאִים מְצוּלוֹת יָם, עוֹבְרִים. וּכְמוֹ שֶׁאוֹתָן מְצוּלוֹת יָם תְּלוּיוֹת, כָּךְ גַּם תְּלוּיוֹת שְׂעָרוֹת (שלו, שהוא צד) שֶׁלּוֹ, שֶׁהוּא צַד שֶׁלָּהֶם, וְשֵׂעָר שֶׁל הַצַּד הַהוּא לֹא חָלָק."],[2,"","כְּמוֹ זֶה כָתוּב, (שם) וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת בְּנֵי יִשְׂרָאֵל וּמִפִּשְׁעֵיהֶם לְכָל חַ אתָם. וְכָל חַ אתָם צָרִיךְ לוֹ לוֹמַר! אֶלָּא לַהֲנָאָה שֶׁלָּהֶם. מִכָּאן וָהָלְאָה לְכָל חַטֹּאתָם, שֶׁלֹּא יָכוֹל הַמְקַטְרֵג לִשְׁלֹט עֲלֵיהֶם (ועל זה) בְּיוֹם כִּפּוּר, שֶׁהוּא הַעֲבָרַת כָּל הַחוֹבוֹת וְנִקּוּי שֶׁלָּהֶם. צְרִיכִים יִשְׂרָאֵל לְנַקּוֹת עַצְמָם וְלָלֶכֶת יְחֵפֵי רַגְלַיִם כְּמַלְאֲכֵי עֶלְיוֹן. חֲמִשָּׁה עִנּוּיִים כְּדֵי לְהֵעָזֵר בַּחֲמִשָּׁה צְדָדִים עֶלְיוֹנִים שֶׁיּוֹם הַכִּפּוּרִים מוֹצִיא אוֹתָם, וְהֵם שְׁעָרִים שֶׁלּוֹ."],[3,"","וְאִם שְׁתִיָּה מַחֲשִׁיב, שֶׁהִיא מִצַּד שֶׁל יִצְחָק, הֲרֵי שִׁשָּׁה. וְאַף עַל גַּב שֶׁבִּכְלַל אֲכִילָה הִיא, וְאָז הֵם שִׁשָּׁה, וְעִנּוּי אַחֲרוֹן תַּשְׁמִישׁ הַמִּטָּה הוּא, וּבְדַרְגָּה שִׁשִּׁית נִמְצָא, וּכְנֶגְדָּהּ אָנוּ עוֹשִׂים עִנּוּי זֶה."],[4,"","כָּתוּב (במדבר כט) וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה, וְכָתוּב (ויקרא כג) אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר - בָּעֲשִׂירִי צָרִיךְ לוֹ לוֹמַר! מַה זֶּה בֶּעָשׂוֹר? אֶלָּא מִשּׁוּם שֶׁעַתָּה בְּיוֹם זֶה, כָּל מַדְרֵגוֹת עֶלְיוֹנוֹת בָּאוֹת אֵלּוּ עַל אֵלּוּ לִשְׁרוֹת עַל הַלְּבָנָה וּלְהָאִיר אוֹתָהּ, וְכֻלָּן בְּסוֹד שֶׁל עֶשֶׂר, עַד שֶׁעוֹלָה לְמֵאָה. וְכַאֲשֶׁר עוֹמֶדֶת בְּסוֹד שֶׁל מֵאָה, אָז הַכֹּל אֶחָד, וְנִקְרָא יוֹם הַכִּפּוּרִים. וְעַל זֶה בֶּעָשׂוֹר, כְּמוֹ שֶׁאַתָּה אוֹמֵר זָכוֹר, שָׁמוֹר, שֶׁכֻּלָּם בָּאִים כְּדֵי לְעַשֵּׂר וּלְהָאִיר בְּסוֹד שֶׁל עֶשֶׂר."],[5,"","הֶחֱזִיר הַזָּקֵן הַזֶּה רֹאשׁוֹ כְּנֶגֶד רַבִּי שִׁמְעוֹן, וְאָמַר לוֹ, (רבי שמעון,) הֲרֵי יָדַעְתִּי שֶׁשְּׁאֵלָה תַקְשֶׁה בְכָאן, בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַדַּאי, (זה בעשירי נכון הוא וכן הוא, אבל בעשור מדוע וכו') בֶּעָשׂוֹר נָכוֹן הוּא. אִם כָּךְ הוּא, מַדּוּעַ עוֹלֶה לְמֵאָה? וַהֲרֵי מֵהַפָּסוּק לֹא נִרְאֶה, אֶלָּא שֶׁעוֹלֶה לְשִׁבְעִים, מִמַּשְׁמָע שֶׁכָּתוּב בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי. וְכַאֲשֶׁר מְעַשְּׂרִים לַשְּׁבִיעִי עֶשֶׂר פְּעָמִים, הֲרֵי וַדַּאי עוֹלֶה לְשִׁבְעִים. אָמַר לוֹ, עַל זֶה הֶחֱזַרְתִּי רֹאשִׁי כְלַפֶּיךְ, שֶׁהֲרֵי יָדַעְתִּי שֶׁחָכָם אַתָּה."],[6,"","בֹּא וּרְאֵה, שְׁנֵי סוֹדוֹת כָּאן. אֶחָד, שֶׁהֲרֵי הַלְּבָנָה נִקְרֵאת חֹדֶשׁ הַשְּׁבִיעִי, וּמִפְּנֵי כֵן נִקְרָא חֹדֶשׁ הַשְּׁבִיעִי עָשׂוֹר, מִפְּנֵי שֶׁכְּשֶׁמְּאִירִים לָהּ עֶשֶׂר פְּעָמִים - הֲרֵי מֵאָה. וְעוֹד, דָּבָר זֶה שֶׁאָמַרְתָּ, וַדַּאי לְשִׁבְעִים עוֹלָה בְּיוֹם זֶה (ובמדרגה של שבעים היא, ובמדרגה של מאה היא, לדרגה של מאה להשלים ולהאיר). וּבְדַרְגָּה זוֹ שֶׁל שִׁבְעִים, שֶׁהֲרֵי בְּיוֹם זֶה נוֹטֵל לְכָל עַם יִשְׂרָאֵל לָדוּן, וְכֻלָּם עוֹמְדִים בַּנְּשָׁמָה יוֹתֵר מֵהַגּוּף, שֶׁהֲרֵי בְּיוֹם זֶה עִנּוּי שֶׁל הַנֶּפֶשׁ הוּא, וְלֹא שֶׁל הַגּוּף, כְּמוֹ שֶׁנֶּאֱמַר וְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם. כִּי כָל הַנֶּפֶשׁ אֲשֶׁר לֹא תְעֻנֶּה. וְיוֹם זֶה לוֹקֵחַ לְכָל הַנְּפָשׁוֹת וְנִמְצָאוֹת בִּרְשׁוּתוֹ. וְאִם לֹא עוֹמֶדֶת בְּסוֹד (ברשות) שֶׁל שִׁבְעִים, אֵין לָהּ רְשׁוּת בַּנְּפָשׁוֹת (לעמד שם), שֶׁעֲמִידַת הַנְּפָשׁוֹת בְּסוֹד שֶׁל שִׁבְעִים, כְּמוֹ שֶׁנֶּאֱמַר (תהליםצ) יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה וְגוֹ'."]]],[["וְאִי תֵּימָא נַפְשָׁאן דְּרַבְיֵי דְּלָא אַשְׁלִימוּ לְשִׁבְעִין שְׁנִין לָא שַׁלְטָא בְּהוּ. וַדַּאי שַׁלְטָא בְּהוּ, אֲבָל לָא בִּשְׁלִימוּ, כְּמַאן דְּזָכֵי יוֹמִין סַגִּיאִין לְפִקּוּדֵי אוֹרַיְיתָא, וְעִם כָּל דָּא בְּכֻלְּהוּ שִׁבְעִין שְׁנִין אַזְלָא. וְעַל דָּא תָּנֵינָן אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט. מַאן אֶחָד. בְּיִחוּדָא דְּשִׁבְעִין שְׁנִין, מַאן דְּאַסְגֵּי, וּמַאן דְּאַמְעִיט.","וְעַל דָּא, בְּיוֹמָא דְּכִפּוּרֵי אַעְבַּר בְּכֻלְּהוּ שִׁבְעִין, וְאִשְׁתְּלִים הַאי דַּרְגָּא בְּכֻלְּהוּ, וְכָל נִשְׁמָתִין סַלְּקִין קָמֵיהּ, וְדָאִין לְהוֹן בְּדִינָא, וְקוּדְשָׁא בְּרִיךְ הוּא חַיִּיס עָלַיְיהוּ דְּיִשְׂרָאֵל בְּיוֹמָא דָּא, מַאן דְּלָא אַעֲבָר טִינָא מִרוּחֵיהּ לְכַפָּרָא עָלֵיהּ, (ביומא דא) כַּד סָלִיק צְלוֹתֵיהּ בְּהַאי יוֹמָא, טָבַע בְּהַהוּא אֲתָר דְּאִקְרֵי רֶפֶשׁ וָטִיט, וְאִיהוּ מְצוּלוֹת (שלח קס\"ג ע\"ב) יָם וְלָא סָלִיק לְאִתְעַטְּרָא בְּרֵישָׁא דְּמַלְכָּא.","בְּיוֹמָא דָּא לָא אִצְטְרִיךְ בַּר נָשׁ (ויקרא רל\"א ע\"א) לְפָרְשָׁא חֲטָאוֹי קָמֵי אַחֲרָא, בְּגִין דְּכַמָּה אִינּוּן דְּנַטְלֵי הַהִיא מִלָּה, וְסַלְקֵי לָהּ לְעֵילָּא, וְאִית סָהֲדִין בְּהַהִיא מִלָּה. וּמַה (מיכה ז׳:ה׳) מִשֹּׁכֶבֶת חֵיקֶךָ שְׁמֹר פִּתְחֵי פִּיךָ, כָּל שֶׁכֵּן אִינּוּן דְּאַזְלֵי וְעַיְּינֵי לְקַטְרְגָא לוֹן, וְסָהֲדֵי עָלֵיהּ. וְכָל שֶׁכֵּן דְּחָצִיפוּ אִיהוּ לְקָמֵי כֹּלָּא, וְחִלוּל שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כְּתִיב, (קהלת ה׳:ה׳) אֶל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ. (מכאן והלאה רזא בגוון)","פָּתַח וְאָמַר, (שמות י״ב:ב׳) הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים וְגוֹ', וְכִי כֻּלְּהוּ זִמְנִין וְחֳדָשִׁין לָאו אִינּוּן דְּקוּדְשָׁא בְּרִיךְ הוּא. (אלא חדשיכם לא כתיב) אֶלָּא הַחֹדֶשׁ הַזֶּה לָכֶם, דִּילִי אִיהוּ, אֲבָל אֲנָא מָסְרִית לֵיהּ לְכוֹן, דִּלְכוֹן אִיהוּ בְּאִתְגַּלְּיָא, אֲבָל שְׁבִיעָאָה דִּילִי אִיהוּ, וְעַל דָּא אִיהוּ בַּכֶּסֶה, וְלָא בְּאִתְגַּלְּיָא. יַרְחָא דִּלְכוֹן, אִיהוּ בְּסִדּוּרָא, כְּסֵדֶר דְּאַתְוָון אָבִיב, דְּאִיהוּ אב\"ג. י\"ב אִיהוּ רָזָא דְּג'. (ס\"א ואיהו אב\"ג כסדרא דאתוון) אֲבָל יַרְחָא שְׁבִיעָאָה דִּילִי אִיהוּ מִסּוֹפָא דְּאַתְוָון. (ס\"א תשרי) מַאי טַעֲמָא. אָתּוּן מִתַּתָּא לְעֵילָּא, וַאֲנָא מֵעֵילָּא לְתַתָּא.","הַאי דִּילִי. בְּרִישָׁא דְּיַרְחָא, אֲנָא אִיהוּ בְּאִתְכַּסְיָיא. בַּעֲשָׂרָה דְּיַרְחָא, אֲנָא אִיהוּ, בְּגִין דַּאֲנָא בְּחָמֵשׁ קַדְמָאֵי, וּבְחָמֵשׁ אַחֲרָנִין, וּבְחָמֵשׁ תְּלִיתָאֵי. בְּקַדְמִיתָא דְּיַרְחָא אֲנָא אִיהוּ, בְּגִין חֲמִשָּׁא יוֹמִין. בַּעֲשָׂרָה דְּיַרְחָא אֲנָא אִיהוּ, בְּגִין חֲמֵשׁ יוֹמִין אַחֲרָנִין. בט\"ו דְּיַרְחָא אֲנָא אִיהוּ, בְּגִין חֲמֵשׁ תְּלִיתָאֵי.","מַאי טַעְמָא כּוּלֵי הַאי. בְּגִין דְּכָל יַרְחָא דָּא מֵעָלְמָא עִלָּאָה אִיהוּ, וְעָלְמָא עִלָּאָה בְּרָזָא דְּחָמֵשׁ אִיהוּ, בְּכָל זִמְנָא וְזִמְנָא, וּבְגִינֵי כַּךְ יַרְחָא דָּא אִיהוּ בַּכֶּסֶה, וְלָא בְּאִתְגַּלְּיָא, בְּגִין דְּעָלְמָא עִלָּאָה בַּכֶּסֶה אִיהוּ, וְכָל מִלּוֹי בְּאִתְכַּסְיָיא. וְיַרְחָא דָּא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ בִּלְחוֹדוֹי. כֵּיוָן דְּמָטָא יוֹמָא דְּחָמֵיסָר, כְּדֵין גַּלְיָיא. כֹּלָּא אִיהוּ מָטָא בְּחַדְתּוּתָא דְּסִיהֲרָא, וְסִיהֲרָא אִשְׁתְּלִימָת, וְאִתְנְהִירַת מֵאִימָּא עִלָּאָה, וְקַיְּימָא לְאַנְהָרָא לְתַתָּאֵי מִגּוֹ נְהוֹרָא דִּלְעֵילָּא, וְעַל דָּא אִקְרֵי רִאשׁוֹן, כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ג:מ׳) וּלְקַחְתֶּם לָכֶם בַּיוֹם הָרִאשׁוֹן. עַד הַשְׁתָּא קַיְימֵי כֻּלְּהוּ יוֹמִין בְּרָזָא עִלָּאָה, מִכָּאן נַחְתִּין לְרָזָא תַּתָּאָה.","תָּא חֲזֵי, מִיּוֹמָא עִלָּאָה הֲווֹ אִלֵּין יוֹמִין קַדְמָאִין, רָזָא דְּעָלְמָא עִלָּאָה, מַאן דָּאִין דִּינָא דְּעָלְמָא, דְּהָא דִּינָא לָא אִשְׁתְּכַח בְּהַאי עָלְמָא, אֶלָּא מִדִּינָא תַּתָּאָה, (ס\"א רזא) דְּדָא (ישעיהו נ״ד:ה׳) אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא. דְּאִי תֵּימָא דִּינָא דְּעָלְמָא דָּאִין לְעֵילָּא, אִי הָכִי לָא אִתְקְרֵי עָלְמָא דְּחִירוּ, עָלְמָא דִּנְהִירוּ דְּכָל עָלְמִין. עָלְמָא דְּכָל חַיִּין, עָלְמָא דְּכָל חִירוּ. וְאִי תֵּימָא מִדִּינָא דְּיִצְחָק. אִי אִיהוּ אִתְּעַר דִּינָא לְגַבֵּי הַאי עָלְמָא, לָא יַכְלִין כָּל עָלְמָא לְמִסְבַּל, דְּהַהוּא אֶשָּׁא תַּקִּיפָא עִלָּאָה, לָא אִית מַאן דְּסָבִיל לֵיהּ, אֶלָּא אֶשָּׁא דִּלְתַתָּא, דְּאִיהוּ אֶשָּׁא דְּסָבִיל אֶשָּׁא.","אֶלָּא, כְּמָה דְּעָלְמָא דָּא עָלְמָא תַּתָּאָה דְּכֻלְּהוּ עָלְמִין. הָכִי נָמֵי כָּל דִּינוֹי מֵעָלְמָא תַּתָּאָה, דֶּאֱלֹהִים שׁוֹפֵט. וְדָא אִקְרֵי דִּינָא עִלָּאָה עַל הַאי עָלְמָא, וּבְגִין דְּאִיהוּ דַּרְגָּא שְׁבִיעָאָה, לָא גָּזִיר גְּזֵרָה עַל בַּר נָשׁ, אֶלָּא מֵעֶשְׂרִין שְׁנִין וּלְעֵילָּא.","אַשְׁגַּח הַאי סָבָא בַּרִבִּי שִׁמְעוֹן, וְחָמָא לֵיהּ דְּזַלְגִּין עֵינוֹי דִּמְעִין. אָמַר רִבִּי שִׁמְעוֹן, אִי הִיא שְׁבִיעָאָה, אֲמַאי מֵעֶשְׂרִין שְׁנִין וּלְעֵילָּא. אָמַר לֵיהּ, זַכָּאָה מַאן דְּמַלִּיל עַל אוּדְנִין דְּשַׁמְעִין."],[[0,"ואי תימא נפשאן דרביי","וכו': ואם תאמר, הרי נפשות הילדים, שלא השלימו לשבעים שנה, תאמר שאין המלכות שולטת בהם. ומשיב, ודאי שולטת בהם, כי מוחין דו\"ק אלו ה\"ס אפי זוטרי שה\"ס הילדים. אבל לא בשלמות כמי שזכה לימים רבים למצות התורה. ועם כל זה בכולם הולכים השבעים שנה. הן בילדים והן בזקנים, ועל זה למדנו, אחד המרבה ואחד הממעיט. מהו \u0003אחד.\u0004 היינו היחוד של ע' שנים: של מי שמרבה דהיינו זקן, ושל מי שממעיט, דהיינו ילד."],[0,"","פירוש. השבעים שנה שהמלכות מקבלת ביום כפור מאמא, בסוד ה' עינוים, היא מקבלת בעת שיש לה גם מוחין דפנים שה\"ס \u0003מאה\u0004 עשר פעם עשר כנ\"ל. וע\"כ גם המוחין דשמאל שמקבלת בסוד עינוי נפש הם נעשים אורות מרובים בסוד ע' שנה. וסוד המוחין דשמאל שהילדים מקבלים, שהם בחינת אפי זוטרי היינו שמאל בלי ימין, הנמשכים ממצב הא' של הנוקבא. (כנ\"ל בהקדמת ספר הזוהר דף יוד ד\"ה ואלמלי, ודף י\"א ד\"ה ובגין עש\"ה) שהמוחין אלו אינם מאירים אלא מעט מאד. וז\"ש, \u0003ודאי שלטא בהו, אבל לא בשלימו כמאן דזכי יומין סגיאין לפקודי אורייתא,\u0004 כי מי שזכה לפקודי אורייתא שה\"ס קו האמצעי הנקרא תורה, מאירים בו אפילו המוחין דשמאל בבחינה מתוקנת וע\"כ זכה לימים רבים. וזהו שמרמז, \u0003אחד המרבה ואחד הממעיט. מהו אחד. ביחודא דשבעין שנין,\u0004 שהמוחין דחכמה דשמאל ה\"ס \u0003אחד\u0004 שבהם ב' בחינות, \u0003מאן דאסגי,\u0004 ה\"ס זקן המשמש במוחין דשמאל אלו, כמו המלכות ביום הכפורים. שההארה מרובה. \u0003מאן דאמעיט,\u0004 ה\"ס ילד, דהיינו אפי זוטרי, שאין לו מוחין דפנים רק מוחין דשמאל האלו לבד, שההארה מועטת מאד. ובזה תבין הרמז הנ\"ל (שבאות ע\"ט) \u0003אערעו בחד סבא, והוה אחיד בידיה חד ינוקא,\u0004 דהיינו שר\"ש הכיר בו, שהיא זקן ויש לו מוחין דפנים, ועכ\"ז הוא אוחז בידו, ילד אחד, שה\"ס מוחין דו\"ק הנ\"ל, שהם בחינת אחורים, אמנם האירו בו הארה מרובה, בשביל שהיה לו גם מוחין דפנים, שה\"ס זקן. והיה בבחי' \u0003אחד המרבה.\u0004 וכל דברי הסבא, הם מב' בחינות מוחין האלו."],[1,"ועל דא ביומא","וכו': וע\"כ ביום הכפורים, עוברת המלכות בכל אלו שבעים, שהם המוחין דשמאל כנ\"ל, ונשלם מדרגה זו, דחכמה, בכל הספירות שכל ספירה מז\"ס קנתה בחינת ג\"ר ונעשים עשר ספירות, אלא שאין שם ג\"ר הכוללים, וע\"כ הם ע'. וכל הנשמות עולות לפניו ודן אותם בדין, כי המוחין דע' שנה הם בסוד הדין, כנ\"ל, והקב\"ה מרחם על ישראל ביום הזה, ומשפיע להם המוחין מבחינת מאה, כנ\"ל. מי שלא העביר הלכלוך מרוחו לנקות אותו, כשתפלתו עולה ביום ההוא היא טובעת במקום ההוא שנקרא רפש וטיט. שהוא סמאל ולילית, והוא מצולות ים, ואין תפלתו עולה להתעטר בראש המלך. \u0003טינא,\u0004 פירושו לכלוך, שצריכים לכפר אותו. כי על רפש וטיט, מתרגם טין וסין, (ישעיה נ\"ז, כ')."],[2,"ביומא דא לא","וכו': ביום הזה אין אדם צריך לגלות חטאיו לפני אחר. משום שהרבה מקטרגים הם, הלוקחים מלה זו שגילה, ומעלים אותה למעלה, ומעידים על מלה ההוא, ומה אם הכתוב אומר, משוכבת חיקך שמור פתחי פיך, כל שכן אלו המקטרגים ההולכים אחריו ומעיינים איך לקטרג עליו ולהעיד עליו. וחוץ מזה, כל שכן שהוא מחוצף כלפי כל. שאינו בוש לגלות חטאיו, והוא חלול השם של הקב\"ה. וע\"כ כתוב, אל תתן את פיך לחטיא את בשרך."],[3,"פתח ואמר החדש","וכו': פתח ואמר, החדש הזה לכם ראש חדשים וגו', שואל, וכי כל הזמנים והחדשים אינם של הקב\"ה, ולמה אומר החדש הזה לכם. ומשיב, אלא החדש הזה לכם, פירושו, שלי הוא, אבל אני מסרתי אותו לכם, שלכם פירושו שהוא בגילוי. כלומר, שהאורות מגולים בו לישראל. אבל החדש השביעי שלי הוא, וע\"כ הוא בכסה, ולא בגילוי כמ\"ש בכסה ליום חגינו. וכל ענין כיסוי וגילוי האורות, הכונה היא להארת החכמה. החדש שלכם הוא בסדר הא\"ב, כסדר האותיות \u0003אביב,\u0004 כי ניסן נקרא חדש האביב. שהוא אב\"ג, כי י\"ב של אביב הוא סוד ג' כי יוד במספר קטן הוא א', ונמצא אותיות אביב שהן אב\"ג. אבל חדש השביעי שלי הוא ע\"כ מתחיל שמו מסוף האותיות של אלפא ביתא, דהיינו תשרי. מהו הטעם. אתם בסדר ישר אב\"ג שהם ממטה למעלה, כלומר שהאותיות עולות בחשבון, תחילה א' אח\"כ ב' וכו'. ואני בסדר למפרע, תשרי, שהוא ממעלה למטה, שהאותיות יורדות בחשבון, תחילה ת', אח\"כ יורד לש', ואח\"כ לר'. (כנ\"ל אות ק\"י)."],[3,"","ביאור הדברים. פרצוף המלכות נקראת שנה, שבו י\"ב חדש. ששה חדשים הם מחזה ולמעלה שהם חג\"ת נה\"י, שמתשרי עד אדר. וששה חדשים מחזה שלה ולמטה שהם חג\"ת נה\"י שמניסן עד אלול. ואע\"פ שמחזה ולמעלה הוא חג\"ת ומחזה ולמטה הוא נה\"י, אמנם כלולים הם זה מזה, וע\"כ יש חג\"ת נה\"י למעלה, וכן למטה. ונודע, שהמלכות מחזה שלה ולמעלה היא בחינת בינה, ושם היא באתכסיא, ומחזה ולמטה נחשבת לבחינת עצמה, ושם היא באתגליא. וז\"ש, \u0003דלכון איהו באתגליא,\u0004 כי החדש ניסן שהוא מחזה ולמטה, הוא באתגליא שהאורות מתגלים. \u0003אבל שביעאה דילי איהו וע\"ד איהו בכסה ולא באתגליא,\u0004 כי החדש תשרי, הוא מחזה ולמעלה, ששם בחינת בינה, ושם הוא באתכסיא וזהו עד חדש אדר אלא כיון שתחלת הכסוי מתחיל בתשרי, ע\"כ מזכיר רק תשרי. וכן הגילוי של חדש ניסן נמשך עד אלול. אלא כיון שבו תחילת הגילוי מזכיר הכתוב רק ניסן. וע\"כ נקרא ראשון לחדשי השנה, דהיינו ראשון לאורות מגולים. כמו שהזהר אומר בט\"ו תשרי משום שבו מתחיל הגילוי כמ\"ש להלאה אות קכ\"ג) וז\"ש \u0003ירחא דלכון\u0004 וכו' \u0003אב\"ג. אבל ירחא שביעאה דילי איהו מסופא דאתוון\u0004 וכו'. כי כשהאותיות כסדרן יורה על גילוי האורות, שכל פעם האורות מתרבים וכשהאותיות למפרע כמו תשרי יורה כיסוי האורות, שהולכים ומתמעטים בחשבון. וכמו שהוא בכללות כן הוא בפרטות, דהיינו בכל חדש וחדש מי\"ב חדשים, אשר חצי החדש הראשון הוא בבחינת למעלה מחזה, והאורות מכוסים. ומחמשה עשר יום ולהלאה הוא למטה מחזה, והאורות מתגלים. כמו שמבאר והולך."],[4,"האי דילי, ברישא","וכו': החדש הזה השביעי הוא שלי, בתחילת החדש אני הוא, במכוסה, בעשור לחדש אני הוא במכוסה, משום שאני בחמשה ימים הראשונים של החדש, ובחמשה ימים האחרים ובחמשה ימים השלישים. בתחלת החדש אני הוא משום שהוא ה' ימים הראשונים, בעשור לחדש אני הוא, משום שהוא ה' ימים האחרים, בט\"ו לחדש אני הוא, משום שהוא חמשה השלישים."],[4,"","פירוש. שהחדש נחלק ג\"כ לשנים על החזה כמו י\"ב חדשי השנה כנ\"ל בדבור הסמוך. ויש בו ג' קוין למעלה מחזה, שהם בינה, והם מכוסים עד החזה וג' קוין מחזה ולמטה הם בחינת המלכות עצמה והם מגולים. וכיון שהקוין נמשכים מבינה, שכוללת חמשה ספירות חג\"ת נ\"ה, ע\"כ יש בכל קו ה' ספירות."],[4,"","וזה אמרו, \u0003בקדמיתא דירחא אנא איהו,\u0004 דהיינו שאני הוא במכוסה ואינו שלכם באתגליא, \u0003בגין חמשא יומין,\u0004 משום שהם ה' ימים חג\"ת נ\"ה מקו ימין שלמעלה מחזה. \u0003בעשרה דירחא אנא איהו,\u0004 במכוסה ואינה שלכם באתגליא, \u0003בגין חמש יומין אחרנין,\u0004 משום שהם ה' ימים חג\"ת נ\"ה השניים דהיינו קו השמאל שלמעלה מחזה. \u0003בט\"ו דירחא אנא איהו,\u0004 בחמשה עשר לחדש, כלומר עד חמשה עשר לחדש, אני הוא באתכסיא ואינו שלכם באתגליא, \u0003בגין חמש תליתאי,\u0004 משום שהם ה' ימים חג\"ת נ\"ה השלישים, דהיינו קו האמצעי שלמעלה מחזה, וע\"כ עד חמשה עשר בחדש האורות מכוסים ואינו שלכם. אבל מחמשה עשר ולמעלה מתגלים האורות כי חמשה עשר ה\"ס נקודת החזה שמשם מתחיל גילוי האורות כמ\"ש לפנינו."],[5,"מ\"ט כולי האי","וכו': שואל, מהו הטעם שהוא מכוסה כל כך, דהיינו עד חמשה עשר לחדש. ומשיב, משום שכל החדש הזה הוא מעלמא עלאה, דהיינו מבינה, כי ששה חדשים הראשונים הם מבינה כנ\"ל, ועולם העליון הוא בסוד חמש בכל זמן וזמן, כלומר, בכל קו וקו יש בו חמש ספירות חג\"ת נ\"ה, ומשום זה חדש הזה הוא במכוסה ולא בגילוי, כי עולם העליון הוא במכוסה, וכל דבריו במכוסה. וחדש הזה הוא של הקב\"ה בלבדו, ואינו לכם, כיון שמגיע יום חמשה עשר לחדש שה\"ס נקודת החזה כנ\"ל בדבור הסמוך, אז מתגלה, כי מחזה ולמטה, הן בבחינת כללת השנה, שהוא ניסן, והן בבחינת כל חדש, שהוא יום החמשה עשר, כבר נחשב לבחינת המלכות עצמה והאורות מתגלים. הכל מגיע להתחדשות הלבנה, שכל האורות שהיו מכוסים מחזה ולמעלה באים מחזה ולמטה בהתחדשות הלבנה, שהוא מלכות, כי מחזה ולמטה כבר הוא בחינת הלבנה עצמה, ולא בינה. וע\"כ הלבנה נשלמת והאירה מאמא עלאה, שהיא בינה, ועומדת להאיר למטה מן האורות שלמעלה. וע\"כ נקרא יום חמשה עשר לחדש בשם ראשון, כמש\"א \u0003ולקחתם לכם ביום הראשון\u0004 כי עד עתה, דהיינו עד יום חמשה עשר, עמדו כל הספירות בסוד עולם העליון, שהוא בינה, מכאן, מיום ט\"ו. יורדים הספירות לסוד עולם התחתון, שהוא המלכות, וע\"כ האורות מתגלים, וכיון שיום ט\"ו הוא הראשון לאורות המגולים, ע\"כ נקרא ראשון."],[6,"ת\"ח מיומא עלאה","וכו': בוא וראה, מיום העליון, דהיינו מבינה, היו אלו ימים הראשונים, שמקודם ט\"ו לחדש, שה\"ס עולם העליון. בינה, שואל, א\"כ, מי דן דין העולם בראש השנה שהרי דין אינו נמצא בעולם הזה אלא מדין עולם התחתון, שזה אלקי כל הארץ יקרא. כי אם תאמר, שדין העולם נידון למעלה, בבינה, א\"כ לא היה, הבינה, נקרא: עולם החירות, עולם שבו הארות של כל העולמות, עולם שבו כל החיים, עולם של כל החירות. וכיון שהבינה נקרא בכל השמות האלו, איך תאמר שיש בה דין לדון העולם. ואם תאמר, שהוא מדינו של יצחק, דהיינו הקו שמאל של הבינה, זה אי אפשר, כי אם היה מעורר דין לעולם הזה, לא היו יכולים כל העולם לסבול. כי אש חזק העליון הזה, של קו שמאל דבינה, אין מי שיוכל לסבלו חוץ מאש שלמטה שהוא מלכות, שהיא אש הסובל אש."],[6,"","פירוש. הקו שמאל דבינה, שה\"ס יצחק, להיותו במקום ג\"ר, נמצא כל התעוררות שלו נבחן להמשכת החכמה ממעלה למטה, שהוא דין קשה מאוד. שהעולם לא היה יכול לסובלו. משא\"כ המלכות, שאע\"פ שגם היא נמשכת מקו שמאל דבינה, שהוא אש חזק, עכ\"ז כיון שהיא בחינת אור נקבה, המאירה רק ממטה למעלה אין הדין שבה קשה כל כך, והעולם יכול לסובלו. ונמצא שהאש של קו שמאל דבינה אינו נתעורר רק להמלכות, שהיא אש שלמטה והמלכות יכולה לסובלו, משום שהיא אור נקבה, וז\"ש \u0003דההוא אשא תקיפא עלאה לא אית מאן דסביל ליה אלא אשא דלתתא.\u0004 כי מתהפך בה להארת הנקבה. המאירה רק ממטה למעלה. שזה אינו קשה כל כך והעולם יכול לסובלו וכיון שרה\"ש היא מחזה ולמעלה שהוא בינה, קשה, מי דן את העולם, כי בינה עצמה הוא עולם החירות, והקו שמאל שלה אם יתעורר לבדו, לא היה העולם יכול לסבול."],[7,"אלא כמה דעלמא","וכו': ומשיב, אלא כמו שעולם הזה שלנו, הוא עולם התחתון של כל העולמות, כך כל דינין שלו הם מעולם התחתון שבאצילות, שהוא המלכות, הנקרא אלקים שופט, ודינים שלה נקראים דין עליון ביחס עולם הזה התחתון שלנו. וע\"כ נבחנים כלפינו כמו דינים דבינה. ומשום שהיא מדרגה השביעית של ז\"א, אינו גוזר גזרה על האדם אלא מעשרים שנה ולמעלה."],[8,"אשגח האי סבא","וכו': הביט זקן ההוא ברבי שמעון, וראוהו שעיניו נוזלים דמעות, אמר רבי שמעון, אם היא שביעית, למה היא דנה את האדם מעשרים שנה ומעלה. אמר לו, אשרי מי שמדבר לאזנים ששומעות."]],[[0,"","וְאִם תֹּאמַר, נַפְשׁוֹת הַיְלָדִים שֶׁלֹּא הִשְׁלִימוּ לְשִׁבְעִים שָׁנָה לֹא שׁוֹלֶטֶת בָּהֶם - וַדַּאי שֶׁשּׁוֹלֶטֶת בָּהֶם, אֲבָל לֹא בִשְׁלֵמוּת, כְּמִי שֶׁזָּכָה לְיָמִים הַרְבֵּה לְמִצְווֹת הַתּוֹרָה, וְעִם כָּל זֶה, בְּכָל שִׁבְעִים שָׁנָה הִיא הוֹלֶכֶת. וְעַל זֶה לָמַדְנוּ, אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט. מַה זֶּה אֶחָד? בְּיִחוּד שֶׁל שִׁבְעִים שָׁנָה, מִי שֶׁמַּרְבֶּה וּמִי שֶׁמַּמְעִיט."],[1,"","וְעַל זֶה בְּיוֹם הַכִּפּוּרִים עוֹבֶרֶת בְּכָל הַשִּׁבְעִים, וְנִשְׁלֶמֶת דַּרְגָּה זוֹ בְּכֻלָּם, וְכָל הַנְּשָׁמוֹת עוֹלוֹת לְפָנָיו, וְדָן אֶת כֻּלָּן בְּדִין, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עַל יִשְׂרָאֵל בְּיוֹם זֶה. מִי שֶׁלֹּא הֶעֱבִיר טִנּוּף מֵרוּחוֹ לְכַפֵּר עָלָיו, (ביום זה) כַּאֲשֶׁר עוֹלָה תְפִלָּתוֹ בְּיוֹם זֶה, טוֹבֵעַ בַּמָּקוֹם הַהוּא שֶׁנִּקְרָא רֶפֶשׁ וָטִיט, וְהוּא מְצוּלוֹת יָם, וְלֹא עוֹלֶה לִהְיוֹת עֲטָרָה בְרֹאשׁ הַמֶּלֶךְ."],[2,"","בְּיוֹם זֶה לֹא צָרִיךְ בֶּן אָדָם לְפָרֵשׁ חֲטָאָיו בִּפְנֵי אַחֵר, מִשּׁוּם שֶׁכַּמָה הֵם שֶׁלּוֹקְחִים הַדִּבּוּר הַהוּא וּמַעֲלִים אוֹתוֹ לְמַעְלָה, וְיֵשׁ עֵדִים בַּדִּבּוּר הַהוּא. וּמָה (מיכהז) מִשֹּׁכֶבֶת חֵיקֶךְ שְׁמֹר פִּתְחֵי פִיךְ - כָּל שֶׁכֵּן אֵלּוּ שֶׁהוֹלְכִים וּמִסְתַּכְּלִים לְקַטְרֵג עֲלֵיהֶם וּמְעִידִים עֲלֵיהֶם, וְכָל שֶׁכֵּן שֶׁעַזּוּת הוּא לִפְנֵי הַכֹּל וְחִלּוּל שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה כָּתוּב, (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ. (מכאן והלאה סוד באופן אחר)"],[3,"","פָּתַח וְאָמַר, (שמות יב) הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים וְגוֹ'. וְכִי כָל הַזְּמַנִּים וְהֶחֳדָשִׁים אֵינָם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? (אלא חדשיכם לא כתוב) אֶלָּא הַחֹדֶשׁ הַזֶּה לָכֶם, שֶׁלִּי הוּא, אֲבָל אֲנִי מָסַרְתִּי אוֹתוֹ לָכֶם. שֶׁלָּכֶם הוּא בְנִגְלֶה, אֲבָל שְׁבִיעִי שֶׁלִּי הוּא, וְעַל זֶה הוּא בַּכֶּסֶה וְלֹא בְגִלּוּי. חֹדֶשׁ שֶׁלָּכֶם הוּא מְסֻדָּר כְּסֵדֶר אוֹתִיּוֹת אָבִיב, שֶׁהוּא א' ב' ג'. י\"ב הוּא סוֹד אוֹת ג' (והוא א' ב' ג' כסדר האותיות). אֲבָל הַחֹדֶשׁ הַשְּׁבִיעִי, שֶׁלִּי הוּא מִסּוֹף הָאוֹתִיּוֹת (תשרי). מָה הַטַּעַם? אַתֶּם מִמַּטָּה לְמַעְלָה, וַאֲנִי מִמַּעְלָה לְמַטָּה."],[4,"","זֶה שֶׁלִּי. בְּרֹאשׁ הַחֹדֶשׁ אֲנִי הוּא בְכִסּוּי, וּבַעֲשָׂרָה לַחֹדֶשׁ אֲנִי הוּא, מִשּׁוּם שֶׁאֲנִי בְּחָמֵשׁ רִאשׁוֹנוֹת, וּבְחָמֵשׁ אַחֲרוֹנוֹת, וּבְחָמֵשׁ שְׁלִישִׁיּוֹת. בִּתְחִלַּת הַחֹדֶשׁ אֲנִי הוּא מִשּׁוּם חֲמִשָּׁה יָמִים. בַּעֲשָׂרָה לַחֹדֶשׁ אֲנִי הוּא מִשּׁוּם חֲמִשָּׁה יָמִים אֲחֵרִים. בַּחֲמִשָּׁה עָשָׂר לַחֹדֶשׁ אֲנִי הוּא מִשּׁוּם חָמֵשׁ שְׁלִישִׁיִּים."],[5,"","מָה הַטַּעַם כָּל זֶה? מִשּׁוּם שֶׁכָּל חֹדֶשׁ זֶה הוּא מֵעוֹלָם הָעֶלְיוֹן, וְעוֹלָם הָעֶלְיוֹן בְּסוֹד חָמֵשׁ הוּא, בְּכָל זְמַן וּזְמַן, וּמִשּׁוּם כָּךְ חֹדֶשׁ זֶה הוּא בְכִסּוּי וְלֹא בְגִלּוּי, מִשּׁוּם שֶׁעוֹלָם הָעֶלְיוֹן בְּכִסּוּי הוּא, וְכָל דְּבָרָיו בְּהֶסְתֵּר. וְחֹדֶשׁ זֶה הוּא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ. כֵּיוָן שֶׁמַּגִּיעַ יוֹם הַט\"ו לַחֹדֶשׁ, אָז מִתְגַּלֶּה. הַכֹּל הוּא מַגִּיעַ בְּהִתְחַדְּשׁוּת הַלְּבָנָה, וְנִשְׁלֶמֶת הַלְּבָנָה וּמְאִירָה מֵאִמָּא הָעֶלְיוֹנָה, וְעוֹמֶדֶת לְהָאִיר לַתַּחְתּוֹנִים מִתּוֹךְ הָאוֹר הָעֶלְיוֹן, וְעַל זֶה נִקְרָא רִאשׁוֹן, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כג) וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן. עַד עַכְשָׁו עוֹמְדִים כָּל הַיָּמִים בְּסוֹד עֶלְיוֹן. מִכָּאן יוֹרְדִים לְסוֹד תַּחְתּוֹן."],[6,"","בֹּא וּרְאֵה, מִיּוֹם הָעֶלְיוֹן הָיוּ יָמִים אֵלּוּ הָרִאשׁוֹנִים, סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, מִי דָן דִּין שֶׁל הָעוֹלָם, שֶׁהֲרֵי דִּין לֹא נִמְצָא בְזֶה הָעוֹלָם אֶלָּא מִדִּין הַתַּחְתּוֹן? (סוד) שֶׁזֶּה - (ישעיה נד) אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא. שֶׁאִם תֹּאמַר דִּין הָעוֹלָם דָּן לְמַעְלָה, אִם כֵּן לֹא הָיָה נִקְרָא עוֹלַם הַחֵרוּת, עוֹלָם שֶׁהוּא אוֹר שֶׁל כָּל הָעוֹלָמוֹת, עוֹלָם שֶׁל כָּל הַחַיִּים, עוֹלָם שֶׁל כָּל הַחֵרוּת. וְאִם תֹּאמַר מִדִּין שֶׁל יִצְחָק - אִם הוּא מְעוֹרֵר דִּין לְגַבֵּי הָעוֹלָם הַזֶּה, לֹא יְכוֹלִים כָּל הָעוֹלָם לִסְבֹּל, שֶׁהָאֵשׁ הָעֶלְיוֹן הַתַּקִּיף הַהוּא, אֵין מִי שֶׁסּוֹבֵל אוֹתוֹ, אֶלָּא אֵשׁ שֶׁלְּמַטָּה, שֶׁהוּא אֵשׁ שֶׁסּוֹבֵל אֵשׁ."],[7,"","אֶלָּא, כְּמוֹ שֶׁהָעוֹלָם הַזֶּה עוֹלָם הַתַּחְתּוֹן שֶׁל כָּל הָעוֹלָמוֹת, כָּךְ גַּם כָּל דִּינָיו מֵעוֹלָם הַתַּחְתּוֹן, שֶׁל אֱלֹקִים שׁוֹפֵט. וְזֶה נִקְרָא דִין עֶלְיוֹן עַל הָעוֹלָם הַזֶּה, וּמִשּׁוּם שֶׁהוּא דַרְגָּה שְׁבִיעִית, לֹא גוֹזְרִים גְּזֵרָה עַל בֶּן אָדָם אֶלָּא מֵעֶשְׂרִים שָׁנָה וָמַעְלָה."],[8,"","הִסְתַּכֵּל הַזָּקֵן הַזֶּה בְּרַבִּי שִׁמְעוֹן, וְרָאָה אוֹתוֹ שֶׁזּוֹלְגוֹת עֵינָיו דְּמָעוֹת. אָמַר רַבִּי שִׁמְעוֹן, אִם הִיא שְׁבִיעִית, מַדּוּעַ מֵעֶשְׂרִים שָׁנָה וָמַעְלָה? אָמַר לוֹ, אַשְׁרֵי מִי שֶׁמְּדַבֵּר עַל אָזְנַיִם שׁוֹמְעוֹת."]]],[["תָּא חֲזֵי, בֵּי דִּינָא דִּלְתַתָּא בְּאַרְעָא, לָא גַּזְרִין דִּינָא עַל בַּר נָשׁ, עַד תְּלֵיסַר שְׁנִין. מַאי טַעֲמָא. בְּגִין דְּשַׁבְקִין שֶׁבַע שְׁנִין לְשְׁבִיעָאָה, אֱלהֵי כָּל הָאָרֶץ יִקָּרֵא. וְלֵית רְשׁוּ לְבַר נָשׁ בְּאִינּוּן שֶׁבַע. וְאִינּוּן שֶׁבַע, לָא שָׁרָאן אֶלָּא עַל תְּלֵיסַר דִּלְתַתָּא, בְּאַרְעָא דְּאִינּוּן כּוּרְסְיָּיא לְגַבֵּיהּ, וּבְגִין כַּךְ, כָּל גִּזְרִין, וְכָל דִּינִין דִּלְתַתָּא, מֵאִינּוּן שֶׁבַע שְׁנִין דִּלְתַתָּא, כְּלָלָא דְּעֶשְׂרִין שְׁנִין אִיהוּ.","וְדִינָא דְּעָלְמָא בְּרֹאשׁ הַשָּׁנָה, עַל יְדָא דְּהַאי דַּרְגָּא אִיהוּ, דְּאִיהוּ מַמָּשׁ קַיְּימָא בְּדִינָא עַל בְּנוֹי בְּהַאי עָלְמָא, בְּגִין לְאִתְדַּכְּאָה לְגַבֵּי עָלְמָא עִלָּאָה, בְּגִין דְּלֵית לֵיהּ סִיוּעַ לְסַלְּקָא וּלְאִתְדַכְּאָה אֶלָּא מִגּוֹ תַּתָּאֵי.","וְכַד יִשְׂרָאֵל אִינּוּן בַּחֲמֵיסָר יוֹמִין, כְּדֵין נָטִיל לִבְנוֹי, לְפָרְשָׂא גַּדְפּוֹי עָלַיְיהוּ, וּלְמֵחדֵי עִמְּהוֹן. וְעַל דָּא כְּתִיב וּלְקַחְתֶּם לָכֶם בַּיוֹם הָרִאשׁוֹן, (נח ס\"ב ע\"א) פְּרִי דָּא, אִיהוּ אִילָנָא דְּאִקְרֵי עֵץ פְּרִי, וְאִשְׁתְּכַח בֵּיהּ פְּרִי. עֵץ הָדָר: כְּמָה דְאַתְּ אָמֵר (תהילים צ״ו:ו׳) הוֹד וְהָדָר לְפָנָיו. מַאי טַעְמָא אִקְרֵי הָדָר, וּמַאן אִיהוּ הָדָר. אֶלָּא דָּא צַדִּיק.","אֲמַאי אִקְרֵי הָדָר, וְהָא אֲתָר טְמִירָא אִיהוּ דְּלֵית לֵיהּ גִּלּוּיָא, וּצְרִיכָא לְאִתְכַּסְיָיא תָּדִיר, וְלֵית הָדָר אֶלָּא מַאן דְּאִתְגַּלְיָיא וְאִתְחַזֵּי. אֶלָּא, אַף עַל גַּב דְּאִיהוּ דַּרְגָּא טְמִירָא, הִדּוּרָא אִיהוּ דְּכָל גּוּפָא, וְלָא אִשְׁתְּכַח הִדּוּרָא לְגוּפָא, אֶלָּא בֵּיהּ. מַאי טַעֲמָא. מַאן דְּלֵית עִמֵּיהּ הַאי דַּרְגָּא, לֵית בֵּיהּ הִדּוּרָא, לְמֵיעַל בִּבְנֵי נָשָׁא. קָלָא לָאו עִמֵּיהּ בִּדְבוּרָא, (ס\"א כדכורא) וְהִדּוּרָא (ס\"א ודבורא) דְּקָלָא אִתְפְּסַק מִנֵּיהּ. דִּיקְנָא, וְהִדּוּרָא דְּדִיקְנָא לָאו עִמֵּיהּ, וְאַף עַל גַּב דְּאִתְכַּסְיָיא הַהוּא דַּרְגָּא, כָּל הִדּוּרָא דְּגוּפָא בֵּיהּ תַּלְיָא. וְאִתְכַּסֵּי וְאִתְגַּלְיָיא. וּבְּגִין כָּךְ עֵץ הָדָר אִיהוּ, עֵץ דְּכָל הִדּוּרָא דְּגוּפָא בֵּיהּ תַּלְיָא, וְדָא אִיהוּ (בראשית א׳:י״ב) עֵץ עוֹשֶׂה פְּרִי.","כַּפֹּת תְּמָרִים, הָכָא אִתְכְּלִילַת אִתְּתָא בְּבַעְלָהּ בְּלָא פִּרוּדָא, כַּפּוֹת תְּמָרִים (ויחי ר\"כ) כַּחֲדָא. וַעֲנַף עֵץ עָבוֹת, תְּלָתָא. וְעָלִין דִּילֵיהּ, דָּא בְּסִטְרָא דָּא, וְדָא בְּסִטְרָא דָּא, וְחַד דְּשַׁלִּיט עָלַיְיהוּ. וְעַרְבֵי נַחַל, תְּרֵין. דְּלֵית לְהוּ רֵיחָא וְטַעְמָא, כְּשׁוֹקִין בִּבְנֵי נָשָׁא. (ובגין כך) לוּלָב נָטִיל כֻּלְּהוּ, כְּחוּטָא דְּשִׁדְרָה קַיָּימָא דְּגוּפָא. וּמַה דְּנָפִיק לְבַר טֶפַח, הָכִי הוּא, בְּגִין לְאַשְׁלְמָא וּלְאַפָּקָא כֹּלָּא, וּלְשַׁמְּשָׁא כַּדְקָא חֲזֵי.","(ובגין כך) בְּהָנֵי זִינִין, בָּעֵי בַּר נָשׁ לְאִתְחֲזָאָה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. עָלִין וְטַרְפִּין דְּהָנִי תְּמָרִים, אִינּוּן כָּל שְׁאַר חֵילִין דְּאִתְאַחֲדָן בְּאִינּוּן כִּנּוּיָין דְּקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי בְּהוֹן. בְּגִין דְּבָּעֵינָן (ס\"א לאתחדתא) לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא, דְּלֵית לָךְ מִלָּה בְּעָלְמָא, דְּלָא אִית לָהּ דּוּגְמָא לְעֵילָּא, כְּגַוְונָא דִּלְעֵילָּא הָכִי אִית לְתַתָּא, וּבְעוּ יִשְׂרָאֵל לְאִתְאַחֲדָא בְּרָזָא דָּא דִּמְהֵימְנוּתָא, קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.","כְּתִיב (ויקרא כ״ג:מ״ב) בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים, דָּא הוּא רָזָא דִּמְהֵימְנוּתָא, וְהַאי קְרָא עַל עָלְמָא עִלָּאָה אִתְּמַר, וְהָכִי תָּנֵינָן, כַּד אִתְבְּרֵי עָלְמָא, אִתְּמַר הַאי קְרָא.","כַּד שָׁרָא חָכְמָה לְנָפְקָא, מֵאֲתָר דְּלָא יְדִיעַ וְלָא אִתְחֲזֵי, כְּדֵין נָפִיק חַד מִשְׁחָתָא, וּבָטַשׁ, וְהַהִיא חָכְמְתָא עִלָּאָה, נָצִיץ וְאִתְפָּשַּׁט לְכָל סִטְרִין, בְּרָזָא דְּמַשְׁכְּנָא עִלָּאָה. וְהַהוּא מַשְׁכְּנָא עִלָּאָה, אַפִּיק שִׁית סִטְרִין, וּכְדֵין הַהוּא נְצִיצוּ דְּמִשְׁחָתָא נָהִיר לְכֹלָּא, וְאָמַר בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים.","מַאן סֻּכֹּת חָסֵר ו'. דָּא מַשְׁכְּנָא תַּתָּאָה, דְּאִיהוּ כַּעֲשָׁשִׁיתָא, לְאַחֲזָאָה לְכָל נְהוֹרִין, וּכְדֵין אָמַר, בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. מַאן שִׁבְעַת יָמִים. מֵעָלְמָא עִלָּאָה לְתַתָּאָה, דְּכֻלְּהוּ קַיְימֵי בְּקִיּוּמָא, לְאַנְהָרָא לְהַאי סֻּכֹּת. וּמַאן אִיהִי. דָּא (עמוס ט׳:י״א) סֻכַּת דָּוִד הַנּוֹפֶלֶת. סֻכַּת שָׁלוֹם. וּבָעֵי עַמָּא קַדִּישָׁא לְמֵיתָב תְּחוֹת צִלָּהָא, בְּרָזָא דִּמְהֵימְנוּתָא, וּמַאן דְּיָתִיב בְּצִלָּא דָּא, יָתִיב בְּאִינּוּן יוֹמִין עִלָּאִין.","וְעַל דָּא כֻּלְּהוּ בַּסֻּכֹּת בַּסֻּכֹּת וְחַד בַּסוּכּוֹת שְׁלִים, חַד שְׁלִים, לְאַחֲזָאָה דְּמַאן דְּיָתִיב בְּצִלָּא דָּא, יָתִיב בְּאִינּוּן יוֹמִין עִלָּאִין לְעֵילָּא, דְּקַיְימִין עַל הַאי תַּתָּאָה, לְאַנְהָרָא לֵיהּ, לְחַפְיָא עָלֵיהּ, וּלְאַגָּנָא לֵיהּ, בְּשַׁעֲתָא דְּאִצְטְרִיךְ."],[[0,"ת\"ח בי דינא","וכו': בוא וראה, בית דין שלמטה בארץ, אינם גוזרים דין על האדם. עד י\"ג שנה. מהו הטעם. הוא משום שעוזבים שבע שנים לשביעי, אשר אלקי כל הארץ יקרא. ואין רשות לאדם באלו שבע, ואלו שבע אינם שורים אלא על י\"ג שלמטה, שהם כסא אליו, ומשום זה, כל הגזרות וכל הדינים שלמטה, הם מאלו שבע שלמטה, שהוא הכלל של עשרים שנה."],[0,"","פירוש. בכל מצב של המלכות שיש בו דין, היא נקראת בית דין. ויש בה ב' מצבים של קטנות שהם דינים. א) כשמקבלת רק מבחינת נקודת החולם, שאז יש בה נפש רוח דקטנות, ודינים אלו הם בחינת דינים דנוקבא, ונקראת אז בית דין של מטה. מצב הב' הוא כשמקבלת מבחינת נקודת השורק, דהיינו שהיא עולה ומלבשת את הקו שמאל של בינה. שאז היא בבחינת חכמה בלי חסדים, (כנ\"ל אות צ\"ח) שאז משגת נשמה דקטנות. ודינים אלו נקראים דינים דדכורא, ונקראת אז בית דין של מעלה, מטעם שדינים אלו נמשכים מג\"ר, דהיינו מנשמה דקטנות. והנה המלכות נקראת שבע, כנ\"ל, וע\"כ נפש רוח ונשמה שלה הם ג' פעמים שבע. באפן, שבמצב הא' דקטנות שאין לה רק נפש רוח דקטנות יש בה ב' פעמים שבע, שהם י\"ד. ובמצב הב' דקטנות שיש לה גם נשמה, יש בה ג' פעמים שבע, שהם כ\"א. וז\"ס שבית דין של מטה הנמשך ממצב הא' של הקטנות דמלכות, אינם מענישים עד י\"ג שנה ויום א', כי יום א' בשנה חשוב שנה, ויש שם ב' פעמים שבע, שהם י\"ד, כעין בית דין של מטה, שהוא נפש רוח דקטנות שבמלכות. אבל בית דין של מעלה, שהוא בחינת נשמה דקטנות אינם מענישים עד כ' שנה ויום א', שיום א' בשנה חשוב שנה, ויש שם ג\"פ שבע שהם כ\"א."],[0,"","וז\"ש לעיל (אות קכ\"ו) \u0003כמה דעלמא דא עלמא תתאה דכלהו עלמין, הכי נמי כל דינוי מעלמא תתאה,\u0004 שהעולם שלנו אינו יכול לקבל רק ממלכות. ולא מבינה, \u0003ודא אקרי דינא עלאה על האי עלמא,\u0004 שהדין של ראש השנה, אע\"פ שבא ממלכות, נחשב כדין עליון הבא מבינה, כלפי עולם הזה שלנו. כי דין זה של ראש השנה הוא מחמת הלבשת המלכות את קו השמאל של הבינה, (כנ\"ל אות צ\"ב בסולם ד\"ה ביאור) שהוא דינים דדכורא ובחינת נשמה דקטנות של המלכות. וע\"כ נחשב כלפינו לבחינת בינה. כי המלכות עולית אז לבינה. ונחשבת אז המלכות בינה ממש, כלפינו אנו. ובזה מתורץ הקושיא כיון שיום א' דרה\"ש הוא בינה מאין יש דינים שם. והתירוץ הוא, כי הדינים הם ממלכות שעלתה לבינה שהוא לנו בינה ממש."],[0,"","וזה אמרו, \u0003בי דינא דלתתא בארעא לא גזרין דינא על בר נש עד י\"ג שנין,\u0004 דהיינו מצב הא' של קטנות המלכות, שהוא רק נפש רוח לבד דקטנות, שהם ב\"פ שבע, שהם י\"ד דהיינו י\"ג ויום אחד כנ\"ל. \u0003מאי טעמא, בגין דשבקין שבע שנין לשביעאה אלקי כל הארץ יקרא.\u0004 כי בית דין שלמטה אין להם אחיזה אלא בב\"פ שבע של נפש רוח דקטנות, ושבע הג' של נשמה דקטנות המה עוזבים בשביל המלכות הנקראת אלקי כל הארץ, \u0003ולית רשו לבר נש באינון שבע,\u0004 כי אין רשות לאדם להתאחז בדינים של שבע הג', משום שנמשכים מעלית המלכות לבינה, ואין אדם משיג ושולט שם. \u0003ואינון שבע לא שראן אלא על תליסר דלתתא דאינון כורסייא לגביה\u0004 ושבע הג', שהם נשמה דקטנות, אי אפשר שיתגלו זולת אחד שכבר המלכות השיגה י\"ג שנים מנפש רוח דקטנות, הנחשבים לכסא לשבע הג', \u0003ובגין כך כל גזרין וכל דינין דלתתא,\u0004 דהיינו הגזירות והדינים הנמשכים לבני אדם המטה שהם, \u0003מאינון שבע שנין דלתתא\u0004 שה\"ס ב\"ד של מעלה, דהיינו שבע הג' של המלכות, שהוא עולם התחתון, שהוא נשמה דקטנות של המלכות, הם \u0003כללא דעשרין שנין,\u0004 דהיינו ששבע הג' כולל בהכרח גם ב\"פ שבע של נפש ורוח. כנ\"ל, וכולל עשרים שנה. שב\"ד של מעלה, דהיינו הנשמה דקטנות המלכות, מענישים אז. כמבואר."],[1,"ודינא דעלמא בר\"ה","וכו': והדין של העולם בראש השנה, על ידי מדרגה הזו היא דהיינו הנשמה דקטנות המלכות שהוא שבע הג' שהיא ממש עומדת בדין על בניה בעולם הזה, כדי להטהר אל עולם העליון, דהיינו כדי לקבל המוחין דגדלות מבינה, משום שאין לה עזרה לעלות ולהטהר אלא מתוך התחתונים. דהיינו שישובו בתשובה ויעלו מ\"ן."],[2,"וכד ישראל אינון","וכו': וכשישראל הם בט\"ו יום בחדש השביעי, אז הקב\"ה לוקח את בניו, לפרוש כנפיו עליהם ולשמח עמהם. וע\"כ, כתוב ולקחתם לכם ביום הראשון פרי עץ הדר, פרי זה, הוא אילן הנקרא עץ פרי דהיינו המלכות שנמצא בו פירות. עץ הדר, הוא כש\"א, הוד והדר לפניו. מהו הטעם שנקרא הדר, ומי הוא הדר. אלא הוא צדיק, דהיינו יסוד. ונקראת המלכות פרי עץ הדר, דהיינו המלכות המושפעת מן היסוד הנקרא הדר."],[3,"אמאי אקרי הדר","וכו': שואל, למה נקרא היסוד הדר, והרי הוא מקום מכוסה שאין לו גילוי וצריך להתכסות תמיד, ואין הדר אלא מי שמתגלה ונראה. ומשיב אע\"פ שהוא מדרגה מכוסה הוא הידורו של כל הגוף, ולא נמצא הידור לגוף אלא בו. מהו הטעם. הוא כי מי שאין לו מדרגה ההיא, אין בו הידור לבא בין אנשים, הקול אין עמו בדבורו, כי הידורו של הקול נפסק ממנו, זקן והדר זקן אין לו, הרי, אע\"פ שמדרגה ההיא נתכסה עכ\"ז, כל הידורו של הגוף בה תלויה, ומתכסה, ומתגלה בהידורו של הגוף. וע\"כ הוא עץ הדר, דהיינו עץ שכל הדורו של הגוף בו תלוי, וזה הוא עץ עושה פרי. אבל המלכות נקראת עץ פרי."],[4,"כפת תמרים, הכא","וכו': כפות תמרים הוא יסוד צדיק, כמ\"ש צדיק כתמר יפרח כאן נכללה אשה בבעלה בלי פירוד. כי כתוב כפות תמרים ולא וכפות תמרים, שה \u0003ו'\u0004 תפסיק בין פרי עץ הדר אל כפות תמרים, להורות שהם כפותים יחד. (כנ\"ל פרשת ויחי אות רי\"ט) כי יסוד ומלכות הם יחד. \u0003וענף עץ עבות:\u0004 הם שלשה, דהיינו ג' קוין חג\"ת, כי העלים שלו הם שלשה, זה בצד ימין, וזה בצד שמאל, ואחד באמצע השולט עליהם. כי קו האמצעי מיחד הימין והשמאל להיות אחד. \u0003וערבי נחל,\u0004 הם שנים, דהיינו נצח והוד, שאין להם ריח וטעם, שהם כבחינת שוקים בבני אדם. \u0003לולב,\u0004 שהוא יסוד, לוקח וכולל כולם, בדומה לחוט השדרה הנמצא בגוף. ומה שיוצא לחוץ מהמינים טפח למעלה, כך צריך להיות, כדי להשלים ולהוציא כל המדרגות ולשמש כראוי. פירוש. כי היסוד עולה דרך חוט השדרה ומוציא טפת הזרע מן מוח הדעת שבראש. ועל זה רומז הלולב שעולה ויוצא טפח מלמעלה מהדסים והערבות, שהם חג\"ת נ\"ה, שטפח זה יורה הדעת שבראש, שהלולב שהוא יסוד מגיע עד שם."],[5,"בהני זינין בעי","וכו': במינים אלו צריך האדם להראות לפני הקב\"ה, שהם כנגד חג\"ת נהי\"מ, כנ\"ל. העלים של אלו תמרים, דהיינו העלים שבעץ התמר, שנקראים בלשון ארמית טרפין, הם רומזים על כל שאר הצבאות, שמתאחדים באלו הכנוים, שהקב\"ה נקרא בהם. וע\"כ נצטוינו לקחת ד' מינים אלו, משום שצריכים לעורר למטה כעין של מעלה, שאין לך דבר בעולם שאין דבר דומה לו למעלה. ולהיפך, כעין של מעלה כך יש למטה, כי העולמות נחתמו זה מזה, והשורשים הם למעלה, שאין דבר בעולמות תחתונים שלא ימצא שורשו בעולמות העליונים. וע\"כ שורשם של ד' המינים הם חג\"ת נהי\"מ שבאצילות, שצריכים ישראל להתאחד בסוד זה של האמונה לפני הקב\"ה."],[6,"כתיב בסוכות תשבו שבעת ימים:","זה הוא סוד האמונה, שהיא המלכות, שבסו\"ה הזה היא מקבלת כל המוחין שלה. ומקרא זה נאמר על עולם העליון, שהוא בינה. וכך למדנו, כאשר נברא העולם נאמר מקרא הזה."],[7,"כד שרא חכמה","וכו': כשהתחילה החכמה, שהיא או\"א עלאין הנקראים אבא וחכמה לצאת ממקום שאינו ידוע ואינו נראה, דהיינו מראש א\"א, אז יצא מסך אחד והכה, וחכמה עליונה ההיא התנוצצה והתפשטה לכל הצדדים בסוד משכן העליון, שהיא ישסו\"ת הנקרא בינה, ואמא, ומשכן העליון ההוא הוציא ששה קצוות, שהם ז\"א, ואז התנוצצות המסך האיר לכל, ואמר בסכת תשבו שבעת ימים."],[8,"מאן סכת חסר","וכו': מהו סכת חסר \u0003ו',\u0004 זה הוא משכן התחתון, דהיינו מלכות, שהוא כמו עששית, שהוא כלי מזכוכית שמשימים בתוכה נר להאיר, להראות כל האורות, ואז אמר התנוצצות המסך, בסכת תשבו שבעת ימים. מי הם שבעת ימים הם מעולם העליון, שהוא בינה, לעולם התחתון, שהוא מלכות, שכל שבעת ימים, שהם חג\"ת נהי\"מ דבינה, עומדים בקיומם להאיר לסכת הזו. ומי היא, זו סכת דוד הנופלת. סכת שלום. דהיינו המלכות. ועם הקדוש צריך לשבת תחת צלה בסוד האמונה, שהיא המלכות, ומי שיושב בצל זה, יושב באלו הימים העליונים של הבינה."],[8,"","ביאור הדברים. שמתחלה נברא העולם במדת הדין, שהיא מלכות דצמצום א', ראה שאין העולם מתקיים, כי הכלים הנמשכים ממלכות דמדת הדין אינם ראוים לקבל אור העליון לתוכם, עמד ושתף עמו מדת הרחמים. דהיינו שהעלה המלכות למקום בינה שהיא מדת הרחמים. ואז נבקעו כל המדרגות לב' חצאים שכתר וחכמה נשארו בראש א\"א, ובינה ותו\"מ שלו נפלו לגוף, וכן כולם, (כנ\"ל בראשית דף ד' ד\"ה ביאור, ע\"ש) שבזה נתמעטו כל המדרגות לו\"ק בלי ראש. שמצב הזה מכונה נקודת החולם, ואח\"כ לעת גדלות, ע\"י הארת ע\"ב ס\"ג דא\"ק חוזרת ויורדת המלכות ממקום בינה למקומה, וכל חצאי המדרגות שנפלו ממדרגתם חוזרים למדרגתם והמדרגות נשלמות שוב בג\"ר, (כנ\"ל בראשית א' דף צ' ד\"ה בגין ע\"ש) ומצב הזה מכונה נקודת השורק. שאז אותם בינה ותו\"מ שחזרו למדרגתם לוקחים עמהם למעלה גם התחתון שהיו שורים בו בזמן נפילתם, והתחתון מקבל מחמת זה המוחין דעליון, (כנ\"ל בהקסה\"ז דף כ' ד\"ה ואמא. ע\"ש) ונמצא שבעת קטנות נפלו בינה ותו\"מ דישסו\"ת, שהם אמא, לזו\"ן, ובעת גדלות, שבינה ותו\"מ חוזרים למדרגתם לבינה, לוקחים עמהם גם זו\"ן למקום בינה, ואז מקבלים הזו\"ן המוחין דבינה. ע\"י הכלים דבינה ותו\"מ דבינה, שהיו אצלם בזמן קטנות, כמ\"ש שם. ונמצא עתה, שזו\"ן ראוים לקבל אור העליון של בינה וכן כל העולמות בי\"ע הנמשכים מהם. ואז נתקיים העולם. ולולא עלית המלכות למקום הבינה, לא היה מציאות, שהעולם יוכל להתקיים. (כנ\"ל בראשית א' ד\"ה וכבר עש\"ה)."],[8,"","וזה אמרו (אות קל\"ד) \u0003כד אתברי עלמא אתמר האי קרא,\u0004 דהיינו בעת ששתף מדת הרחמים עם המלכות כדי שהעולם יוכל להתקיים. \u0003כד שרא חכמה לנפקא מאתר דלא ידיע ולא אתחזי,\u0004 דהיינו בעת שעלתה המלכות במקום בינה דראש א\"א, ונשאר א\"א בכתר וחכמה, ובינה ותו\"מ שלו נפלו לבחינת גוף שלו, ובינה זו שיצאה לחוץ מראש דא\"א נתחלקה לשנים, הג\"ר שלה נתקנו באו\"א עלאין, ונקראים חכמה, והז\"ת שלה נתקנו בישסו\"ת ונקראים בינה. וז\"ש, \u0003כדין נפיק חד משחתא,\u0004 דהיינו המסך של המלכות שעלתה לראש דא\"א, \u0003ובטש,\u0004 דהיינו שהוציא הבינה דא\"א לחוץ מראש, \u0003וההיא חכמתא עלאה,\u0004 שהוא ג\"ר דבינה, שנתקנו לאו\"א עלאין. \u0003נציץ,\u0004 בבחינת הקטנות שנפלו הבינה ותו\"מ שלו למטה לבינה. \u0003ואתפשט לכל סטרין ברזא דמשכנא עלאה,\u0004 היינו בעת גדלות, שהחזיר הבינה ותו\"מ שלו עלתה אליו גם משכנא עלאה שהיא בינה וקבלה ממנו מוחין. ועד\"ז, \u0003וההוא משכנא עלאה אפיק שית סטרין,\u0004 שגם הבינה החזירה אליה בינה ותו\"מ שלה שנפלו לזו\"ן, שעי\"ז קבלו זו\"ן המוחין דבינה, והבינה הוציאה ששה סטרין שהם זו\"ן. \u0003וכדין ההוא נציצו דמשחתא,\u0004 דהיינו סוד הארת המסך והמיעוט שנעשה ע\"י עלית המלכות לבינה, \u0003נהיר לכלא,\u0004 האיר מוחין דבינה לכל, דהיינו לז\"א ולנוקבא, \u0003ואמר,\u0004 אל המוחין, שהם חג\"ת נה\"י דבינה, \u0003בסכת תשבו שבעת ימים,\u0004 דהיינו שיתפשטו אל המלכות הנקרא סכת חסר \u0003ו'.\u0004 ונבחן, ש \u0003אמר,\u0004 כי לולא הצל, שפירושו התמעטות האור, של נציצו דמשחתא שנעשה בבינה, שה\"ס הסכך, לא היו נמשכים שבעת ימים, שהם חג\"ת נהי\"מ דבינה אל הסכת, שהיא המלכות למטה, אמנם גם בה אותו הצל של נציצו דמשחתא שה\"ס הסכך, כי גם בה יש ע\"ס. והמלכות שלה עלתה ג\"כ למקום בינה שלה, ובינה ותו\"מ שלה נפלו לבי\"ע, שמחמת זה לעת גדלות כשמחזרת בינה ותו\"מ שלה לאצילות עולים עמהם גם בי\"ע בדרך המדרגה, לאצילות ומקבלים ממנה המוחין דשבעת ימים. באפן ששורש הסכך הוא בבינה, ומשם הוא אומר, בסכת תשבו שבעת ימים. וז\"ש (באות קל\"ד) \u0003האי קרא על עלמא עלאה אתמר,\u0004 אמנם אותו הצל והסכך נמצא ג\"כ במלכות, וע\"כ היא נקראת סכה בלי \u0003ו',\u0004 שהכונה היא על אותו הסכך של הבינה הנמצא במלכות."],[9,"וע\"ד כלהו בסכת","וכו': וע\"כ בכולם כתוב סכת סכת חסר \u0003ו',\u0004 שהכונה היא על המלכות כנ\"ל, ובמקום אחד כתוב, בסוכות, מלא. האחד המלא, הוא להראות, שמי שיושב בצל זה, של נציצו דמשחתא הנ\"ל, הוא יושב באלו ימים עליונים שלמעלה, דהיינו חג\"ת נהי\"מ דבינה, העומדים על התחתונה, שהיא מלכות, להאיר לה, ולכסות עליה, כי אותו הסכך דבינה נמשך גם אליה כנ\"ל בדבור הסמוך, ולהגן עליה בשעה שהיא צריכה."]],[[0,"","בֹּא וּרְאֵה, בֵּית דִּין שֶׁלְּמַטָּה בָּאָרֶץ לֹא גוֹזְרִים דִּין עַל בֶּן אָדָם עַד שְׁלֹשׁ עֶשְׂרֵה שָׁנָה. מָה הַטַּעַם? מִשּׁוּם שֶׁעוֹזְבִים שֶׁבַע שָׁנִים לַשְּׁבִיעִית, אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא. וְאֵין רְשׁוּת לָאָדָם בְּאֵלּוּ הַשֶּׁבַע. וְאֵלּוּ הַשֶּׁבַע לֹא נִמְצָאוֹת אֶלָּא עַל שְׁלֹשׁ עֶשְׂרֵה שֶׁלְּמַטָּה (בארץ), שֶׁאֵלּוּ כִסֵּא לְגַבָּיו, וּמִשּׁוּם זֶה כָּל גְּזֵרוֹת וְכָל הַדִּינִים שֶׁלְּמַטָּה, מֵאֵלּוּ הַשֶּׁבַע שָׁנִים שֶׁלְּמַטָּה, כְּלָלוּת שֶׁל עֶשְׂרִים שָׁנָה הֵם."],[1,"","וְדִין הָעוֹלָם בְּרֹאשׁ הַשָּׁנָה הוּא עַל יְדֵי זוֹ הַמַּדְרֵגָה, שֶׁהוּא מַמָּשׁ עוֹמֵד בְּדִין עַל בָּנָיו בָּעוֹלָם הַזֶּה כְּדֵי לְהִטַּהֵר לְגַבֵּי הָעוֹלָם הָעֶלְיוֹן, מִשּׁוּם שֶׁאֵין לוֹ סִיּוּעַ לַעֲלוֹת וּלְהִטַּהֵר אֶלָּא מִתּוֹךְ הַתַּחְתּוֹנִים."],[2,"","וְכַאֲשֶׁר יִשְׂרָאֵל הֵם בַּחֲמִשָּׁה עָשָׂר יוֹם, אָז נוֹטֵל לְבָנָיו לִפְרֹשׂ כְּנָפָיו עֲלֵיהֶם וְלִשְׂמֹחַ עִמָּהֶם. וְעַל זֶה כָּתוּב וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן. פְּרִי זֶה הוּא אִילָן שֶׁנִּקְרָא עֵץ פְּרִי, וְנִמְצָא בוֹ פְּרִי. עֵץ הָדָר - כְּמוֹ שֶׁנֶּאֱמַר (תהלים צו) הוֹד וְהָדָר לְפָנָיו. מָה הַטַּעַם נִקְרָא הָדָר, וּמִי הוּא הָדָר? אֶלָּא זֶה צַדִּיק."],[3,"","מַדּוּעַ נִקְרָא הָדָר, וַהֲרֵי מָקוֹם מֻסְתָּר הוּא שֶׁאֵין לוֹ גִלּוּי, וְצָרִיךְ לְהִתְכַּסּוֹת תָּמִיד, וְאֵין הָדָר אֶלָּא מִי שֶׁמִּתְגַּלֶּה וּמִתְרָאֶה? אֶלָּא, אַף עַל גַּב שֶׁהוּא דַרְגָּה מֻסְתֶּרֶת, הִדּוּר הוּא שֶׁל כָּל הַגּוּף, וְלֹא נִמְצָא הִדּוּר לַגּוּף אֶלָּא בוֹ. מָה הַטַּעַם? מִי שֶׁאֵין עִמּוֹ מַדְרֵגָה זוֹ, אֵין בּוֹ הִדּוּר לָבֹא בִּבְנֵי אָדָם. קוֹלוֹ אֵין עִמּוֹ בְדִבּוּרוֹ (כזכר), וְהִדּוּר (ודבור) שֶׁל קוֹל נִפְסָק מִמֶּנּוּ. זְקָנוֹ וַהֲדַר זְקָנוֹ לֹא עִמּוֹ, וְאַף עַל גַּב שֶׁמִּתְכַּסֵּית הַדַּרְגָּה הַהִיא, כָּל הִדּוּר הַגּוּף תָּלוּי בּוֹ, וּמִתְכַּסֶּה וּמִתְגַּלֶּה. וּמִפְּנֵי כֵן עֵץ הָדָר הוּא, עֵץ שֶׁכָּל הִדּוּר הַגּוּף תָּלוּי בּוֹ, וְזֶהוּ הוּא עֵץ עֹשֶׂה פְּרִי."],[4,"","כַּפֹּת תְּמָרִים - כָּאן נִכְלֶלֶת אִשָּׁה בְּבַעְלָהּ בְּלִי פֵרוּד, כַּפֹּת תְּמָרִים כְּאֶחָד. וַעֲנַף עֵץ עָבֹת - שְׁלֹשָׁה. וְעָלִים שֶׁלּוֹ - זֶה בְּצַד זֶה, וְזֶה בְּצַד זֶה, וְאֶחָד שֶׁשּׁוֹלֵט עֲלֵיהֶם. וְעַרְבֵי נָחַל - שְׁנַיִם, שֶׁאֵין לָהֶם רֵיחַ וְטַעַם, כְּשׁוֹקַיִם בְּבֶן אָדָם. (ומפני כן) לוּלָב נוֹטֵל כֻּלָּם, כְּחוּט הַשִּׁדְרָה שֶׁמַּעֲמִיד אֶת הַגּוּף. וּמַה שֶּׁיּוֹצֵא הַחוּצָה טֶפַח - כָּךְ הוּא, כְּדֵי לְהַשְׁלִים וּלְהוֹצִיא הַכֹּל וּלְשַׁמֵּשׁ כְּמוֹ שֶׁצָּרִיךְ."],[5,"","(ומפני כן) בְּמִינִים אֵלּוּ צָרִיךְ בֶּן אָדָם לְהֵרָאוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. עָלִים שֶׁל אֵלּוּ הַתְּמָרִים, הֵם כָּל שְׁאָר חֵילוֹת שֶׁמִּתְאַחֲזִים בְּאֵלּוּ הַכִּנּוּיִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בָהֶם, מִפְּנֵי שֶׁצְּרִיכִים (להתאחז) לְמַטָּה כְּדֻגְמַת לְמַעְלָה. שֶׁאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁאֵין לוֹ דֻגְמָא לְמַעְלָה. כְּדֻגְמָא שֶׁל לְמַעְלָה כָּךְ יֵשׁ לְמַטָּה. וּצְרִיכִים יִשְׂרָאֵל לְהִתְאַחֵז בְּסוֹד זֶה שֶׁל הָאֱמוּנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","כָּתוּב (ויקרא כג) בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. זֶהוּ סוֹד הָאֱמוּנָה, וְסוֹד זֶה נֶאֱמַר עַל הָעוֹלָם הָעֶלְיוֹן. וְכָךְ לָמַדְנוּ, כַּאֲשֶׁר נִבְרָא הָעוֹלָם נֶאֱמַר פָּסוּק זֶה."],[7,"","כַּאֲשֶׁר הִתְחִילָה חָכְמָה לָצֵאת מִמָּקוֹם שֶׁלֹּא יָדוּעַ וְלֹא נִרְאֶה, אָז יוֹצֵאת מִדָּה אַחַת וּמַכָּה, וְהַחָכְמָה הַהִיא הָעֶלְיוֹנָה מְאִירָה וּמִתְפַּשֶּׁטֶת לְכָל הַצְּדָדִים בְּסוֹד הַמִּשְׁכָּן הָעֶלְיוֹן. וְהַמִּשְׁכָּן הָעֶלְיוֹן הַהוּא מוֹצִיא שִׁשָּׁה צְדָדִים, וְאָז הַנִּיצוֹץ הַהוּא שֶׁל הַמִּדָּה מֵאִיר לְכֻלָּם, וְאָמַר בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים."],[8,"","מִי הוּא סֻכֹּת חָסֵר ו'? זֶה מִשְׁכָּן תַּחְתּוֹן, שֶׁהוּא כַּעֲשָׁשִׁית, לְהַרְאוֹת אֶת כָּל הָאוֹרוֹת. וְאָז אָמַר בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. מִי הֵם שִׁבְעַת יָמִים? מֵעוֹלָם הָעֶלְיוֹן לַתַּחְתּוֹן, שֶׁכֻּלָּם עוֹמְדִים וּמְזֻמָּנִים לְהָאִיר לְזוֹ הַסֻּכֹּת. וּמִי הִיא? זוֹ (עמוס ט) סֻכַּת דָּוִיד הַנֹּפֶלֶת. סֻכַּת שָׁלוֹם. וְצָרִיךְ הָעָם הַקָּדוֹשׁ לָשֶׁבֶת תַּחַת הַצֵּל שֶׁלָּהּ, בְּסוֹד הָאֱמוּנָה. וּמִי שֶׁיּוֹשֵׁב בְּצֵל זֶה, יוֹשֵׁב בְּאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים."],[9,"","וְעַל זֶה כֻּלָּם בַּסֻּכֹּת בַּסֻּכֹּת, וְאֶחָד בַּסֻּכּוֹת שָׁלֵם. אֶחָד שָׁלֵם, לְהַרְאוֹת שֶׁמִּי שֶׁיּוֹשֵׁב בְּצֵל זֶה, יוֹשֵׁב בְּאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים לְמַעְלָה, שֶׁעוֹמְדִים עַל זֶה הַתַּחְתּוֹן לְהָאִיר לוֹ, לְכַסּוֹת עָלָיו וּלְהָגֵן עָלָיו בְּשָׁעָה שֶׁצָּרִיךְ."]]],[["וְתוּ, כֻּלְּהוּ אִקְרוּן סֻכּוֹת בִּשְׁלִימוּ, וּכְתִיב סֻכַּת חָסֵר, דָּא עָלְמָא תַּתָּאָה, דְּבָעָא בְּהָנֵי ז' יוֹמִין קַדִּישִׁין, לְמֵיזָן לִשְׁאַר מְמָנָן רַבְרְבָן דְּעַמִּין, בְּעוֹד דְּאִיהִי נַטְלָא חֶדְוָה בְּבַעְלָהּ, וְלָא יְקַטְרְגוּן חֶדְוָותָא, בְּגִין דְיִתְרַבְרְבוּן (ס\"א דיתעדנון) בְּהַהוּא מְזוֹנָא, קָרְבָּנִין דִּלְהוֹן סַגִּיאִין יַתִּיר מִשְּׁאָר יוֹמִין, בְּגִין דְּיִתְעַסְּקוּן בְּהוּ, וְלָא יִתְעָרְבוּן לְבָתַר בְּחֶדְוָה דְּיִשְׂרָאֵל. וּמַאן חֶדְוָה דְּיִשְׂרָאֵל, דָּא יוֹמָא תְּמִינָאָה דַּעֲצֶרֶת.","וְתָּא חֲזֵי, בְּעוֹד דְּאִינּוּן שְׁאַר מְמָנָן חַדָּאן, וְאַכְלִין בְּהַהוּא מְזוֹנָא דִּמְתַּקְנִי לוֹן יִשְׂרָאֵל. אִינּוּן מְתַקְּנֵי כּוּרְסְיָּיא לְקוּדְשָׁא בְּרִיךְ הוּא מִתַּתָּא, וּלְסַלְּקָא לֵיהּ לְעֵילָּא, בְּאִינּוּן זִינִין, וּבְחֶדְוָה, וּבְהִלּוּלָא, וּלְאַקְפָא מַדְבְּחָא. כְּדֵין אִיהִי סַלְּקָא, וְנַטְלָא בִּרְכָּאן וְחֶדְוָה בְּבַעְלָהּ.","וּשְׁאַר חֵיוָון רַבְרְבָן מְמָנָן דְּעַמִּין, אָכְלָן וּמַדְקָן וְרַפְסָן וְאִתְּזָנוּ. וְאִיהִי נַקְטָא נַפְשָׁאן בְּעִנּוּגִין לְעֵילָּא, כְּמָה דְּאִתְּמַר. כֵּיוָן דְּנַחְתָּא, וְהָא נַקְטָא כָּל בִּרְכָּאן וְכָל קִדּוּשִׁין וְכָל עִנּוּגִין, וְיִשְׂרָאֵל כָּל הָנֵי שִׁבְעָה יוֹמִין הֲווֹ (ויקרא רצ\"ד ע\"ב) מַשְׁכִין לָהּ בְּאִינּוּן עוֹבָדִין דְּקָא עַבְדִּין וּמְקָרְבִין בַּהֲדָהּ, כְּדֵין נַחְתָּא לְקָרְבָא בִּבְנָהָא, וּלְמֵחדֵי לוֹן יוֹמָא חַד, וְהַהוּא יוֹמָא אִיהוּ יוֹמָא תְּמִינָאָה, בְּגִין דְּכָל ז' יוֹמִין אַחֲרָנִין בַּהֲדָהּ. וְעַל דָּא אִיהוּ תְּמִינָאָה, וּתְמַנְיָא יוֹמִין כַּחֲדָא. וּבְגִין כַּךְ אִקְרֵי עֲצֶרֶת: כְּנִישִׁין. כְּנִישִׁין כֻּלְּהוּ בְּהַאי יוֹמָא. וְאִקְרֵי שְׁמִינִי, וְלֵית שְׁמִינִי אֶלָּא מִגּוֹ שִׁבְעָה.","כְּתִיב (איוב א) יְהִי שֵׁם יְיָ' מְבוֹרָךְ. מַאי מְבוֹרָךְ. (אלא כלא ידעי), אֲבָל רָזָא חֲדָא יָדַע חַד מֵחַבְרָנָא, בְּמַדְבְּרָא אַחְזִיאוּ לֵיהּ בְּחֶלְמָא, וְרִבִּי יִצְחָק כַּפְתּוֹרָא שְׁמֵיהּ. מַאי מְבוֹרָךְ. שֵׁירוּתָא קָשֶׁה, וְסוֹפֵיהּ רַךְ. מ\"ב קָשֶׁה, וְדִינָא אִיהוּ וַדַּאי. (ולבתר כך) כְּגַוְונָא דָּא, יוֹמָא דְּרֹאשׁ הַשָּׁנָה מ\"ב, דְּהָא בְּמ\"ב (וברזא דמ\"ב) אַתְוָון אִתְבְּרֵי עָלְמָא, וְעַל דָּא אִתְבְּרֵי בְּדִינָא. לְבָתַר רַךְ, וְעַל דָא תָּנֵינָן, כָּל שֵׁירוּתִין קָשִׁין, וְסוֹפָא דִּלְהוֹן רָכִין. (ס\"א דא במ\"ב וברזא דמ\"ב אתוון אתברי עלמא ועל דא אתברי בדינא לבתר כך כגוונא דא) בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה מ\"ב קָשֶׁה בְּדִינָא. בְּיוֹמָא דַּעֲצֶרֶת רַךְ בְּחֶדְוָה.","תָּא חֲזֵי, מָה בֵּין דִּינָא עִלָּאָה, לְהַאי דִּינָא. דִּינָא עִלָּאָה שֵׁירוּתָא וְסוֹפָא קָשֶׁה, וְלֵית מַאן דְּיֵקוּם בֵּיהּ, וְכָל מָה דְּאָזִיל אִתְתָּקַּף, וּבָתַר דְּשָׁאֲרִי, לָא סָלִיק מִנֵּיהּ, עַד דְּאָכִיל וְשֵׁצֵי כֹּלָּא, דְּלָא אִשְׁתְּאַר כְּלוּם. אֲבָל דִּינָא אַחֲרָא דְּתַתָּא, שֵׁירוּתָא קָשֶׁה, וְכָל מָה דְּאָזִיל אִתְחֲלָשׁ, עַד דְּנָהִיר אַנְפִּין, כְּגַוְונָא (ס\"א דא דינא דנוקבא) דְּנוּקְבָּא דְּחָלָשׁ חֵילָהָא.","אֵימָתַי אִתְּעַר דִּינָא דִּלְעֵילָּא לְמִשְׁרֵי עַל עָלְמָא. בְּיוֹמָא דְּטוֹפָנָא. וְעַל דָּא לָא אִשְׁתְּאַר כְּלוּם בְּעָלְמָא, בַּר הַהוּא תֵּבוּתָא דְּנֹחַ, דְּאִיהִי כְּגַוְונָא עִלָּאָה, דְּסָבִיל לְהַהוּא תּוּקְפָּא. וְאִי לָאו דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתְּכַח בְּרַחֲמֵי עַל עָלְמָא, כָּל עָלְמָא אִתְאֲבִיד, דִּכְתִּיב, (תהילים כ״ט:י׳) יְיָ' לַמַּבּוּל יָשָׁב, וְעַל דָּא לָא שַׁרְיָא דִּינָא דִּלְעֵילָּא עַל עָלְמָא, דְּלָא יָכִיל עָלְמָא לְמִסְבַּל לֵיהּ, אֲפִילּוּ רִגְעָא חֲדָא.","אַדְּהָכִי הֲוָה רִבִּי שִׁמְעוֹן בָּכֵי וְחַדֵּי. זָקְפוּ עַיְינִין, וְחָמוּ חֲמִשָּׁה מֵאִינּוּן פְּרוּשִׁים, דַּהֲווֹ אַזְלֵי אֲבַתְרֵיהּ, לְמִתְבַּע לֵיהּ. קָמוּ. אָמַר רִבִּי שִׁמְעוֹן, מִכָּאן וּלְהָלְאָה מָה שְׁמָךְ. אָמַר, נְהוֹרָאי סָבָא, בְּגִין דִּנְהוֹרָאי אַחֲרָא אִית גַּבָּן. אַזְלוּ רִבִּי שִׁמְעוֹן וְאִינּוּן חַבְרַיָּיא עִמֵּיהּ תְּלַת מִילִין, אָמַר רִבִּי שִׁמְעוֹן, לְאִינּוּן אַחֲרָנִין, מַה אָרְחָא דָּא גַּבַּיְיכוּ. אָמְרוּ, לְמִתְבַּע לֵיהּ לְהַאי סָבָא, דְּמֵימוֹי אֲנָן שָׁתָאן בְּמַדְבְּרָא. אָתָא רִבִּי שִׁמְעוֹן וּנְשָׁקֵיהּ, אָמַר לֵיהּ, נְהוֹרָאי שְׁמָךְ, וּנְהוֹרָא אַנְתְּ, וּנְהוֹרָא עִמָּךְ שָׁרֵי.","פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר, (דניאל ב׳:כ״ב) הוּא גָּלֵא עֲמִיקָתָא וּמְסַּתְּרָתָא יָדַע מָה בַחֲשׁוֹכָא וּנְהוֹרָא עִמֵּהּ שְׁרֵא. הוּא גָּלֵה עֲמִיקָתָא וּמְסַּתְּרָתָא, קוּדְשָׁא בְּרִיךְ הוּא גַּלֵּי עֲמִיקָתָא וּמְסַּתְּרָתָא, דְּכָל עֲמִיקִין סְתִימִין עִלָּאִין אִיהוּ גַּלֵּי לוֹן. וּמַאי טַעֲמָא גַּלֵּי לוֹן. בְּגִין דְּיָדַע מָה בַחֲשׁוֹכָא. דְּאִלְמָלֵא חֲשׁוֹכָא לָא אִתְיְדַע נְהוֹרָא. וְאִיהוּ יָדַע מָה בַחֲשׁוֹכָא. וּבְגִין כַּךְ גַּלֵּי עֲמִיקָתָא וּמְסַּתְּרָתָא, דְּאִי לָאו חֲשׁוֹכָא לָא יִתְגַּלְיָין עֲמִיקִין וּמְסַתְּרָאָן. וּנְהוֹרָא עִמֵּהּ שְׁרֵא. מַאן נְהוֹרָא דָּא. נְהוֹרָא דְּאִתְגַּלְיָיא מִגּוֹ חֲשׁוֹכָא."],[[0,"ותו כלהו אקרון","וכו': ועוד, יש לומר, שכולם נקראים סוכות במלואו, דהיינו הסכך דבינה והסכך דז\"א, והכתוב, סכת חסר, זה הוא עולם התחתון, שהוא המלכות, שצריך בז' ימים אלו הקדושים לזון שאר הממונים שרי העולם, שה\"ס ע' פרים שמקריבים בז' ימי הסוכות, שהיא צריכה להתמעט מאור ולעורר המוחין דשמאל, שהם האחורים שלה, שמהם נזונים ע' שרים אלו, בעוד שהיא מקבלת שמחה בבעלה במוחין דפנים, וצריכה לזה, כדי שלא יקטרגו בעת השמחה, ונותנת להם להתעדן במזון ההוא, והקרבנות שלהם מרובים יותר מבשאר הימים, כדי שיתעסקו בהם, ולא יתערבו אחר כך בשמחת ישראל. שהוא על דרך שנותנים להם חלק בשעיר ר\"ח ושעיר לעזאזל, (כנ\"ל אות ק') ומטעם מיעוט הזה להזין שרי האומות, היא נקראת סכת חסר \u0003ו'.\u0004 ומהו שמחת ישראל. זהו יום שמיני העצרת."],[1,"ות\"ח בעוד דאינון","וכו': ובוא וראה. בעוד שאלו שאר הממונים שמחים ואוכלים מזון ההוא שישראל מתקנים בשבילם, דהיינו ע' הפרים, באותו זמן, הם מתקנים כסא אל הקב\"ה מלמטה, דהיינו שמתקנים המלכות להיות כסא להקב\"ה, ולהעלות אותה למעלה, באלו ד' המינים, ובשמחת החג, ובאמירת הלל. ובהקפת המזבח, אז היא, המלכות, עולה ומקבלת ברכה ושמחה בבעלה, בז\"א."],[2,"ושאר חיוון רברבין","וכו': ושאר החיות שהם ע' שרים הממונים על העמים, אוכלים ולועסים הדק והנשאר מאכילתם דרכו ברגליהם, וניזונו. (דהיינו כמ\"ש בחיה הד', בספר דניאל ז') דהיינו מע' פרים כנ\"ל. והיא, המלכות, לוקחת הנפשות ומעלה אותן לתענוג העליון, לז\"א, כמו שאמרנו, כיון שירדה והיא אוחזת כל הברכות וכל הקדושות וכל התענוגים, שישראל המשיכו לה בכל אלו שבעת הימים, באלו המעשים שעשו והקריבו לה, אז ירדה להתקרב לבניה, ולשמח אותם יום אחד, ויום ההוא הוא יום השמיני, משום שכל ז' ימים האחרים עמה, כנ\"ל, וע\"כ היא שמינית, והיא שמונה ימים יחד, ומשום זה נקראת \u0003עצרת,\u0004 שפירושו קבוץ, שכל ז' ימים מתקבצים ביום השמיני ההוא, ונקראת \u0003שמיני\u0004 דהיינו שמיני העצרת. ואין שמיני אלא מתוך שבעה. וע\"כ נקראת בשני שמות, נקראת שמיני להיותה שמיני לז' הימים. ונקראת עצרת, להיותה כולל בתוכה כל שבעת הימים יחד."],[3,"כתיב, יהי שם ה' מבורך: מהו מבורך.","אבל סוד אחד, ידע אחד מן החברים שלנו, שהראו לו בחלום, ושמו ר' יצחק כפתורא. ואמר, מהו מבורך. הוא, שהתחלתו קשה וסופו רך. כי \u0003מבורך,\u0004 הוא אותיות \u0003מ\"ב ור\"ך,\u0004 מ\"ב, הוא קשה, והוא דין ודאי, כעין זה יום של ראש השנה, הוא מ\"ב, כי במ\"ב אותיות נברא העולם דהיינו בל\"ב אלקים, ועשרה מאמרות, שהם מ\"ב, וכן יש מ\"ב אותיות מן ב' דבראשית עד ה \u0003ב\u0004 של המלה ו \u0003ב\u0004 והו, וע\"כ נברא בדין. ואח\"כ \u0003רך.\u0004 וע\"כ למדנו כל התחלות קשות וסוף שלהם רכים. כי ביום ראש השנה, \u0003מ\"ב,\u0004 בדין קשה, ביום שמיני העצרת \u0003רך\u0004 בשמחה."],[3,"","פירוש. הנוקבא כולה נבנה מקו שמאל, וכל תקונה היא להכלל בחסדים שבימין. וע\"כ בראש הנוקבא, שה\"ס מ\"ב, עוד לא נכלל השמאל בימין, וע\"כ היא \u0003קשה,\u0004 שיש בה דינים דשמאל בלי ימין. וסופה, כבר נכללה כולה בחסדים, דהיינו ביום שמיני העצרת ואז הוא \u0003רך.\u0004 וזסו\"ה יהי שם ה' \u0003מבורך,\u0004 ששם ה', שהיא הנוקבא הנקראת שם תהיה \u0003מ\"ב ר\"ך. מ\"ב\u0004 יורה, על ראש הנוקבא שה\"ס ראש השנה. שאז הוא קשה. \u0003רך,\u0004 יורה, על שמיני העצרת שאז היא \u0003רך.\u0004"],[4,"ת\"ח מה בין","וכו': בוא וראה, מה בין דין עליון, דהיינו קו שמאל מבינה, שה\"ס יצחק, שהוא אור זכר, לדין הזה של הנוקבא. דין עליון שבזכר, המאיר מלמעלה למטה, ההתחלה והסוף קשים, ואין מי שיוכל לעמוד בדינים ההם, וכל מה שהולך ונמשך הוא מתחזק, ואחר שהתחיל, אינו עוזב אותו, עד שאוכל ומכלה הכל ולא נשאר כלום, אבל דין האחר שלמטה, דהיינו שבמלכות, שהיא אור נקבה המאירה ממטה למעלה, ההתחלה קשה, דהיינו בראש השנה, וכל מה שהולך ומתפשט הוא נחלש, עד שמאיר המוחין דפנים בשמיני עצרת. וזה דומה לנקבה, שכחה חלש. וכבר נתבאר לעיל (אות קכ\"ה בהסולם ד\"ה פירוש)."],[5,"אימתי אתער דינא","וכו': שואל, מתי נתעורר הדין של מעלה, מזכר, לשרות על העולם. ומשיב, ביום המבול. וע\"כ לא נשאר אז כלום בעולם חוץ מהתיבה של נח. שהיא כעין התיבה העליונה, שהיא המלכות, הסובלת לאותו תוקף הדין, שהיא \u0003אשא דסביל אשא\u0004 (כנ\"ל אות קכ\"ה) ואם לא שהכין לו הקב\"ה התיבה, ונמצא ברחמים על העולם, היה נאבד כל העולם. שכתוב, הוי\"ה למבול ישב, ששם הויה הוא רחמים. ועל כן מאז ולהלאה, אין שורה הדין של מעלה על העולם, כי העולם לא היה יכול לסובלו אפילו רגע אחד."],[6,"אדהכי הוה ר\"ש","וכו': בתוך כך היה ר' שמעון בוכה ושמח. נשאו עיניהם וראו, חמשה אנשים מאלו פורשי המדבר, שהיו הולכים אחר הזקן לבקש אותו, לומר להם תורה. קמו. אמר ר' שמעון מכאן ולהלאה מה שמך. אמר, נהוראי סבא. משום שיש נהוראי אחר אצלנו ע\"כ קוראים לי נהוראי סבא. הלכו, ר\"ש והחבריא שלו עמו, שלשה מילין. אמר ר' שמעון לאלו אנשים האחרים, למה הוא הדרך הזה לכם. אמרו לו, באנו לבקש לזקן הזה, שיאמר לנו תורה, כי מימיו אנו שותים במדבר, כלומר, שהם תלמידיו שבמדבר. בא ר\"ש ונשקו לאותו זקן. אמר לו נהוראי שמך, ואור אתה, והאור שורה עמך. כי נהוראי פירושו אור."],[7,"פתח ר\"ש ואמר","וכו': פר\"ש ואמר, הוא גלה עמיקתא ומסתרתא ידע מה בחשוכא ונהורא עמה שרא. \u0003הוא גלי עמיקתא ומסתרתא,\u0004 היינו שהקב\"ה מגלה עמוקות ונסתרות, שכל עמוקות הסתומים העליונים הוא מגלה אותם. דהיינו קו אמצעי המגלה העמוקות שבב' הקוין דבינה. ומה הטעם שגילה אותם. הוא משום שידע מה בחשך, דהיינו בחשך דשמאל, ששם נשקע אור החכמה, מטעם חוסר חסדים, ואם לא היה החשך לא היה אח\"כ מתגלה האור על ידי קו האמצעי, והוא יודע מה בחשך, דהיינו שכלל אותו בקו ימין, ומשום זה גלה עמוקות ונסתרות, שאם לא החשך דשמאל לא היו נגלות עמוקות ונסתרות. ואז, \u0003ונהורא עמה שרא.\u0004 מהו אור הזה. הוא אור שנגלה מתוך החשך, שהוא חכמה."]],[[0,"","וְעוֹד, כֻּלָּם נִקְרָאִים סֻכּוֹת בִּשְׁלֵמוּת, וְכָתוּב סֻכֹּת חָסֵר, זֶה הָעוֹלָם הַתַּחְתּוֹן שֶׁצָּרִיךְ בְּאֵלּוּ הַשִּׁבְעָה יָמִים קְדוֹשִׁים לָזוּן לִשְׁאָר הַמְמֻנִּים הַגְּדוֹלִים שֶׁל הָעַמִּים, בְּשָׁעָה שֶׁהִיא לוֹקַחַת שִׂמְחָה בְּבַעְלָהּ, וְלֹא יְקַלְקְלוּ שִׂמְחָתָהּ, כְּדֵי שֶׁיִּתְבַּלְבְּלוּ (שיתעדנו) בַּמָּזוֹן הַהוּא, הַקָּרְבָּנוֹת שֶׁלָּהֶם רַבִּים יוֹתֵר מִשְּׁאָר יָמִים, כְּדֵי שֶׁיִּתְעַסְּקוּ בָהֶם וְלֹא יִתְעָרְבוּ לְבַסּוֹף בַּשִּׂמְחָה שֶׁל יִשְׂרָאֵל. וּמִי הִיא שִׂמְחָה שֶׁל יִשְׂרָאֵל? זֶה יוֹם שְׁמִינִי עֲצֶרֶת."],[1,"","וּבֹא רְאֵה, בְּעוֹד שֶׁאֵלּוּ שְׁאָר הַמְמֻנִּים שְׂמֵחִים וְאוֹכְלִים בַּמָּזוֹן הַהוּא שֶׁמְּתַקְּנִים לָהֶם יִשְׂרָאֵל, הֵם מְתַקְּנִים כִּסֵּא לַקָּבָּ\"ה מִלְּמַטָּה, וּלְהַעֲלוֹת אוֹתוֹ לְמַעְלָה בְּאֵלּוּ הַמִּינִים, וּבְשִׂמְחָה, וּבְהַלֵּל, וּלְהַקִּיף הַמִּזְבֵּחַ. אָז הִיא עוֹלָה וְלוֹקַחַת בְּרָכוֹת וְשִׂמְחָה בְּבַעְלָהּ."],[2,"","וּשְׁאָר חַיּוֹת גְּדוֹלוֹת מְמֻנּוֹת הָעַמִּים, אוֹכְלוֹת וְשׁוֹחֲקוֹת וְרוֹמְסוֹת וְנִזּוֹנוֹת. וְהִיא נוֹטֶלֶת נְפָשׁוֹת בְּעֹנֶג לְמַעְלָה, כְּמוֹ שֶׁאָמַרְנוּ. כֵּיוָן שֶׁיּוֹרֶדֶת, וְהִיא לוֹקַחַת כָּל הַבְּרָכוֹת וְכָל הַקְּדֻשּׁוֹת וְכָל הָעִנּוּגִים, וְיִשְׂרָאֵל כָּל אֵלּוּ הַשִּׁבְעָה יָמִים הָיוּ מוֹשְׁכִים אוֹתָהּ בְּאֵלּוּ הַמַּעֲשִׂים שֶׁהֵם עוֹשִׂים וּמַקְרִיבִים לָהּ, אָז יוֹרֶדֶת לְהִתְקָרֵב בְּבָנֶיהָ וּלְשַׂמֵּחַ אוֹתָם יוֹם אֶחָד. וְהַיּוֹם הַהוּא הוּא יוֹם שְׁמִינִי, מִשּׁוּם שֶׁכָּל שִׁבְעָה יָמִים אֲחֵרִים אִתָּהּ. וְעַל זֶה הוּא שְׁמִינִי, וּשְׁמוֹנָה יָמִים כְּאֶחָד. וּמִפְּנֵי זֶה נִקְרָא עֲצֶרֶת - כִּנּוּס. מִתְכַּנְּסִים כֻּלָּם בְּיוֹם זֶה. וְנִקְרָא שְׁמִינִי, וְאֵין שְׁמִינִי אֶלָּא מִתּוֹךְ שִׁבְעָה."],[3,"","כָּתוּב (איוב א) יְהִי שֵׁם ה' מְבֹרָךְ. מַהוּ מְבֹרָךְ? (אלאהכלידוע) אֲבָל סוֹד אֶחָד יָדַע אֶחָד מֵחֲבֵרֵנוּ, בַּמִּדְבָּר הֶרְאוּ לוֹ בַחֲלוֹם, וּשְׁמוֹ רַבִּי יִצְחָק מִכַּפְתּוֹר. מַהוּ מְבֹרָךְ? רֵאשִׁיתוֹ קָשָׁה וְסוֹפוֹ רַךְ. מ\"ב קָשֶׁה, וְדִין הוּא וַדַּאי. (ואחר כך) כְּעֵין זֶה יוֹם שֶׁל רֹאשׁ הַשָּׁנָה מ\"ב, שֶׁהֲרֵי בְּאַרְבָּעִים וּשְׁתַּיִם (ובסוד מ\"ב) אוֹתִיּוֹת נִבְרָא הָעוֹלָם, וְעַל זֶה נִבְרָא בְדִין. לְבַסּוֹף רַךְ. וְעַל זֶה לָמַדְנוּ, כָּל הַהַתְחָלוֹת קָשׁוֹת, וְסוֹף הַכֹּל רַךְ. (זה מ\"ב ובסוד של ארבעים ושתים אותיות נברא העולם, ועל זה נברא בדין לבסוףכדגמתזה) בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה מ\"ב קָשֶׁה, בְּדִין. בַּיּוֹם שֶׁל עֲצֶרֶת רַךְ, בְּשִׂמְחָה."],[4,"","בֹּא וּרְאֵה מַה בֵּין דִּין עֶלְיוֹן לְדִין זֶה. דִּין עֶלְיוֹן תְּחִלָּתוֹ וְסוֹפוֹ קָשֶׁה, וְאֵין מִי שֶׁיַּעֲמֹד בּוֹ, וְכָל מַה שֶּׁהוֹלֵךְ מִתְחַזֵּק, וּלְבַסּוֹף שֶׁשּׁוֹרֶה, לֹא זָז מִשָּׁם עַד שֶׁמְּכַלֶּה וּמַכְרִית הַכֹּל שֶׁלֹּא נִשְׁאָר כְּלוּם. אֲבָל דִּין אַחֵר שֶׁלְּמַטָּה, רֵאשִׁית קָשָׁה, וְכָל מַה שֶּׁהוֹלֵךְ - נֶחֱלָשׁ, עַד שֶׁמֵּאִיר פָּנִים, כְּדֻגְמַת (זה דין של הגקבה) הַנְּקֵבָה שֶׁנֶּחֱלָשׁ כֹּחָהּ."],[5,"","מִמָּתַי הִתְעוֹרֵר דִּין שֶׁלְּמַעְלָה לִשְׁרוֹת עַל הָעוֹלָם? בְּיוֹם הַמַּבּוּל. וְעַל זֶה לֹא נִשְׁאַר כְּלוּם בָּעוֹלָם חוּץ מֵהַתֵּבָה הַהִיא שֶׁל נֹחַ, שֶׁהִיא כַּדֻּגְמָא הָעֶלְיוֹן שֶׁסָּבְלָה לְכֹּחַ הַדִּין הַהוּא. וְאִלּוּלֵי שֶׁהִזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִמְצָא בְרַחֲמִים עַל הָעוֹלָם, כָּל הָעוֹלָם הָיָה נֶאֱבָד, שֶׁכָּתוּב (תהלים כט) ה' לַמַּבּוּל יָשָׁב. וְעַל זֶה לֹא שׁוֹרֶה דִין שֶׁלְּמַעְלָה עַל הָעוֹלָם, שֶׁלֹּא יָכוֹל הָעוֹלָם לִסְבֹּל אוֹתוֹ אֲפִלּוּ רֶגַע אֶחָד."],[6,"","בְּתוֹךָ כָּךְ הָיָה רַבִּי שִׁמְעוֹן בּוֹכֶה וְשָׂמֵחַ. נָשְׂאוּ עֵינַיִם וְרָאוּ חֲמִשָּׁה מֵאֵלֶּה הָאֲנָשִׁים הַפְּרוּשִׁים שֶׁהָיוּ הוֹלְכִים אַחֲרָיו לְבַקֵּשׁ אוֹתוֹ. עָמְדוּ. אָמַר רַבִּי שִׁמְעוֹן, מִכָּאן וָהָלְאָה מַה שִּׁמְךְ? אָמַר, נְהוֹרַאי סָבָא, מִשּׁוּם שֶׁיֵּשׁ נְהוֹרַאי אַחֵר אֶצְלֵנוּ. הָלְכוּ רַבִּי שִׁמְעוֹן וְהַחֲבֵרִים הָאֵלֶּה עִמּוֹ שְׁלֹשָׁה מִילִין. אָמַר רַבִּי שִׁמְעוֹן לְאֵלּוּ הָאֲחֵרִים, מַה דֶּרֶךְ זוֹ אֶצְלְכֶם? אָמְרוּ, לְבַקֵּשׁ אֶת הַזָּקֵן הַזֶּה, שֶׁמִּמֵּימָיו אָנוּ שׁוֹתִים בַּמִּדְבָּר. בָּא רַבִּי שִׁמְעוֹן וּנְשָׁקוֹ. אָמַר לוֹ, שִׁמְךְ נְהוֹרַאי, וְאוֹר אַתָּה, וְאוֹר עִמְּךְ נִמְצָא."],[7,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דניאל ב) הוּא מְגַלֶּה עֲמֻקּוֹת וְנִסְתָּרוֹת, יוֹדֵעַ מַה בַּחֹשֶׁךְ, וְהָאוֹר שׁוֹרֶה עִמּוֹ. הוּא גָּלֵא עַמִּיקָתָא וּמְסַתְּרָתָא - הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה עֲמֻקּוֹת וְנִסְתָּרוֹת, שֶׁכָּל הַדְּבָרִים הָעֲמֻקִּים וְהַסְּתוּמִים הָעֶלְיוֹנִים הוּא מְגַלֶּה לָהֶם. וּמָה הַטַּעַם מְגַלֶּה לָהֶם? מִשּׁוּם שֶׁיָּדַע מָה בַחֲשׁוֹכָא. שֶׁאִם לֹא הָיָה הַחֹשֶׁךְ, לֹא נוֹדַע הָאוֹר. וְהוּא יָדַע מַה בַּחֹשֶׁךְ, וּמִפְּנֵי כָּךְ מְגַלֶּה עֲמֻקּוֹת וְנִסְתָּרוֹת. שֶׁאִם לֹא הַחֹשֶׁךְ, לֹא יִתְגַּלּוּ הַדְּבָרִים הָעֲמֻקִּים וְהַנִּסְתָּרִים. וּנְהוֹרָא עִמֵּהּ שְׁרֵא - מַהוּ אוֹר זֶה? אוֹר שֶׁמִּתְגַּלֶּה מִתּוֹךְ הַחֹשֶׁךְ."]]],[["וַאֲנָן מִגּוֹ חֲשׁוֹכָא דְּהַוָה בְּמַדְבְּרָא, אִתְגְּלֵי לָן נְהוֹרָא דָּא. רַחֲמָנָא יַשְׁרֵי עִמָּךְ נְהוֹרָא, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. אָזְלֵי רַבִּי שִׁמְעוֹן וְחַבְרַיָּיא, אִלֵּין תְּלַת מִילִין אֲבַתְרֵיהּ, אָמַר לֵיהּ, אֲמַאי לָא אָזְלֵי אִלֵּין עִמָּךְ כְּקַדְמִיתָא. אֲמַר לֵיהּ, לָא בְּעֵינָא לְאַטְרְחָא לְבַר נָשׁ עִמִּי, הַשְׁתָּא דְּאָתוּ נֵזִיל כַּחֲדָא. אָזְלוּ, וְרַבִּי שִׁמְעוֹן אָזַל לְאָרְחֵיהּ. אָמַר רִבִּי אַבָּא, הָא אֲנָן יְדַעְנָא שְׁמֵיהּ, וְאִיהוּ לָא יָדַע שְׁמֵיהּ דְּמֹר, אָמַר לֵיהּ, מִנֵּיהּ יָדַעְנָא דְּלָא לְאִתְחֲזָאָה. בָּרוּךָ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן:"],[[0,"ואנן מגו חשוכא","וכו': ואנו, מתוך החשך שהיית במדבר נגלה לנו אור הזה. הרחמן ישרה עמך אור בעולם הזה ובעולם הבא. הלכו ר\"ש והחברים ג' מלין אחריו. אמר לו ר\"ש למה לא הלכו עמך, חמשה האנשים שלך מתחילה, אלא שבאו עתה. אמר לו הזקן, לא רציתי להטריח לאדם שילוו אותי, עתה שבאו. נלך ביחד. הלכו. ור\"ש הלך לדרכו. אמר לו רבי אבא. הרי אנו יודעים שמו של הזקן, והוא אינו יודע שמו של אדוני. אמר לו ממנו אני יודע שלא להתראות. שהרי לא אמר לי שמו מטרם ששאלתיו."]],[[0,"","וְאָנוּ, מִתּוֹךְ הַחֹשֶׁךְ שֶׁהָיָה בַּמִּדְבָּר, מִתְגַּלֶּה לָנוּ אוֹר זֶה. הַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁרֶה עִמְּךְ אוֹר בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. הָלְכוּ רַבִּי שִׁמְעוֹן וְהַחֲבֵרִים שְׁלֹשָׁה מִילִין אֵלּוּ אַחֲרָיו. אָמַר לוֹ, מַדּוּעַ לֹא הוֹלְכִים אֵלּוּ עִמְּךְ כְּבָרִאשׁוֹנָה? אָמַר לוֹ, לֹא רָצִיתִי לְהַטְרִיחַ לְבֶן אָדָם עִמִּי. עַכְשָׁו שֶׁבָּאוּ, נֵלֵךְ כְּאֶחָד. הָלְכוּ, וְרַבִּי שִׁמְעוֹן הָלַךְ לְדַרְכּוֹ. אָמַר רַבִּי אַבָּא, הֲרֵי אָנוּ יוֹדְעִים אֶת שְׁמוֹ, וְהוּא לֹא יוֹדֵעַ אֶת שְׁמוֹ שֶׁל מֹר? אָמַר לוֹ, מִמֶּנּוּ יָדַעְתִּי שֶׁלֹּא לְהִתְרָאוֹת. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
